CREATE OR REPLACE FUNCTION "public"."accept_invitation_atomic"("p_invite_code" "text", "p_first_name" "text", "p_last_name" "text", "p_phone" "text", "p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_invite RECORD;
  v_user_id UUID;
  v_user_email TEXT;
  v_membership_id INTEGER;
  v_branch_id INTEGER;
BEGIN
  -- Si se pasa p_user_id (flujo admin/server-side), usarlo.
  -- Si no, usar auth.uid() (flujo con sesion del cliente).
  v_user_id := COALESCE(p_user_id, auth.uid());
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'No hay sesion activa. Debes abrir el enlace de invitacion desde tu correo.';
  END IF;

  SELECT email INTO v_user_email FROM auth.users WHERE id = v_user_id;

  SELECT * INTO v_invite
  FROM invitations
  WHERE code = p_invite_code
    AND status = 'pending'
    AND expires_at > NOW()
  FOR UPDATE;

  IF v_invite IS NULL THEN
    RAISE EXCEPTION 'La invitacion no existe, ya fue utilizada o expiro.';
  END IF;

  IF v_user_email IS NULL OR lower(v_user_email) <> lower(v_invite.email) THEN
    RAISE EXCEPTION 'La invitacion fue enviada a otro correo electronico.';
  END IF;

  -- Resolver branch_id: invitacion > sucursal principal de la organizacion
  v_branch_id := v_invite.branch_id;
  IF v_branch_id IS NULL THEN
    SELECT b.id INTO v_branch_id
    FROM branches b
    WHERE b.organization_id = v_invite.organization_id
      AND b.is_main = true
      AND b.is_active = true
    LIMIT 1;
  END IF;

  -- 1. Perfil (profiles no tiene branch_id/organization_id/role_id; se guardan en last_org_id)
  INSERT INTO profiles (id, email, first_name, last_name, phone, last_org_id, status)
  VALUES (v_user_id, v_user_email, p_first_name, p_last_name, p_phone, v_invite.organization_id, 'active')
  ON CONFLICT (id) DO UPDATE SET
    first_name = EXCLUDED.first_name,
    last_name = EXCLUDED.last_name,
    phone = EXCLUDED.phone,
    last_org_id = EXCLUDED.last_org_id,
    status = 'active';

  -- 2. Membresia en la organizacion (con job_position_id)
  SELECT id INTO v_membership_id
  FROM organization_members
  WHERE user_id = v_user_id AND organization_id = v_invite.organization_id;

  IF v_membership_id IS NULL THEN
    INSERT INTO organization_members (user_id, organization_id, role_id, job_position_id, is_active)
    VALUES (v_user_id, v_invite.organization_id, v_invite.role_id, v_invite.job_position_id, true)
    RETURNING id INTO v_membership_id;
  ELSE
    UPDATE organization_members
    SET role_id = v_invite.role_id,
        job_position_id = COALESCE(v_invite.job_position_id, organization_members.job_position_id),
        is_active = true
    WHERE id = v_membership_id;
  END IF;

  -- 3. Asignar sucursal en member_branches (usa branch resuelto, no solo el de la invitacion)
  IF v_branch_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM member_branches
      WHERE organization_member_id = v_membership_id
        AND branch_id = v_branch_id
    ) THEN
      INSERT INTO member_branches (organization_member_id, branch_id)
      VALUES (v_membership_id, v_branch_id);
    END IF;

    -- 4. Asegurar que el employment creado por el trigger tenga el branch_id correcto
    UPDATE employments
    SET branch_id = v_branch_id, updated_at = NOW()
    WHERE organization_member_id = v_membership_id
      AND branch_id IS NULL;
  END IF;

  -- 5. Marcar invitacion como utilizada
  UPDATE invitations
  SET status = 'used', used_at = NOW()
  WHERE id = v_invite.id;

  RETURN jsonb_build_object(
    'user_id', v_user_id,
    'organization_id', v_invite.organization_id,
    'membership_id', v_membership_id,
    'branch_id', v_branch_id,
    'job_position_id', v_invite.job_position_id
  );
END;
$$;


ALTER FUNCTION "public"."accept_invitation_atomic"("p_invite_code" "text", "p_first_name" "text", "p_last_name" "text", "p_phone" "text", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_organization_currency"("p_organization_id" integer, "p_currency_code" character, "p_is_base" boolean DEFAULT false, "p_auto_update" boolean DEFAULT true) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  -- Verificar que la moneda existe en el catálogo global
  IF NOT EXISTS (SELECT 1 FROM currencies WHERE code = p_currency_code) THEN
    RAISE EXCEPTION 'La moneda con código % no existe en el catálogo global', p_currency_code;
  END IF;

  -- Verificar que la moneda no esté ya asociada a esta organización
  IF EXISTS (
    SELECT 1 
    FROM organization_currencies 
    WHERE organization_id = p_organization_id AND currency_code = p_currency_code
  ) THEN
    RAISE EXCEPTION 'La moneda con código % ya está asociada a esta organización', p_currency_code;
  END IF;

  -- Si es moneda base, actualizar todas las demás para que no sean base
  IF p_is_base THEN
    UPDATE organization_currencies
    SET is_base = FALSE
    WHERE organization_id = p_organization_id;
  END IF;

  -- Insertar la nueva asociación entre organización y moneda
  INSERT INTO organization_currencies(organization_id, currency_code, is_base, auto_update)
  VALUES (p_organization_id, p_currency_code, p_is_base, p_auto_update);

  RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."add_organization_currency"("p_organization_id" integer, "p_currency_code" character, "p_is_base" boolean, "p_auto_update" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_insert_shared_image"("p_image_url" "text", "p_storage_path" "text", "p_file_name" "text", "p_file_size" integer, "p_mime_type" "text", "p_organization_id" integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_image_id INTEGER;
BEGIN
    -- Usamos el super usuario para esta inserción
    -- dándole permiso explícito para ignorar RLS
    ALTER TABLE shared_images DISABLE ROW LEVEL SECURITY;
    
    INSERT INTO public.shared_images (
        image_url, 
        storage_path, 
        file_name, 
        file_size, 
        mime_type, 
        organization_id,
        is_public,
        created_at
    ) VALUES (
        p_image_url, 
        p_storage_path, 
        p_file_name, 
        p_file_size, 
        p_mime_type, 
        p_organization_id,
        false,
        now()
    )
    RETURNING id INTO v_image_id;
    
    -- Restaurar RLS
    ALTER TABLE shared_images ENABLE ROW LEVEL SECURITY;
    
    RETURN v_image_id;
EXCEPTION
    WHEN OTHERS THEN
        -- Asegurar que siempre volvemos a habilitar RLS
        ALTER TABLE shared_images ENABLE ROW LEVEL SECURITY;
        RAISE;
END;
$$;


ALTER FUNCTION "public"."admin_insert_shared_image"("p_image_url" "text", "p_storage_path" "text", "p_file_name" "text", "p_file_size" integer, "p_mime_type" "text", "p_organization_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_register_image"("p_image_url" "text", "p_storage_path" "text", "p_file_name" "text", "p_file_size" integer, "p_mime_type" "text", "p_organization_id" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_image_id INTEGER;
BEGIN
    BEGIN
        v_image_id := admin_insert_shared_image(
            p_image_url,
            p_storage_path,
            p_file_name,
            p_file_size,
            p_mime_type,
            p_organization_id
        );
        
        RETURN jsonb_build_object(
            'success', true,
            'image_id', v_image_id,
            'message', 'Image registered successfully'
        );
    EXCEPTION
        WHEN OTHERS THEN
            RETURN jsonb_build_object(
                'success', false,
                'error', SQLERRM,
                'error_code', SQLSTATE,
                'organization_id', p_organization_id
            );
    END;
END;
$$;


ALTER FUNCTION "public"."admin_register_image"("p_image_url" "text", "p_storage_path" "text", "p_file_name" "text", "p_file_size" integer, "p_mime_type" "text", "p_organization_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."app_branch_access"("p_branch_id" integer) RETURNS boolean
    LANGUAGE "sql" SECURITY DEFINER
    AS $$
  SELECT
    -- 1) Sin sucursal especificada: permitir
    p_branch_id IS NULL
    -- 2) Super admin o Admin de organización: acceso total
    OR EXISTS (
      SELECT 1 FROM organization_members om
      WHERE om.user_id = auth.uid()
        AND om.is_active = true
        AND (
          om.is_super_admin = true
          OR om.role_id IN (
            SELECT r.id FROM roles r
            WHERE r.name = ANY (ARRAY['Super Admin','Admin de organización'])
          )
        )
    )
    -- 3) Empleado con sucursal específica asignada en member_branches
    OR EXISTS (
      SELECT 1 FROM member_branches mb
      JOIN organization_members om ON om.id = mb.organization_member_id
      WHERE om.user_id = auth.uid()
        AND mb.branch_id = p_branch_id
    );
$$;


ALTER FUNCTION "public"."app_branch_access"("p_branch_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assign_core_modules_to_organization"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  -- Insertar todos los módulos core activos para la nueva organización
  INSERT INTO organization_modules (organization_id, module_code, is_active, enabled_at)
  SELECT NEW.id, m.code, true, NOW()
  FROM modules m
  WHERE m.is_core = true
    AND m.is_active = true
  ON CONFLICT (organization_id, module_code) DO NOTHING;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."assign_core_modules_to_organization"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."associate_image_to_product"("p_shared_image_id" integer, "p_product_id" integer, "p_display_order" integer DEFAULT 1, "p_is_primary" boolean DEFAULT false) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_organization_id INTEGER;
    v_image_url TEXT;
    v_storage_path TEXT;
    v_product_image_id INTEGER;
    v_has_access BOOLEAN;
    v_image_is_public BOOLEAN;
    v_image_org_id INTEGER;
BEGIN
    -- Obtener la organización del token JWT
    v_organization_id := (auth.jwt() ->> 'organization_id')::INTEGER;
    
    -- Primero verificamos si la imagen existe y obtenemos su información
    SELECT image_url, storage_path, organization_id, is_public 
    FROM shared_images 
    WHERE id = p_shared_image_id
    INTO v_image_url, v_storage_path, v_image_org_id, v_image_is_public;
    
    IF v_image_url IS NULL THEN
        RAISE EXCEPTION 'La imagen solicitada no existe';
    END IF;
    
    -- Verificar si la organización tiene acceso a la imagen
    -- Una imagen es accesible si:
    -- 1. Es pública (is_public = TRUE) sin importar la organización, O
    -- 2. Pertenece a la organización del usuario, O
    -- 3. Existe un registro en organization_images que otorga acceso
    v_has_access := (
        v_image_is_public OR 
        v_image_org_id = v_organization_id OR
        EXISTS(
            SELECT 1 FROM organization_images
            WHERE organization_id = v_organization_id 
            AND shared_image_id = p_shared_image_id
        )
    );
    
    IF NOT v_has_access THEN
        RAISE EXCEPTION 'No tienes acceso a esta imagen';
    END IF;
    
    -- Si esta imagen es primaria, actualizar otras imágenes para quitar el flag is_primary
    IF p_is_primary THEN
        UPDATE product_images
        SET is_primary = FALSE
        WHERE product_id = p_product_id;
    END IF;
    
    -- Insertar en product_images
    INSERT INTO product_images (
        product_id, 
        image_url, 
        storage_path, 
        display_order, 
        is_primary,
        shared_image_id
    )
    VALUES (
        p_product_id,
        v_image_url,
        v_storage_path,
        p_display_order,
        p_is_primary,
        p_shared_image_id
    )
    RETURNING id INTO v_product_image_id;
    
    RETURN v_product_image_id;
END;
$$;


ALTER FUNCTION "public"."associate_image_to_product"("p_shared_image_id" integer, "p_product_id" integer, "p_display_order" integer, "p_is_primary" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."audit_finance_changes"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_old_data jsonb;
  v_new_data jsonb;
  v_action text;
  v_diff jsonb;
  v_org_id integer;
  v_entity_id text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_action := 'insert';
    v_new_data := to_jsonb(NEW);
    v_diff := jsonb_build_object('new', v_new_data);
  ELSIF TG_OP = 'UPDATE' THEN
    v_action := 'update';
    v_old_data := to_jsonb(OLD);
    v_new_data := to_jsonb(NEW);
    v_diff := jsonb_build_object('old', v_old_data, 'new', v_new_data);
  ELSIF TG_OP = 'DELETE' THEN
    v_action := 'delete';
    v_old_data := to_jsonb(OLD);
    v_diff := jsonb_build_object('old', v_old_data);
  END IF;

  IF TG_OP = 'DELETE' THEN
    v_org_id := COALESCE((OLD.organization_id)::integer, 0);
    v_entity_id := (OLD.id)::text;
  ELSE
    v_org_id := COALESCE((NEW.organization_id)::integer, 0);
    v_entity_id := (NEW.id)::text;
  END IF;

  INSERT INTO finance_audit_log (
    organization_id,
    entity,
    entity_id,
    action,
    user_id,
    diff,
    timestamp
  ) VALUES (
    v_org_id,
    TG_TABLE_NAME,
    v_entity_id,
    v_action,
    auth.uid(),
    v_diff,
    NOW()
  );

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  ELSE
    RETURN NEW;
  END IF;
END;
$$;


ALTER FUNCTION "public"."audit_finance_changes"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."audit_finance_changes"() IS 'Función de auditoría para cambios en finanzas (sales, invoice_sales, payments)';



CREATE OR REPLACE FUNCTION "public"."audit_ops_changes"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_old_data jsonb;
  v_new_data jsonb;
  v_action text;
  v_changed_fields text[];
  v_org_id integer;
  v_branch_id integer;
  v_entity_id text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_action := 'create';
    v_old_data := NULL;
    v_new_data := to_jsonb(NEW);
    v_changed_fields := ARRAY(SELECT jsonb_object_keys(v_new_data));
  ELSIF TG_OP = 'UPDATE' THEN
    v_action := 'update';
    v_old_data := to_jsonb(OLD);
    v_new_data := to_jsonb(NEW);
    SELECT ARRAY_AGG(key) INTO v_changed_fields
    FROM jsonb_each(v_new_data) AS n(key, value)
    WHERE v_old_data->key IS DISTINCT FROM n.value;
  ELSIF TG_OP = 'DELETE' THEN
    v_action := 'delete';
    v_old_data := to_jsonb(OLD);
    v_new_data := NULL;
    v_changed_fields := NULL;
  END IF;

  IF TG_OP = 'DELETE' THEN
    v_org_id := COALESCE((OLD.organization_id)::integer, 0);
    v_branch_id := (OLD.branch_id)::integer;
    v_entity_id := (OLD.id)::text;
  ELSE
    v_org_id := COALESCE((NEW.organization_id)::integer, 0);
    v_branch_id := (NEW.branch_id)::integer;
    v_entity_id := (NEW.id)::text;
  END IF;

  INSERT INTO ops_audit_log (
    id,
    organization_id,
    branch_id,
    user_id,
    entity_type,
    entity_id,
    action,
    previous_data,
    new_data,
    changed_fields,
    created_at
  ) VALUES (
    gen_random_uuid(),
    v_org_id,
    v_branch_id,
    auth.uid(),
    TG_TABLE_NAME,
    v_entity_id,
    v_action,
    v_old_data,
    v_new_data,
    v_changed_fields,
    NOW()
  );

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  ELSE
    RETURN NEW;
  END IF;
END;
$$;


ALTER FUNCTION "public"."audit_ops_changes"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."audit_ops_changes"() IS 'Función de auditoría para cambios en operaciones (customers, reservations, shipments, inventory)';



CREATE OR REPLACE FUNCTION "public"."audit_products_changes"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_old_data jsonb;
  v_new_data jsonb;
  v_changes jsonb;
  v_action_type text;
  v_entity_type text;
BEGIN
  -- Mapear nombre de tabla a entity_type permitido
  v_entity_type := CASE TG_TABLE_NAME
    WHEN 'products' THEN 'product'
    WHEN 'product_variants' THEN 'product_variant'
    WHEN 'product_images' THEN 'product_image'
    WHEN 'product_tags' THEN 'product_tag'
    ELSE 'product'
  END;

  IF TG_OP = 'INSERT' THEN
    v_action_type := 'create';
    v_old_data := NULL;
    v_new_data := to_jsonb(NEW);
    v_changes := jsonb_build_object('after', v_new_data);
  ELSIF TG_OP = 'UPDATE' THEN
    v_action_type := 'update';
    v_old_data := to_jsonb(OLD);
    v_new_data := to_jsonb(NEW);
    v_changes := jsonb_build_object('before', v_old_data, 'after', v_new_data);
  ELSIF TG_OP = 'DELETE' THEN
    v_action_type := 'delete';
    v_old_data := to_jsonb(OLD);
    v_new_data := NULL;
    v_changes := jsonb_build_object('before', v_old_data);
  END IF;

  INSERT INTO products_audit_log (
    id,
    organization_id,
    entity_type,
    entity_id,
    action_type,
    changes,
    user_id,
    created_at
  ) VALUES (
    gen_random_uuid(),
    COALESCE(
      CASE WHEN TG_OP = 'DELETE' THEN OLD.organization_id ELSE NEW.organization_id END,
      0
    ),
    v_entity_type,
    CASE WHEN TG_OP = 'DELETE' THEN OLD.id ELSE NEW.id END,
    v_action_type,
    v_changes,
    auth.uid(),
    NOW()
  );

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  ELSE
    RETURN NEW;
  END IF;
END;
$$;


ALTER FUNCTION "public"."audit_products_changes"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."audit_products_changes"() IS 'Función de auditoría para cambios en productos';



CREATE OR REPLACE FUNCTION "public"."auto_assign_base_permissions_to_job_position"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  -- Insertar permisos base para el nuevo cargo
  -- Estos son permisos mínimos que todo empleado debería tener
  INSERT INTO job_position_permissions (job_position_id, permission_id, allowed)
  SELECT 
    NEW.id,
    p.id,
    true
  FROM permissions p
  WHERE p.code IN (
    'calendar.view',           -- Ver calendario
    'notifications.view'       -- Ver notificaciones
  )
  ON CONFLICT (job_position_id, permission_id) DO NOTHING;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."auto_assign_base_permissions_to_job_position"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."auto_close_inactive_conversations"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  closed_count integer;
BEGIN
  WITH updated AS (
    UPDATE conversations c
    SET 
      status = 'closed',
      updated_at = now()
    FROM channels ch
    WHERE c.channel_id = ch.id
      AND c.status = 'open'
      AND ch.auto_close_inactive_hours IS NOT NULL
      AND c.last_message_at < (now() - (ch.auto_close_inactive_hours || ' hours')::interval)
    RETURNING 1
  )
  SELECT COUNT(*) INTO closed_count FROM updated;
  
  RETURN closed_count;
END;
$$;


ALTER FUNCTION "public"."auto_close_inactive_conversations"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."auto_close_inactive_conversations"() IS 'Cierra automáticamente conversaciones inactivas según configuración del canal';



CREATE OR REPLACE FUNCTION "public"."auto_generate_missing_rates"() RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    start_date date;
    current_date_iter date;
    filled_count integer := 0;
    base_rates jsonb;
    daily_variation numeric;
    result jsonb;
BEGIN
    -- Definir fecha inicio: desde hace 15 días hasta hoy
    start_date := CURRENT_DATE - INTERVAL '15 days';
    
    -- Tasas base realistas (simulando datos reales del mercado)
    base_rates := '{
        "COP": 4049.91,
        "MXN": 18.65268,
        "EUR": 0.85569,
        "GBP": 0.74621,
        "JPY": 147.35875,
        "CAD": 1.37412,
        "AUD": 1.54871,
        "BRL": 5.47708,
        "CLP": 976.22900,
        "USD": 1.000000
    }';
    
    -- Iterar cada día desde start_date hasta hoy
    current_date_iter := start_date;
    WHILE current_date_iter <= CURRENT_DATE LOOP
        -- Verificar si ya existen datos para esta fecha
        IF NOT EXISTS (
            SELECT 1 FROM currency_rates 
            WHERE rate_date = current_date_iter
        ) AND EXTRACT(dow FROM current_date_iter) != 0 THEN  -- Excluir domingos
            
            -- Generar variación diaria basada en la fecha para consistencia
            daily_variation := (EXTRACT(epoch FROM current_date_iter)::numeric / 86400) * 0.001;
            
            -- Insertar tasas con variación realista por fecha
            INSERT INTO currency_rates (code, rate, source, rate_date, created_at, updated_at, base_currency_code)
            SELECT 
                key as code,
                (value::numeric * (1 + sin(daily_variation) * 0.015))::numeric(15,6) as rate,  -- Variación senoidal ±1.5%
                'auto_generated_daily' as source,
                current_date_iter as rate_date,  -- Tipo correcto: date
                NOW() as created_at,
                NOW() as updated_at,
                'USD' as base_currency_code
            FROM jsonb_each_text(base_rates);
            
            filled_count := filled_count + 1;
            RAISE LOG 'Generadas tasas para fecha: %', current_date_iter;
        END IF;
        
        current_date_iter := current_date_iter + INTERVAL '1 day';
    END LOOP;
    
    result := jsonb_build_object(
        'success', true,
        'dates_filled', filled_count,
        'start_date', start_date,
        'end_date', CURRENT_DATE,
        'message', format('Tasas generadas automáticamente para %s fechas faltantes', filled_count)
    );
    
    RETURN result;
END;
$$;


ALTER FUNCTION "public"."auto_generate_missing_rates"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."auto_update_exchange_rates"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_project_url TEXT;
  v_anon_key TEXT;
  v_response_id BIGINT;
BEGIN
  -- URL del proyecto Supabase
  v_project_url := 'https://jgmgphmzusbluqhuqihj.supabase.co';
  
  -- Obtener anon key desde vault o usar una hardcoded para cron
  -- Nota: La Edge Function tiene verify_jwt: false, así que no necesitamos auth real
  v_anon_key := '<ANON_KEY>';
  
  -- Llamar a la Edge Function usando pg_net
  SELECT net.http_post(
    url := v_project_url || '/functions/v1/actualizar-tasas-cambio',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || v_anon_key
    ),
    body := jsonb_build_object('source', 'pg_cron')
  ) INTO v_response_id;
  
  -- Log del intento
  RAISE NOTICE 'Edge Function called, request_id: %', v_response_id;
  
EXCEPTION WHEN OTHERS THEN
  -- Registrar error en logs
  PERFORM public.log_exchange_rates_execution(
    now(),
    false,
    SQLERRM,
    0, 0, 0,
    jsonb_build_array(
      jsonb_build_object(
        'operation', 'cron_edge_function_call',
        'error', SQLERRM
      )
    )
  );
  RAISE NOTICE 'Error calling Edge Function: %', SQLERRM;
END;
$$;


ALTER FUNCTION "public"."auto_update_exchange_rates"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."auto_update_exchange_rates"() IS 'Función automática para actualizar tasas de cambio diariamente. Debe ser llamada por cron job o Edge Function.';



CREATE OR REPLACE FUNCTION "public"."buscar_productos"("p_org" integer, "p_tokens" "text"[], "p_limite" integer DEFAULT 6, "p_umbral" real DEFAULT 2.0) RETURNS TABLE("id" bigint, "nombre" "text", "sku" "text", "precio" numeric, "precio_anterior" numeric, "imagen" "text", "stock" numeric, "puntaje" real, "presentaciones" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  with tokens as (
    select distinct public.normalizar_busqueda(w) as tok
    from unnest(coalesce(p_tokens, '{}'::text[])) as w
  ),
  tokens_utiles as (
    select tok from tokens where length(tok) >= 2
  ),
  candidatos as (
    select
      p.id,
      p.name,
      p.sku,
      p.parent_product_id,
      coalesce(p.parent_product_id, p.id) as raiz,
      ' ' || p.busqueda_nombre || ' '      as n_nombre,
      ' ' || p.busqueda_marca || ' '       as n_marca,
      ' ' || p.busqueda_descripcion || ' ' as n_desc,
      ' ' || public.normalizar_busqueda(coalesce(cat.name, '')) || ' ' as n_categoria,
      lower(coalesce(p.sku, ''))           as l_sku,
      lower(coalesce(p.reference, ''))     as l_ref
    from public.products p
    left join public.categories cat on cat.id = p.category_id
    where p.organization_id = p_org
      and p.status = 'active'
  ),
  puntuados as (
    select c.*,
      (
        select coalesce(sum(
          case
            when c.l_sku = t.tok or c.l_ref = t.tok then 6.0
            when c.n_nombre like '% ' || t.tok || ' %' then 4.0
            when c.n_marca like '% ' || t.tok || ' %' then 3.0
            -- La categoria ayuda cuando el catalogo esta en otro idioma que el
            -- cliente: una tienda de calzado tiene su catalogo en ingles
            -- pero su categoria se llama "Calzado".
            when c.n_categoria like '% ' || t.tok || ' %' then 2.5
            when length(t.tok) >= 4 and c.n_nombre like '%' || t.tok || '%' then 2.0
            when length(t.tok) >= 4 and c.n_marca  like '%' || t.tok || '%' then 1.5
            when length(t.tok) >= 4 and c.n_desc   like '%' || t.tok || '%' then 0.75
            else 0
          end), 0)::real
        from tokens_utiles t
      ) as score
    from candidatos c
  ),
  relevantes as (
    select * from puntuados where score >= p_umbral
  ),
  representantes as (
    select distinct on (raiz)
      raiz, id, name, sku, score
    from relevantes
    order by raiz, (parent_product_id is null) desc, score desc, id
  ),
  conteo as (
    select raiz, count(*)::integer as n from relevantes group by raiz
  )
  select
    r.id, r.name, r.sku,
    pr.price, pr.compare_price, im.storage_path, st.qty,
    r.score, co.n
  from representantes r
  join conteo co on co.raiz = r.raiz
  left join lateral (
    select pp.price, pp.compare_price
    from public.products p2
    join public.product_prices pp on pp.product_id = p2.id and pp.effective_to is null
    where p2.organization_id = p_org and coalesce(p2.parent_product_id, p2.id) = r.raiz
    order by (p2.id = r.id) desc, pp.price asc nulls last
    limit 1
  ) pr on true
  left join lateral (
    select pi.storage_path
    from public.products p2
    join public.product_images pi on pi.product_id = p2.id
    where p2.organization_id = p_org and coalesce(p2.parent_product_id, p2.id) = r.raiz
    order by (p2.id = r.id) desc, pi.is_primary desc nulls last, pi.display_order asc nulls last
    limit 1
  ) im on true
  left join lateral (
    select sum(sl.qty_on_hand) as qty
    from public.products p2
    join public.stock_levels sl on sl.product_id = p2.id
    where p2.organization_id = p_org and coalesce(p2.parent_product_id, p2.id) = r.raiz
  ) st on true
  order by r.score desc, r.id
  limit greatest(coalesce(p_limite, 6), 1);
$$;


ALTER FUNCTION "public"."buscar_productos"("p_org" integer, "p_tokens" "text"[], "p_limite" integer, "p_umbral" real) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_days_overdue"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  -- Calcular días de atraso si hay fecha de vencimiento y balance pendiente
  IF NEW.due_date IS NOT NULL AND NEW.balance > 0 THEN
    -- Calcular días de atraso (solo si está vencida)
    IF NEW.due_date::date < CURRENT_DATE THEN
      NEW.days_overdue := (CURRENT_DATE - NEW.due_date::date)::integer;
      
      -- Actualizar status si es necesario
      IF NEW.status = 'current' THEN
        NEW.status := 'overdue';
      END IF;
    ELSE
      -- Si no está vencida, días de atraso = 0
      NEW.days_overdue := 0;
      
      -- Si está pagada parcialmente, mantener status 'partial'
      -- Si no tiene pagos, mantener 'current'
      IF NEW.status = 'overdue' AND NEW.balance = NEW.amount THEN
        NEW.status := 'current';
      END IF;
    END IF;
  ELSE
    -- Si no hay balance pendiente o no hay fecha de vencimiento
    NEW.days_overdue := 0;
    
    -- Si balance es 0, marcar como pagada
    IF NEW.balance = 0 THEN
      NEW.status := 'paid';
    END IF;
  END IF;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."calculate_days_overdue"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_first_response_time"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  first_customer_message_time timestamptz;
BEGIN
  -- Solo para mensajes de agente
  IF NEW.role = 'agent' AND NEW.direction = 'outbound' THEN
    -- Buscar el primer mensaje del cliente en esta conversación
    SELECT created_at INTO first_customer_message_time
    FROM messages
    WHERE conversation_id = NEW.conversation_id
      AND role = 'customer'
      AND direction = 'inbound'
    ORDER BY created_at ASC
    LIMIT 1;
    
    -- Si existe y la conversación no tiene first_response_time, calcularlo
    IF first_customer_message_time IS NOT NULL THEN
      UPDATE conversations
      SET 
        first_response_time_seconds = EXTRACT(EPOCH FROM (NEW.created_at - first_customer_message_time))::integer,
        updated_at = now()
      WHERE id = NEW.conversation_id
        AND first_response_time_seconds IS NULL;
    END IF;
  END IF;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."calculate_first_response_time"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_parking_session_amount"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_rate_price NUMERIC;
    v_rate_unit TEXT;
    v_grace_period INTEGER;
    v_duration_minutes INTEGER;
    v_unit_count NUMERIC;
BEGIN
    -- Solo proceder si estamos cerrando la sesión
    IF NEW.status = 'closed' AND OLD.status = 'open' THEN
        -- Calcular duración en minutos
        NEW.duration_min := EXTRACT(EPOCH FROM (NEW.exit_at - NEW.entry_at)) / 60;
        
        -- Si hay una tarifa asociada, calcular el monto
        IF NEW.rate_id IS NOT NULL THEN
            -- Obtener datos de la tarifa
            SELECT price, unit::TEXT, COALESCE(grace_period_min, 0)
            INTO v_rate_price, v_rate_unit, v_grace_period
            FROM parking_rates
            WHERE id = NEW.rate_id;
            
            -- Aplicar período de gracia
            v_duration_minutes := GREATEST(0, NEW.duration_min - v_grace_period);
            
            -- Calcular unidades según tipo de tarifa
            CASE v_rate_unit
                WHEN 'minute' THEN v_unit_count := v_duration_minutes;
                WHEN 'hour' THEN v_unit_count := CEILING(v_duration_minutes / 60.0);
                WHEN 'day' THEN v_unit_count := CEILING(v_duration_minutes / (60.0 * 24));
                ELSE v_unit_count := 0;
            END CASE;
            
            -- Calcular monto final
            NEW.amount := v_rate_price * v_unit_count;
        END IF;
    END IF;
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."calculate_parking_session_amount"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_reservation_total"("p_organization_id" integer, "p_space_type_id" "uuid", "p_checkin" "date", "p_checkout" "date", "p_plan" "text" DEFAULT NULL::"text") RETURNS TABLE("total_amount" numeric, "nights" integer, "daily_rate" numeric, "rate_source" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_nights integer;
  v_daily_rate numeric;
  v_rate_source text;
  v_current_date date;
  v_total numeric := 0;
  v_rate_record record;
BEGIN
  -- Calcular noches
  v_nights := p_checkout - p_checkin;
  
  IF v_nights <= 0 THEN
    RAISE EXCEPTION 'La fecha de checkout debe ser posterior al checkin';
  END IF;
  
  -- Por simplicidad, usar la tarifa del día de check-in
  -- (Opcionalmente se puede iterar día por día para tarifas variables)
  SELECT * INTO v_rate_record
  FROM public.get_rate_for_date(p_organization_id, p_space_type_id, p_checkin, p_plan);
  
  v_daily_rate := v_rate_record.price;
  v_rate_source := CASE WHEN v_rate_record.is_from_rates THEN 'tarifa' ELSE 'base_rate' END;
  v_total := v_daily_rate * v_nights;
  
  RETURN QUERY SELECT v_total, v_nights, v_daily_rate, v_rate_source;
END;
$$;


ALTER FUNCTION "public"."calculate_reservation_total"("p_organization_id" integer, "p_space_type_id" "uuid", "p_checkin" "date", "p_checkout" "date", "p_plan" "text") OWNER TO "postgres";


