CREATE OR REPLACE FUNCTION "public"."check_rate_conflicts"("p_organization_id" integer, "p_space_type_id" "uuid", "p_date_from" "date", "p_date_to" "date", "p_plan" "text" DEFAULT NULL::"text", "p_exclude_rate_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("conflicting_rate_id" "uuid", "conflicting_priority" integer, "conflicting_date_from" "date", "conflicting_date_to" "date", "conflicting_plan" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    r.id as conflicting_rate_id,
    r.priority as conflicting_priority,
    r.date_from as conflicting_date_from,
    r.date_to as conflicting_date_to,
    r.restrictions->>'plan' as conflicting_plan
  FROM rates r
  WHERE r.organization_id = p_organization_id
    AND r.space_type_id = p_space_type_id
    AND r.is_active = true
    AND (p_exclude_rate_id IS NULL OR r.id != p_exclude_rate_id)
    AND (
      (p_date_from BETWEEN r.date_from AND r.date_to) OR
      (p_date_to BETWEEN r.date_from AND r.date_to) OR
      (r.date_from BETWEEN p_date_from AND p_date_to) OR
      (r.date_to BETWEEN p_date_from AND p_date_to)
    )
    AND (
      p_plan IS NULL OR 
      r.restrictions->>'plan' IS NULL OR 
      r.restrictions->>'plan' = p_plan
    );
END;
$$;


ALTER FUNCTION "public"."check_rate_conflicts"("p_organization_id" integer, "p_space_type_id" "uuid", "p_date_from" "date", "p_date_to" "date", "p_plan" "text", "p_exclude_rate_id" "uuid") OWNER TO "postgres";


