CREATE OR REPLACE FUNCTION "public"."cleanup_residual_signup_data"() RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    cleanup_count INTEGER := 0;
    user_record RECORD;
BEGIN
    -- Buscar usuarios con signup_data que tengan email confirmado hace más de 1 hora
    FOR user_record IN 
        SELECT id, email, email_confirmed_at
        FROM auth.users 
        WHERE raw_user_meta_data ? 'signup_data'
        AND email_confirmed_at IS NOT NULL
        AND email_confirmed_at < NOW() - INTERVAL '1 hour'
    LOOP
        -- Limpiar signup_data
        UPDATE auth.users 
        SET raw_user_meta_data = raw_user_meta_data - 'signup_data'
        WHERE id = user_record.id;
        
        -- Log de la limpieza
        INSERT INTO public.signup_debug_logs (
            user_id, 
            email, 
            error_message
        ) VALUES (
            user_record.id,
            user_record.email,
            'LIMPIEZA AUTOMÁTICA: signup_data residual eliminado (confirmado: ' || user_record.email_confirmed_at || ')'
        );
        
        cleanup_count := cleanup_count + 1;
    END LOOP;
    
    RETURN 'Limpieza automática completada. ' || cleanup_count || ' usuarios procesados.';
END;
$$;


ALTER FUNCTION "public"."cleanup_residual_signup_data"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cleanup_residual_signup_data"() IS 'Función para limpiar automáticamente signup_data residual de usuarios que confirmaron su email hace más de 1 hora. Ejecutar periódicamente para mantener limpia la base de datos.';



CREATE OR REPLACE FUNCTION "public"."cleanup_signup_data"("user_email" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    user_record RECORD;
    had_data BOOLEAN := FALSE;
    result_message TEXT;
BEGIN
    -- Verificar si el usuario existe y tiene signup_data
    SELECT id, users.email, 
           (raw_user_meta_data ? 'signup_data') as has_signup_data
    INTO user_record
    FROM auth.users 
    WHERE users.email = user_email;
    
    IF NOT FOUND THEN
        RETURN 'ERROR: Usuario con email ' || user_email || ' no encontrado';
    END IF;
    
    had_data := user_record.has_signup_data;
    
    -- Limpiar signup_data si existe
    IF had_data THEN
        UPDATE auth.users 
        SET raw_user_meta_data = raw_user_meta_data - 'signup_data'
        WHERE users.email = user_email;
        
        -- Log de la limpieza
        INSERT INTO public.signup_debug_logs (
            user_id, 
            email, 
            error_message
        ) VALUES (
            user_record.id,
            user_email,
            'LIMPIEZA MANUAL: signup_data eliminado manualmente'
        );
        
        result_message := 'ÉXITO: signup_data eliminado para usuario ' || user_email;
    ELSE
        result_message := 'INFO: Usuario ' || user_email || ' no tenía signup_data';
    END IF;
    
    RETURN result_message;
END;
$$;


ALTER FUNCTION "public"."cleanup_signup_data"("user_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cleanup_temporary_members"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  deleted_count integer;
BEGIN
  DELETE FROM public.organization_members
  WHERE is_temporary = true
    AND created_at < now() - interval '2 hours';
  
  GET DIAGNOSTICS deleted_count = ROW_COUNT;
  RETURN deleted_count;
END;
$$;


ALTER FUNCTION "public"."cleanup_temporary_members"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_invitation_registration"("invitation_code" "text", "user_id" "uuid", "user_email" "text", "first_name" "text", "last_name" "text", "phone_number" "text", "user_password" "text") RETURNS "json"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  invite_record RECORD;
  new_member_id bigint;
  result JSON;
BEGIN
  -- 1. Validar que la invitación existe y está pendiente
  SELECT * INTO invite_record
  FROM invitations
  WHERE code = invitation_code
    AND status = 'pending'
    AND expires_at > NOW();
    
  IF NOT FOUND THEN
    RETURN json_build_object(
      'success', false,
      'error', 'Invitación no válida, expirada o ya utilizada'
    );
  END IF;
  
  -- 2. Verificar que el email coincide
  IF invite_record.email != user_email THEN
    RETURN json_build_object(
      'success', false,
      'error', 'El email no coincide con la invitación'
    );
  END IF;
  
  -- 3. Crear el perfil del usuario
  INSERT INTO profiles (
    id,
    email,
    first_name,
    last_name,
    phone,
    last_org_id,
    avatar_url,
    preferred_language,
    status
  ) VALUES (
    user_id,
    user_email,
    first_name,
    last_name,
    phone_number,
    invite_record.organization_id,
    null,
    'es',
    'active'
  );
  
  -- 4. Crear membresía en la organización y obtener el ID
  INSERT INTO organization_members (
    organization_id,
    user_id,
    role_id,
    is_super_admin,
    is_active
  ) VALUES (
    invite_record.organization_id,
    user_id,
    invite_record.role_id,
    false,
    true
  )
  RETURNING id INTO new_member_id;
  
  -- 5. NUEVO: Crear registro de empleo (employment)
  INSERT INTO employments (
    organization_member_id,
    status,
    hire_date,
    employment_type,
    contract_type,
    work_location,
    work_hours_per_week,
    currency_code,
    salary_period
  ) VALUES (
    new_member_id,
    'active',                    -- Estado activo
    CURRENT_DATE,                -- Fecha de contratación = hoy
    'employee',                  -- Tipo de empleo por defecto
    'indefinite',                -- Contrato indefinido por defecto
    'onsite',                    -- Ubicación por defecto
    48,                          -- Horas semanales estándar Colombia
    'COP',                       -- Moneda por defecto
    'monthly'                    -- Período de salario mensual
  );
  
  -- 6. Marcar invitación como utilizada
  UPDATE invitations
  SET status = 'used', used_at = NOW()
  WHERE id = invite_record.id;
  
  -- 7. Retornar éxito
  RETURN json_build_object(
    'success', true,
    'organization_id', invite_record.organization_id,
    'role_id', invite_record.role_id,
    'organization_member_id', new_member_id
  );
  
EXCEPTION WHEN OTHERS THEN
  RETURN json_build_object(
    'success', false,
    'error', 'Error interno: ' || SQLERRM
  );
END;
$$;


ALTER FUNCTION "public"."complete_invitation_registration"("invitation_code" "text", "user_id" "uuid", "user_email" "text", "first_name" "text", "last_name" "text", "phone_number" "text", "user_password" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."complete_invitation_registration"("invitation_code" "text", "user_id" "uuid", "user_email" "text", "first_name" "text", "last_name" "text", "phone_number" "text", "user_password" "text") IS 'Completa el registro de un usuario invitado:
1. Crea perfil
2. Crea organization_member
3. Crea employment (registro de empleo)
4. Marca invitación como usada';



CREATE OR REPLACE FUNCTION "public"."complete_production_order"("p_order_id" integer, "p_produced_qty" numeric, "p_updated_by" "uuid" DEFAULT NULL::"uuid") RETURNS "json"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_order RECORD;
  v_recipe RECORD;
  v_ingredient RECORD;
  v_conv_factor NUMERIC;
  v_converted_qty NUMERIC;
  v_needed_qty NUMERIC;
  v_movement_id INTEGER;
  v_consumption_id INTEGER;
  v_ingredients_processed INTEGER := 0;
  v_existing_stock RECORD;
  v_new_qty NUMERIC;
  v_prod_track_stock BOOLEAN;
BEGIN
  SELECT * INTO v_order FROM production_orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Orden de producción % no encontrada', p_order_id; END IF;
  IF v_order.status NOT IN ('in_progress','confirmed') THEN RAISE EXCEPTION 'La orden % no se puede completar desde estado %', p_order_id, v_order.status; END IF;
  SELECT id, name, yield_qty, yield_unit_code INTO v_recipe FROM product_recipes WHERE id = v_order.recipe_id AND is_active = true LIMIT 1;
  IF NOT FOUND THEN RAISE EXCEPTION 'La receta % de la orden no está activa', v_order.recipe_id; END IF;
  v_conv_factor := p_produced_qty / COALESCE(NULLIF(v_recipe.yield_qty, 0), 1);
  FOR v_ingredient IN SELECT ri.id, ri.ingredient_product_id, ri.quantity, ri.unit_code, ri.is_optional, p.track_stock, p.name AS ingredient_name, p.unit_code AS product_unit_code FROM recipe_ingredients ri JOIN products p ON p.id = ri.ingredient_product_id WHERE ri.recipe_id = v_recipe.id ORDER BY ri.sort_order LOOP
    IF v_ingredient.track_stock = false OR v_ingredient.track_stock IS NULL THEN CONTINUE; END IF;
    v_needed_qty := v_ingredient.quantity * v_conv_factor;
    v_converted_qty := v_needed_qty;
    IF v_ingredient.unit_code IS NOT NULL AND v_ingredient.product_unit_code IS NOT NULL AND v_ingredient.unit_code <> v_ingredient.product_unit_code THEN
      SELECT uc.factor INTO v_conv_factor FROM unit_conversions uc WHERE uc.from_unit_code = v_ingredient.unit_code AND uc.to_unit_code = v_ingredient.product_unit_code AND (uc.organization_id = v_order.organization_id OR uc.organization_id IS NULL) ORDER BY uc.organization_id NULLS LAST LIMIT 1;
      IF FOUND AND v_conv_factor IS NOT NULL AND v_conv_factor > 0 THEN v_converted_qty := v_needed_qty * v_conv_factor; END IF;
    END IF;
    SELECT id, qty_on_hand, avg_cost INTO v_existing_stock FROM stock_levels WHERE product_id = v_ingredient.ingredient_product_id AND branch_id = v_order.branch_id AND lot_id IS NULL LIMIT 1;
    IF v_existing_stock IS NOT NULL THEN v_new_qty := COALESCE(v_existing_stock.qty_on_hand, 0) - v_converted_qty; UPDATE stock_levels SET qty_on_hand = v_new_qty, updated_at = now() WHERE id = v_existing_stock.id; ELSE v_new_qty := -v_converted_qty; INSERT INTO stock_levels (product_id, branch_id, lot_id, qty_on_hand, qty_reserved, avg_cost, min_level) VALUES (v_ingredient.ingredient_product_id, v_order.branch_id, NULL, v_new_qty, 0, 0, 0); END IF;
    INSERT INTO stock_movements (organization_id, branch_id, product_id, lot_id, direction, qty, unit_cost, source, source_id, note, updated_by) VALUES (v_order.organization_id, v_order.branch_id, v_ingredient.ingredient_product_id, NULL, 'out', v_converted_qty, COALESCE(v_existing_stock.avg_cost, 0), 'production', p_order_id::text, CONCAT('Consumo producción #', p_order_id, ' - ', v_ingredient.ingredient_name), p_updated_by) RETURNING id INTO v_movement_id;
    INSERT INTO production_order_consumptions (production_order_id, ingredient_product_id, quantity_consumed, unit_code, stock_movement_id) VALUES (p_order_id, v_ingredient.ingredient_product_id, v_converted_qty, v_ingredient.unit_code, v_movement_id) RETURNING id INTO v_consumption_id;
    v_ingredients_processed := v_ingredients_processed + 1;
  END LOOP;
  SELECT track_stock INTO v_prod_track_stock FROM products WHERE id = v_order.product_id;
  IF v_prod_track_stock = true THEN
    SELECT id, qty_on_hand, avg_cost INTO v_existing_stock FROM stock_levels WHERE product_id = v_order.product_id AND branch_id = v_order.branch_id AND lot_id IS NULL LIMIT 1;
    IF v_existing_stock IS NOT NULL THEN v_new_qty := COALESCE(v_existing_stock.qty_on_hand, 0) + p_produced_qty; UPDATE stock_levels SET qty_on_hand = v_new_qty, updated_at = now() WHERE id = v_existing_stock.id; ELSE INSERT INTO stock_levels (product_id, branch_id, lot_id, qty_on_hand, qty_reserved, avg_cost, min_level) VALUES (v_order.product_id, v_order.branch_id, NULL, p_produced_qty, 0, 0, 0); END IF;
    INSERT INTO stock_movements (organization_id, branch_id, product_id, lot_id, direction, qty, unit_cost, source, source_id, note, updated_by) VALUES (v_order.organization_id, v_order.branch_id, v_order.product_id, NULL, 'in', p_produced_qty, 0, 'production', p_order_id::text, CONCAT('Producción #', p_order_id, ' - ingreso producto terminado'), p_updated_by) RETURNING id INTO v_movement_id;
  END IF;
  UPDATE production_orders SET status = 'completed', produced_qty = p_produced_qty, completed_at = now(), updated_at = now() WHERE id = p_order_id;
  RETURN json_build_object('success', true, 'order_id', p_order_id, 'produced_qty', p_produced_qty, 'ingredients_processed', v_ingredients_processed, 'product_stock_added', v_prod_track_stock = true);
END;
$$;


ALTER FUNCTION "public"."complete_production_order"("p_order_id" integer, "p_produced_qty" numeric, "p_updated_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_purchase_invoice"("invoice_id_param" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  invoice_record RECORD;
BEGIN
  -- Verificar que la factura exista y esté en draft
  SELECT * INTO invoice_record FROM invoice_purchase WHERE id = invoice_id_param;
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Factura de compra no encontrada con ID: %', invoice_id_param;
  END IF;
  
  IF invoice_record.status != 'draft' THEN
    RAISE EXCEPTION 'La factura de compra con ID: % no está en estado borrador', invoice_id_param;
  END IF;
  
  -- Actualizar la factura a received
  UPDATE invoice_purchase
  SET 
    status = 'received',
    updated_at = NOW()
  WHERE id = invoice_id_param;
  
  -- Asegurar que la cuenta por pagar esté actualizada
  UPDATE accounts_payable
  SET 
    status = 'pending',
    updated_at = NOW()
  WHERE invoice_id = invoice_id_param;
  
  RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."confirm_purchase_invoice"("invoice_id_param" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crear_tipo_variante"("p_name" "text", "p_organization_id" integer, "p_values" "text"[]) RETURNS "json"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_type_id INTEGER;
  v_result JSON;
  v_user_id UUID;
  v_can_access BOOLEAN;
BEGIN
  -- Obtener el ID del usuario actual
  v_user_id := auth.uid();
  
  -- Verificar si el usuario tiene acceso a la organización
  SELECT EXISTS (
    SELECT 1 FROM organization_members 
    WHERE organization_id = p_organization_id 
    AND user_id = v_user_id
  ) INTO v_can_access;
  
  -- Si es organización global (0) o el usuario tiene acceso, proceder
  IF p_organization_id = 0 OR v_can_access THEN
    -- Insertar el tipo de variante
    INSERT INTO variant_types (name, organization_id)
    VALUES (p_name, p_organization_id)
    RETURNING id INTO v_type_id;
    
    -- Insertar los valores para cada elemento en el array
    FOR i IN 1..array_length(p_values, 1) LOOP
      INSERT INTO variant_values (variant_type_id, value, display_order)
      VALUES (v_type_id, p_values[i], i);
    END LOOP;
    
    -- Devolver el resultado
    v_result := json_build_object('id', v_type_id, 'success', true);
    RETURN v_result;
  ELSE
    RAISE EXCEPTION 'El usuario no tiene acceso a esta organización';
  END IF;
END;
$$;


ALTER FUNCTION "public"."crear_tipo_variante"("p_name" "text", "p_organization_id" integer, "p_values" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_account_receivable"("invoice_id_param" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  ar_id UUID;
  invoice_record RECORD;
BEGIN
  -- Buscar la factura con conversión explícita a UUID
  BEGIN
    SELECT * INTO invoice_record FROM invoice_sales WHERE id = invoice_id_param::UUID;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'Error al convertir o buscar factura con ID %: %', invoice_id_param, SQLERRM;
  END;
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Factura no encontrada con ID: %', invoice_id_param;
  END IF;
  
  -- Verificar si ya existe una cuenta por cobrar para esta factura
  SELECT id INTO ar_id FROM accounts_receivable WHERE invoice_id = invoice_id_param::UUID LIMIT 1;
  
  IF FOUND THEN
    -- Ya existe, actualizamos
    UPDATE accounts_receivable
    SET 
      amount = invoice_record.total,
      balance = invoice_record.balance,
      status = CASE
                WHEN invoice_record.balance <= 0 THEN 'paid'
                WHEN invoice_record.balance < invoice_record.total THEN 'partial'
                WHEN invoice_record.due_date < NOW() THEN 'overdue'
                ELSE 'current'
              END,
      updated_at = NOW()
    WHERE id = ar_id;
    
    RETURN ar_id;
  ELSE
    -- Crear cuenta por cobrar, solo si no es draft o si se llama explícitamente
    INSERT INTO accounts_receivable (
      id,
      organization_id,
      customer_id,
      invoice_id,
      sale_id,
      amount,
      balance,
      due_date,
      status,
      days_overdue,
      created_at,
      updated_at
    ) VALUES (
      gen_random_uuid(),
      invoice_record.organization_id,
      invoice_record.customer_id,
      invoice_record.id,
      invoice_record.sale_id,
      invoice_record.total,
      invoice_record.balance,
      invoice_record.due_date,
      CASE
        WHEN invoice_record.balance <= 0 THEN 'paid'
        WHEN invoice_record.balance < invoice_record.total THEN 'partial'
        WHEN invoice_record.due_date < NOW() THEN 'overdue'
        ELSE 'current'
      END,
      CASE
        WHEN invoice_record.due_date < NOW() THEN EXTRACT(DAY FROM NOW() - invoice_record.due_date)::integer
        ELSE 0
      END,
      NOW(),
      NOW()
    )
    RETURNING id INTO ar_id;
    
    RETURN ar_id;
  END IF;
END;
$$;


ALTER FUNCTION "public"."create_account_receivable"("invoice_id_param" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_account_receivable"("p_organization_id" integer, "p_customer_id" "uuid", "p_invoice_id" "uuid", "p_amount" numeric, "p_balance" numeric, "p_due_date" timestamp with time zone, "p_status" "text", "p_days_overdue" integer DEFAULT 0) RETURNS "json"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    result json;
BEGIN
    INSERT INTO accounts_receivable (
        organization_id,
        customer_id,
        invoice_id,
        amount,
        balance,
        due_date,
        status,
        days_overdue
    ) VALUES (
        p_organization_id,
        p_customer_id,
        p_invoice_id,
        p_amount,
        p_balance,
        p_due_date,
        p_status,
        p_days_overdue
    ) RETURNING to_json(accounts_receivable.*) INTO result;
    
    RETURN result;
END;
$$;


ALTER FUNCTION "public"."create_account_receivable"("p_organization_id" integer, "p_customer_id" "uuid", "p_invoice_id" "uuid", "p_amount" numeric, "p_balance" numeric, "p_due_date" timestamp with time zone, "p_status" "text", "p_days_overdue" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_account_receivable_on_invoice"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  -- Solo ejecutar si la factura NO está en estado draft o si cambió de draft a otro estado
  IF NEW.status != 'draft' OR (OLD.status = 'draft' AND NEW.status != 'draft') THEN
    -- Convertir explícitamente el ID a texto antes de llamar a la función
    PERFORM create_account_receivable(NEW.id::TEXT);
  END IF;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."create_account_receivable_on_invoice"() OWNER TO "postgres";


