CREATE OR REPLACE FUNCTION "public"."create_default_subscription"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Solo crear si no existe ya una suscripción
  IF NOT EXISTS (
    SELECT 1 FROM subscriptions WHERE organization_id = NEW.id
  ) THEN
    INSERT INTO subscriptions (
      organization_id,
      plan_id,
      status,
      current_period_start,
      current_period_end,
      skip_trial,
      billing_period
    ) VALUES (
      NEW.id,
      COALESCE(NEW.plan_id, 1), -- Default: Free Plan
      'active',
      NOW(),
      NOW() + INTERVAL '1 year', -- 1 año para free plan
      false,
      NULL -- NULL para plan free
    );
    
    RAISE NOTICE 'Suscripción por defecto creada para organización %', NEW.id;
  END IF;
  
  RETURN NEW;
EXCEPTION
  WHEN OTHERS THEN
    -- Si falla, no interrumpir el proceso de creación
    RAISE NOTICE 'Error creando suscripción por defecto: %', SQLERRM;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."create_default_subscription"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_default_website_settings"("org_id" integer, "org_type_id" integer, "org_name" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  type_name TEXT;
  settings_id UUID;
  template TEXT;
  primary_col TEXT;
  secondary_col TEXT;
  cta_text TEXT;
  show_reservations BOOLEAN := false;
  show_online_ordering BOOLEAN := false;
  show_appointments BOOLEAN := false;
  show_memberships BOOLEAN := false;
  show_tickets BOOLEAN := false;
  show_parking BOOLEAN := false;
BEGIN
  IF EXISTS (SELECT 1 FROM website_settings WHERE organization_id = org_id) THEN
    SELECT id INTO settings_id FROM website_settings WHERE organization_id = org_id;
    RETURN settings_id;
  END IF;

  SELECT name INTO type_name FROM organization_types WHERE id = org_type_id;
  
  CASE type_name
    WHEN 'restaurant' THEN
      template := 'restaurant';
      primary_col := '#EF4444';
      secondary_col := '#F97316';
      cta_text := 'Reservar Mesa';
      show_reservations := true;
      show_online_ordering := true;
    WHEN 'hotel' THEN
      template := 'hotel';
      primary_col := '#0EA5E9';
      secondary_col := '#6366F1';
      cta_text := 'Reservar Ahora';
      show_reservations := true;
    WHEN 'retail' THEN
      template := 'ecommerce';
      primary_col := '#8B5CF6';
      secondary_col := '#EC4899';
      cta_text := 'Ver Catálogo';
      show_online_ordering := true;
    WHEN 'saas' THEN
      template := 'modern';
      primary_col := '#3B82F6';
      secondary_col := '#10B981';
      cta_text := 'Comenzar Ahora';
    WHEN 'gym' THEN
      template := 'bold';
      primary_col := '#F59E0B';
      secondary_col := '#EF4444';
      cta_text := 'Únete Ahora';
      show_memberships := true;
      show_appointments := true;
    WHEN 'transport' THEN
      template := 'modern';
      primary_col := '#14B8A6';
      secondary_col := '#3B82F6';
      cta_text := 'Reservar Viaje';
      show_reservations := true;
      show_tickets := true;
    WHEN 'parking' THEN
      template := 'minimal';
      primary_col := '#6366F1';
      secondary_col := '#8B5CF6';
      cta_text := 'Reservar Espacio';
      show_parking := true;
      show_reservations := true;
    ELSE
      template := 'modern';
      primary_col := '#3B82F6';
      secondary_col := '#6366F1';
      cta_text := 'Contáctanos';
  END CASE;

  INSERT INTO website_settings (
    organization_id, template_id, primary_color, secondary_color,
    header_cta_text,
    enable_reservations, enable_online_ordering, enable_appointments,
    enable_memberships, enable_tickets, enable_parking_booking,
    is_published, show_products, show_services, show_gallery,
    show_testimonials, show_faq, show_contact, show_map, show_social_links,
    meta_title, meta_description
  ) VALUES (
    org_id, template, primary_col, secondary_col,
    cta_text,
    show_reservations, show_online_ordering, show_appointments,
    show_memberships, show_tickets, show_parking,
    true, true, true, true, true, true, true, true, true,
    'Bienvenido a ' || org_name,
    org_name || ' - Tu empresa de confianza'
  )
  RETURNING id INTO settings_id;

  RETURN settings_id;
END;
$$;


ALTER FUNCTION "public"."create_default_website_settings"("org_id" integer, "org_type_id" integer, "org_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_employment_for_new_member"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_branch_id INTEGER;
BEGIN
  -- Solo crear employment si no existe uno para este member
  IF NOT EXISTS (
    SELECT 1 FROM employments
    WHERE organization_member_id = NEW.id
  ) THEN

    -- Resolver branch_id en orden de prioridad:
    -- 1. Asignacion explicita en member_branches (si ya existe)
    SELECT mb.branch_id INTO v_branch_id
    FROM member_branches mb
    WHERE mb.organization_member_id = NEW.id
    ORDER BY mb.id ASC
    LIMIT 1;

    -- 2. Sucursal principal de la organizacion (fallback robusto)
    IF v_branch_id IS NULL THEN
      SELECT b.id INTO v_branch_id
      FROM branches b
      WHERE b.organization_id = NEW.organization_id
        AND b.is_main = true
        AND b.is_active = true
      LIMIT 1;
    END IF;

    INSERT INTO employments (
      organization_member_id,
      status,
      hire_date,
      employment_type,
      contract_type,
      work_location,
      work_hours_per_week,
      currency_code,
      salary_period,
      branch_id
    ) VALUES (
      NEW.id,
      'active',
      CURRENT_DATE,
      'employee',
      'indefinite',
      'onsite',
      48,
      'COP',
      'monthly',
      v_branch_id
    );
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."create_employment_for_new_member"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_employment_for_new_member"() IS 'Crea automáticamente un registro de employment cuando se agrega 
un nuevo miembro a una organización (vía invitación u otro medio).
Valores por defecto: status=active, hire_date=hoy, employment_type=employee,
contract_type=indefinite, 48h/semana, COP, pago mensual.';



CREATE OR REPLACE FUNCTION "public"."create_payment_method"("p_organization_id" integer, "p_code" "text", "p_name" "text", "p_requires_reference" boolean, "p_is_active" boolean, "p_settings" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  -- Insertar en la tabla principal
  INSERT INTO payment_methods (
    code, name, requires_reference, is_active, is_system
  ) VALUES (
    p_code, p_name, p_requires_reference, p_is_active, false
  );
  
  -- Crear configuración específica para la organización
  INSERT INTO organization_payment_methods (
    organization_id, payment_method_code, is_active, settings
