CREATE OR REPLACE FUNCTION "public"."create_product_with_images"("p_product_data" "jsonb", "p_shared_image_ids" integer[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_organization_id INTEGER;
    v_product_id INTEGER;
    v_image_id INTEGER;
    v_display_order INTEGER := 1;
    v_result JSONB;
BEGIN
    -- Obtener la organización del token JWT
    v_organization_id := (auth.jwt() ->> 'organization_id')::INTEGER;
    
    -- Insertar el nuevo producto
    INSERT INTO products (
        organization_id,
        sku,
        name,
        category_id,
        unit_code,
        track_stock,
        cost,
        price,
        is_menu_item,
        description,
        barcode,
        status,
        supplier_id
    ) VALUES (
        v_organization_id,
        p_product_data->>'sku',
        p_product_data->>'name',
        (p_product_data->>'category_id')::INTEGER,
        p_product_data->>'unit_code',
        (p_product_data->>'track_stock')::BOOLEAN,
        (p_product_data->>'cost')::NUMERIC,
        (p_product_data->>'price')::NUMERIC,
        (p_product_data->>'is_menu_item')::BOOLEAN,
        p_product_data->>'description',
        p_product_data->>'barcode',
        p_product_data->>'status',
        (p_product_data->>'supplier_id')::INTEGER
    )
    RETURNING id INTO v_product_id;
    
    -- Asociar las imágenes al producto si existen
    IF p_shared_image_ids IS NOT NULL AND array_length(p_shared_image_ids, 1) > 0 THEN
        FOREACH v_image_id IN ARRAY p_shared_image_ids
        LOOP
            -- La primera imagen será la primaria
            PERFORM associate_image_to_product(
                v_image_id, 
                v_product_id, 
                v_display_order, 
                v_display_order = 1
            );
            v_display_order := v_display_order + 1;
        END LOOP;
    END IF;
    
    -- Preparar resultado
    SELECT jsonb_build_object(
        'product_id', v_product_id,
        'product_data', p_product_data,
        'image_count', array_length(p_shared_image_ids, 1)
    ) INTO v_result;
    
    RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."create_product_with_images"("p_product_data" "jsonb", "p_shared_image_ids" integer[]) OWNER TO "postgres";


