CREATE OR REPLACE FUNCTION "public"."create_rate_with_validation"("p_organization_id" integer, "p_space_type_id" "uuid", "p_date_from" "date", "p_date_to" "date", "p_price" numeric, "p_priority" integer DEFAULT 0, "p_restrictions" "jsonb" DEFAULT '{"min_stay": 1}'::"jsonb", "p_is_active" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_rate_id uuid;
  v_conflict record;
  v_plan text;
  v_has_conflict boolean := false;
  v_conflict_same_priority boolean := false;
BEGIN
  v_plan := p_restrictions->>'plan';
  
  FOR v_conflict IN 
    SELECT * FROM public.check_rate_conflicts(
      p_organization_id, p_space_type_id, p_date_from, p_date_to, v_plan, NULL
    )
  LOOP
    v_has_conflict := true;
    IF v_conflict.conflicting_priority = p_priority THEN
      v_conflict_same_priority := true;
    END IF;
  END LOOP;
  
  IF v_conflict_same_priority THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'CONFLICT_SAME_PRIORITY',
      'message', 'Ya existe una tarifa con la misma prioridad que se solapa en fechas. Debe asignar una prioridad diferente.'
    );
  END IF;
  
  INSERT INTO rates (organization_id, space_type_id, date_from, date_to, price, priority, restrictions, is_active)
  VALUES (p_organization_id, p_space_type_id, p_date_from, p_date_to, p_price, p_priority, p_restrictions, p_is_active)
  RETURNING id INTO v_rate_id;
  
  RETURN jsonb_build_object(
    'success', true,
    'rate_id', v_rate_id,
    'has_lower_priority_conflicts', v_has_conflict AND NOT v_conflict_same_priority
  );
END;
$$;


ALTER FUNCTION "public"."create_rate_with_validation"("p_organization_id" integer, "p_space_type_id" "uuid", "p_date_from" "date", "p_date_to" "date", "p_price" numeric, "p_priority" integer, "p_restrictions" "jsonb", "p_is_active" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_restaurant_reservation"("p_organization_id" integer, "p_reservation_date" "date", "p_reservation_time" time without time zone, "p_party_size" integer, "p_customer_name" "text", "p_branch_id" integer DEFAULT NULL::integer, "p_customer_phone" "text" DEFAULT NULL::"text", "p_customer_email" "text" DEFAULT NULL::"text", "p_zone" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text", "p_special_requests" "text" DEFAULT NULL::"text", "p_source" "text" DEFAULT 'website'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_settings        record;
  v_turn_duration   integer := 90;
  v_buffer          integer := 15;
  v_slot_minutes    integer;
  v_slot_end        integer;
  v_assigned_table  uuid;
  v_customer_id     uuid;
  v_reservation_id  uuid;
  v_status          text;
  v_conflict        boolean;
  v_table_rec       record;
BEGIN
  SELECT * INTO v_settings
  FROM public.restaurant_booking_settings
  WHERE organization_id = p_organization_id
    AND (branch_id = p_branch_id OR (branch_id IS NULL AND p_branch_id IS NULL))
  ORDER BY branch_id NULLS LAST
  LIMIT 1;

  IF v_settings IS NOT NULL THEN
    v_turn_duration := COALESCE(v_settings.turn_duration_minutes, 90);
    v_buffer := COALESCE(v_settings.buffer_minutes, 15);
    IF v_settings.is_enabled = false THEN
      RAISE EXCEPTION 'Las reservas online estan deshabilitadas para este restaurante';
    END IF;
    IF p_party_size < COALESCE(v_settings.min_party_size, 1) THEN
      RAISE EXCEPTION 'El numero minimo de personas es %', v_settings.min_party_size;
    END IF;
    IF p_party_size > COALESCE(v_settings.max_party_size, 12) THEN
      RAISE EXCEPTION 'El numero maximo de personas es %', v_settings.max_party_size;
    END IF;
    v_status := CASE WHEN v_settings.require_confirmation THEN 'pending' ELSE 'confirmed' END;
  ELSE
    v_status := 'confirmed';
  END IF;

  v_slot_minutes := EXTRACT(hour FROM p_reservation_time) * 60 + EXTRACT(minute FROM p_reservation_time);
  v_slot_end := v_slot_minutes + v_turn_duration + v_buffer;

  FOR v_table_rec IN
    SELECT t.id, t.capacity
    FROM public.restaurant_tables t
    WHERE t.organization_id = p_organization_id
      AND COALESCE(t.capacity, 4) >= p_party_size
      AND (p_zone IS NULL OR t.zone = p_zone)
    ORDER BY t.capacity ASC
    FOR UPDATE OF t
  LOOP
    SELECT EXISTS(
      SELECT 1
      FROM public.restaurant_reservations r
      WHERE r.restaurant_table_id = v_table_rec.id
        AND r.reservation_date = p_reservation_date
        AND r.status IN ('pending', 'confirmed', 'seated')
        AND (
          (EXTRACT(hour FROM r.reservation_time) * 60 + EXTRACT(minute FROM r.reservation_time))
            < v_slot_end
          AND
          (EXTRACT(hour FROM r.reservation_time) * 60 + EXTRACT(minute FROM r.reservation_time)
            + COALESCE(r.duration_minutes, v_turn_duration) + v_buffer)
            > v_slot_minutes
        )
    ) INTO v_conflict;

    IF NOT v_conflict THEN
      v_assigned_table := v_table_rec.id;
      EXIT;
    END IF;
  END LOOP;

  IF v_assigned_table IS NULL THEN
    RAISE EXCEPTION 'No hay mesas disponibles para la fecha y hora seleccionadas';
  END IF;

  PERFORM 1
  FROM public.restaurant_reservations r
  WHERE r.restaurant_table_id = v_assigned_table
    AND r.reservation_date = p_reservation_date
    AND r.status IN ('pending', 'confirmed', 'seated')
  FOR UPDATE OF r;

  IF p_customer_email IS NOT NULL AND p_customer_email != '' THEN
    SELECT c.id INTO v_customer_id
    FROM public.customers c
    WHERE c.organization_id = p_organization_id
      AND c.email = p_customer_email
    LIMIT 1;

    IF v_customer_id IS NULL THEN
      INSERT INTO public.customers (organization_id, first_name, full_name, email, phone, is_registered)
      VALUES (p_organization_id, p_customer_name, p_customer_name, p_customer_email, p_customer_phone, false)
      RETURNING id INTO v_customer_id;
    END IF;
  END IF;

  INSERT INTO public.restaurant_reservations (
    organization_id, branch_id, restaurant_table_id,
    customer_name, customer_phone, customer_email, customer_id,
    party_size, reservation_date, reservation_time, duration_minutes,
    status, source, notes, special_requests,
    confirmed_at
  )
  VALUES (
    p_organization_id, p_branch_id, v_assigned_table,
    p_customer_name, p_customer_phone, p_customer_email, v_customer_id,
    p_party_size, p_reservation_date, p_reservation_time, v_turn_duration,
    v_status, p_source, p_notes, p_special_requests,
    CASE WHEN v_status = 'confirmed' THEN now() ELSE NULL END
  )
  RETURNING id INTO v_reservation_id;

  RETURN jsonb_build_object(
    'success', true,
    'reservation_id', v_reservation_id,
    'table_id', v_assigned_table,
    'customer_id', v_customer_id,
    'status', v_status,
    'code', upper(substring(v_reservation_id::text, 1, 8))
  );
END;
$$;


ALTER FUNCTION "public"."create_restaurant_reservation"("p_organization_id" integer, "p_reservation_date" "date", "p_reservation_time" time without time zone, "p_party_size" integer, "p_customer_name" "text", "p_branch_id" integer, "p_customer_phone" "text", "p_customer_email" "text", "p_zone" "text", "p_notes" "text", "p_special_requests" "text", "p_source" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_restaurant_reservation"("p_organization_id" integer, "p_reservation_date" "date", "p_reservation_time" time without time zone, "p_party_size" integer, "p_customer_name" "text", "p_branch_id" integer, "p_customer_phone" "text", "p_customer_email" "text", "p_zone" "text", "p_notes" "text", "p_special_requests" "text", "p_source" "text") IS 'FASE 8: Crea una reserva de mesa atomicamente con FOR UPDATE.';



CREATE OR REPLACE FUNCTION "public"."create_user_fallback"("user_id" "uuid", "user_email" "text", "user_password" "text", "user_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  encrypted_pw TEXT;
BEGIN
  -- Encriptar la contraseña
  encrypted_pw := crypt(user_password, gen_salt('bf'));
  
  -- Insertar usuario en auth.users
  INSERT INTO auth.users (
    instance_id,
    id,
    aud,
    role,
    email,
    encrypted_password,
    email_confirmed_at,
    confirmation_sent_at,
    created_at,
    updated_at,
    raw_app_meta_data,
    raw_user_meta_data,
    is_super_admin,
    confirmation_token,
    recovery_token
  ) VALUES (
    '00000000-0000-0000-0000-000000000000',
    user_id,
    'authenticated',
    'authenticated',
    user_email,
    encrypted_pw,
    now(), -- Pre-confirmar email para desarrollo
    now(),
    now(),
    now(),
    '{"provider": "email", "providers": ["email"]}'::jsonb,
    user_metadata,
    false,
    '',
    ''
  );
  
  RETURN user_id;
END;
$$;


ALTER FUNCTION "public"."create_user_fallback"("user_id" "uuid", "user_email" "text", "user_password" "text", "user_metadata" "jsonb") OWNER TO "postgres";


