CREATE OR REPLACE FUNCTION "public"."daily_update_overdue_accounts"() RETURNS TABLE("updated_accounts" integer, "overdue_accounts" integer, "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  total_updated integer := 0;
  total_overdue integer := 0;
BEGIN
  -- Actualizar días de atraso para todas las cuentas con balance pendiente
  UPDATE accounts_receivable 
  SET 
    days_overdue = CASE 
      WHEN due_date::date < CURRENT_DATE AND balance > 0 
      THEN (CURRENT_DATE - due_date::date)::integer
      ELSE 0 
    END,
    status = CASE 
      WHEN balance = 0 THEN 'paid'
      WHEN due_date::date < CURRENT_DATE AND balance > 0 AND balance < amount THEN 'partial'
      WHEN due_date::date < CURRENT_DATE AND balance > 0 AND balance = amount THEN 'overdue'
      WHEN balance > 0 AND balance < amount THEN 'partial'
      ELSE 'current'
    END,
    updated_at = NOW()
  WHERE balance > 0 OR status != 'paid';
  
  GET DIAGNOSTICS total_updated = ROW_COUNT;
  
  -- Contar cuentas vencidas
  SELECT COUNT(*) INTO total_overdue
  FROM accounts_receivable 
  WHERE balance > 0 AND due_date::date < CURRENT_DATE;
  
  RETURN QUERY SELECT 
    total_updated, 
    total_overdue, 
    format('Actualizado: %s cuentas. Vencidas: %s', total_updated, total_overdue)::text;
END;
$$;


ALTER FUNCTION "public"."daily_update_overdue_accounts"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."deactivate_product"("p_product_id" integer) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_organization_id INTEGER;
    v_product_exists BOOLEAN;
BEGIN
    -- Obtener la organización del token JWT
    v_organization_id := (auth.jwt() ->> 'organization_id')::INTEGER;
    
    -- Verificar que el producto existe y pertenece a la organización
    SELECT EXISTS(
        SELECT 1 FROM products 
        WHERE id = p_product_id AND organization_id = v_organization_id
    ) INTO v_product_exists;
    
    IF NOT v_product_exists THEN
        RAISE EXCEPTION 'Producto no encontrado o no tienes permiso para modificarlo';
    END IF;
    
    -- Actualizar el estado del producto a "deleted" (eliminado)
    UPDATE products 
    SET status = 'deleted', 
        updated_at = NOW()
    WHERE id = p_product_id 
    AND organization_id = v_organization_id;
    
    RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."deactivate_product"("p_product_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."deactivate_product"("p_product_id" integer, "p_organization_id" integer DEFAULT NULL::integer) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_organization_id INTEGER;
    v_product_exists BOOLEAN;
BEGIN
    -- Si no se proporciona explícitamente, intentar obtener la organización del token JWT
    IF p_organization_id IS NULL THEN
        v_organization_id := (auth.jwt() ->> 'organization_id')::INTEGER;
    ELSE
        v_organization_id := p_organization_id;
    END IF;
    
    -- Si aún no tenemos un ID de organización, no podemos proceder
    IF v_organization_id IS NULL THEN
        RAISE EXCEPTION 'No se puede determinar la organización a la que perteneces';
    END IF;
    
    -- Verificar que el producto existe y pertenece a la organización
    SELECT EXISTS(
        SELECT 1 FROM products 
        WHERE id = p_product_id AND organization_id = v_organization_id
    ) INTO v_product_exists;
    
    IF NOT v_product_exists THEN
        RAISE EXCEPTION 'Producto no encontrado o no tienes permiso para modificarlo';
    END IF;
    
    -- Actualizar el estado del producto a "deleted" (eliminado)
    UPDATE products 
    SET status = 'deleted', 
        updated_at = NOW()
    WHERE id = p_product_id 
    AND organization_id = v_organization_id;
    
    RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."deactivate_product"("p_product_id" integer, "p_organization_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."decrement_ai_credits"("p_org_id" integer, "p_cost" integer) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_remaining integer;
BEGIN
  SELECT credits_remaining INTO v_remaining
    FROM ai_settings
    WHERE organization_id = p_org_id
    FOR UPDATE; -- bloqueo a nivel fila para evitar race condition

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ai_settings no encontrada para organization_id %', p_org_id;
  END IF;

  IF v_remaining < p_cost THEN
    RETURN false;
  END IF;

  UPDATE ai_settings
    SET credits_remaining = v_remaining - p_cost
    WHERE organization_id = p_org_id;

  RETURN true;
END;
$$;


ALTER FUNCTION "public"."decrement_ai_credits"("p_org_id" integer, "p_cost" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."decrement_stock_on_sale"("p_organization_id" integer, "p_branch_id" integer, "p_product_id" integer, "p_qty" numeric, "p_source" "text", "p_source_id" "text" DEFAULT NULL::"text", "p_unit_cost" numeric DEFAULT NULL::numeric, "p_note" "text" DEFAULT NULL::"text", "p_updated_by" "uuid" DEFAULT NULL::"uuid") RETURNS "json"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_track_stock boolean;
  v_existing_stock record;
  v_new_qty numeric;
  v_movement_id integer;
BEGIN
  -- 1. Verificar si el producto rastrea stock
  SELECT track_stock INTO v_track_stock
  FROM products
  WHERE id = p_product_id;

  -- Si no se encuentra el producto o no rastrea stock, salir sin error
  IF NOT FOUND OR v_track_stock = false OR v_track_stock IS NULL THEN
    RETURN json_build_object('success', true, 'skipped', true, 'reason', 'no_track_stock');
  END IF;

  -- 2. Buscar stock_level existente (sin lot_id)
  SELECT id, qty_on_hand, avg_cost INTO v_existing_stock
  FROM stock_levels
  WHERE product_id = p_product_id
    AND branch_id = p_branch_id
    AND lot_id IS NULL
  LIMIT 1;

  -- 3. Actualizar o crear stock_level
  IF v_existing_stock IS NOT NULL THEN
    v_new_qty := COALESCE(v_existing_stock.qty_on_hand, 0) - p_qty;
    UPDATE stock_levels
    SET qty_on_hand = v_new_qty,
        updated_at = now()
    WHERE id = v_existing_stock.id;
  ELSE
    v_new_qty := -p_qty;
    INSERT INTO stock_levels (product_id, branch_id, lot_id, qty_on_hand, qty_reserved, avg_cost, min_level)
    VALUES (p_product_id, p_branch_id, NULL, v_new_qty, 0, COALESCE(p_unit_cost, 0), 0);
  END IF;

  -- 4. Crear movimiento de stock
  INSERT INTO stock_movements (
    organization_id, branch_id, product_id, lot_id,
    direction, qty, unit_cost, source, source_id, note, updated_by
  )
  VALUES (
    p_organization_id, p_branch_id, p_product_id, NULL,
    'out', p_qty, COALESCE(p_unit_cost, v_existing_stock.avg_cost, 0),
    p_source, p_source_id, p_note, p_updated_by
  )
  RETURNING id INTO v_movement_id;

  RETURN json_build_object(
    'success', true,
    'skipped', false,
    'movement_id', v_movement_id,
    'new_qty', v_new_qty
  );
END;
$$;


ALTER FUNCTION "public"."decrement_stock_on_sale"("p_organization_id" integer, "p_branch_id" integer, "p_product_id" integer, "p_qty" numeric, "p_source" "text", "p_source_id" "text", "p_unit_cost" numeric, "p_note" "text", "p_updated_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."decrement_stock_with_recipe"("p_organization_id" integer, "p_branch_id" integer, "p_product_id" integer, "p_qty" numeric, "p_source" "text", "p_source_id" "text" DEFAULT NULL::"text", "p_unit_cost" numeric DEFAULT NULL::numeric, "p_updated_by" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "json"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_recipe RECORD;
  v_ingredient RECORD;
  v_conv_factor NUMERIC;
  v_converted_qty NUMERIC;
  v_result JSON;
  v_ingredients_processed INTEGER := 0;
  v_product_track_stock BOOLEAN;
  v_ingredient_note TEXT;
BEGIN
  SELECT id, name, yield_qty, yield_unit_code INTO v_recipe FROM product_recipes WHERE product_id = p_product_id AND is_active = true LIMIT 1;
  IF NOT FOUND THEN
    SELECT * INTO v_result FROM decrement_stock_on_sale(p_organization_id, p_branch_id, p_product_id, p_qty, p_source, p_source_id, p_unit_cost, p_note, p_updated_by);
    RETURN v_result;
  END IF;
  FOR v_ingredient IN SELECT ri.id, ri.ingredient_product_id, ri.quantity, ri.unit_code, ri.is_optional, ri.notes, p.track_stock, p.name AS ingredient_name, p.unit_code AS product_unit_code FROM recipe_ingredients ri JOIN products p ON p.id = ri.ingredient_product_id WHERE ri.recipe_id = v_recipe.id ORDER BY ri.sort_order LOOP
    IF v_ingredient.track_stock = false OR v_ingredient.track_stock IS NULL THEN CONTINUE; END IF;
    v_converted_qty := v_ingredient.quantity * p_qty;
    -- Conversión de unidades: recipe_unit -> product_unit
    IF v_ingredient.unit_code IS NOT NULL AND v_ingredient.product_unit_code IS NOT NULL AND v_ingredient.unit_code <> v_ingredient.product_unit_code THEN
      SELECT uc.factor INTO v_conv_factor FROM unit_conversions uc WHERE uc.from_unit_code = v_ingredient.unit_code AND uc.to_unit_code = v_ingredient.product_unit_code AND (uc.organization_id = p_organization_id OR uc.organization_id IS NULL) ORDER BY uc.organization_id NULLS LAST LIMIT 1;
      IF FOUND AND v_conv_factor IS NOT NULL AND v_conv_factor > 0 THEN v_converted_qty := v_converted_qty * v_conv_factor; END IF;
    END IF;
    v_ingredient_note := CONCAT('Ingrediente de receta: ', COALESCE(v_recipe.name, 'receta'), ' - ', v_ingredient.ingredient_name, COALESCE(' | ' || p_note, ''));
    PERFORM decrement_stock_on_sale(p_organization_id, p_branch_id, v_ingredient.ingredient_product_id, v_converted_qty, p_source, p_source_id, NULL, v_ingredient_note, p_updated_by);
    v_ingredients_processed := v_ingredients_processed + 1;
  END LOOP;
  SELECT track_stock INTO v_product_track_stock FROM products WHERE id = p_product_id;
  IF v_product_track_stock = true THEN PERFORM decrement_stock_on_sale(p_organization_id, p_branch_id, p_product_id, p_qty, p_source, p_source_id, p_unit_cost, p_note, p_updated_by); END IF;
  RETURN json_build_object('success', true, 'mode', 'recipe', 'recipe_id', v_recipe.id, 'ingredients_processed', v_ingredients_processed, 'product_stock_deducted', v_product_track_stock = true);
END;
$$;


ALTER FUNCTION "public"."decrement_stock_with_recipe"("p_organization_id" integer, "p_branch_id" integer, "p_product_id" integer, "p_qty" numeric, "p_source" "text", "p_source_id" "text", "p_unit_cost" numeric, "p_updated_by" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."deduct_comm_credits"("p_org_id" integer, "p_channel" "text", "p_amount" integer DEFAULT 1) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_id        uuid;
  v_sms       integer;
  v_wa        integer;
  v_voice     integer;
  v_remaining integer;
  v_amount    integer := COALESCE(p_amount, 1);
  v_cap       integer;
  v_new       integer;
BEGIN
  IF p_org_id IS NULL OR p_channel IS NULL
     OR p_channel NOT IN ('sms', 'whatsapp', 'voice') THEN
    RETURN false; -- canal desconocido: fail-closed
  END IF;

  SELECT id, sms_remaining, whatsapp_remaining, voice_minutes_remaining
    INTO v_id, v_sms, v_wa, v_voice
    FROM public.comm_settings
   WHERE organization_id = p_org_id
     AND is_active = true
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN false; -- sin configuración activa NO se envía (antes: "ilimitado")
  END IF;

  v_remaining := CASE p_channel
                   WHEN 'sms'      THEN v_sms
                   WHEN 'whatsapp' THEN v_wa
                   ELSE                 v_voice
                 END;

  IF v_remaining IS NULL THEN
    RETURN true; -- ilimitado explícito (Enterprise): ni se debita ni se abona
  END IF;

  IF v_amount = 0 THEN
    RETURN true;
  END IF;

  IF v_amount > 0 THEN
    IF v_remaining < v_amount THEN
      RETURN false;
    END IF;
    v_new := v_remaining - v_amount;
  ELSE
    -- Reembolso acotado al cupo del plan
    SELECT CASE p_channel
             WHEN 'sms'      THEN pl.comm_sms_monthly
             WHEN 'whatsapp' THEN pl.comm_whatsapp_monthly
             ELSE                 pl.comm_voice_minutes_monthly
           END
      INTO v_cap
      FROM public.organizations o
      JOIN public.plans pl ON pl.id = o.plan_id
     WHERE o.id = p_org_id;

    v_new := v_remaining + (-v_amount);
    IF v_cap IS NOT NULL THEN
      v_new := LEAST(v_new, GREATEST(v_cap, v_remaining));
    END IF;
  END IF;

  UPDATE public.comm_settings
     SET sms_remaining           = CASE WHEN p_channel = 'sms'      THEN v_new ELSE sms_remaining           END,
         whatsapp_remaining      = CASE WHEN p_channel = 'whatsapp' THEN v_new ELSE whatsapp_remaining      END,
         voice_minutes_remaining = CASE WHEN p_channel = 'voice'    THEN v_new ELSE voice_minutes_remaining END,
         updated_at = now()
   WHERE id = v_id;

  RETURN true;
END $$;


ALTER FUNCTION "public"."deduct_comm_credits"("p_org_id" integer, "p_channel" "text", "p_amount" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."deduct_comm_credits"("p_org_id" integer, "p_channel" "text", "p_amount" integer) IS 'Debita (p_amount>0) o reembolsa (p_amount<0) saldo de comunicaciones de forma atómica (FOR UPDATE). Fail-closed: sin fila activa en comm_settings o canal desconocido -> false. NULL en la columna = ilimitado explícito. El reembolso nunca supera plans.comm_<canal>_monthly cuando la org tiene plan.';



