CREATE OR REPLACE FUNCTION "public"."delete_organization_tax"("p_tax_id" "text", "p_organization_id" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_user_id UUID;
    v_user_has_access BOOLEAN;
    v_tax_exists BOOLEAN;
    v_is_default BOOLEAN;
    v_tax_id_uuid UUID;
    v_usage_count INTEGER;
BEGIN
    -- Convertir el ID del impuesto a UUID
    BEGIN
        v_tax_id_uuid := p_tax_id::UUID;
    EXCEPTION WHEN others THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'message', 'ID de impuesto inválido',
            'code', 'INVALID_ID'
        );
    END;

    -- Obtener el ID del usuario autenticado
    v_user_id := (auth.uid())::UUID;
    
    -- Verificar si el usuario tiene acceso a la organización
    SELECT EXISTS (
        SELECT 1 
        FROM public.organization_members 
        WHERE 
            user_id = v_user_id AND 
            organization_id = p_organization_id AND 
            is_active = TRUE
    ) INTO v_user_has_access;
    
    -- Si el usuario no tiene acceso, abortar
    IF NOT v_user_has_access THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'message', 'No tiene permisos para eliminar impuestos en esta organización',
            'code', 'PERMISSION_DENIED'
        );
    END IF;
    
    -- Verificar que el impuesto exista y pertenezca a la organización
    SELECT 
        EXISTS (
            SELECT 1 
            FROM public.organization_taxes 
            WHERE id = v_tax_id_uuid AND organization_id = p_organization_id
        ),
        is_default 
    INTO 
        v_tax_exists, 
        v_is_default
    FROM public.organization_taxes 
    WHERE id = v_tax_id_uuid;
    
    -- Si el impuesto no existe o no pertenece a esta organización
    IF NOT v_tax_exists THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'message', 'El impuesto no existe o no pertenece a esta organización',
            'code', 'TAX_NOT_FOUND'
        );
    END IF;
    
    -- Verificar si el impuesto es predeterminado
    IF v_is_default THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'message', 'No se puede eliminar el impuesto predeterminado. Primero establezca otro impuesto como predeterminado.',
            'code', 'DEFAULT_TAX_DELETION'
        );
    END IF;
    
    -- Verificar si el impuesto está siendo utilizado por algún producto
    SELECT COUNT(*) INTO v_usage_count
    FROM public.product_tax_relations
    WHERE tax_id = v_tax_id_uuid;
    
    IF v_usage_count > 0 THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'message', 'No se puede eliminar el impuesto porque está siendo utilizado por ' || v_usage_count || ' producto(s).',
            'code', 'TAX_IN_USE'
        );
    END IF;
    
    -- Eliminar el impuesto
    DELETE FROM public.organization_taxes
    WHERE id = v_tax_id_uuid AND organization_id = p_organization_id;
    
    -- Construir el resultado
    RETURN jsonb_build_object(
        'success', TRUE,
        'message', 'Impuesto eliminado correctamente'
    );
END;
$$;


ALTER FUNCTION "public"."delete_organization_tax"("p_tax_id" "text", "p_organization_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."direct_update_opportunity"("p_opportunity_id" "uuid", "p_stage_id" "uuid", "p_status" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_result JSONB;
    v_opportunity JSONB;
    v_message TEXT;
BEGIN
    -- Capturar datos de la oportunidad antes de actualizar
    SELECT jsonb_build_object(
        'id', id,
        'stage_id', stage_id,
        'status', status,
        'organization_id', organization_id
    ) INTO v_opportunity
    FROM opportunities
    WHERE id = p_opportunity_id;

    IF v_opportunity IS NULL THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'message', 'Oportunidad no encontrada',
            'error_code', 'NOT_FOUND'
        );
    END IF;

    -- Realizar actualización directa sin verificar permisos
    BEGIN
        IF p_status IS NULL THEN
            UPDATE opportunities 
            SET stage_id = p_stage_id,
                updated_at = NOW() 
            WHERE id = p_opportunity_id;
        ELSE
            UPDATE opportunities 
            SET stage_id = p_stage_id,
                status = p_status,
                updated_at = NOW() 
            WHERE id = p_opportunity_id;
        END IF;

        GET DIAGNOSTICS v_message = ROW_COUNT;
        
        IF v_message = '0' THEN
            RETURN jsonb_build_object(
                'success', FALSE,
                'message', 'No se actualizó ninguna fila',
                'error_code', 'NO_UPDATE',
                'opportunity', v_opportunity
            );
        END IF;

        -- Retornar éxito con información
        RETURN jsonb_build_object(
            'success', TRUE,
            'message', 'Oportunidad actualizada correctamente',
            'rows_updated', v_message,
            'previous_data', v_opportunity
        );
    EXCEPTION WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'message', SQLERRM,
            'error_code', SQLSTATE,
            'opportunity', v_opportunity
        );
    END;
END;
$$;


ALTER FUNCTION "public"."direct_update_opportunity"("p_opportunity_id" "uuid", "p_stage_id" "uuid", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."direct_update_opportunity_bypass"("p_opportunity_id" "uuid", "p_stage_id" "uuid", "p_status" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_user_id UUID;
    v_organization_id INT;
    v_belongs_to_org BOOLEAN;
    v_result BOOLEAN := FALSE;
BEGIN
    -- Obtener el ID del usuario actual
    v_user_id := auth.uid();
    
    IF v_user_id IS NULL THEN
        RETURN FALSE;
    END IF;
    
    -- Obtener el organization_id de la oportunidad
    SELECT organization_id INTO v_organization_id
    FROM opportunities
    WHERE id = p_opportunity_id;
    
    IF v_organization_id IS NULL THEN
        RETURN FALSE;
    END IF;
    
    -- Verificar pertenencia a la organización
    SELECT EXISTS(
        SELECT 1 FROM organization_members
        WHERE user_id = v_user_id
        AND organization_id = v_organization_id
    ) INTO v_belongs_to_org;
    
    IF NOT v_belongs_to_org THEN
        RETURN FALSE;
    END IF;
    
    -- Actualizar directamente usando UPDATE con ejecución bajo SECURITY DEFINER
    BEGIN
        -- Actualización usando operador raw SQL para evitar middleware de Supabase
        IF p_status IS NULL THEN
            UPDATE opportunities 
            SET stage_id = p_stage_id, 
                updated_at = NOW() 
            WHERE id = p_opportunity_id;
        ELSE
            UPDATE opportunities 
            SET stage_id = p_stage_id, 
                status = p_status, 
                updated_at = NOW() 
            WHERE id = p_opportunity_id;
        END IF;
        
        GET DIAGNOSTICS v_result = ROW_COUNT;
        RETURN v_result > 0;
    EXCEPTION WHEN OTHERS THEN
        RAISE NOTICE 'Error en actualización directa: %', SQLERRM;
        RETURN FALSE;
    END;
END;
$$;


ALTER FUNCTION "public"."direct_update_opportunity_bypass"("p_opportunity_id" "uuid", "p_stage_id" "uuid", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."direct_update_opportunity_stage"("p_opportunity_id" "uuid", "p_stage_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_user_id UUID;
  v_organization_id INT;
  v_belongs_to_org BOOLEAN;
BEGIN
  -- Obtener el ID del usuario actual
  v_user_id := auth.uid();
  
  IF v_user_id IS NULL THEN
    RETURN FALSE;
  END IF;
  
  -- Obtener el ID de la organización de la oportunidad
  SELECT organization_id INTO v_organization_id
  FROM opportunities
  WHERE id = p_opportunity_id;
  
  IF v_organization_id IS NULL THEN
    RETURN FALSE;
  END IF;
  
  -- Verificar si el usuario pertenece a la organización
  SELECT EXISTS(
    SELECT 1 FROM organization_members
    WHERE user_id = v_user_id
    AND organization_id = v_organization_id
  ) INTO v_belongs_to_org;
  
  -- Si el usuario no pertenece a la organización, devolver falso
  IF NOT v_belongs_to_org THEN
    RETURN FALSE;
  END IF;
  
  -- Actualizar directamente con SQL puro para evitar triggers y problemas con vistas
  EXECUTE '
    UPDATE opportunities 
    SET stage_id = $1, updated_at = NOW() 
    WHERE id = $2
  ' USING p_stage_id, p_opportunity_id;
  
  RETURN TRUE;
END;
$_$;


ALTER FUNCTION "public"."direct_update_opportunity_stage"("p_opportunity_id" "uuid", "p_stage_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_organization_has_currency"("org_id" integer) RETURNS "json"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
    currency_exists BOOLEAN;
    template_record RECORD;
    result JSON;
BEGIN
    -- Verificar si la organización ya tiene monedas
    SELECT EXISTS (
        SELECT 1 FROM organization_currencies 
        WHERE organization_id = org_id
    ) INTO currency_exists;
    
    -- Si no tiene monedas, crear la moneda COP en organization_currencies
    IF NOT currency_exists THEN
        -- Verificar si existe la moneda COP en el catálogo global
        SELECT EXISTS (
            SELECT 1 FROM currencies 
            WHERE code = 'COP'
        ) INTO currency_exists;
        
        -- Si no existe la moneda en el catálogo, la creamos
        IF NOT currency_exists THEN
            INSERT INTO currencies (
                code, 
                name, 
                symbol, 
                decimals,
                auto_update,
                created_at, 
                updated_at
            ) VALUES (
                'COP',
                'Peso colombiano',
                '$',
                0,
                true,
                NOW(),
                NOW()
            );
        END IF;
        
        -- Obtener datos de la moneda COP
        SELECT * FROM currencies 
        WHERE code = 'COP' 
        INTO STRICT template_record;
        
        -- Insertar en organization_currencies
        INSERT INTO organization_currencies (
            organization_id,
            currency_code,
            is_base,
            auto_update,
            created_at,
            updated_at
        ) VALUES (
            org_id,
            'COP',
            true, -- Establecer como moneda base por defecto
            true, -- Configurar para actualización automática
            NOW(),
            NOW()
        );
        
        result := json_build_object(
            'success', true,
            'message', 'Moneda COP creada automáticamente como moneda base',
            'currency_code', 'COP'
        );
    ELSE
        result := json_build_object(
            'success', true,
            'message', 'La organización ya tiene monedas configuradas'
        );
    END IF;
    
    RETURN result;
END;
$_$;


ALTER FUNCTION "public"."ensure_organization_has_currency"("org_id" integer) OWNER TO "postgres";


