CREATE OR REPLACE FUNCTION "public"."execute_alert_condition"("condition_sql" "text", "organization_id" integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "statement_timeout" TO '10s'
    AS $$
DECLARE
  result_count INTEGER := 0;
  safe_sql TEXT;
BEGIN
  -- Validaciones de seguridad
  IF condition_sql IS NULL OR TRIM(condition_sql) = '' THEN
    RAISE EXCEPTION 'Condición SQL no puede estar vacía';
  END IF;
  
  -- Verificar que la consulta sea un SELECT seguro
  safe_sql := UPPER(TRIM(condition_sql));
  
  -- No permitir operaciones peligrosas
  IF safe_sql ~ '(DROP|DELETE|UPDATE|INSERT|ALTER|CREATE|TRUNCATE|GRANT|REVOKE)' THEN
    RAISE EXCEPTION 'Solo se permiten consultas SELECT';
  END IF;
  
  -- Debe contener COUNT(*)
  IF safe_sql !~ 'COUNT\s*\(\s*\*\s*\)' THEN
    RAISE EXCEPTION 'La consulta debe usar COUNT(*)';
  END IF;
  
  -- Preparar la consulta con filtro de organización si se proporciona
  IF organization_id IS NOT NULL THEN
    -- Verificar si ya tiene WHERE clause
    IF safe_sql ~ 'WHERE' THEN
      safe_sql := condition_sql || ' AND organization_id = ' || organization_id;
    ELSE
      safe_sql := condition_sql || ' WHERE organization_id = ' || organization_id;
    END IF;
  ELSE
    safe_sql := condition_sql;
  END IF;
  
  -- Ejecutar la consulta de forma segura
  BEGIN
    EXECUTE safe_sql INTO result_count;
  EXCEPTION
    WHEN OTHERS THEN
      RAISE EXCEPTION 'Error ejecutando condición SQL: %', SQLERRM;
  END;
  
  -- Asegurar que el resultado sea un número válido
  IF result_count IS NULL THEN
    result_count := 0;
  END IF;
  
  RETURN result_count;
END;
$$;


ALTER FUNCTION "public"."execute_alert_condition"("condition_sql" "text", "organization_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."execute_sql"("sql_query" "text") RETURNS "json"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    result json;
BEGIN
    -- Validar que la consulta sea segura (solo SELECT)
    IF NOT (sql_query ILIKE 'SELECT%' OR sql_query ILIKE 'WITH%') THEN
        RAISE EXCEPTION 'Solo se permiten consultas SELECT';
    END IF;
    
    -- Ejecutar la consulta y retornar como JSON
    EXECUTE 'SELECT json_agg(row_to_json(t)) FROM (' || sql_query || ') t' INTO result;
    
    -- Si no hay resultados, retornar array vacío
    IF result IS NULL THEN
        result := '[]'::json;
    END IF;
    
    RETURN result;
END;
$$;


ALTER FUNCTION "public"."execute_sql"("sql_query" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."expire_old_notifications"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_org_id              integer;
  v_unread_ttl_days     integer := 30;
  v_delete_ttl_days     integer := 90;
  v_marked_read_total   integer := 0;
  v_deleted_total       integer := 0;
  v_processed_orgs      integer := 0;
  v_settings            jsonb;
  v_marked_read         integer;
  v_deleted             integer;
BEGIN
  -- Prevenir ejecuciones concurrentes (el lock se libera al terminar la transacción)
  PERFORM pg_advisory_xact_lock(hashtext('expire_old_notifications'));

  -- Recorrer cada organización que tiene notificaciones
  FOR v_org_id IN
    SELECT DISTINCT organization_id
      FROM notifications
     WHERE organization_id IS NOT NULL
  LOOP
    -- Leer configuración TTL de organization_settings (key='notifications')
    SELECT settings INTO v_settings
      FROM organization_settings
     WHERE organization_id = v_org_id
       AND key = 'notifications'
     LIMIT 1;

    -- Si no hay fila o faltan campos, usar defaults (30 / 90).
    -- GREATEST(..., 1) asegura mínimo 1 día: previene que TTL=0 o negativo
    -- limpie todas las notificaciones inmediatamente.
    v_unread_ttl_days := GREATEST(
      COALESCE(
        NULLIF((v_settings->>'unread_ttl_days')::integer, NULL),
        30
      ),
      1
    );
    v_delete_ttl_days := GREATEST(
      COALESCE(
        NULLIF((v_settings->>'delete_ttl_days')::integer, NULL),
        90
      ),
      1
    );

    -- Etapa 1: marcar como leídas las no leídas con > unread_ttl_days
    UPDATE notifications
       SET read_at = now(),
           updated_at = now()
     WHERE read_at IS NULL
       AND status != 'deleted'
       AND organization_id = v_org_id
       AND created_at < now() - (v_unread_ttl_days || ' days')::interval;

    GET DIAGNOSTICS v_marked_read = ROW_COUNT;
    v_marked_read_total := v_marked_read_total + v_marked_read;

    -- Etapa 2: eliminar (status='deleted') las notificaciones con > delete_ttl_days.
    -- NOTA: delete_ttl aplica a TODAS las notificaciones viejas (leídas y no leídas)
    -- por diseño ("limpieza total"). NO se filtra read_at IS NULL aquí.
    UPDATE notifications
       SET status = 'deleted',
           updated_at = now()
     WHERE status != 'deleted'
       AND organization_id = v_org_id
       AND created_at < now() - (v_delete_ttl_days || ' days')::interval;

    GET DIAGNOSTICS v_deleted = ROW_COUNT;
    v_deleted_total := v_deleted_total + v_deleted;

    v_processed_orgs := v_processed_orgs + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'marked_read',    v_marked_read_total,
    'deleted',        v_deleted_total,
    'processed_orgs', v_processed_orgs
  );
END;
$$;


ALTER FUNCTION "public"."expire_old_notifications"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."expire_pending_web_orders"("p_expiration_minutes" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_order record;
  v_expired integer := 0;
BEGIN
  FOR v_order IN
    SELECT
      w.id,
      w.organization_id,
      w.branch_id,
      w.order_number,
      w.payment_method,
      COALESCE(
        NULLIF(
          (os.settings->>'order_expiration_minutes')::integer,
          0
        ),
        CASE
          WHEN w.payment_method IN ('transfer','cash','bancolombia_transfer','bancolombia_collect','pse')
            THEN 1440
          ELSE p_expiration_minutes
        END
      ) AS effective_minutes
    FROM web_orders w
    LEFT JOIN LATERAL (
      SELECT settings
      FROM organization_settings
      WHERE organization_id = w.organization_id
        AND key = 'web_commerce'
      LIMIT 1
    ) os ON true
    WHERE w.status = 'pending'
      AND w.payment_status = 'pending'
      AND w.stock_released_at IS NULL
      AND w.created_at < now() - (
        COALESCE(
          NULLIF(
            (os.settings->>'order_expiration_minutes')::integer,
            0
          ),
          CASE
            WHEN w.payment_method IN ('transfer','cash','bancolombia_transfer','bancolombia_collect','pse')
              THEN 1440
            ELSE p_expiration_minutes
          END
        ) || ' minutes'
      )::interval
    ORDER BY w.created_at ASC
    FOR UPDATE OF w SKIP LOCKED
  LOOP
    PERFORM release_stock_for_order(v_order.id);

    UPDATE web_orders
       SET status = 'expired',
           payment_status = 'failed',
           cancelled_at = now(),
           cancellation_reason = 'Expirado por falta de pago'
     WHERE id = v_order.id;

    v_expired := v_expired + 1;
  END LOOP;

  RETURN jsonb_build_object('ok', true, 'expired_count', v_expired);
END;
$$;


ALTER FUNCTION "public"."expire_pending_web_orders"("p_expiration_minutes" integer) OWNER TO "postgres";


