CREATE OR REPLACE FUNCTION "public"."fn_add_module_accounts"("org_id" integer, "country_code" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF country_code = 'COL' THEN
    INSERT INTO public.chart_of_accounts (organization_id, account_code, name, type, parent_code, is_active, description)
    SELECT org_id, code, name, type, NULL, true, 'Cuenta de modulo (parking/folio/payroll/comisiones)'
    FROM (VALUES
      ('2370','Obligaciones Laborales y Seguridad Social por Pagar','liability'),
      ('4110','Ingresos por Alimentos y Bebidas','income'),
      ('4115','Ingresos por Servicios','income'),
      ('4235','Ingresos por Parqueadero','income'),
      ('4250','Otros Ingresos Operacionales','income'),
      ('5150','Gastos de Mantenimiento y Reparaciones','expense'),
      ('5195','Aportes Seguridad Social Patronal','expense')
    ) AS v(code, name, type)
    WHERE NOT EXISTS (SELECT 1 FROM public.chart_of_accounts c WHERE c.organization_id = org_id AND c.account_code = v.code);
  ELSE
    -- GEN / generico (usado cuando country_code es NULL)
    INSERT INTO public.chart_of_accounts (organization_id, account_code, name, type, parent_code, is_active, description)
    SELECT org_id, code, name, type, NULL, true, 'Cuenta de modulo (parking/folio/payroll/comisiones)'
    FROM (VALUES
      ('2104','Employer Social Security Payable','liability'),
      ('5193','Employer Social Security Expense','expense')
    ) AS v(code, name, type)
    WHERE NOT EXISTS (SELECT 1 FROM public.chart_of_accounts c WHERE c.organization_id = org_id AND c.account_code = v.code);
  END IF;
END;
$$;


ALTER FUNCTION "public"."fn_add_module_accounts"("org_id" integer, "country_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_add_sale_to_folio"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_folio_id UUID;
  v_folio_balance NUMERIC;
BEGIN
  -- Solo procesar si la venta tiene reservation_id
  IF NEW.reservation_id IS NOT NULL THEN
    
    -- Buscar el folio abierto de esta reserva
    SELECT id, balance INTO v_folio_id, v_folio_balance
    FROM folios
    WHERE reservation_id = NEW.reservation_id
      AND status = 'open'
    LIMIT 1;
    
    -- Si existe un folio abierto, agregar el cargo
    IF v_folio_id IS NOT NULL THEN
      
      -- Insertar item en el folio
      INSERT INTO folio_items (
        folio_id,
        source,
        description,
        amount,
        tax_code,
        created_by
      ) VALUES (
        v_folio_id,
        'pos',
        'Consumo POS - Venta #' || NEW.id,
        NEW.total,
        NULL,
        NEW.user_id
      );
      
      -- Actualizar balance del folio
      UPDATE folios
      SET 
        balance = balance + NEW.total,
        updated_at = NOW()
      WHERE id = v_folio_id;
      
      -- Log para debugging
      RAISE NOTICE 'Cargo POS agregado al folio %. Monto: %', v_folio_id, NEW.total;
      
    END IF;
    
  END IF;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_add_sale_to_folio"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_add_sale_to_folio"() IS 'Función trigger que automáticamente agrega cargos de ventas POS al folio de la reserva.
Se ejecuta cuando se inserta una venta con reservation_id no nulo.';



CREATE OR REPLACE FUNCTION "public"."fn_agent_ensure_operational_goal"("p_org_id" integer) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_goal_id uuid;
BEGIN
  -- Buscar meta operativa existente del agente
  SELECT id INTO v_goal_id
  FROM goals
  WHERE organization_id = p_org_id
    AND type = 'goal'
    AND status IN ('draft','active')
    AND title = 'Operación Diaria – Agente'
  ORDER BY created_at
  LIMIT 1;

  IF v_goal_id IS NULL THEN
    INSERT INTO goals (organization_id, title, description, type, status, priority, start_date)
    VALUES (
      p_org_id,
      'Operación Diaria – Agente',
      'Meta operativa automática generada por el agente PM para agrupar las tareas recurrentes de operación.',
      'goal',
      'active',
      'high',
      date_trunc('month', now())
    )
    RETURNING id INTO v_goal_id;
  END IF;

  RETURN v_goal_id;
END;
$$;


ALTER FUNCTION "public"."fn_agent_ensure_operational_goal"("p_org_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_agent_pick_assignee"("p_org_id" integer, "p_dept_kw" "text"[], "p_pos_kw" "text"[], "p_role_ids" integer[]) RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user uuid;
BEGIN
  -- 1. Por CARGO vía empleo activo
  IF p_pos_kw IS NOT NULL THEN
    SELECT om.user_id INTO v_user
    FROM employments e
    JOIN organization_members om ON om.id = e.organization_member_id
    JOIN job_positions jp ON jp.id = e.position_id
    WHERE om.organization_id = p_org_id
      AND om.is_active = true
      AND e.status = 'active'
      AND EXISTS (SELECT 1 FROM unnest(p_pos_kw) kw WHERE jp.name ILIKE '%' || kw || '%')
    ORDER BY e.hire_date NULLS LAST, om.id
    LIMIT 1;
    IF v_user IS NOT NULL THEN RETURN v_user; END IF;

    -- 1b. Por CARGO directo en organization_members.job_position_id
    SELECT om.user_id INTO v_user
    FROM organization_members om
    JOIN job_positions jp ON jp.id = om.job_position_id
    WHERE om.organization_id = p_org_id
      AND om.is_active = true
      AND EXISTS (SELECT 1 FROM unnest(p_pos_kw) kw WHERE jp.name ILIKE '%' || kw || '%')
    ORDER BY om.id
    LIMIT 1;
    IF v_user IS NOT NULL THEN RETURN v_user; END IF;
  END IF;

  -- 2. Por DEPARTAMENTO vía empleo activo
  IF p_dept_kw IS NOT NULL THEN
    SELECT om.user_id INTO v_user
    FROM employments e
    JOIN organization_members om ON om.id = e.organization_member_id
    JOIN departments d ON d.id = e.department_id
    WHERE om.organization_id = p_org_id
      AND om.is_active = true
      AND e.status = 'active'
      AND d.is_active = true
      AND EXISTS (SELECT 1 FROM unnest(p_dept_kw) kw WHERE d.name ILIKE '%' || kw || '%')
    ORDER BY e.hire_date NULLS LAST, om.id
    LIMIT 1;
    IF v_user IS NOT NULL THEN RETURN v_user; END IF;
  END IF;

  -- 3. Fallback por ROL
  RETURN fn_agent_pick_member(p_org_id, p_role_ids);
END;
$$;


ALTER FUNCTION "public"."fn_agent_pick_assignee"("p_org_id" integer, "p_dept_kw" "text"[], "p_pos_kw" "text"[], "p_role_ids" integer[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_agent_pick_member"("p_org_id" integer, "p_role_ids" integer[]) RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT om.user_id
  FROM organization_members om
  WHERE om.organization_id = p_org_id
    AND om.is_active = true
    AND om.role_id = ANY(p_role_ids)
  ORDER BY array_position(p_role_ids, om.role_id), om.id
  LIMIT 1;
$$;


ALTER FUNCTION "public"."fn_agent_pick_member"("p_org_id" integer, "p_role_ids" integer[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_agent_upsert_task"("p_org_id" integer, "p_detector" "text", "p_title" "text", "p_description" "text", "p_role_ids" integer[], "p_priority" "text" DEFAULT 'high'::"text", "p_dept_kw" "text"[] DEFAULT NULL::"text"[], "p_pos_kw" "text"[] DEFAULT NULL::"text"[], "p_estimated_hours" numeric DEFAULT NULL::numeric) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_task_id uuid;
  v_assignee uuid;
  v_project_id uuid;
  v_goal_id uuid;
  v_due timestamptz := date_trunc('day', now()) + interval '18 hours';
BEGIN
  v_assignee := fn_agent_pick_assignee(p_org_id, p_dept_kw, p_pos_kw, p_role_ids);
  v_goal_id := fn_agent_ensure_operational_goal(p_org_id);

  SELECT id INTO v_task_id
  FROM tasks
  WHERE organization_id = p_org_id
    AND related_to_type = p_detector
    AND status IN ('open','in_progress')
  ORDER BY created_at DESC
  LIMIT 1;

  IF v_task_id IS NOT NULL THEN
    UPDATE tasks
    SET due_date = v_due,
        title = p_title,
        description = p_description,
        priority = p_priority,
        assigned_to = COALESCE(assigned_to, v_assignee),
        estimated_hours = COALESCE(estimated_hours, p_estimated_hours),
        goal_id = COALESCE(goal_id, v_goal_id),
        updated_at = now()
    WHERE id = v_task_id;
    PERFORM fn_create_org_notification(
      p_org_id, v_assignee, 'app', 'task_agent',
      'Tarea reprogramada: ' || p_title,
      'Sigue pendiente y su plazo se movió para hoy. ' || p_description,
      jsonb_build_object('task_id', v_task_id, 'detector', p_detector, 'source', 'agent')
    );
  ELSE
    SELECT id INTO v_project_id
    FROM projects
    WHERE organization_id = p_org_id AND status = 'active'
    ORDER BY created_at
    LIMIT 1;

    INSERT INTO tasks (
      organization_id, project_id, goal_id, title, description,
      type, status, priority, due_date, assigned_to,
      related_to_type, estimated_hours, tags
    )
    VALUES (
      p_org_id, v_project_id, v_goal_id, p_title, p_description,
      'operational', 'open', p_priority, v_due, v_assignee,
      p_detector, p_estimated_hours, ARRAY['agente','operacion']
    )
    RETURNING id INTO v_task_id;
    PERFORM fn_create_org_notification(
      p_org_id, v_assignee, 'app', 'task_agent',
      'Nueva tarea: ' || p_title,
      p_description,
      jsonb_build_object('task_id', v_task_id, 'detector', p_detector, 'source', 'agent')
    );
  END IF;
END;
$$;


ALTER FUNCTION "public"."fn_agent_upsert_task"("p_org_id" integer, "p_detector" "text", "p_title" "text", "p_description" "text", "p_role_ids" integer[], "p_priority" "text", "p_dept_kw" "text"[], "p_pos_kw" "text"[], "p_estimated_hours" numeric) OWNER TO "postgres";


