CREATE OR REPLACE FUNCTION "public"."fn_apply_conversation_tag"("p_conversation_id" "uuid", "p_tag_name" "text", "p_tag_color" "text" DEFAULT '#3b82f6'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_org_id int;
  v_tag_id uuid;
  v_relation_id uuid;
  v_member_id bigint;
BEGIN
  -- Obtener organization_id
  SELECT organization_id INTO v_org_id FROM conversations WHERE id = p_conversation_id;
  
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Conversación no encontrada: %', p_conversation_id;
  END IF;
  
  -- Obtener o crear la etiqueta
  INSERT INTO conversation_tags (organization_id, name, color, created_at)
  VALUES (v_org_id, p_tag_name, p_tag_color, NOW())
  ON CONFLICT (organization_id, name) DO UPDATE SET name = EXCLUDED.name
  RETURNING id INTO v_tag_id;
  
  -- Obtener member_id del usuario actual (si existe)
  SELECT id INTO v_member_id FROM organization_members 
  WHERE user_id = auth.uid() AND organization_id = v_org_id AND is_active = true 
  LIMIT 1;
  
  -- Crear la relación (si no existe)
  INSERT INTO conversation_tag_relations (
    organization_id,
    conversation_id,
    tag_id,
    created_by,
    created_at
  ) VALUES (
    v_org_id,
    p_conversation_id,
    v_tag_id,
    v_member_id,
    NOW()
  )
  ON CONFLICT (conversation_id, tag_id) DO NOTHING
  RETURNING id INTO v_relation_id;
  
  RETURN COALESCE(v_relation_id, v_tag_id);
END;
$$;


ALTER FUNCTION "public"."fn_apply_conversation_tag"("p_conversation_id" "uuid", "p_tag_name" "text", "p_tag_color" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_apply_conversation_tag"("p_conversation_id" "uuid", "p_tag_name" "text", "p_tag_color" "text") IS 'Aplica una etiqueta a una conversación, creando la etiqueta si no existe';



CREATE OR REPLACE FUNCTION "public"."fn_apply_customer_credit"("p_credit_id" "uuid", "p_invoice_id" "uuid", "p_amount" numeric, "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_credit public.credit_notes%ROWTYPE;
  v_inv public.invoice_sales%ROWTYPE;
  v_app_id uuid;
  v_entry integer;
  v_new_inv_balance numeric;
  v_new_status text;
  v_ar_id uuid;
  v_ar_balance numeric;
BEGIN
  SELECT * INTO v_credit FROM public.credit_notes WHERE id = p_credit_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Saldo a favor no encontrado'; END IF;
  IF v_credit.status <> 'active' OR v_credit.balance <= 0 THEN
    RAISE EXCEPTION 'El saldo a favor no está disponible';
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 THEN RAISE EXCEPTION 'El monto debe ser mayor a 0'; END IF;
  IF p_amount > v_credit.balance THEN RAISE EXCEPTION 'El monto excede el saldo disponible'; END IF;

  SELECT * INTO v_inv FROM public.invoice_sales WHERE id = p_invoice_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Factura no encontrada'; END IF;
  IF v_inv.organization_id <> v_credit.organization_id THEN
    RAISE EXCEPTION 'La factura pertenece a otra organización';
  END IF;
  IF p_amount > v_inv.balance THEN RAISE EXCEPTION 'El monto excede el saldo de la factura'; END IF;

  INSERT INTO public.credit_note_applications(organization_id, credit_note_id, invoice_id, amount, created_by)
  VALUES (v_credit.organization_id, p_credit_id, p_invoice_id, p_amount, p_created_by)
  RETURNING id INTO v_app_id;

  UPDATE public.credit_notes
  SET balance = balance - p_amount,
      status = CASE WHEN balance - p_amount <= 0 THEN 'used' ELSE 'active' END,
      updated_at = now()
  WHERE id = p_credit_id;

  v_new_inv_balance := GREATEST(0, v_inv.balance - p_amount);
  v_new_status := CASE
    WHEN v_new_inv_balance <= 0 THEN 'paid'
    WHEN v_new_inv_balance < v_inv.total THEN 'partial'
    ELSE v_inv.status END;
  UPDATE public.invoice_sales
  SET balance = v_new_inv_balance, status = v_new_status, updated_at = now()
  WHERE id = p_invoice_id;

  SELECT id, balance INTO v_ar_id, v_ar_balance
  FROM public.accounts_receivable WHERE invoice_id = p_invoice_id LIMIT 1;
  IF v_ar_id IS NOT NULL THEN
    UPDATE public.accounts_receivable
    SET balance = GREATEST(0, v_ar_balance - p_amount),
        status = CASE WHEN GREATEST(0, v_ar_balance - p_amount) <= 0 THEN 'paid' ELSE status END,
        updated_at = now()
    WHERE id = v_ar_id;
  END IF;

  v_entry := fn_create_journal_entry(
    p_organization_id := v_credit.organization_id,
    p_branch_id := v_inv.branch_id,
    p_entry_date := now(),
    p_memo := 'Aplicación saldo a favor a ' || COALESCE(v_inv.number, v_inv.id::text),
    p_source := 'customer_credit',
    p_source_id := v_app_id::text,
    p_debit_account := '2805',
    p_credit_account := '1305',
    p_amount := p_amount,
    p_tax_account := NULL,
    p_tax_amount := 0
  );

  RETURN v_app_id;
END;
$$;


ALTER FUNCTION "public"."fn_apply_customer_credit"("p_credit_id" "uuid", "p_invoice_id" "uuid", "p_amount" numeric, "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_ar_installments_before_save"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    NEW.updated_at = now();
    
    -- Calcular días de atraso
    IF NEW.status IN ('pending', 'partial', 'overdue') AND NEW.due_date < CURRENT_DATE THEN
        NEW.days_overdue := (CURRENT_DATE - NEW.due_date)::INTEGER;
    ELSE
        NEW.days_overdue := 0;
    END IF;
    
    -- Actualizar status basado en pagos y fecha
    IF NEW.paid_amount >= NEW.amount THEN
        NEW.status := 'paid';
        NEW.balance := 0;
        NEW.paid_at := COALESCE(NEW.paid_at, now());
        NEW.days_overdue := 0;
    ELSIF NEW.paid_amount > 0 THEN
        NEW.status := CASE WHEN NEW.due_date < CURRENT_DATE THEN 'overdue' ELSE 'partial' END;
        NEW.balance := NEW.amount - NEW.paid_amount;
    ELSIF NEW.due_date < CURRENT_DATE AND NEW.status = 'pending' THEN
        NEW.status := 'overdue';
    END IF;
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_ar_installments_before_save"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auto_assign_customer_branch"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.branch_id IS NULL THEN
    SELECT id INTO NEW.branch_id FROM branches
    WHERE organization_id = NEW.organization_id AND is_main = true
    LIMIT 1;
    IF NEW.branch_id IS NULL THEN
      SELECT id INTO NEW.branch_id FROM branches
      WHERE organization_id = NEW.organization_id AND is_active = true
      ORDER BY id LIMIT 1;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


