CREATE OR REPLACE FUNCTION "public"."fn_auto_journal_ap"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_rule RECORD;
    v_entry_id integer;
    v_default_branch integer;
BEGIN
    IF COALESCE(NEW.amount, 0) <= 0 THEN
        RETURN NEW;
    END IF;

    SELECT MIN(id) INTO v_default_branch FROM branches WHERE organization_id = NEW.organization_id;

    SELECT * INTO v_rule
    FROM accounting_rules
    WHERE organization_id = NEW.organization_id
      AND source_type = 'purchase'
      AND event_type = 'created'
      AND is_active = true
    ORDER BY priority
    LIMIT 1;

    IF v_rule IS NULL THEN
        SELECT * INTO v_rule
        FROM accounting_rules
        WHERE organization_id = NEW.organization_id
          AND source_type = 'purchase'
          AND is_active = true
        ORDER BY priority
        LIMIT 1;
    END IF;

    IF v_rule IS NULL THEN
        RETURN NEW;
    END IF;

    v_entry_id := fn_create_journal_entry(
        p_organization_id := NEW.organization_id,
        p_branch_id := v_default_branch,
        p_entry_date := COALESCE(NEW.created_at, now()),
        p_memo := 'CxP - ' || COALESCE(NEW.id::text, ''),
        p_source := 'accounts_payable',
        p_source_id := NEW.id::text,
        p_debit_account := v_rule.debit_account_code,
        p_credit_account := v_rule.credit_account_code,
        p_amount := NEW.amount
    );

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_journal_ap"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auto_journal_ap_installment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_rule RECORD;
    v_entry_id integer;
    v_ap RECORD;
    v_org_id integer;
    v_default_branch integer;
BEGIN
    -- Solo cuotas pagadas
    IF NEW.status::text NOT IN ('paid', 'completed') THEN
        RETURN NEW;
    END IF;

    IF COALESCE(NEW.paid_amount, 0) <= 0 THEN
        RETURN NEW;
    END IF;

    -- Obtener organización desde accounts_payable
    SELECT * INTO v_ap FROM accounts_payable WHERE id = NEW.account_payable_id;
    IF v_ap IS NULL THEN
        RETURN NEW;
    END IF;

    v_org_id := v_ap.organization_id;
    SELECT MIN(id) INTO v_default_branch FROM branches WHERE organization_id = v_org_id;

    SELECT * INTO v_rule
    FROM accounting_rules
    WHERE organization_id = v_org_id
      AND source_type = 'installment'
      AND is_active = true
    ORDER BY priority LIMIT 1;

    IF v_rule IS NULL THEN
        RETURN NEW;
    END IF;

    v_entry_id := fn_create_journal_entry(
        p_organization_id := v_org_id,
        p_branch_id := v_default_branch,
        p_entry_date := COALESCE(NEW.paid_at, NEW.created_at, now()),
        p_memo := 'Cuota CxP ' || COALESCE(NEW.id::text, ''),
        p_source := 'ap_installments',
        p_source_id := NEW.id::text,
        p_debit_account := v_rule.debit_account_code,
        p_credit_account := v_rule.credit_account_code,
        p_amount := NEW.paid_amount
    );

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_journal_ap_installment"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auto_journal_ar"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_rule RECORD;
    v_entry_id integer;
    v_default_branch integer;
BEGIN
    IF COALESCE(NEW.amount, 0) <= 0 THEN
        RETURN NEW;
    END IF;

    SELECT MIN(id) INTO v_default_branch FROM branches WHERE organization_id = NEW.organization_id;

    SELECT * INTO v_rule
    FROM accounting_rules
    WHERE organization_id = NEW.organization_id
      AND source_type = 'sale'
      AND event_type = 'created'
      AND is_active = true
    ORDER BY priority
    LIMIT 1;

    IF v_rule IS NULL THEN
        SELECT * INTO v_rule
        FROM accounting_rules
        WHERE organization_id = NEW.organization_id
          AND source_type = 'sale'
          AND is_active = true
        ORDER BY priority
        LIMIT 1;
    END IF;

    IF v_rule IS NULL THEN
        RETURN NEW;
    END IF;

    v_entry_id := fn_create_journal_entry(
        p_organization_id := NEW.organization_id,
        p_branch_id := v_default_branch,
        p_entry_date := COALESCE(NEW.created_at, now()),
        p_memo := 'CxC - ' || COALESCE(NEW.id::text, ''),
        p_source := 'accounts_receivable',
        p_source_id := NEW.id::text,
        p_debit_account := v_rule.debit_account_code,
        p_credit_account := v_rule.credit_account_code,
        p_amount := NEW.amount
    );

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_journal_ar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auto_journal_bank"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_rule RECORD;
    v_entry_id integer;
    v_branch_id integer;
    v_default_branch integer;
BEGIN
    SELECT * INTO v_rule
    FROM accounting_rules
    WHERE organization_id = NEW.organization_id
      AND source_type = 'bank'
      AND event_type = 'adjusted'
      AND is_active = true
    ORDER BY priority
    LIMIT 1;

    IF v_rule IS NULL THEN
        SELECT * INTO v_rule
        FROM accounting_rules
        WHERE organization_id = NEW.organization_id
          AND source_type = 'bank'
          AND is_active = true
        ORDER BY priority
        LIMIT 1;
    END IF;

    IF v_rule IS NULL THEN
        RETURN NEW;
    END IF;

    SELECT branch_id INTO v_branch_id
    FROM bank_accounts
    WHERE id = NEW.bank_account_id;

    SELECT MIN(id) INTO v_default_branch FROM branches WHERE organization_id = NEW.organization_id;
    v_branch_id := COALESCE(v_branch_id, v_default_branch);

    IF NEW.amount > 0 THEN
        v_entry_id := fn_create_journal_entry(
            p_organization_id := NEW.organization_id,
            p_branch_id := v_branch_id,
            p_entry_date := COALESCE(NEW.trans_date, NEW.created_at, now()),
            p_memo := 'Trans. Bancaria - ' || COALESCE(NEW.description, NEW.transaction_type),
            p_source := 'bank_transactions',
            p_source_id := NEW.id::text,
            p_debit_account := v_rule.debit_account_code,
            p_credit_account := v_rule.credit_account_code,
            p_amount := ABS(NEW.amount)
        );
    ELSE
        v_entry_id := fn_create_journal_entry(
            p_organization_id := NEW.organization_id,
            p_branch_id := v_branch_id,
            p_entry_date := COALESCE(NEW.trans_date, NEW.created_at, now()),
            p_memo := 'Trans. Bancaria - ' || COALESCE(NEW.description, NEW.transaction_type),
            p_source := 'bank_transactions',
            p_source_id := NEW.id::text,
            p_debit_account := v_rule.credit_account_code,
            p_credit_account := v_rule.debit_account_code,
            p_amount := ABS(NEW.amount)
        );
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_journal_bank"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auto_journal_bank_transfer"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_rule RECORD;
    v_entry_id integer;
    v_from_account RECORD;
    v_to_account RECORD;
BEGIN
    -- Solo procesar transferencias completadas
    IF NEW.status IS NULL OR NEW.status NOT IN ('completed', 'confirmed') THEN
        RETURN NEW;
    END IF;

    -- Obtener cuentas bancarias
    SELECT account_number, branch_id INTO v_from_account
    FROM bank_accounts WHERE id = NEW.from_account_id;

    SELECT account_number, branch_id INTO v_to_account
    FROM bank_accounts WHERE id = NEW.to_account_id;

    -- Buscar regla de bank
    SELECT * INTO v_rule
    FROM accounting_rules
    WHERE organization_id = NEW.organization_id
      AND source_type = 'bank'
      AND is_active = true
    ORDER BY priority
    LIMIT 1;

    IF v_rule IS NULL THEN
        RETURN NEW;
    END IF;

    -- Crear asiento: débito cuenta destino, crédito cuenta origen
    v_entry_id := fn_create_journal_entry(
        p_organization_id := NEW.organization_id,
        p_branch_id := COALESCE(v_to_account.branch_id, 0),
        p_entry_date := COALESCE(NEW.transfer_date, NEW.created_at, now()),
        p_memo := 'Transferencia bancaria - ' || COALESCE(NEW.reference, NEW.id::text),
        p_source := 'bank_transfers',
        p_source_id := NEW.id::text,
        p_debit_account := v_rule.debit_account_code,
        p_credit_account := v_rule.debit_account_code,
        p_amount := ABS(NEW.amount)
    );

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_journal_bank_transfer"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auto_journal_cash_movement"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_rule RECORD;
    v_entry_id integer;
    v_session RECORD;
BEGIN
    SELECT cs.organization_id, cs.branch_id 
    INTO v_session
    FROM cash_sessions cs
    WHERE cs.id = NEW.cash_session_id;

    IF v_session IS NULL THEN
        RETURN NEW;
    END IF;

    SELECT * INTO v_rule
    FROM accounting_rules
    WHERE organization_id = v_session.organization_id
      AND source_type = 'cash_movement'
      AND event_type = 'created'
      AND is_active = true
    ORDER BY priority
    LIMIT 1;

    IF v_rule IS NULL THEN
        RETURN NEW;
    END IF;

    v_entry_id := fn_create_journal_entry(
        p_organization_id := v_session.organization_id,
        p_branch_id := v_session.branch_id,
        p_entry_date := NEW.created_at,
        p_memo := 'Mov. Caja: ' || NEW.type || ' - ' || COALESCE(NEW.concept, ''),
        p_source := 'cash_movements',
        p_source_id := NEW.id::text,
        p_debit_account := CASE WHEN NEW.amount > 0 THEN v_rule.debit_account_code ELSE v_rule.credit_account_code END,
        p_credit_account := CASE WHEN NEW.amount > 0 THEN v_rule.credit_account_code ELSE v_rule.debit_account_code END,
        p_amount := ABS(NEW.amount)
    );

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_journal_cash_movement"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_auto_journal_cash_movement"() IS 'Trigger para asiento automático de movimientos de caja';



CREATE OR REPLACE FUNCTION "public"."fn_auto_journal_cash_session"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_rule RECORD;
    v_entry_id integer;
    v_diff numeric;
BEGIN
    -- Solo cuando se cierra la sesión
    IF NEW.status = 'closed' AND (OLD.status IS DISTINCT FROM 'closed') THEN
        v_diff := COALESCE(NEW.difference, COALESCE(NEW.final_amount, 0) - COALESCE(NEW.initial_amount, 0));

        IF v_diff = 0 THEN
            RETURN NEW;
        END IF;

        SELECT * INTO v_rule
        FROM accounting_rules
        WHERE organization_id = NEW.organization_id
          AND source_type = 'cash_movement'
          AND is_active = true
        ORDER BY priority
        LIMIT 1;

        IF v_rule IS NULL THEN
            RETURN NEW;
        END IF;

        v_entry_id := fn_create_journal_entry(
            p_organization_id := NEW.organization_id,
            p_branch_id := COALESCE(NEW.branch_id, 0),
            p_entry_date := COALESCE(NEW.closed_at, now()),
            p_memo := 'Cierre de Caja - Sesión ' || NEW.id::text,
            p_source := 'cash_sessions',
            p_source_id := NEW.id::text,
            p_debit_account := CASE WHEN v_diff > 0 THEN v_rule.debit_account_code ELSE v_rule.credit_account_code END,
            p_credit_account := CASE WHEN v_diff > 0 THEN v_rule.credit_account_code ELSE v_rule.debit_account_code END,
            p_amount := ABS(v_diff)
        );
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_journal_cash_session"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auto_journal_commission"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_rule RECORD;
    v_entry_id integer;
    v_branch_id integer;
    v_event_type text;
    v_memo text;
    v_source_id text;
BEGIN
    IF NEW.status IS NULL THEN
        RETURN NEW;
    END IF;

    IF NEW.status = 'accrued' AND (OLD.status IS DISTINCT FROM NEW.status OR TG_OP = 'INSERT') THEN
        v_event_type := 'accrued';
    ELSIF NEW.status = 'paid' AND OLD.status IS DISTINCT FROM NEW.status THEN
        v_event_type := 'paid';
    ELSE
        RETURN NEW;
    END IF;

    IF COALESCE(NEW.commission_amount, 0) <= 0 THEN
        RETURN NEW;
    END IF;

    IF v_event_type = 'paid' AND NEW.metadata ? 'payroll_slip_id' THEN
        RETURN NEW;
    END IF;

    SELECT * INTO v_rule
    FROM accounting_rules
    WHERE organization_id = NEW.organization_id
      AND source_type = 'commission'
      AND event_type = v_event_type
      AND is_active = true
    ORDER BY priority LIMIT 1;

    IF v_rule IS NULL THEN
        RETURN NEW;
    END IF;

    IF NEW.branch_id IS NOT NULL THEN
        v_branch_id := NEW.branch_id;
    ELSE
        SELECT MIN(id) INTO v_branch_id FROM branches WHERE organization_id = NEW.organization_id;
    END IF;

    v_memo := CASE NEW.commission_type
        WHEN 'salesperson' THEN 'Comisión Vendedor - ' || COALESCE(NEW.payee_name, NEW.payee_id::text, 'N/A')
        WHEN 'intermediation_sale' THEN 'Comisión Intermediación Venta - ' || COALESCE(NEW.payee_name, NEW.source_id)
        WHEN 'intermediation_purchase' THEN 'Comisión Intermediación Compra - ' || COALESCE(NEW.payee_name, NEW.source_id)
        ELSE 'Comisión - ' || COALESCE(NEW.payee_name, 'N/A')
    END;

    v_source_id := NEW.id::text || ':' || v_event_type;

    v_entry_id := fn_create_journal_entry(
        p_organization_id := NEW.organization_id,
        p_branch_id := v_branch_id,
        p_entry_date := CASE v_event_type
            WHEN 'accrued' THEN COALESCE(NEW.accrued_at, NEW.created_at, now())
            WHEN 'paid' THEN COALESCE(NEW.paid_at, NEW.updated_at, now())
        END,
        p_memo := v_memo,
        p_source := 'commissions',
        p_source_id := v_source_id,
        p_debit_account := v_rule.debit_account_code,
        p_credit_account := v_rule.credit_account_code,
        p_amount := NEW.commission_amount
    );

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_journal_commission"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auto_journal_credit_note"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_rule RECORD;
    v_entry_id integer;
BEGIN
    -- Solo procesar notas de crédito
    IF NEW.document_type IS NULL OR NEW.document_type != 'credit_note' THEN
        RETURN NEW;
    END IF;

    -- Buscar regla
    SELECT * INTO v_rule
    FROM accounting_rules
    WHERE organization_id = NEW.organization_id
      AND source_type = 'sale_credit_note'
      AND event_type = 'created'
      AND is_active = true
    ORDER BY priority
    LIMIT 1;

    IF v_rule IS NULL THEN
        RETURN NEW;
    END IF;

    -- Crear asiento (inverso a la venta: débito = ventas/ingreso, crédito = cliente)
    -- Se usa ABS() porque las notas de crédito almacenan total/impuesto en negativo
    -- y fn_create_journal_entry descarta montos <= 0.
    v_entry_id := fn_create_journal_entry(
        p_organization_id := NEW.organization_id,
        p_branch_id := NEW.branch_id,
        p_entry_date := COALESCE(NEW.issue_date, now()),
        p_memo := 'Nota Crédito ' || COALESCE(NEW.number, NEW.id::text),
        p_source := 'invoice_sales',
        p_source_id := NEW.id::text,
        p_debit_account := v_rule.debit_account_code,
        p_credit_account := v_rule.credit_account_code,
        p_amount := ABS(COALESCE(NEW.total, 0)),
        p_tax_account := v_rule.tax_account_code,
        p_tax_amount := CASE WHEN v_rule.use_tax_from_document THEN ABS(COALESCE(NEW.tax_total, 0)) ELSE 0 END
    );

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_journal_credit_note"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auto_journal_employee_loan"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_rule RECORD;
    v_entry_id integer;
    v_branch_id integer;
    v_memo text;
    v_source_id text;
BEGIN
    -- Solo cuando el préstamo/anticipo se aprueba (pasa a 'active')
    IF NEW.status = 'active' AND (OLD.status IS DISTINCT FROM NEW.status OR TG_OP = 'INSERT') THEN
        SELECT * INTO v_rule
        FROM accounting_rules
        WHERE organization_id = NEW.organization_id
          AND source_type = 'loan'
          AND event_type = 'paid'
          AND is_active = true
        ORDER BY priority LIMIT 1;

        -- Fallback: cualquier regla de loan activa
        IF v_rule IS NULL THEN
            SELECT * INTO v_rule
            FROM accounting_rules
            WHERE organization_id = NEW.organization_id
              AND source_type = 'loan'
              AND is_active = true
            ORDER BY priority LIMIT 1;
        END IF;

        IF v_rule IS NULL THEN RETURN NEW; END IF;

        SELECT MIN(id) INTO v_branch_id FROM branches WHERE organization_id = NEW.organization_id;

        -- Distinguir memo según loan_type
        v_memo := CASE NEW.loan_type
            WHEN 'advance' THEN 'Anticipo Salario - ' || COALESCE(NEW.loan_number, NEW.id::text)
            WHEN 'emergency' THEN 'Préstamo Emergencia - ' || COALESCE(NEW.loan_number, NEW.id::text)
            ELSE 'Préstamo Empleado - ' || COALESCE(NEW.loan_number, NEW.id::text)
        END;

        -- source_id incluye loan_type para evitar colisiones
        v_source_id := NEW.id::text;

        v_entry_id := fn_create_journal_entry(
            p_organization_id := NEW.organization_id,
            p_branch_id := v_branch_id,
            p_entry_date := COALESCE(NEW.disbursement_date, NEW.approved_at, NEW.created_at, now()),
            p_memo := v_memo,
            p_source := 'employee_loans',
            p_source_id := v_source_id,
            p_debit_account := v_rule.debit_account_code,
            p_credit_account := v_rule.credit_account_code,
            p_amount := NEW.principal
        );
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_journal_employee_loan"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auto_journal_folio_close"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_reservation RECORD;
    v_folio_items RECORD;
    v_invoice_id uuid;
    v_existing_invoice uuid;
    v_subtotal numeric := 0;
    v_tax_total numeric := 0;
    v_total numeric := 0;
    v_sale_id uuid;
BEGIN
    -- Solo cuando el folio cambia a closed
    IF (NEW.status IS DISTINCT FROM OLD.status) AND NEW.status = 'closed' THEN
        -- Obtener reserva
        SELECT r.organization_id, r.branch_id, r.customer_id, r.id
        INTO v_reservation
        FROM reservations r
        WHERE r.id = NEW.reservation_id
        LIMIT 1;

        IF NOT FOUND THEN
            RETURN NEW;
        END IF;

        -- Verificar si ya existe factura para esta reserva
        -- sale_id es uuid, no text
        SELECT id INTO v_existing_invoice
        FROM invoice_sales
        WHERE sale_id IS NOT NULL
          AND organization_id = v_reservation.organization_id
          AND (
            -- Buscar por sale_id si existe una venta vinculada
            EXISTS (
              SELECT 1 FROM sales s 
              WHERE s.id = invoice_sales.sale_id 
                AND s.notes LIKE '%Checkout reserva ' || v_reservation.id::text || '%'
            )
            -- O por number que contiene el folio id
            OR number = 'FOLIO-' || NEW.id::text
          )
        LIMIT 1;

        IF v_existing_invoice IS NOT NULL THEN
            RETURN NEW;
        END IF;

        -- Sumar items del folio
        SELECT 
            COALESCE(SUM(amount), 0),
            COALESCE(SUM(CASE WHEN tax_code IS NOT NULL THEN amount * 0.19 ELSE 0 END), 0)
        INTO v_subtotal, v_tax_total
        FROM folio_items
        WHERE folio_id = NEW.id;

        v_total := v_subtotal + v_tax_total;

        IF v_total <= 0 THEN
            RETURN NEW;
        END IF;

        -- Crear factura de venta desde el folio
        -- Esto disparara el trigger trg_auto_journal_sale existente
        INSERT INTO invoice_sales (
            organization_id, branch_id, customer_id, sale_id,
            number, issue_date, subtotal, tax_total, total,
            status, document_type, tax_included, created_at
        ) VALUES (
            v_reservation.organization_id,
            v_reservation.branch_id,
            v_reservation.customer_id,
            NULL, -- sin sale_id directa (la venta se crea desde createSaleFromFolio)
            'FOLIO-' || NEW.id::text,
            now(),
            v_subtotal - v_tax_total,
            v_tax_total,
            v_total,
            'confirmed',
            'invoice',
            false,
            now()
        ) RETURNING id INTO v_invoice_id;

        RETURN NEW;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_journal_folio_close"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auto_journal_folio_item"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_rule RECORD;
    v_folio RECORD;
    v_reservation RECORD;
    v_amount numeric;
    v_description text;
    v_source text;
    v_priority smallint;
BEGIN
    v_amount := COALESCE(NEW.amount, 0);
    IF v_amount <= 0 THEN
        RETURN NEW;
    END IF;

    -- Obtener folio y reserva para organization_id y branch_id
    SELECT f.id, f.reservation_id INTO v_folio
    FROM folios f
    WHERE f.id = NEW.folio_id
    LIMIT 1;

    IF NOT FOUND THEN
        RETURN NEW;
    END IF;

    SELECT r.organization_id, r.branch_id INTO v_reservation
    FROM reservations r
    WHERE r.id = v_folio.reservation_id
    LIMIT 1;

    IF NOT FOUND THEN
        RETURN NEW;
    END IF;

    -- Determinar prioridad segun el source del folio_item
    v_source := NEW.source;
    v_priority := CASE
        WHEN v_source = 'room' OR v_source = 'hospedaje' THEN 10
        WHEN v_source = 'pos' OR v_source = 'food' OR v_source = 'minibar' THEN 11
        ELSE 12
    END;

    -- Buscar regla contable por prioridad
    SELECT * INTO v_rule
    FROM accounting_rules
    WHERE organization_id = v_reservation.organization_id
      AND source_type = 'folio_item'
      AND event_type = 'created'
      AND priority = v_priority
      AND is_active = true
    LIMIT 1;

    -- Fallback: cualquier regla de folio_item
    IF NOT FOUND THEN
        SELECT * INTO v_rule
        FROM accounting_rules
        WHERE organization_id = v_reservation.organization_id
          AND source_type = 'folio_item'
          AND event_type = 'created'
          AND is_active = true
        LIMIT 1;
    END IF;

    IF NOT FOUND THEN
        RETURN NEW;
    END IF;

    v_description := 'Cargo Folio - ' || COALESCE(NEW.description, v_source);

    -- CORREGIDO: orden correcto de parámetros
    PERFORM fn_create_journal_entry(
        p_organization_id := v_reservation.organization_id,
        p_branch_id := COALESCE(v_reservation.branch_id, 0),
        p_entry_date := COALESCE(NEW.created_at, now()),
        p_memo := v_description,
        p_source := 'folio_items',
        p_source_id := NEW.id::text,
        p_debit_account := v_rule.debit_account_code,
        p_credit_account := v_rule.credit_account_code,
        p_amount := v_amount
    );

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_journal_folio_item"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auto_journal_folio_payment"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_rule RECORD;
    v_folio RECORD;
    v_reservation RECORD;
    v_amount numeric;
    v_description text;
    v_source_id_uuid uuid;
BEGIN
    -- Solo pagos vinculados a folios
    IF NEW.source IS DISTINCT FROM 'folio' THEN
        RETURN NEW;
    END IF;

    v_amount := COALESCE(NEW.amount, 0);
    IF v_amount <= 0 THEN
        RETURN NEW;
    END IF;

    -- Convertir source_id (text) a uuid de forma segura
    BEGIN
        v_source_id_uuid := NEW.source_id::uuid;
    EXCEPTION WHEN OTHERS THEN
        RETURN NEW;
    END;

    -- Obtener folio y reserva
    SELECT f.id, f.reservation_id INTO v_folio
    FROM folios f
    WHERE f.id = v_source_id_uuid
    LIMIT 1;

    IF NOT FOUND THEN
        RETURN NEW;
    END IF;

    SELECT r.organization_id, r.branch_id INTO v_reservation
    FROM reservations r
    WHERE r.id = v_folio.reservation_id
    LIMIT 1;

    IF NOT FOUND THEN
        RETURN NEW;
    END IF;

    -- Buscar regla contable
    SELECT * INTO v_rule
    FROM accounting_rules
    WHERE organization_id = v_reservation.organization_id
      AND source_type = 'folio_payment'
      AND event_type = 'received'
      AND is_active = true
    LIMIT 1;

    IF NOT FOUND THEN
        RETURN NEW;
    END IF;

    v_description := 'Pago Folio ' || v_folio.id::text;

    -- Llamar con argumentos nombrados en el orden correcto
    PERFORM fn_create_journal_entry(
        p_organization_id := v_reservation.organization_id,
        p_branch_id := COALESCE(v_reservation.branch_id, 0),
        p_entry_date := NEW.created_at,
        p_memo := v_description,
        p_source := 'folio_payment',
        p_source_id := NEW.id::text,
        p_debit_account := v_rule.debit_account_code,
        p_credit_account := v_rule.credit_account_code,
        p_amount := v_amount,
        p_created_by := NEW.created_by
    );

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_journal_folio_payment"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auto_journal_inventory_adjustment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_rule RECORD;
    v_amount numeric;
    v_description text;
    v_event_type text;
    v_existing_entry integer;
    v_total_qty numeric;
    v_avg_cost numeric;
    v_debit_account text;
    v_credit_account text;
BEGIN
    IF NEW.status != 'posted' THEN
        RETURN NEW;
    END IF;

    IF TG_OP = 'UPDATE' AND NEW.status = OLD.status THEN
        RETURN NEW;
    END IF;

    IF NEW.type = 'gain' THEN
        v_event_type := 'gain';
    ELSIF NEW.type = 'loss' THEN
        v_event_type := 'loss';
    ELSE
        RETURN NEW;
    END IF;

    -- Calcular monto desde stock_movements asociados
    SELECT 
        COALESCE(SUM(ABS(sm.qty)), 0),
        COALESCE(AVG(sm.unit_cost), 0)
    INTO v_total_qty, v_avg_cost
    FROM stock_movements sm
    WHERE sm.source = 'adjustment'
      AND sm.source_id = NEW.id::text
      AND sm.organization_id = NEW.organization_id;

    IF v_avg_cost = 0 OR v_avg_cost IS NULL THEN
        SELECT sl.avg_cost INTO v_avg_cost
        FROM stock_levels sl
        WHERE sl.branch_id = NEW.branch_id
        ORDER BY sl.updated_at DESC
        LIMIT 1;
    END IF;

    v_amount := v_total_qty * COALESCE(v_avg_cost, 0);
    IF v_amount <= 0 THEN
        RETURN NEW;
    END IF;

    -- Verificar asiento existente
    SELECT je.id INTO v_existing_entry
    FROM journal_entries je
    WHERE je.source = 'inventory_adjustment'
      AND je.source_id = NEW.id::text
      AND je.organization_id = NEW.organization_id
    LIMIT 1;

    IF v_existing_entry IS NOT NULL THEN
        RETURN NEW;
    END IF;

    -- Buscar regla contable
    SELECT * INTO v_rule
    FROM accounting_rules
    WHERE organization_id = NEW.organization_id
      AND source_type = 'inventory_adjustment'
      AND event_type = v_event_type
      AND is_active = true
    ORDER BY priority
    LIMIT 1;

    IF v_rule IS NULL THEN
        RETURN NEW;
    END IF;

    -- Resolver sub-cuentas: Inventario (1405) tiene sub-cuenta por sucursal
    -- Para gain: débito=1405 (inventario), crédito=4250 (ingreso)
    -- Para loss: débito=5150 (gasto), crédito=1405 (inventario)
    SELECT sub_account_code INTO v_debit_account
    FROM branch_account_mappings
    WHERE organization_id = NEW.organization_id
      AND branch_id = NEW.branch_id
      AND base_account_code = v_rule.debit_account_code
    LIMIT 1;

    SELECT sub_account_code INTO v_credit_account
    FROM branch_account_mappings
    WHERE organization_id = NEW.organization_id
      AND branch_id = NEW.branch_id
      AND base_account_code = v_rule.credit_account_code
    LIMIT 1;

    -- Fallback a cuenta base si no hay sub-cuenta
    v_debit_account := COALESCE(v_debit_account, v_rule.debit_account_code);
    v_credit_account := COALESCE(v_credit_account, v_rule.credit_account_code);

    v_description := 'Ajuste Inventario ' || NEW.type || ' - ' || COALESCE(NEW.reason, 'N/A') || ' - ' || COALESCE(NEW.notes, '');

    PERFORM fn_create_journal_entry(
        NEW.organization_id, NEW.branch_id, COALESCE(NEW.updated_at, now()),
        v_description, 'inventory_adjustment', NEW.id::text,
        v_debit_account, v_credit_account, v_amount
    );

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_journal_inventory_adjustment"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auto_journal_inventory_transfer"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_rule RECORD;
    v_amount numeric;
    v_description text;
    v_existing_entry integer;
    v_origin_account text;
    v_dest_account text;
    v_avg_cost numeric;
    v_total_qty numeric;
    v_product_name text;
BEGIN
    -- Solo cuando el status cambia a 'received'
    IF NEW.status != 'received' THEN
        RETURN NEW;
    END IF;

    IF TG_OP = 'UPDATE' AND NEW.status = OLD.status THEN
        RETURN NEW;
    END IF;

    -- Calcular monto desde stock_movements asociados a esta transferencia
    SELECT 
        COALESCE(SUM(ABS(sm.qty)), 0),
        COALESCE(AVG(sm.unit_cost), 0)
    INTO v_total_qty, v_avg_cost
    FROM stock_movements sm
    WHERE sm.source = 'transfer'
      AND sm.source_id = NEW.id::text
      AND sm.organization_id = NEW.organization_id;

    -- Si no hay unit_cost, buscar avg_cost de stock_levels de la sucursal origen
    IF v_avg_cost = 0 OR v_avg_cost IS NULL THEN
        SELECT sl.avg_cost INTO v_avg_cost
        FROM stock_levels sl
        WHERE sl.branch_id = NEW.origin_branch_id
        ORDER BY sl.updated_at DESC
        LIMIT 1;
    END IF;

    v_amount := v_total_qty * COALESCE(v_avg_cost, 0);
    IF v_amount <= 0 THEN
        RETURN NEW;
    END IF;

    -- Verificar asiento existente
    SELECT je.id INTO v_existing_entry
    FROM journal_entries je
    WHERE je.source = 'inventory_transfer'
      AND je.source_id = NEW.id::text
      AND je.organization_id = NEW.organization_id
    LIMIT 1;

    IF v_existing_entry IS NOT NULL THEN
        RETURN NEW;
    END IF;

    -- Resolver sub-cuentas de inventario por sucursal
    -- Origen: crédito (sale inventario de sucursal origen)
    SELECT sub_account_code INTO v_origin_account
    FROM branch_account_mappings
    WHERE organization_id = NEW.organization_id
      AND branch_id = NEW.origin_branch_id
      AND base_account_code = '1405'
    LIMIT 1;

    -- Destino: débito (entra inventario a sucursal destino)
    SELECT sub_account_code INTO v_dest_account
    FROM branch_account_mappings
    WHERE organization_id = NEW.organization_id
      AND branch_id = NEW.dest_branch_id
      AND base_account_code = '1405'
    LIMIT 1;

    -- Si ambas sucursales tienen la misma sub-cuenta o no hay mapeo, no generar asiento
    IF v_origin_account IS NULL OR v_dest_account IS NULL OR v_origin_account = v_dest_account THEN
        RETURN NEW;
    END IF;

    v_description := 'Transferencia Inv ' || NEW.origin_branch_id || ' → ' || NEW.dest_branch_id || ' - TF-' || NEW.id;

    -- Débito: Inventario sucursal destino
    -- Crédito: Inventario sucursal origen
    PERFORM fn_create_journal_entry(
        NEW.organization_id, NEW.dest_branch_id, COALESCE(NEW.updated_at, now()),
        v_description, 'inventory_transfer', NEW.id::text,
        v_dest_account, v_origin_account, v_amount
    );

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_journal_inventory_transfer"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auto_journal_loan_installment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_rule RECORD;
    v_entry_id integer;
    v_loan RECORD;
    v_org_id integer;
    v_default_branch integer;
    v_memo text;
BEGIN
    -- Solo cuotas pagadas y solo cuando cambia el estado
    IF NEW.status NOT IN ('paid', 'completed') THEN
        RETURN NEW;
    END IF;

    IF OLD.status IS NOT DISTINCT FROM NEW.status THEN
        RETURN NEW;
    END IF;

    IF COALESCE(NEW.amount, 0) <= 0 THEN
        RETURN NEW;
    END IF;

    -- Obtener organización desde employee_loans
    SELECT * INTO v_loan FROM employee_loans WHERE id = NEW.loan_id;
    IF v_loan IS NULL THEN
        RETURN NEW;
    END IF;

    v_org_id := v_loan.organization_id;
    SELECT MIN(id) INTO v_default_branch FROM branches WHERE organization_id = v_org_id;

    -- Buscar regla específica de installment/paid
    SELECT * INTO v_rule
    FROM accounting_rules
    WHERE organization_id = v_org_id
      AND source_type = 'installment'
      AND event_type = 'paid'
      AND is_active = true
    ORDER BY priority LIMIT 1;

    -- Fallback: cualquier regla de installment activa
    IF v_rule IS NULL THEN
        SELECT * INTO v_rule
        FROM accounting_rules
        WHERE organization_id = v_org_id
          AND source_type = 'installment'
          AND is_active = true
        ORDER BY priority LIMIT 1;
    END IF;

    -- Fallback final: regla de loan/paid
    IF v_rule IS NULL THEN
        SELECT * INTO v_rule
        FROM accounting_rules
        WHERE organization_id = v_org_id
          AND source_type = 'loan'
          AND event_type = 'paid'
          AND is_active = true
        ORDER BY priority LIMIT 1;
    END IF;

    IF v_rule IS NULL THEN
        RETURN NEW;
    END IF;

    -- Memo diferenciado según loan_type
    v_memo := CASE v_loan.loan_type
        WHEN 'advance' THEN 'Descuento Anticipo N°' || NEW.installment_number::text || ' - ' || COALESCE(v_loan.loan_number, v_loan.id::text)
        ELSE 'Cuota préstamo N°' || NEW.installment_number::text || ' - ' || COALESCE(v_loan.loan_number, v_loan.id::text)
    END;

    v_entry_id := fn_create_journal_entry(
        p_organization_id := v_org_id,
        p_branch_id := v_default_branch,
        p_entry_date := COALESCE(NEW.paid_at, NEW.updated_at, now()),
        p_memo := v_memo,
        p_source := 'loan_installments',
        p_source_id := NEW.id::text,
        p_debit_account := v_rule.debit_account_code,
        p_credit_account := v_rule.credit_account_code,
        p_amount := NEW.amount
    );

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_journal_loan_installment"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auto_journal_maintenance"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_rule RECORD;
    v_amount numeric;
    v_description text;
    v_org_id integer;
BEGIN
    -- Solo cuando el status cambia a completed
    IF (NEW.status IS DISTINCT FROM OLD.status) AND NEW.status = 'completed' THEN
        v_amount := COALESCE(NEW.cost_estimate, 0);
        IF v_amount <= 0 THEN
            RETURN NEW;
        END IF;

        -- Obtener organization_id desde branch
        SELECT b.organization_id INTO v_org_id
        FROM branches b
        WHERE b.id = NEW.branch_id
        LIMIT 1;

        IF v_org_id IS NULL THEN
            RETURN NEW;
        END IF;

        -- Buscar regla contable
        SELECT * INTO v_rule
        FROM accounting_rules
        WHERE organization_id = v_org_id
          AND source_type = 'maintenance'
          AND event_type = 'completed'
          AND is_active = true
        LIMIT 1;

        IF NOT FOUND THEN
            RETURN NEW;
        END IF;

        v_description := 'Mantenimiento Completado - Orden ' || NEW.id::text;

        PERFORM fn_create_journal_entry(
            v_org_id,
            NEW.branch_id,
            'maintenance',
            'completed',
            NEW.id::text,
            v_amount,
            v_rule.debit_account_code,
            v_rule.credit_account_code,
            v_description,
            COALESCE(NEW.resolved_at, now())
        );
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_journal_maintenance"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auto_journal_manifest"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_rule RECORD;
    v_amount numeric;
    v_description text;
    v_org_id integer;
    v_branch_id integer;
    v_carrier_type text;
BEGIN
    -- Solo en UPDATE cuando cambia el status a completed
    IF TG_OP != 'UPDATE' THEN
        RETURN NEW;
    END IF;

    IF (NEW.status IS NOT DISTINCT FROM OLD.status) THEN
        RETURN NEW;
    END IF;

    IF NEW.status != 'completed' THEN
        RETURN NEW;
    END IF;

    v_org_id := NEW.organization_id;
    v_branch_id := COALESCE(NEW.branch_id, 0);

    -- Verificar si el carrier es tercero
    SELECT carrier_type INTO v_carrier_type
    FROM transport_carriers
    WHERE id = NEW.carrier_id
    LIMIT 1;

    -- Solo registrar gasto si es carrier tercero
    IF v_carrier_type = 'third_party' THEN
        v_amount := COALESCE(NEW.total_cod_amount, 0);
        IF v_amount <= 0 THEN
            -- Usar total_weight como base de costo si no hay COD
            v_amount := COALESCE(NEW.total_weight_kg, 0) * 100; -- Estimación básica
        END IF;

        IF v_amount <= 0 THEN
            RETURN NEW;
        END IF;

        v_description := 'Costo Carrier Manifiesto ' || COALESCE(NEW.manifest_number, NEW.id::text);

        SELECT * INTO v_rule
        FROM accounting_rules
        WHERE organization_id = v_org_id
          AND source_type = 'manifest'
          AND event_type = 'completed'
          AND is_active = true
        LIMIT 1;

        IF FOUND THEN
            PERFORM fn_create_journal_entry(
                v_org_id, v_branch_id, COALESCE(NEW.completed_at, now()),
                v_description, 'manifest', NEW.id::text,
                v_rule.debit_account_code, v_rule.credit_account_code,
                v_amount
            );
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_journal_manifest"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auto_journal_membership"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_rule RECORD;
    v_amount numeric;
    v_description text;
    v_org_id integer;
    v_branch_id integer;
    v_plan_name text;
    v_plan_price numeric;
    v_event_type text;
    v_customer_name text;
    v_existing_entry integer;
BEGIN
    v_org_id := NEW.organization_id;

    -- Obtener datos del plan
    SELECT name, price INTO v_plan_name, v_plan_price
    FROM membership_plans
    WHERE id = NEW.membership_plan_id
    LIMIT 1;

    v_amount := COALESCE(v_plan_price, 0);
    IF v_amount <= 0 THEN
        RETURN NEW;
    END IF;

    -- Obtener nombre del cliente para descripción
    SELECT (first_name || ' ' || last_name) INTO v_customer_name
    FROM customers
    WHERE id = NEW.customer_id
    LIMIT 1;

    -- Obtener branch_id desde member_branches (primera sucursal del miembro)
    SELECT mb.branch_id INTO v_branch_id
    FROM member_branches mb
    WHERE mb.organization_member_id = NEW.id
    LIMIT 1;

    v_branch_id := COALESCE(v_branch_id, 0);

    -- =====================================================
    -- INSERT: Nueva membresía
    -- =====================================================
    IF TG_OP = 'INSERT' THEN
        -- Si tiene sale_id, la venta ya fue contabilizada por trg_auto_journal_sale
        IF NEW.sale_id IS NOT NULL THEN
            RETURN NEW;
        END IF;

        -- Verificar si ya existe asiento para esta membresía
        SELECT je.id INTO v_existing_entry
        FROM journal_entries je
        WHERE je.source = 'membership'
          AND je.source_id = NEW.id::text
          AND je.organization_id = v_org_id
        LIMIT 1;

        IF v_existing_entry IS NOT NULL THEN
            RETURN NEW;
        END IF;

        -- Determinar evento: created (contado) o created_credit (crédito)
        -- Por defecto asumimos contado al crear membresía
        v_event_type := 'created';

        v_description := 'Membresía Gym - ' || COALESCE(v_plan_name, 'Plan') || ' - ' || COALESCE(v_customer_name, 'Cliente');

        SELECT * INTO v_rule
        FROM accounting_rules
        WHERE organization_id = v_org_id
          AND source_type = 'membership'
          AND event_type = v_event_type
          AND is_active = true
        ORDER BY priority
        LIMIT 1;

        IF FOUND THEN
            PERFORM fn_create_journal_entry(
                v_org_id,
                v_branch_id,
                COALESCE(NEW.created_at, now()),
                v_description,
                'membership',
                NEW.id::text,
                v_rule.debit_account_code,
                v_rule.credit_account_code,
                v_amount
            );
        END IF;

        RETURN NEW;
    END IF;

    -- =====================================================
    -- UPDATE: Cambio de status
    -- =====================================================
    IF TG_OP = 'UPDATE' AND (NEW.status IS DISTINCT FROM OLD.status) THEN

        -- RENOVACIÓN: status vuelve a active desde expired/cancelled
        IF NEW.status = 'active' AND OLD.status IN ('expired', 'cancelled') THEN
            -- Si tiene sale_id, la venta ya contabiliza
            IF NEW.sale_id IS NOT NULL THEN
                RETURN NEW;
            END IF;

            -- Verificar asiento de renovación existente
            SELECT je.id INTO v_existing_entry
            FROM journal_entries je
            WHERE je.source = 'membership'
              AND je.source_id = NEW.id::text
              AND je.organization_id = v_org_id
              AND je.memo LIKE '%Renovación%'
            LIMIT 1;

            IF v_existing_entry IS NOT NULL THEN
                RETURN NEW;
            END IF;

            v_event_type := 'renewed';
            v_description := 'Renovación Membresía Gym - ' || COALESCE(v_plan_name, 'Plan') || ' - ' || COALESCE(v_customer_name, 'Cliente');

            SELECT * INTO v_rule
            FROM accounting_rules
            WHERE organization_id = v_org_id
              AND source_type = 'membership'
              AND event_type = v_event_type
              AND is_active = true
            ORDER BY priority
            LIMIT 1;

            IF FOUND THEN
                PERFORM fn_create_journal_entry(
                    v_org_id,
                    v_branch_id,
                    COALESCE(NEW.updated_at, now()),
                    v_description,
                    'membership',
                    NEW.id::text,
                    v_rule.debit_account_code,
                    v_rule.credit_account_code,
                    v_amount
                );
            END IF;

        -- CANCELACIÓN: de active a cancelled
        ELSIF NEW.status = 'cancelled' AND OLD.status = 'active' THEN
            -- Solo reversar si no tiene sale_id (la venta maneja su propia reversa)
            IF NEW.sale_id IS NOT NULL THEN
                RETURN NEW;
            END IF;

            v_event_type := 'cancelled';
            v_description := 'Reversa Cancelación Membresía - ' || COALESCE(v_plan_name, 'Plan') || ' - ' || COALESCE(v_customer_name, 'Cliente');

            SELECT * INTO v_rule
            FROM accounting_rules
            WHERE organization_id = v_org_id
              AND source_type = 'membership'
              AND event_type = v_event_type
              AND is_active = true
            ORDER BY priority
            LIMIT 1;

            IF FOUND THEN
                PERFORM fn_create_journal_entry(
                    v_org_id,
                    v_branch_id,
                    COALESCE(NEW.updated_at, now()),
                    v_description,
                    'membership',
                    NEW.id::text,
                    v_rule.debit_account_code,
                    v_rule.credit_account_code,
                    v_amount
                );
            END IF;
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_journal_membership"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auto_journal_membership_payment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_rule RECORD;
    v_amount numeric;
    v_description text;
    v_org_id integer;
    v_branch_id integer;
    v_plan_name text;
    v_customer_name text;
    v_membership_id integer;
    v_has_sale boolean;
    v_has_invoice boolean;
BEGIN
    -- Solo para pagos de membresías
    IF NEW.source != 'membership' THEN
        RETURN NEW;
    END IF;

    -- Solo pagos completados
    IF NEW.status != 'completed' THEN
        RETURN NEW;
    END IF;

    v_org_id := NEW.organization_id;
    v_branch_id := COALESCE(NEW.branch_id, 0);
    v_amount := COALESCE(NEW.amount, 0);

    IF v_amount <= 0 THEN
        RETURN NEW;
    END IF;

    -- El source_id debe ser el membership_id
    v_membership_id := NEW.source_id::integer;

    -- Verificar si la membresía tiene sale_id (la venta ya contabiliza)
    SELECT sale_id IS NOT NULL INTO v_has_sale
    FROM memberships
    WHERE id = v_membership_id
    LIMIT 1;

    IF v_has_sale THEN
        RETURN NEW;
    END IF;

    -- Verificar si el pago tiene factura vinculada
    v_has_invoice := NEW.reference IS NOT NULL AND NEW.reference LIKE 'INV:%';

    IF v_has_invoice THEN
        RETURN NEW;
    END IF;

    -- Obtener datos para descripción
    SELECT mp.name, (c.first_name || ' ' || c.last_name)
    INTO v_plan_name, v_customer_name
    FROM memberships m
    JOIN membership_plans mp ON m.membership_plan_id = mp.id
    JOIN customers c ON m.customer_id = c.id
    WHERE m.id = v_membership_id
    LIMIT 1;

    v_description := 'Pago Membresía Gym - ' || COALESCE(v_plan_name, 'Plan') || ' - ' || COALESCE(v_customer_name, 'Cliente');

    -- Buscar regla contable
    SELECT * INTO v_rule
    FROM accounting_rules
    WHERE organization_id = v_org_id
      AND source_type = 'membership'
      AND event_type = 'paid'
      AND is_active = true
    ORDER BY priority
    LIMIT 1;

    IF NOT FOUND THEN
        RETURN NEW;
    END IF;

    -- Crear asiento contable
    PERFORM fn_create_journal_entry(
        v_org_id,
        v_branch_id,
        COALESCE(NEW.created_at, now()),
        v_description,
        'membership_payment',
        NEW.id::text,
        v_rule.debit_account_code,
        v_rule.credit_account_code,
        v_amount,
        NULL,
        0,
        NEW.created_by
    );

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_journal_membership_payment"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auto_journal_ota_commission"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_rule RECORD;
    v_reservation RECORD;
    v_amount numeric;
    v_description text;
    v_channel text;
    v_priority smallint;
BEGIN
    -- Determinar canal y monto de comision
    -- Funciona para booking_reservation_details y expedia_reservation_details
    v_amount := COALESCE(NEW.commission_amount, 0);
    IF v_amount <= 0 THEN
        RETURN NEW;
    END IF;

    -- Determinar canal segun la tabla (TG_TABLE_NAME)
    v_channel := CASE TG_TABLE_NAME
        WHEN 'booking_reservation_details' THEN 'booking'
        WHEN 'expedia_reservation_details' THEN 'expedia'
        ELSE 'unknown'
    END;

    v_priority := CASE v_channel
        WHEN 'booking' THEN 10
        WHEN 'expedia' THEN 11
        ELSE 10
    END;

    -- Obtener reserva
    SELECT r.organization_id, r.branch_id INTO v_reservation
    FROM reservations r
    WHERE r.id = NEW.reservation_id
    LIMIT 1;

    IF NOT FOUND THEN
        RETURN NEW;
    END IF;

    -- Buscar regla contable
    SELECT * INTO v_rule
    FROM accounting_rules
    WHERE organization_id = v_reservation.organization_id
      AND source_type = 'ota_commission'
      AND event_type = 'confirmed'
      AND priority = v_priority
      AND is_active = true
    LIMIT 1;

    -- Fallback: cualquier regla de ota_commission
    IF NOT FOUND THEN
        SELECT * INTO v_rule
        FROM accounting_rules
        WHERE organization_id = v_reservation.organization_id
          AND source_type = 'ota_commission'
          AND event_type = 'confirmed'
          AND is_active = true
        LIMIT 1;
    END IF;

    IF NOT FOUND THEN
        RETURN NEW;
    END IF;

    v_description := 'Comision ' || v_channel || ' - Reserva ' || NEW.reservation_id::text;

    PERFORM fn_create_journal_entry(
        v_reservation.organization_id,
        COALESCE(v_reservation.branch_id, 0),
        'ota_commission',
        'confirmed',
        NEW.id::text,
        v_amount,
        v_rule.debit_account_code,
        v_rule.credit_account_code,
        v_description,
        COALESCE(NEW.updated_at, now())
    );

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_journal_ota_commission"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auto_journal_parking_pass"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_rule RECORD;
    v_entry_id integer;
    v_event_type text;
    v_branch_id integer;
BEGIN
    IF NEW.status IS NULL THEN RETURN NEW; END IF;

    IF NEW.status = 'active' AND (OLD.status IS DISTINCT FROM NEW.status OR TG_OP = 'INSERT') THEN
        v_event_type := 'paid';
    ELSIF NEW.status = 'cancelled' OR NEW.status = 'suspended' THEN
        v_event_type := 'reversed';
    ELSE
        RETURN NEW;
    END IF;

    SELECT * INTO v_rule
    FROM accounting_rules
    WHERE organization_id = NEW.organization_id
      AND source_type = 'parking_pass'
      AND event_type = v_event_type
      AND is_active = true
    ORDER BY priority LIMIT 1;

    IF v_rule IS NULL THEN
        SELECT * INTO v_rule
        FROM accounting_rules
        WHERE organization_id = NEW.organization_id
          AND source_type = 'parking_pass'
          AND is_active = true
        ORDER BY priority LIMIT 1;
    END IF;

    IF v_rule IS NULL THEN RETURN NEW; END IF;

    SELECT MIN(id) INTO v_branch_id FROM branches WHERE organization_id = NEW.organization_id;

    v_entry_id := fn_create_journal_entry(
        p_organization_id := NEW.organization_id,
        p_branch_id := v_branch_id,
        p_entry_date := COALESCE(NEW.updated_at, NEW.created_at, now()),
        p_memo := 'Pase Parqueadero - ' || COALESCE(NEW.plan_name, NEW.id::text),
        p_source := 'parking_passes',
        p_source_id := NEW.id::text,
        p_debit_account := v_rule.debit_account_code,
        p_credit_account := v_rule.credit_account_code,
        p_amount := COALESCE(NEW.price, 0)
    );

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_journal_parking_pass"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auto_journal_parking_payment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_rule RECORD;
    v_amount numeric;
    v_description text;
    v_org_id integer;
    v_branch_id integer;
    v_source_type text;
    v_event_type text;
    v_vehicle_plate text;
    v_has_invoice boolean;
    v_payment_method text;
BEGIN
    -- Solo para pagos de parking
    IF NEW.source NOT IN ('parking_session', 'parking_pass') THEN
        RETURN NEW;
    END IF;

    -- Solo pagos completados
    IF NEW.status != 'completed' THEN
        RETURN NEW;
    END IF;

    v_org_id := NEW.organization_id;
    v_branch_id := COALESCE(NEW.branch_id, 0);
    v_amount := COALESCE(NEW.amount, 0);
    v_payment_method := COALESCE(NEW.method, 'cash');

    IF v_amount <= 0 THEN
        RETURN NEW;
    END IF;

    -- Verificar si el pago ya tiene factura vinculada (reference = INV:xxx)
    -- Si tiene factura, trg_auto_journal_sale ya contabilizó el ingreso
    v_has_invoice := NEW.reference IS NOT NULL AND NEW.reference LIKE 'INV:%';

    IF v_has_invoice THEN
        RETURN NEW;
    END IF;

    -- Determinar source_type y event_type
    IF NEW.source = 'parking_session' THEN
        v_source_type := 'parking_session';
        
        -- Obtener placa para descripción
        SELECT vehicle_plate INTO v_vehicle_plate
        FROM parking_sessions
        WHERE id::text = NEW.source_id
        LIMIT 1;

        -- Si el método es crédito, usar regla de CxC
        IF v_payment_method = 'credit' THEN
            v_event_type := 'paid_credit';
        ELSE
            v_event_type := 'paid';
        END IF;

        v_description := 'Parqueadero - Sesión ' || COALESCE(v_vehicle_plate, NEW.source_id);
    ELSE
        v_source_type := 'parking_pass';
        
        -- Obtener nombre del plan para descripción
        SELECT plan_name INTO v_vehicle_plate
        FROM parking_passes
        WHERE id::text = NEW.source_id
        LIMIT 1;

        IF v_payment_method = 'credit' THEN
            v_event_type := 'paid_credit';
        ELSE
            v_event_type := 'paid';
        END IF;

        v_description := 'Parqueadero - Pase ' || COALESCE(v_vehicle_plate, NEW.source_id);
    END IF;

    -- Buscar regla contable
    SELECT * INTO v_rule
    FROM accounting_rules
    WHERE organization_id = v_org_id
      AND source_type = v_source_type
      AND event_type = v_event_type
      AND is_active = true
    ORDER BY priority
    LIMIT 1;

    IF NOT FOUND THEN
        RETURN NEW;
    END IF;

    -- Crear asiento contable
    PERFORM fn_create_journal_entry(
        v_org_id,
        v_branch_id,
        COALESCE(NEW.created_at, now()),
        v_description,
        'parking_payment',
        NEW.id::text,
        v_rule.debit_account_code,
        v_rule.credit_account_code,
        v_amount,
        NULL,
        0,
        NEW.created_by
    );

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_journal_parking_payment"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auto_journal_parking_reversal"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_rule RECORD;
    v_amount numeric;
    v_description text;
    v_org_id integer;
    v_branch_id integer;
    v_source_type text;
    v_vehicle_plate text;
    v_has_invoice boolean;
BEGIN
    -- Solo para pagos de parking
    IF NEW.source NOT IN ('parking_session', 'parking_pass') THEN
        RETURN NEW;
    END IF;

    -- Solo cuando cambia de completed a reversed
    IF (NEW.status IS NOT DISTINCT FROM OLD.status) THEN
        RETURN NEW;
    END IF;

    IF NEW.status != 'reversed' OR OLD.status != 'completed' THEN
        RETURN NEW;
    END IF;

    v_org_id := NEW.organization_id;
    v_branch_id := COALESCE(NEW.branch_id, 0);
    v_amount := COALESCE(NEW.amount, 0);

    IF v_amount <= 0 THEN
        RETURN NEW;
    END IF;

    -- Si tenía factura vinculada, la reversa se maneja por nota crédito
    v_has_invoice := NEW.reference IS NOT NULL AND NEW.reference LIKE 'INV:%';

    IF v_has_invoice THEN
        RETURN NEW;
    END IF;

    -- Determinar source_type
    IF NEW.source = 'parking_session' THEN
        v_source_type := 'parking_session';
        
        SELECT vehicle_plate INTO v_vehicle_plate
        FROM parking_sessions
        WHERE id::text = NEW.source_id
        LIMIT 1;

        v_description := 'Reversa Parqueadero - Sesión ' || COALESCE(v_vehicle_plate, NEW.source_id);
    ELSE
        v_source_type := 'parking_pass';
        
        SELECT plan_name INTO v_vehicle_plate
        FROM parking_passes
        WHERE id::text = NEW.source_id
        LIMIT 1;

        v_description := 'Reversa Parqueadero - Pase ' || COALESCE(v_vehicle_plate, NEW.source_id);
    END IF;

    -- Buscar regla contable de reversa
    SELECT * INTO v_rule
    FROM accounting_rules
    WHERE organization_id = v_org_id
      AND source_type = v_source_type
      AND event_type = 'reversed'
      AND is_active = true
    ORDER BY priority
    LIMIT 1;

    IF NOT FOUND THEN
        RETURN NEW;
    END IF;

    -- Crear asiento contable de reversa
    PERFORM fn_create_journal_entry(
        v_org_id,
        v_branch_id,
        now(),
        v_description,
        'parking_reversal',
        NEW.id::text,
        v_rule.debit_account_code,
        v_rule.credit_account_code,
        v_amount,
        NULL,
        0,
        NEW.created_by
    );

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_journal_parking_reversal"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auto_journal_parking_session"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_rule RECORD;
    v_entry_id integer;
    v_org_id integer;
BEGIN
    -- Solo sesiones cerradas con monto
    IF NEW.status::text NOT IN ('closed', 'paid', 'completed') THEN
        RETURN NEW;
    END IF;

    IF COALESCE(NEW.amount, 0) <= 0 THEN
        RETURN NEW;
    END IF;

    -- Obtener organization_id desde branch
    SELECT organization_id INTO v_org_id FROM branches WHERE id = NEW.branch_id;
    IF v_org_id IS NULL THEN
        RETURN NEW;
    END IF;

    SELECT * INTO v_rule
    FROM accounting_rules
    WHERE organization_id = v_org_id
      AND source_type = 'parking'
      AND is_active = true
    ORDER BY priority LIMIT 1;

    IF v_rule IS NULL THEN
        RETURN NEW;
    END IF;

    v_entry_id := fn_create_journal_entry(
        p_organization_id := v_org_id,
        p_branch_id := NEW.branch_id,
        p_entry_date := COALESCE(NEW.exit_at, NEW.created_at, now()),
        p_memo := 'Parking - ' || COALESCE(NEW.vehicle_plate, NEW.id::text),
        p_source := 'parking_sessions',
        p_source_id := NEW.id::text,
        p_debit_account := v_rule.debit_account_code,
        p_credit_account := v_rule.credit_account_code,
        p_amount := NEW.amount
    );

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_journal_parking_session"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auto_journal_payment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_rule RECORD;
    v_entry_id integer;
    v_source_type text;
    v_event_type text;
    v_memo text;
    v_discount numeric;
    v_discount_on_debit boolean;
BEGIN
    -- Determinar tipo de fuente y evento para buscar regla
    IF NEW.source = 'invoice_sales' OR NEW.source = 'account_receivable' THEN
        v_source_type := 'sale_payment';
        v_memo := 'Cobro recibido';
        v_discount_on_debit := true;  -- descuento concedido va al débito (junto al efectivo)
        IF NEW.status = 'partial' THEN
            v_event_type := 'partial_paid';
        ELSE
            v_event_type := 'paid';
        END IF;
    ELSIF NEW.source = 'invoice_purchase' OR NEW.source = 'account_payable' THEN
        v_source_type := 'purchase_payment';
        v_event_type := 'paid';
        v_memo := 'Pago a proveedor';
        v_discount_on_debit := false; -- descuento obtenido va al crédito (junto al efectivo)
    ELSE
        -- Otros tipos de pago (PMS, parking, membership, etc.) - los manejan otros triggers
        RETURN NEW;
    END IF;

    -- Buscar regla de contabilización
    SELECT * INTO v_rule
    FROM accounting_rules
    WHERE organization_id = NEW.organization_id
      AND source_type = v_source_type
      AND event_type = v_event_type
      AND is_active = true
    ORDER BY priority
    LIMIT 1;

    -- Fallback: cualquier regla de sale_payment/purchase_payment
    IF v_rule IS NULL THEN
        SELECT * INTO v_rule
        FROM accounting_rules
        WHERE organization_id = NEW.organization_id
          AND source_type = v_source_type
          AND is_active = true
        ORDER BY priority
        LIMIT 1;
    END IF;

    IF v_rule IS NULL THEN
        RETURN NEW;
    END IF;

    v_discount := COALESCE(NEW.discount_amount, 0);

    -- Crear asiento contable (con línea de descuento si aplica y hay cuenta configurada)
    v_entry_id := fn_create_journal_entry_with_discount(
        p_organization_id := NEW.organization_id,
        p_branch_id := NEW.branch_id,
        p_entry_date := NEW.created_at,
        p_memo := v_memo || ' - Ref: ' || COALESCE(NEW.reference, NEW.id::text),
        p_source := 'payments',
        p_source_id := NEW.id::text,
        p_debit_account := v_rule.debit_account_code,
        p_credit_account := v_rule.credit_account_code,
        p_amount := NEW.amount,
        p_discount_account := v_rule.discount_account_code,
        p_discount_amount := v_discount,
        p_discount_on_debit := v_discount_on_debit,
        p_created_by := NEW.created_by
    );

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_journal_payment"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_auto_journal_payment"() IS 'Trigger para asiento automático de pagos';



CREATE OR REPLACE FUNCTION "public"."fn_auto_journal_payroll"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_rule RECORD;
    v_entry_id integer;
    v_run RECORD;
    v_org_id integer;
    v_branch_id integer;
    v_event_type text;
    v_memo text;
    v_source_id text;
    v_total_debit numeric := 0;
    v_country_code text;
BEGIN
    IF NEW.status IS NULL THEN
        RETURN NEW;
    END IF;

    -- Disparar cuando el slip cambia a 'approved' (devengo) o 'paid' (pago)
    IF (NEW.status = 'approved' OR NEW.status = 'paid')
       AND (OLD.status IS DISTINCT FROM NEW.status) THEN

        SELECT * INTO v_run
        FROM payroll_runs
        WHERE id = NEW.payroll_run_id;

        IF v_run IS NULL THEN
            RETURN NEW;
        END IF;

        SELECT organization_id INTO v_org_id
        FROM payroll_periods
        WHERE id = v_run.payroll_period_id;

        IF v_org_id IS NULL THEN
            RETURN NEW;
        END IF;

        v_event_type := CASE NEW.status
            WHEN 'approved' THEN 'created'
            WHEN 'paid' THEN 'paid'
        END;

        -- Buscar regla contable
        SELECT * INTO v_rule
        FROM accounting_rules
        WHERE organization_id = v_org_id
          AND source_type = 'payroll'
          AND event_type = v_event_type
          AND is_active = true
        ORDER BY priority LIMIT 1;

        IF v_rule IS NULL THEN
            SELECT * INTO v_rule
            FROM accounting_rules
            WHERE organization_id = v_org_id
              AND source_type = 'payroll'
              AND is_active = true
            ORDER BY priority LIMIT 1;
        END IF;

        IF v_rule IS NULL THEN
            RETURN NEW;
        END IF;

        SELECT MIN(id) INTO v_branch_id FROM branches WHERE organization_id = v_org_id;
        SELECT country_code INTO v_country_code FROM organizations WHERE id = v_org_id;

        v_memo := 'Nómina - Slip: ' || NEW.id::text || ' (' || v_event_type || ')';
        v_source_id := NEW.id::text || ':' || v_event_type;

        IF v_event_type = 'paid' THEN
            -- Pago: asiento simple pasivo → banco
            v_entry_id := fn_create_journal_entry(
                p_organization_id := v_org_id,
                p_branch_id := v_branch_id,
                p_entry_date := COALESCE(NEW.paid_at, NEW.updated_at, now()),
                p_memo := v_memo,
                p_source := 'payroll_slips',
                p_source_id := v_source_id,
                p_debit_account := v_rule.debit_account_code,
                p_credit_account := v_rule.credit_account_code,
                p_amount := NEW.net_pay
            );
        ELSE
            -- Devengo: asiento multi-línea con provisiones
            -- Solo si el país tiene plan PUC (COL), usar cuentas detalladas
            -- Para otros países, usar fn_create_journal_entry simple
            IF v_country_code = 'COL' THEN
                -- Crear cabecera
                INSERT INTO journal_entries (
                    organization_id, branch_id, entry_date, memo,
                    source, source_id, posted
                ) VALUES (
                    v_org_id, v_branch_id,
                    COALESCE(NEW.updated_at, now()),
                    v_memo, 'payroll_slips', v_source_id, true
                ) RETURNING id INTO v_entry_id;

                -- 1. Gasto salario base (5105)
                IF COALESCE(NEW.gross_pay, 0) > 0 THEN
                    INSERT INTO journal_lines (journal_entry_id, organization_id, account_code, description, debit, credit)
                    VALUES (v_entry_id, v_org_id, '5105', 'Salario base', NEW.gross_pay, 0);
                    v_total_debit := v_total_debit + NEW.gross_pay;
                END IF;

                -- 2. Salud patronal (5195) → pasivo (2370)
                IF COALESCE(NEW.employer_health, 0) > 0 THEN
                    INSERT INTO journal_lines (journal_entry_id, organization_id, account_code, description, debit, credit)
                    VALUES (v_entry_id, v_org_id, '5195', 'Salud patronal', NEW.employer_health, 0);
                    v_total_debit := v_total_debit + NEW.employer_health;
                END IF;

                -- 3. Pensión patronal (5195) → pasivo (2370)
                IF COALESCE(NEW.employer_pension, 0) > 0 THEN
                    INSERT INTO journal_lines (journal_entry_id, organization_id, account_code, description, debit, credit)
                    VALUES (v_entry_id, v_org_id, '5195', 'Pensión patronal', NEW.employer_pension, 0);
                    v_total_debit := v_total_debit + NEW.employer_pension;
                END IF;

                -- 4. ARL (5195)
                IF COALESCE(NEW.employer_arl, 0) > 0 THEN
                    INSERT INTO journal_lines (journal_entry_id, organization_id, account_code, description, debit, credit)
                    VALUES (v_entry_id, v_org_id, '5195', 'ARL patronal', NEW.employer_arl, 0);
                    v_total_debit := v_total_debit + NEW.employer_arl;
                END IF;

                -- 5. Parafiscales (5195)
                IF COALESCE(NEW.employer_parafiscales, 0) > 0 THEN
                    INSERT INTO journal_lines (journal_entry_id, organization_id, account_code, description, debit, credit)
                    VALUES (v_entry_id, v_org_id, '5195', 'Parafiscales', NEW.employer_parafiscales, 0);
                    v_total_debit := v_total_debit + NEW.employer_parafiscales;
                END IF;

                -- 6. Cesantías (5195)
                IF COALESCE(NEW.employer_severance, 0) > 0 THEN
                    INSERT INTO journal_lines (journal_entry_id, organization_id, account_code, description, debit, credit)
                    VALUES (v_entry_id, v_org_id, '5195', 'Provisión cesantías', NEW.employer_severance, 0);
                    v_total_debit := v_total_debit + NEW.employer_severance;
                END IF;

                -- 7. Interés cesantías (5195)
                IF COALESCE(NEW.employer_severance_interest, 0) > 0 THEN
                    INSERT INTO journal_lines (journal_entry_id, organization_id, account_code, description, debit, credit)
                    VALUES (v_entry_id, v_org_id, '5195', 'Interés cesantías', NEW.employer_severance_interest, 0);
                    v_total_debit := v_total_debit + NEW.employer_severance_interest;
                END IF;

                -- 8. Provisión vacaciones (5195)
                IF COALESCE(NEW.employer_vacation_provision, 0) > 0 THEN
                    INSERT INTO journal_lines (journal_entry_id, organization_id, account_code, description, debit, credit)
                    VALUES (v_entry_id, v_org_id, '5195', 'Provisión vacaciones', NEW.employer_vacation_provision, 0);
                    v_total_debit := v_total_debit + NEW.employer_vacation_provision;
                END IF;

                -- 9. Provisión prima (5195)
                IF COALESCE(NEW.employer_bonus_provision, 0) > 0 THEN
                    INSERT INTO journal_lines (journal_entry_id, organization_id, account_code, description, debit, credit)
                    VALUES (v_entry_id, v_org_id, '5195', 'Provisión prima', NEW.employer_bonus_provision, 0);
                    v_total_debit := v_total_debit + NEW.employer_bonus_provision;
                END IF;

                -- Línea de crédito: pasivo nómina por pagar (2505)
                -- Total = net_pay (al empleado) + todas las provisiones patronales
                INSERT INTO journal_lines (journal_entry_id, organization_id, account_code, description, debit, credit)
                VALUES (v_entry_id, v_org_id, '2505', 'Nómina por pagar', 0, v_total_debit);

            ELSE
                -- Para otros países, asiento simple con gross_pay
                v_entry_id := fn_create_journal_entry(
                    p_organization_id := v_org_id,
                    p_branch_id := v_branch_id,
                    p_entry_date := COALESCE(NEW.updated_at, now()),
                    p_memo := v_memo,
                    p_source := 'payroll_slips',
                    p_source_id := v_source_id,
                    p_debit_account := v_rule.debit_account_code,
                    p_credit_account := v_rule.credit_account_code,
                    p_amount := NEW.net_pay
                );
            END IF;
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_journal_payroll"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auto_journal_payroll_period"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_rule RECORD;
    v_entry_id integer;
    v_branch_id integer;
    v_event_type text;
    v_amount numeric;
BEGIN
    IF NEW.status IS NULL THEN
        RETURN NEW;
    END IF;

    -- 'approved' → event_type 'created' (provisionar costo patronal)
    -- 'paid' → event_type 'paid' (pagar obligaciones patronales)
    IF (NEW.status = 'approved' OR NEW.status = 'paid')
       AND (OLD.status IS DISTINCT FROM NEW.status) THEN

        v_event_type := CASE NEW.status
            WHEN 'approved' THEN 'created'
            WHEN 'paid' THEN 'paid'
        END;

        -- Monto = costo patronal (no duplica slips que usan net_pay)
        v_amount := COALESCE(NEW.total_employer_cost, 0);
        IF v_amount <= 0 THEN
            RETURN NEW;
        END IF;

        SELECT * INTO v_rule
        FROM accounting_rules
        WHERE organization_id = NEW.organization_id
          AND source_type = 'payroll_period'
          AND event_type = v_event_type
          AND is_active = true
        ORDER BY priority LIMIT 1;

        IF v_rule IS NULL THEN
            SELECT * INTO v_rule
            FROM accounting_rules
            WHERE organization_id = NEW.organization_id
              AND source_type = 'payroll_period'
              AND is_active = true
            ORDER BY priority LIMIT 1;
        END IF;

        IF v_rule IS NULL THEN
            RETURN NEW;
        END IF;

        SELECT MIN(id) INTO v_branch_id FROM branches WHERE organization_id = NEW.organization_id;

        v_entry_id := fn_create_journal_entry(
            p_organization_id := NEW.organization_id,
            p_branch_id := v_branch_id,
            p_entry_date := COALESCE(NEW.payment_date, NEW.approved_at, NEW.updated_at, now()),
            p_memo := 'Cierre Período Nómina - ' || COALESCE(NEW.name, NEW.id::text) || ' (' || v_event_type || ')',
            p_source := 'payroll_periods',
            p_source_id := NEW.id::text || ':' || v_event_type,
            p_debit_account := v_rule.debit_account_code,
            p_credit_account := v_rule.credit_account_code,
            p_amount := v_amount
        );
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_journal_payroll_period"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auto_journal_purchase"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_rule RECORD;
    v_entry_id integer;
    v_exists boolean;
    v_is_credit boolean;
BEGIN
    IF NEW.status IS DISTINCT FROM 'received' THEN
        RETURN NEW;
    END IF;

    IF TG_OP = 'UPDATE' AND OLD.status = 'received' THEN
        RETURN NEW;
    END IF;

    SELECT EXISTS(
        SELECT 1 FROM journal_entries
        WHERE source = 'invoice_purchase'
          AND source_id = NEW.id::text
          AND memo LIKE 'Compra %'
    ) INTO v_exists;
    IF v_exists THEN
        RETURN NEW;
    END IF;

    v_is_credit := (NEW.payment_method = 'credit');

    SELECT * INTO v_rule
    FROM accounting_rules
    WHERE organization_id = NEW.organization_id
      AND source_type = 'purchase'
      AND event_type = 'created'
      AND is_active = true
      AND (conditions->>'is_credit')::boolean = v_is_credit
    ORDER BY priority
    LIMIT 1;

    IF v_rule IS NULL THEN
        SELECT * INTO v_rule
        FROM accounting_rules
        WHERE organization_id = NEW.organization_id
          AND source_type = 'purchase'
          AND event_type = 'created'
          AND is_active = true
        ORDER BY priority
        LIMIT 1;
    END IF;

    IF v_rule IS NULL THEN
        RETURN NEW;
    END IF;

    v_entry_id := fn_create_journal_entry(
        p_organization_id := NEW.organization_id,
        p_branch_id := NEW.branch_id,
        p_entry_date := COALESCE(NEW.issue_date, now()),
        p_memo := 'Compra ' || COALESCE(NEW.number_ext, NEW.id::text),
        p_source := 'invoice_purchase',
        p_source_id := NEW.id::text,
        p_debit_account := v_rule.debit_account_code,
        p_credit_account := v_rule.credit_account_code,
        p_amount := NEW.total,
        p_tax_account := v_rule.tax_account_code,
        p_tax_amount := CASE WHEN v_rule.use_tax_from_document THEN NEW.tax_total ELSE 0 END
    );

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_journal_purchase"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_auto_journal_purchase"() IS 'Trigger para asiento automático de compras';



CREATE OR REPLACE FUNCTION "public"."fn_auto_journal_purchase_order"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_rule RECORD;
    v_amount numeric;
    v_description text;
    v_supplier_name text;
    v_existing_entry integer;
    v_event_type text;
    v_debit_account text;
    v_credit_account text;
    v_credit_days integer;
BEGIN
    IF NEW.status != 'received' THEN
        RETURN NEW;
    END IF;

    IF TG_OP = 'UPDATE' AND NEW.status = OLD.status THEN
        RETURN NEW;
    END IF;

    v_amount := COALESCE(NEW.total, 0);
    IF v_amount <= 0 THEN
        RETURN NEW;
    END IF;

    -- Verificar asiento existente
    SELECT je.id INTO v_existing_entry
    FROM journal_entries je
    WHERE je.source = 'purchase_order'
      AND je.source_id = NEW.id::text
      AND je.organization_id = NEW.organization_id
    LIMIT 1;

    IF v_existing_entry IS NOT NULL THEN
        RETURN NEW;
    END IF;

    SELECT name INTO v_supplier_name FROM suppliers WHERE id = NEW.supplier_id LIMIT 1;

    -- Determinar contado vs crédito
    SELECT COALESCE(s.credit_days, 0) INTO v_credit_days
    FROM suppliers s WHERE s.id = NEW.supplier_id LIMIT 1;

    IF v_credit_days = 0 THEN
        v_event_type := 'received_cash';
    ELSE
        v_event_type := 'received';
    END IF;

    -- Buscar regla contable
    SELECT * INTO v_rule
    FROM accounting_rules
    WHERE organization_id = NEW.organization_id
      AND source_type = 'purchase_order'
      AND event_type = v_event_type
      AND is_active = true
    ORDER BY priority
    LIMIT 1;

    IF v_rule IS NULL THEN
        RETURN NEW;
    END IF;

    -- Resolver sub-cuenta de inventario (1405 → 1405-0X) para el débito
    SELECT sub_account_code INTO v_debit_account
    FROM branch_account_mappings
    WHERE organization_id = NEW.organization_id
      AND branch_id = NEW.branch_id
      AND base_account_code = v_rule.debit_account_code
    LIMIT 1;

    -- El crédito (CxP o Caja) no tiene sub-cuenta por sucursal
    v_credit_account := v_rule.credit_account_code;

    -- Fallback
    v_debit_account := COALESCE(v_debit_account, v_rule.debit_account_code);

    v_description := 'Recepción OC-' || NEW.id || ' - ' || COALESCE(v_supplier_name, 'Proveedor');

    PERFORM fn_create_journal_entry(
        NEW.organization_id, NEW.branch_id, COALESCE(NEW.updated_at, now()),
        v_description, 'purchase_order', NEW.id::text,
        v_debit_account, v_credit_account, v_amount
    );

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_journal_purchase_order"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auto_journal_refund"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_rule RECORD;
    v_entry_id integer;
BEGIN
    -- Solo procesar devoluciones confirmadas o completadas
    IF NEW.status IS NULL THEN
        RETURN NEW;
    END IF;

    IF (NEW.status = 'confirmed' OR NEW.status = 'completed' OR NEW.status = 'approved')
       AND (OLD.status IS DISTINCT FROM NEW.status) THEN

        -- Buscar regla con event_type 'refunded'
        SELECT * INTO v_rule
        FROM accounting_rules
        WHERE organization_id = NEW.organization_id
          AND source_type = 'refund'
          AND event_type = 'refunded'
          AND is_active = true
        ORDER BY priority
        LIMIT 1;

        -- Fallback: cualquier regla de refund
        IF v_rule IS NULL THEN
            SELECT * INTO v_rule
            FROM accounting_rules
            WHERE organization_id = NEW.organization_id
              AND source_type = 'refund'
              AND is_active = true
            ORDER BY priority
            LIMIT 1;
        END IF;

        IF v_rule IS NULL THEN
            RETURN NEW;
        END IF;

        -- Crear asiento: débito = Devoluciones/Reembolsos, crédito = Caja/Banco
        v_entry_id := fn_create_journal_entry(
            p_organization_id := NEW.organization_id,
            p_branch_id := NEW.branch_id,
            p_entry_date := COALESCE(NEW.return_date, NEW.created_at, now()),
            p_memo := 'Reembolso - Venta:' || COALESCE(NEW.sale_id::text, '') || ' - ' || COALESCE(NEW.reason, ''),
            p_source := 'returns',
            p_source_id := NEW.id::text,
            p_debit_account := v_rule.debit_account_code,
            p_credit_account := v_rule.credit_account_code,
            p_amount := NEW.total_refund
        );
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_journal_refund"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auto_journal_reservation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_rule RECORD;
    v_amount numeric;
    v_event_type text;
    v_description text;
    v_branch_id integer;
BEGIN
    -- Solo actuar cuando el status cambia
    IF (NEW.status IS NOT DISTINCT FROM OLD.status) THEN
        RETURN NEW;
    END IF;

    -- Determinar event_type segun el nuevo status
    v_event_type := CASE NEW.status
        WHEN 'confirmed' THEN 'confirmed'
        WHEN 'cancelled' THEN 'cancelled'
        WHEN 'no_show' THEN 'no_show'
        ELSE NULL
    END;

    IF v_event_type IS NULL THEN
        RETURN NEW;
    END IF;

    -- Solo si hay monto estimado
    v_amount := COALESCE(NEW.total_estimated, 0);
    IF v_amount <= 0 THEN
        RETURN NEW;
    END IF;

    v_branch_id := COALESCE(NEW.branch_id, 0);

    -- Buscar regla contable
    SELECT * INTO v_rule
    FROM accounting_rules
    WHERE organization_id = NEW.organization_id
      AND source_type = 'reservation'
      AND event_type = v_event_type
      AND is_active = true
    LIMIT 1;

    IF NOT FOUND THEN
        RETURN NEW;
    END IF;

    v_description := CASE v_event_type
        WHEN 'confirmed' THEN 'Anticipo Reserva ' || NEW.id::text
        WHEN 'cancelled' THEN 'Reversa Cancelacion Reserva ' || NEW.id::text
        WHEN 'no_show' THEN 'Penalidad No-Show Reserva ' || NEW.id::text
    END;

    -- CORREGIDO: orden correcto de parámetros
    PERFORM fn_create_journal_entry(
        p_organization_id := NEW.organization_id,
        p_branch_id := v_branch_id,
        p_entry_date := COALESCE(NEW.updated_at, now()),
        p_memo := v_description,
        p_source := 'reservation',
        p_source_id := NEW.id::text,
        p_debit_account := v_rule.debit_account_code,
        p_credit_account := v_rule.credit_account_code,
        p_amount := v_amount
    );

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_journal_reservation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auto_journal_sale"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_rule RECORD;
    v_entry_id integer;
    v_is_credit boolean;
BEGIN
    IF NEW.document_type IS NOT NULL AND NEW.document_type != 'invoice' THEN
        RETURN NEW;
    END IF;

    v_is_credit := (NEW.payment_method = 'credit');

    -- Preferir la regla cuyo conditions coincida con is_credit
    SELECT * INTO v_rule
    FROM accounting_rules
    WHERE organization_id = NEW.organization_id
      AND source_type = 'sale'
      AND event_type = 'created'
      AND is_active = true
      AND (conditions->>'is_credit')::boolean = v_is_credit
    ORDER BY priority
    LIMIT 1;

    -- Fallback: si no hay regla con condiciones, usar la de menor prioridad
    IF v_rule IS NULL THEN
        SELECT * INTO v_rule
        FROM accounting_rules
        WHERE organization_id = NEW.organization_id
          AND source_type = 'sale'
          AND event_type = 'created'
          AND is_active = true
        ORDER BY priority
        LIMIT 1;
    END IF;

    IF v_rule IS NULL THEN
        RETURN NEW;
    END IF;

    v_entry_id := fn_create_journal_entry(
        p_organization_id := NEW.organization_id,
        p_branch_id := NEW.branch_id,
        p_entry_date := COALESCE(NEW.issue_date, now()),
        p_memo := 'Venta ' || COALESCE(NEW.number, NEW.id::text),
        p_source := 'invoice_sales',
        p_source_id := NEW.id::text,
        p_debit_account := v_rule.debit_account_code,
        p_credit_account := v_rule.credit_account_code,
        p_amount := NEW.total,
        p_tax_account := v_rule.tax_account_code,
        p_tax_amount := CASE WHEN v_rule.use_tax_from_document THEN NEW.tax_total ELSE 0 END
    );

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_journal_sale"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_auto_journal_sale"() IS 'Trigger para asiento automático de ventas';



CREATE OR REPLACE FUNCTION "public"."fn_auto_journal_sale_item_cogs"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_rule RECORD;
    v_entry_id integer;
    v_sale RECORD;
    v_unit_cost numeric;
    v_cogs_amount numeric;
BEGIN
    -- Solo procesar si hay product_id
    IF NEW.product_id IS NULL THEN
        RETURN NEW;
    END IF;

    -- Obtener datos de la venta
    SELECT * INTO v_sale
    FROM sales
    WHERE id = NEW.sale_id;

    IF v_sale IS NULL THEN
        RETURN NEW;
    END IF;

    -- Obtener costo unitario del último movimiento de stock de entrada
    SELECT unit_cost INTO v_unit_cost
    FROM stock_movements
    WHERE product_id = NEW.product_id
      AND organization_id = v_sale.organization_id
      AND direction = 'in'
    ORDER BY created_at DESC
    LIMIT 1;

    v_unit_cost := COALESCE(v_unit_cost, 0);
    v_cogs_amount := NEW.quantity * v_unit_cost;

    IF v_cogs_amount = 0 THEN
        RETURN NEW;
    END IF;

    -- Buscar regla de CMV (source_type='inventory', event_type='confirmed')
    SELECT * INTO v_rule
    FROM accounting_rules
    WHERE organization_id = v_sale.organization_id
      AND source_type = 'inventory'
      AND event_type = 'confirmed'
      AND is_active = true
    ORDER BY priority
    LIMIT 1;

    IF v_rule IS NULL THEN
        RETURN NEW;
    END IF;

    -- Crear asiento: débito CMV, crédito Inventario
    v_entry_id := fn_create_journal_entry(
        p_organization_id := v_sale.organization_id,
        p_branch_id := v_sale.branch_id,
        p_entry_date := COALESCE(NEW.created_at, now()),
        p_memo := 'CMV - Venta Prod:' || NEW.product_id,
        p_source := 'sale_items',
        p_source_id := NEW.id::text,
        p_debit_account := v_rule.debit_account_code,
        p_credit_account := v_rule.credit_account_code,
        p_amount := v_cogs_amount
    );

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_journal_sale_item_cogs"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auto_journal_sale_pos"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_rule RECORD;
    v_entry_id integer;
    v_event_type text;
    v_memo text;
    v_existing_id integer;
BEGIN
    -- Solo procesar ventas confirmadas o pagadas
    IF NEW.status NOT IN ('paid', 'confirmed', 'completed') THEN
        RETURN NEW;
    END IF;

    -- IDEMPOTENCIA: si ya existe un asiento para esta venta, no crear otro
    SELECT id INTO v_existing_id
    FROM journal_entries
    WHERE source = 'sales' AND source_id = NEW.id::text
    LIMIT 1;

    IF v_existing_id IS NOT NULL THEN
        RETURN NEW;
    END IF;

    -- Determinar event_type
    v_event_type := CASE NEW.status
        WHEN 'paid' THEN 'paid'
        WHEN 'confirmed' THEN 'created'
        WHEN 'completed' THEN 'created'
    END;

    -- Buscar regla con event_type específico
    SELECT * INTO v_rule
    FROM accounting_rules
    WHERE organization_id = NEW.organization_id
      AND source_type = 'sale'
      AND event_type = v_event_type
      AND is_active = true
    ORDER BY priority
    LIMIT 1;

    -- Fallback: buscar cualquier regla de sale con event_type='created'
    IF v_rule IS NULL THEN
        SELECT * INTO v_rule
        FROM accounting_rules
        WHERE organization_id = NEW.organization_id
          AND source_type = 'sale'
          AND event_type = 'created'
          AND is_active = true
        ORDER BY priority
        LIMIT 1;
    END IF;

    -- Fallback final: cualquier regla de sale
    IF v_rule IS NULL THEN
        SELECT * INTO v_rule
        FROM accounting_rules
        WHERE organization_id = NEW.organization_id
          AND source_type = 'sale'
          AND is_active = true
        ORDER BY priority
        LIMIT 1;
    END IF;

    IF v_rule IS NULL THEN
        RETURN NEW;
    END IF;

    v_memo := 'Venta POS ' || COALESCE(NEW.id::text, '');

    -- Crear asiento contable
    v_entry_id := fn_create_journal_entry(
        p_organization_id := NEW.organization_id,
        p_branch_id := COALESCE(NEW.branch_id, 0),
        p_entry_date := COALESCE(NEW.sale_date, NEW.created_at, now()),
        p_memo := v_memo,
        p_source := 'sales',
        p_source_id := NEW.id::text,
        p_debit_account := v_rule.debit_account_code,
        p_credit_account := v_rule.credit_account_code,
        p_amount := NEW.total,
        p_tax_account := v_rule.tax_account_code,
        p_tax_amount := CASE WHEN v_rule.use_tax_from_document THEN NEW.tax_total ELSE 0 END
    );

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_journal_sale_pos"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auto_journal_shipment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_rule RECORD;
    v_amount numeric;
    v_description text;
    v_org_id integer;
    v_branch_id integer;
    v_event_type text;
    v_carrier_type text;
BEGIN
    v_org_id := NEW.organization_id;
    v_branch_id := COALESCE(NEW.branch_id, 0);

    -- Determinar tipo de evento
    -- INSERT con shipping_fee > 0 y no viene de web_order = created
    IF TG_OP = 'INSERT' AND NEW.source_type IS DISTINCT FROM 'web_order' THEN
        v_event_type := 'created';
        v_amount := COALESCE(NEW.shipping_fee, 0);
        IF v_amount <= 0 THEN
            RETURN NEW;
        END IF;

        v_description := 'Flete Envío ' || COALESCE(NEW.shipment_number, NEW.id::text);

        -- Buscar regla de flete
        SELECT * INTO v_rule
        FROM accounting_rules
        WHERE organization_id = v_org_id
          AND source_type = 'shipment'
          AND event_type = 'created'
          AND is_active = true
          AND priority = 10
        LIMIT 1;

        IF FOUND THEN
            PERFORM fn_create_journal_entry(
                v_org_id, v_branch_id, COALESCE(NEW.created_at, now()),
                v_description, 'shipment', NEW.id::text,
                v_rule.debit_account_code, v_rule.credit_account_code,
                v_amount
            );
        END IF;

        -- Regla de seguro si aplica
        v_amount := COALESCE(NEW.insurance_fee, 0);
        IF v_amount > 0 THEN
            v_description := 'Seguro Envío ' || COALESCE(NEW.shipment_number, NEW.id::text);
            SELECT * INTO v_rule
            FROM accounting_rules
            WHERE organization_id = v_org_id
              AND source_type = 'shipment'
              AND event_type = 'created'
              AND is_active = true
              AND priority = 11
            LIMIT 1;

            IF FOUND THEN
                PERFORM fn_create_journal_entry(
                    v_org_id, v_branch_id, COALESCE(NEW.created_at, now()),
                    v_description, 'shipment', NEW.id::text,
                    v_rule.debit_account_code, v_rule.credit_account_code,
                    v_amount
                );
            END IF;
        END IF;

        RETURN NEW;
    END IF;

    -- UPDATE: cambio de status
    IF TG_OP = 'UPDATE' AND (NEW.status IS DISTINCT FROM OLD.status) THEN

        -- DELIVERED con COD > 0
        IF NEW.status = 'delivered' AND COALESCE(NEW.cod_amount, 0) > 0 THEN
            v_event_type := 'delivered_cod';
            v_amount := NEW.cod_amount;
            v_description := 'COD Entregado - Envío ' || COALESCE(NEW.shipment_number, NEW.id::text);

            SELECT * INTO v_rule
            FROM accounting_rules
            WHERE organization_id = v_org_id
              AND source_type = 'shipment'
              AND event_type = 'delivered_cod'
              AND is_active = true
            LIMIT 1;

            IF FOUND THEN
                PERFORM fn_create_journal_entry(
                    v_org_id, v_branch_id, COALESCE(NEW.delivered_at, now()),
                    v_description, 'shipment', NEW.id::text,
                    v_rule.debit_account_code, v_rule.credit_account_code,
                    v_amount
                );
            END IF;
        END IF;

        -- RETURNED: reversa de flete (solo si no viene de web_order)
        IF NEW.status = 'returned' AND NEW.source_type IS DISTINCT FROM 'web_order' THEN
            v_amount := COALESCE(NEW.shipping_fee, 0);
            IF v_amount > 0 THEN
                v_description := 'Reversa Flete - Envío Devuelto ' || COALESCE(NEW.shipment_number, NEW.id::text);

                SELECT * INTO v_rule
                FROM accounting_rules
                WHERE organization_id = v_org_id
                  AND source_type = 'shipment'
                  AND event_type = 'returned'
                  AND is_active = true
                LIMIT 1;

                IF FOUND THEN
                    PERFORM fn_create_journal_entry(
                        v_org_id, v_branch_id, now(),
                        v_description, 'shipment', NEW.id::text,
                        v_rule.debit_account_code, v_rule.credit_account_code,
                        v_amount
                    );
                END IF;
            END IF;
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_journal_shipment"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auto_journal_stock_movement"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_rule RECORD;
    v_amount numeric;
    v_unit_cost numeric;
    v_description text;
    v_product_name text;
    v_existing_entry integer;
    v_debit_account text;
    v_credit_account text;
BEGIN
    -- Excluir movimientos de setup inicial, compras y transferencias
    IF NEW.source IN ('initial', 'purchase', 'transfer') THEN
        RETURN NEW;
    END IF;

    IF NEW.direction NOT IN ('out', 'in') THEN
        RETURN NEW;
    END IF;

    -- Obtener costo unitario
    v_unit_cost := COALESCE(NEW.unit_cost, 0);
    IF v_unit_cost = 0 THEN
        SELECT sl.avg_cost INTO v_unit_cost
        FROM stock_levels sl
        WHERE sl.product_id = NEW.product_id
          AND sl.branch_id = NEW.branch_id
        LIMIT 1;
    END IF;

    v_amount := ABS(NEW.qty) * COALESCE(v_unit_cost, 0);
    IF v_amount <= 0 THEN
        RETURN NEW;
    END IF;

    -- Verificar asiento existente
    SELECT je.id INTO v_existing_entry
    FROM journal_entries je
    WHERE je.source = 'stock_movements'
      AND je.source_id = NEW.id::text
      AND je.organization_id = NEW.organization_id
    LIMIT 1;

    IF v_existing_entry IS NOT NULL THEN
        RETURN NEW;
    END IF;

    -- Buscar regla contable
    SELECT * INTO v_rule
    FROM accounting_rules
    WHERE organization_id = NEW.organization_id
      AND source_type = 'inventory'
      AND event_type = 'adjusted'
      AND is_active = true
    ORDER BY priority
    LIMIT 1;

    IF v_rule IS NULL THEN
        RETURN NEW;
    END IF;

    -- Resolver sub-cuentas por sucursal (1405 → 1405-0X, 6105 → 6105-0X)
    SELECT sub_account_code INTO v_debit_account
    FROM branch_account_mappings
    WHERE organization_id = NEW.organization_id
      AND branch_id = NEW.branch_id
      AND base_account_code = v_rule.debit_account_code
    LIMIT 1;

    SELECT sub_account_code INTO v_credit_account
    FROM branch_account_mappings
    WHERE organization_id = NEW.organization_id
      AND branch_id = NEW.branch_id
      AND base_account_code = v_rule.credit_account_code
    LIMIT 1;

    -- Fallback a cuenta base si no hay sub-cuenta
    v_debit_account := COALESCE(v_debit_account, v_rule.debit_account_code);
    v_credit_account := COALESCE(v_credit_account, v_rule.credit_account_code);

    SELECT name INTO v_product_name FROM products WHERE id = NEW.product_id LIMIT 1;

    IF NEW.direction = 'out' THEN
        v_description := 'Salida Inventario - ' || COALESCE(v_product_name, 'Prod:' || NEW.product_id) || ' - ' || COALESCE(NEW.source, '');
        PERFORM fn_create_journal_entry(
            NEW.organization_id, NEW.branch_id, COALESCE(NEW.created_at, now()),
            v_description, 'stock_movements', NEW.id::text,
            v_debit_account, v_credit_account, v_amount
        );
    ELSE
        v_description := 'Entrada Ajuste - ' || COALESCE(v_product_name, 'Prod:' || NEW.product_id);
        PERFORM fn_create_journal_entry(
            NEW.organization_id, NEW.branch_id, COALESCE(NEW.created_at, now()),
            v_description, 'stock_movements', NEW.id::text,
            v_credit_account, v_debit_account, v_amount
        );
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_journal_stock_movement"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auto_journal_tip"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_rule RECORD;
    v_entry_id integer;
    v_default_branch integer;
BEGIN
    IF COALESCE(NEW.amount, 0) <= 0 THEN
        RETURN NEW;
    END IF;

    SELECT MIN(id) INTO v_default_branch FROM branches WHERE organization_id = NEW.organization_id;

    SELECT * INTO v_rule
    FROM accounting_rules
    WHERE organization_id = NEW.organization_id
      AND source_type = 'tip'
      AND is_active = true
    ORDER BY priority LIMIT 1;

    IF v_rule IS NULL THEN
        RETURN NEW;
    END IF;

    v_entry_id := fn_create_journal_entry(
        p_organization_id := NEW.organization_id,
        p_branch_id := COALESCE(NEW.branch_id, v_default_branch),
        p_entry_date := COALESCE(NEW.created_at, now()),
        p_memo := 'Propina - ' || COALESCE(NEW.id::text, ''),
        p_source := 'tips',
        p_source_id := NEW.id::text,
        p_debit_account := v_rule.debit_account_code,
        p_credit_account := v_rule.credit_account_code,
        p_amount := NEW.amount
    );

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_journal_tip"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auto_journal_transport_incident"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_rule RECORD;
    v_amount numeric;
    v_description text;
    v_org_id integer;
BEGIN
    -- Solo en UPDATE cuando cambia el status
    IF TG_OP != 'UPDATE' THEN
        RETURN NEW;
    END IF;

    IF (NEW.status IS NOT DISTINCT FROM OLD.status) THEN
        RETURN NEW;
    END IF;

    v_org_id := NEW.organization_id;

    -- Solo cuando se resuelve o cierra con costo real
    IF NEW.status IN ('resolved', 'closed') THEN
        v_amount := COALESCE(NEW.actual_cost, 0);
        IF v_amount <= 0 THEN
            RETURN NEW;
        END IF;

        v_description := 'Incidente Transporte ' || COALESCE(NEW.title, NEW.id::text);

        SELECT * INTO v_rule
        FROM accounting_rules
        WHERE organization_id = v_org_id
          AND source_type = 'transport_incident'
          AND event_type = 'resolved'
          AND is_active = true
        LIMIT 1;

        IF FOUND THEN
            PERFORM fn_create_journal_entry(
                v_org_id, 0, COALESCE(NEW.resolved_at, now()),
                v_description, 'transport_incident', NEW.id::text,
                v_rule.debit_account_code, v_rule.credit_account_code,
                v_amount
            );
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_journal_transport_incident"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auto_journal_trip"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_rule RECORD;
    v_amount numeric;
    v_description text;
    v_org_id integer;
    v_branch_id integer;
    v_seats_sold integer;
BEGIN
    -- Solo en UPDATE cuando cambia el status
    IF TG_OP != 'UPDATE' THEN
        RETURN NEW;
    END IF;

    IF (NEW.status IS NOT DISTINCT FROM OLD.status) THEN
        RETURN NEW;
    END IF;

    v_org_id := NEW.organization_id;
    v_branch_id := COALESCE(NEW.branch_id, 0);

    -- Calcular asientos vendidos
    v_seats_sold := GREATEST(NEW.total_seats - NEW.available_seats, 0);
    v_amount := v_seats_sold * COALESCE(NEW.base_fare, 0);

    IF v_amount <= 0 THEN
        RETURN NEW;
    END IF;

    -- TRIP COMPLETED
    IF NEW.status = 'completed' THEN
        v_description := 'Pasajes Viaje ' || COALESCE(NEW.trip_code, NEW.id::text) || ' (' || v_seats_sold || ' asientos)';

        SELECT * INTO v_rule
        FROM accounting_rules
        WHERE organization_id = v_org_id
          AND source_type = 'trip'
          AND event_type = 'completed'
          AND is_active = true
        LIMIT 1;

        IF FOUND THEN
            PERFORM fn_create_journal_entry(
                v_org_id, v_branch_id, COALESCE(NEW.actual_arrival, NEW.updated_at, now()),
                v_description, 'trip', NEW.id::text,
                v_rule.debit_account_code, v_rule.credit_account_code,
                v_amount
            );
        END IF;

    -- TRIP CANCELLED
    ELSIF NEW.status = 'cancelled' THEN
        v_description := 'Reversa Pasajes - Viaje Cancelado ' || COALESCE(NEW.trip_code, NEW.id::text);

        SELECT * INTO v_rule
        FROM accounting_rules
        WHERE organization_id = v_org_id
          AND source_type = 'trip'
          AND event_type = 'cancelled'
          AND is_active = true
        LIMIT 1;

        IF FOUND THEN
            PERFORM fn_create_journal_entry(
                v_org_id, v_branch_id, now(),
                v_description, 'trip', NEW.id::text,
                v_rule.debit_account_code, v_rule.credit_account_code,
                v_amount
            );
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_journal_trip"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auto_journal_trip_ticket"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_rule RECORD;
    v_entry_id integer;
    v_default_branch integer;
BEGIN
    -- Solo boletos confirmados o con pago
    IF NEW.status NOT IN ('confirmed', 'paid', 'completed') THEN
        RETURN NEW;
    END IF;

    IF COALESCE(NEW.total, 0) <= 0 THEN
        RETURN NEW;
    END IF;

    SELECT MIN(id) INTO v_default_branch FROM branches WHERE organization_id = NEW.organization_id;

    SELECT * INTO v_rule
    FROM accounting_rules
    WHERE organization_id = NEW.organization_id
      AND source_type = 'transport'
      AND is_active = true
    ORDER BY priority LIMIT 1;

    IF v_rule IS NULL THEN
        RETURN NEW;
    END IF;

    v_entry_id := fn_create_journal_entry(
        p_organization_id := NEW.organization_id,
        p_branch_id := v_default_branch,
        p_entry_date := COALESCE(NEW.created_at, now()),
        p_memo := 'Boleto transporte ' || COALESCE(NEW.ticket_number, NEW.id::text),
        p_source := 'trip_tickets',
        p_source_id := NEW.id::text,
        p_debit_account := v_rule.debit_account_code,
        p_credit_account := v_rule.credit_account_code,
        p_amount := NEW.total
    );

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_journal_trip_ticket"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auto_journal_void"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_rule RECORD;
    v_entry_id integer;
BEGIN
    -- Detectar transición a un estado de anulación ('void' es el único permitido
    -- por el check de invoice_sales; se mantienen 'voided'/'cancelled' por robustez).
    IF (NEW.status IN ('void','voided','cancelled'))
       AND (OLD.status IS DISTINCT FROM NEW.status)
       AND (OLD.status NOT IN ('void','voided','cancelled')) THEN

        -- Si el documento es una nota de crédito, no genera asiento de anulación
        -- (la NC ya tiene su propio asiento vía fn_auto_journal_credit_note).
        IF NEW.document_type = 'credit_note' THEN
            RETURN NEW;
        END IF;

        -- Si la factura fue anulada por una nota de crédito relacionada,
        -- la reversión ya quedó registrada; evitar doble asiento.
        IF EXISTS (
            SELECT 1 FROM invoice_sales cn
            WHERE cn.related_invoice_id = NEW.id
              AND cn.document_type = 'credit_note'
        ) THEN
            RETURN NEW;
        END IF;

        -- Buscar regla de anulación de venta
        SELECT * INTO v_rule
        FROM accounting_rules
        WHERE organization_id = NEW.organization_id
          AND source_type = 'sale'
          AND event_type = 'voided'
          AND is_active = true
        ORDER BY priority
        LIMIT 1;

        IF v_rule IS NULL THEN
            RETURN NEW;
        END IF;

        -- Crear asiento de reversión (inverso al original de la venta)
        -- Usar source_id con sufijo ':void' para evitar violación de unique constraint
        v_entry_id := fn_create_journal_entry(
            p_organization_id := NEW.organization_id,
            p_branch_id := NEW.branch_id,
            p_entry_date := now(),
            p_memo := 'Anulación Factura ' || COALESCE(NEW.number, NEW.id::text),
            p_source := 'invoice_sales',
            p_source_id := NEW.id::text || ':void',
            p_debit_account := v_rule.debit_account_code,
            p_credit_account := v_rule.credit_account_code,
            p_amount := ABS(COALESCE(NEW.total, 0)),
            p_tax_account := v_rule.tax_account_code,
            p_tax_amount := CASE WHEN v_rule.use_tax_from_document THEN ABS(COALESCE(NEW.tax_total, 0)) ELSE 0 END
        );
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_journal_void"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auto_journal_web_order"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_invoice RECORD;
    v_invoice_id uuid;
    v_existing_invoice uuid;
BEGIN
    -- Solo cuando el pedido cambia a 'confirmed' o 'completed' y tiene sale_id
    IF (NEW.status = 'confirmed' OR NEW.status = 'completed' OR NEW.status = 'delivered')
       AND (OLD.status IS DISTINCT FROM NEW.status)
       AND NEW.sale_id IS NOT NULL THEN

        -- Verificar si ya existe una factura para esta venta
        SELECT id INTO v_existing_invoice
        FROM invoice_sales
        WHERE sale_id = NEW.sale_id
          AND organization_id = NEW.organization_id
        LIMIT 1;

        -- Si ya existe factura, el trigger de invoice_sales ya la contabilizó
        IF v_existing_invoice IS NOT NULL THEN
            RETURN NEW;
        END IF;

        -- Crear factura de venta desde la web order
        -- Esto disparará el trigger trg_auto_journal_sale existente
        INSERT INTO invoice_sales (
            organization_id, branch_id, customer_id, sale_id,
            number, issue_date, subtotal, tax_total, total,
            status, document_type, tax_included, created_at
        ) VALUES (
            NEW.organization_id,
            NEW.branch_id,
            NULL,
            NEW.sale_id,
            'WEB-' || NEW.id::text,
            COALESCE(NEW.created_at, now()),
            NEW.total - COALESCE(NEW.tax_total, 0),
            COALESCE(NEW.tax_total, 0),
            NEW.total,
            'confirmed',
            'invoice',
            false,
            now()
        ) RETURNING id INTO v_invoice_id;

        RETURN NEW;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_journal_web_order"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auto_tag_conversation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_content_lower text;
  v_current_priority text;
  v_new_priority text := NULL;
  v_msg_count int;
BEGIN
  -- Solo procesar mensajes de clientes (inbound)
  IF NEW.direction = 'inbound' THEN
    v_content_lower := LOWER(COALESCE(NEW.content, ''));
    
    SELECT priority INTO v_current_priority FROM conversations WHERE id = NEW.conversation_id;
    
    -- ALTA: urgencias reales (patrones con límites de palabra)
    IF v_content_lower ~ '\murgente?\M' OR v_content_lower ~ '\masap\M'
       OR v_content_lower LIKE '%inmediato%' OR v_content_lower LIKE '%emergencia%'
       OR v_content_lower LIKE '%emergency%' OR v_content_lower LIKE '%lo antes posible%' THEN
      PERFORM fn_apply_conversation_tag(NEW.conversation_id, 'Urgente', '#ef4444');
      v_new_priority := 'high';
    END IF;
    
    -- ALTA: quejas y reclamos
    IF v_content_lower LIKE '%queja%' OR v_content_lower LIKE '%complaint%' 
       OR v_content_lower LIKE '%molest%' OR v_content_lower LIKE '%insatisf%'
       OR v_content_lower LIKE '%reclamo%' OR v_content_lower LIKE '%devolucion%'
       OR v_content_lower LIKE '%devolución%' OR v_content_lower LIKE '%pesimo%'
       OR v_content_lower LIKE '%pésimo%' OR v_content_lower LIKE '%estafa%' THEN
      PERFORM fn_apply_conversation_tag(NEW.conversation_id, 'Queja', '#f97316');
      v_new_priority := 'high';
    END IF;
    
    -- NORMAL: ventas/compras
    IF v_content_lower LIKE '%precio%' OR v_content_lower LIKE '%comprar%' 
       OR v_content_lower LIKE '%cotiza%' OR v_content_lower LIKE '%presupuesto%'
       OR v_content_lower LIKE '%disponible%' OR v_content_lower LIKE '%interesado%'
       OR v_content_lower LIKE '%cuánto cuesta%' OR v_content_lower LIKE '%cuanto cuesta%'
       OR v_content_lower LIKE '%pedido%' THEN
      PERFORM fn_apply_conversation_tag(NEW.conversation_id, 'Venta', '#22c55e');
      IF v_new_priority IS NULL THEN
        v_new_priority := 'normal';
      END IF;
    END IF;
    
    -- NORMAL: soporte técnico
    IF v_content_lower ~ '\merror\M' OR v_content_lower LIKE '%no funciona%' 
       OR v_content_lower LIKE '%problema%' OR v_content_lower LIKE '%no sirve%'
       OR v_content_lower LIKE '%soporte%' OR v_content_lower LIKE '%falla%'
       OR v_content_lower LIKE '%dañado%' OR v_content_lower LIKE '%danado%' THEN
      PERFORM fn_apply_conversation_tag(NEW.conversation_id, 'Soporte', '#3b82f6');
      IF v_new_priority IS NULL THEN
        v_new_priority := 'normal';
      END IF;
    END IF;
    
    -- NORMAL: facturación
    IF v_content_lower LIKE '%factura%' OR v_content_lower ~ '\mpago\M'
       OR v_content_lower LIKE '%cobro%' OR v_content_lower LIKE '%recibo%' THEN
      PERFORM fn_apply_conversation_tag(NEW.conversation_id, 'Facturación', '#8b5cf6');
      IF v_new_priority IS NULL THEN
        v_new_priority := 'normal';
      END IF;
    END IF;
    
    -- BAJA: saludos/agradecimientos al inicio de la conversación (primeros 2 mensajes inbound)
    IF v_new_priority IS NULL THEN
      SELECT COUNT(*) INTO v_msg_count FROM messages 
      WHERE conversation_id = NEW.conversation_id AND direction = 'inbound';
      
      IF v_msg_count <= 2 AND (
         v_content_lower ~ '^\s*(hola|buenos dias|buenos días|buenas tardes|buenas noches|buen dia|buen día|hey|hi|hello)\M'
         OR v_content_lower LIKE '%gracias%'
      ) THEN
        v_new_priority := 'low';
      END IF;
    END IF;
    
    -- Actualizar prioridad:
    -- 'high' siempre escala. 'normal' sube desde low/NULL. 'low' solo aplica al inicio si está en el valor por defecto.
    IF v_new_priority = 'high' AND v_current_priority IS DISTINCT FROM 'high' THEN
      UPDATE conversations SET priority = 'high', updated_at = NOW() WHERE id = NEW.conversation_id;
    ELSIF v_new_priority = 'normal' AND (v_current_priority IS NULL OR v_current_priority = 'low') THEN
      UPDATE conversations SET priority = 'normal', updated_at = NOW() WHERE id = NEW.conversation_id;
    ELSIF v_new_priority = 'low' AND (v_current_priority IS NULL OR v_current_priority = 'normal') THEN
      UPDATE conversations SET priority = 'low', updated_at = NOW() WHERE id = NEW.conversation_id;
    END IF;
  END IF;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_tag_conversation"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_auto_tag_conversation"() IS 'Aplica etiquetas automáticamente basado en palabras clave en mensajes entrantes';



CREATE OR REPLACE FUNCTION "public"."fn_availability"("p_start_date" "date", "p_end_date" "date", "p_space_type_id" "uuid" DEFAULT NULL::"uuid", "p_branch_id" integer DEFAULT NULL::integer) RETURNS TABLE("space_id" "uuid", "space_label" "text", "space_type_name" "text", "floor_zone" "text", "is_available" boolean, "current_status" "text", "next_reservation_checkin" "date")
    LANGUAGE "plpgsql" STABLE
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    s.id AS space_id,
    s.label AS space_label,
    st.name AS space_type_name,
    s.floor_zone,
    -- Espacio está disponible si:
    -- 1. No está en mantenimiento/fuera de servicio
    -- 2. No tiene reservas confirmadas/checked_in que se solapen
    (
      s.status NOT IN ('out_of_order', 'maintenance')
      AND NOT EXISTS (
        SELECT 1 
        FROM reservation_spaces rs
        JOIN reservations r ON rs.reservation_id = r.id
        WHERE rs.space_id = s.id
          AND r.status IN ('confirmed', 'checked_in')
          AND daterange(r.checkin, r.checkout, '[)') && 
              daterange(p_start_date, p_end_date, '[)')
      )
    ) AS is_available,
    s.status::TEXT AS current_status,
    -- Próxima reserva para este espacio
    (
      SELECT MIN(r.checkin)
      FROM reservation_spaces rs
      JOIN reservations r ON rs.reservation_id = r.id
      WHERE rs.space_id = s.id
        AND r.status IN ('confirmed', 'checked_in')
        AND r.checkin >= p_start_date
    ) AS next_reservation_checkin
  FROM spaces s
  JOIN space_types st ON s.space_type_id = st.id
  WHERE 
    (p_space_type_id IS NULL OR s.space_type_id = p_space_type_id)
    AND (p_branch_id IS NULL OR s.branch_id = p_branch_id)
  ORDER BY s.label;
END;
$$;


ALTER FUNCTION "public"."fn_availability"("p_start_date" "date", "p_end_date" "date", "p_space_type_id" "uuid", "p_branch_id" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_availability"("p_start_date" "date", "p_end_date" "date", "p_space_type_id" "uuid", "p_branch_id" integer) IS 'Consulta disponibilidad de espacios en un rango de fechas. 
Retorna todos los espacios con su estado de disponibilidad.
Uso: SELECT * FROM fn_availability(''2025-11-10'', ''2025-11-15'');';



