CREATE OR REPLACE FUNCTION "public"."fn_branch_set_default"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_count integer;
  v_branch integer;
BEGIN
  -- Ya trae sucursal o no hay organización: no hacemos nada
  IF NEW.branch_id IS NOT NULL OR NEW.organization_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- 1) Si el usuario tiene EXACTAMENTE una sucursal asignada en esta organización, usarla
  IF v_uid IS NOT NULL THEN
    SELECT count(*), min(mb.branch_id)
      INTO v_count, v_branch
    FROM public.member_branches mb
    JOIN public.organization_members om ON om.id = mb.organization_member_id
    WHERE om.user_id = v_uid
      AND om.organization_id = NEW.organization_id
      AND om.is_active = true;

    IF v_count = 1 THEN
      NEW.branch_id := v_branch;
      RETURN NEW;
    END IF;
  END IF;

  -- 2) Fallback: sucursal principal de la organización
  SELECT id INTO v_branch
  FROM public.branches
  WHERE organization_id = NEW.organization_id AND is_main = true
  ORDER BY id
  LIMIT 1;

  -- 3) Fallback final: primera sucursal de la organización
  IF v_branch IS NULL THEN
    SELECT id INTO v_branch
    FROM public.branches
    WHERE organization_id = NEW.organization_id
    ORDER BY id
    LIMIT 1;
  END IF;

  NEW.branch_id := v_branch;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_branch_set_default"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_branch_write_audit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org integer;
  v_branch integer;
  v_entity_id text;
  v_prev jsonb;
  v_new jsonb;
  v_changed text[];
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_org := OLD.organization_id;
    v_branch := OLD.branch_id;
    v_entity_id := OLD.id::text;
    v_prev := to_jsonb(OLD);
    v_new := NULL;
  ELSIF TG_OP = 'INSERT' THEN
    v_org := NEW.organization_id;
    v_branch := NEW.branch_id;
    v_entity_id := NEW.id::text;
    v_prev := NULL;
    v_new := to_jsonb(NEW);
  ELSE
    v_org := NEW.organization_id;
    v_branch := NEW.branch_id;
    v_entity_id := NEW.id::text;
    v_prev := to_jsonb(OLD);
    v_new := to_jsonb(NEW);
    SELECT array_agg(e.key) INTO v_changed
    FROM jsonb_each(v_new) e
    WHERE e.value IS DISTINCT FROM (v_prev -> e.key);
  END IF;

  INSERT INTO public.ops_audit_log
    (organization_id, branch_id, user_id, entity_type, entity_id, action,
     previous_data, new_data, changed_fields)
  VALUES
    (v_org, v_branch, auth.uid(), TG_TABLE_NAME, v_entity_id, TG_OP,
     v_prev, v_new, v_changed);

  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."fn_branch_write_audit"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_call_quality"("p_org_id" integer, "p_start" "date", "p_end" "date", "p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("user_id" "uuid", "call_date" "date", "total_calls" bigint, "analyzed_calls" bigint, "avg_quality" numeric, "avg_talk_ratio_agent" numeric, "avg_duration_seconds" numeric)
    LANGUAGE "sql" STABLE
    AS $$
  WITH analysis AS (
    SELECT
      ca.call_id,
      AVG(ca.quality_score) AS quality_score,
      AVG(ca.talk_ratio_agent) AS talk_ratio_agent
    FROM call_analyses ca
    WHERE ca.organization_id = p_org_id
    GROUP BY ca.call_id
  )
  SELECT
    c.user_id,
    DATE_TRUNC('day', c.started_at)::date AS call_date,
    COUNT(DISTINCT c.id) AS total_calls,
    COUNT(DISTINCT c.id) FILTER (WHERE a.call_id IS NOT NULL) AS analyzed_calls,
    ROUND(AVG(a.quality_score), 2) AS avg_quality,
    ROUND(AVG(a.talk_ratio_agent), 4) AS avg_talk_ratio_agent,
    ROUND(AVG(c.duration_seconds), 1) AS avg_duration_seconds
  FROM calls c
  LEFT JOIN analysis a ON a.call_id = c.id
  WHERE c.organization_id = p_org_id
    AND c.status = 'completed'
    AND c.started_at >= p_start
    AND c.started_at < p_end
    AND (p_user_id IS NULL OR c.user_id = p_user_id)
  GROUP BY c.user_id, DATE_TRUNC('day', c.started_at)
  ORDER BY call_date DESC, c.user_id;
$$;


ALTER FUNCTION "public"."fn_call_quality"("p_org_id" integer, "p_start" "date", "p_end" "date", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_campaign_mark_bounced"("p_campaign_id" "uuid", "p_customer_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  UPDATE campaign_contacts
  SET 
    state = 'bounced',
    bounced_at = NOW(),
    updated_at = NOW()
  WHERE campaign_id = p_campaign_id AND customer_id = p_customer_id;
  
  IF FOUND THEN
    UPDATE campaigns
    SET statistics = jsonb_set(
      COALESCE(statistics, '{}'::jsonb),
      '{bounced_count}',
      to_jsonb(COALESCE((statistics->>'bounced_count')::int, 0) + 1)
    ),
    updated_at = NOW()
    WHERE id = p_campaign_id;
  END IF;
END;
$$;


ALTER FUNCTION "public"."fn_campaign_mark_bounced"("p_campaign_id" "uuid", "p_customer_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_campaign_mark_bounced"("p_campaign_id" "uuid", "p_customer_id" "uuid") IS 'Registra bounce/rebote de campaña';



CREATE OR REPLACE FUNCTION "public"."fn_campaign_mark_clicked"("p_campaign_id" "uuid", "p_customer_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  UPDATE campaign_contacts
  SET 
    clicked_at = COALESCE(clicked_at, NOW()),
    opened_at = COALESCE(opened_at, NOW()), -- Si hizo click, también abrió
    updated_at = NOW()
  WHERE campaign_id = p_campaign_id AND customer_id = p_customer_id
    AND clicked_at IS NULL;
  
  IF FOUND THEN
    UPDATE campaigns
    SET statistics = jsonb_set(
      COALESCE(statistics, '{}'::jsonb),
      '{clicked_count}',
      to_jsonb(COALESCE((statistics->>'clicked_count')::int, 0) + 1)
    ),
    updated_at = NOW()
    WHERE id = p_campaign_id;
  END IF;
END;
$$;


