CREATE OR REPLACE FUNCTION "public"."fn_campaign_mark_sent"("p_campaign_id" "uuid", "p_customer_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_contact_id uuid;
BEGIN
  UPDATE campaign_contacts
  SET 
    state = 'sent',
    sent_at = NOW(),
    updated_at = NOW()
  WHERE campaign_id = p_campaign_id AND customer_id = p_customer_id
  RETURNING id INTO v_contact_id;
  
  -- Si no existe, crear el registro
  IF v_contact_id IS NULL THEN
    INSERT INTO campaign_contacts (campaign_id, customer_id, state, sent_at, created_at, updated_at)
    VALUES (p_campaign_id, p_customer_id, 'sent', NOW(), NOW(), NOW())
    RETURNING id INTO v_contact_id;
  END IF;
  
  -- Actualizar estadísticas de la campaña
  UPDATE campaigns
  SET statistics = jsonb_set(
    COALESCE(statistics, '{}'::jsonb),
    '{sent_count}',
    to_jsonb(COALESCE((statistics->>'sent_count')::int, 0) + 1)
  ),
  updated_at = NOW()
  WHERE id = p_campaign_id;
  
  RETURN v_contact_id;
END;
$$;


ALTER FUNCTION "public"."fn_campaign_mark_sent"("p_campaign_id" "uuid", "p_customer_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_campaign_mark_sent"("p_campaign_id" "uuid", "p_customer_id" "uuid") IS 'Marca un contacto como enviado en una campaña';



CREATE OR REPLACE FUNCTION "public"."fn_can_contact"("p_org" integer, "p_customer" "uuid", "p_channel" "text", "p_purpose" "text" DEFAULT 'utility'::"text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_meta jsonb;
  v_dnc boolean;
  v_consent text;
  v_flag text;
BEGIN
  -- fail-closed: canal desconocido o NULL => no contactar
  IF p_channel IS NULL OR p_channel NOT IN ('email','whatsapp','sms','voice') THEN RETURN false; END IF;
  -- p_purpose se ignora explicitamente en F0 (reservado para reglas marketing/utility/transactional)
  SELECT metadata, do_not_call INTO v_meta, v_dnc
    FROM public.customers WHERE id = p_customer AND organization_id = p_org;
  IF NOT FOUND THEN RETURN false; END IF;

  -- F6: columna real de "no llamar" (solo aplica al canal de voz)
  IF p_channel = 'voice' AND COALESCE(v_dnc, false) THEN RETURN false; END IF;

  SELECT status INTO v_consent FROM public.contact_consents
   WHERE organization_id = p_org AND customer_id = p_customer AND channel = p_channel;
  IF v_consent = 'opted_out' THEN RETURN false; END IF;

  v_flag := CASE p_channel
              WHEN 'email' THEN 'do_not_email'
              WHEN 'whatsapp' THEN 'do_not_whatsapp'
              WHEN 'sms' THEN 'do_not_sms'
              WHEN 'voice' THEN 'do_not_call'
              ELSE NULL END;
  IF v_flag IS NOT NULL AND COALESCE(v_meta ->> v_flag, 'false') IN ('true','1') THEN RETURN false; END IF;
  RETURN true;
END $$;


ALTER FUNCTION "public"."fn_can_contact"("p_org" integer, "p_customer" "uuid", "p_channel" "text", "p_purpose" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_check_periodic_notifications"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$
DECLARE
  v_rec RECORD;
  v_count INT := 0;
  v_owner_id UUID;
  v_ai_credits INT;
  v_ai_max INT;
BEGIN
  -- =============================================
  -- 1. TRIAL POR VENCER (≤ 3 días)
  -- =============================================
  FOR v_rec IN
    SELECT s.organization_id, s.trial_end, o.owner_user_id
    FROM subscriptions s
    JOIN organizations o ON o.id = s.organization_id
    WHERE s.status = 'trialing'
      AND s.trial_end IS NOT NULL
      AND s.trial_end BETWEEN now() AND now() + INTERVAL '3 days'
      -- Evitar duplicados: no notificar si ya se envió hoy
      AND NOT EXISTS (
        SELECT 1 FROM notifications n
        WHERE n.organization_id = s.organization_id
          AND n.payload->>'type' = 'trial_expiring'
          AND n.created_at > now() - INTERVAL '24 hours'
      )
  LOOP
    PERFORM fn_create_org_notification(
      v_rec.organization_id,
      v_rec.owner_user_id,
      'app',
      'trial_expiring',
      'Tu período de prueba está por vencer',
      'Tu trial vence el ' || to_char(v_rec.trial_end, 'DD/MM/YYYY') || '. Actualiza tu plan para no perder acceso.',
      jsonb_build_object('trial_end', v_rec.trial_end::text)
    );
    v_count := v_count + 1;
  END LOOP;

  -- =============================================
  -- 2. CUENTAS POR COBRAR VENCIDAS
  -- =============================================
  FOR v_rec IN
    SELECT ar.organization_id, ar.id, ar.balance, ar.due_date, o.owner_user_id
    FROM accounts_receivable ar
    JOIN organizations o ON o.id = ar.organization_id
    WHERE ar.status NOT IN ('paid', 'cancelled', 'written_off')
      AND ar.due_date < now()
      AND ar.balance > 0
      -- Evitar duplicados: no notificar la misma CxC en 7 días
      AND NOT EXISTS (
        SELECT 1 FROM notifications n
        WHERE n.organization_id = ar.organization_id
          AND n.payload->>'type' = 'ar_overdue'
          AND n.payload->>'ar_id' = ar.id::text
          AND n.created_at > now() - INTERVAL '7 days'
      )
  LOOP
    PERFORM fn_create_org_notification(
      v_rec.organization_id,
      NULL,
      'app',
      'ar_overdue',
      'Cuenta por cobrar vencida',
      'CxC #' || LEFT(v_rec.id::text, 8) || ' vencida el ' || to_char(v_rec.due_date, 'DD/MM/YYYY') || '. Saldo: $' || v_rec.balance,
      jsonb_build_object('ar_id', v_rec.id::text, 'balance', v_rec.balance::text, 'due_date', v_rec.due_date::text)
    );
    v_count := v_count + 1;
  END LOOP;

  -- =============================================
  -- 3. CUENTAS POR PAGAR VENCIDAS
  -- =============================================
  FOR v_rec IN
    SELECT ap.organization_id, ap.id, ap.balance, ap.due_date, o.owner_user_id
    FROM accounts_payable ap
    JOIN organizations o ON o.id = ap.organization_id
    WHERE ap.status NOT IN ('paid', 'cancelled')
      AND ap.due_date < now()
      AND ap.balance > 0
      AND NOT EXISTS (
        SELECT 1 FROM notifications n
        WHERE n.organization_id = ap.organization_id
          AND n.payload->>'type' = 'ap_overdue'
          AND n.payload->>'ap_id' = ap.id::text
          AND n.created_at > now() - INTERVAL '7 days'
      )
  LOOP
    PERFORM fn_create_org_notification(
      v_rec.organization_id,
      NULL,
      'app',
      'ap_overdue',
      'Cuenta por pagar vencida',
      'CxP #' || LEFT(v_rec.id::text, 8) || ' vencida el ' || to_char(v_rec.due_date, 'DD/MM/YYYY') || '. Saldo: $' || v_rec.balance,
      jsonb_build_object('ap_id', v_rec.id::text, 'balance', v_rec.balance::text)
    );
    v_count := v_count + 1;
  END LOOP;

  -- =============================================
  -- 4. CRÉDITOS DE IA BAJOS (≤ 20% del plan)
  -- =============================================
  FOR v_rec IN
    SELECT s.organization_id, o.owner_user_id, p.ai_credits_monthly,
           COALESCE(s.metadata->>'ai_credits_remaining', '0')::int as credits_remaining
    FROM subscriptions s
    JOIN organizations o ON o.id = s.organization_id
    JOIN plans p ON p.id = s.plan_id
    WHERE s.status IN ('active', 'trialing')
      AND p.ai_credits_monthly > 0
      AND COALESCE(s.metadata->>'ai_credits_remaining', '0')::int <= (p.ai_credits_monthly * 0.2)
      AND COALESCE(s.metadata->>'ai_credits_remaining', '0')::int > 0
      AND NOT EXISTS (
        SELECT 1 FROM notifications n
        WHERE n.organization_id = s.organization_id
          AND n.payload->>'type' = 'ai_credits_low'
          AND n.created_at > now() - INTERVAL '3 days'
      )
  LOOP
    PERFORM fn_create_org_notification(
      v_rec.organization_id,
      v_rec.owner_user_id,
      'app',
      'ai_credits_low',
      'Créditos de IA bajos',
      'Te quedan ' || v_rec.credits_remaining || ' créditos de IA (de ' || v_rec.ai_credits_monthly || '). Considera actualizar tu plan.',
      jsonb_build_object('credits_remaining', v_rec.credits_remaining::text, 'credits_max', v_rec.ai_credits_monthly::text)
    );
    v_count := v_count + 1;
  END LOOP;

  -- =============================================
  -- 5. STOCK BAJO GENERAL (revisión periódica)
  -- =============================================
  FOR v_rec IN
    SELECT p.organization_id, p.name as product_name, sl.qty_on_hand, sl.min_level, sl.branch_id
    FROM stock_levels sl
    JOIN products p ON p.id = sl.product_id
    WHERE sl.min_level IS NOT NULL
      AND sl.qty_on_hand <= sl.min_level
      AND sl.qty_on_hand > 0
      AND NOT EXISTS (
        SELECT 1 FROM notifications n
        WHERE n.organization_id = p.organization_id
          AND n.payload->>'type' = 'stock_low_periodic'
          AND n.payload->>'product_name' = p.name
          AND n.created_at > now() - INTERVAL '3 days'
      )
  LOOP
    PERFORM fn_create_org_notification(
      v_rec.organization_id, NULL, 'app', 'stock_low_periodic',
      'Stock bajo: ' || v_rec.product_name,
      'Quedan ' || v_rec.qty_on_hand || ' unidades (mín: ' || v_rec.min_level || '). Reabastece pronto.',
      jsonb_build_object('product_name', v_rec.product_name, 'qty', v_rec.qty_on_hand::text, 'min', v_rec.min_level::text)
    );
    v_count := v_count + 1;
  END LOOP;

  RETURN jsonb_build_object('notifications_created', v_count, 'executed_at', now()::text);
END;
$_$;


ALTER FUNCTION "public"."fn_check_periodic_notifications"() OWNER TO "postgres";

SET default_tablespace = '';

SET default_table_access_method = "heap";


CREATE TABLE IF NOT EXISTS "public"."outbound_jobs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" integer NOT NULL,
    "kind" "text" NOT NULL,
    "payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "status" "text" DEFAULT 'queued'::"text" NOT NULL,
    "run_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "attempts" integer DEFAULT 0 NOT NULL,
    "max_attempts" integer DEFAULT 5 NOT NULL,
    "last_error" "text",
    "locked_at" timestamp with time zone,
    "locked_by" "text",
    "dedupe_key" "text",
    "result" "jsonb",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "outbound_jobs_kind_check" CHECK (("kind" = ANY (ARRAY['email'::"text", 'whatsapp'::"text", 'sms'::"text", 'ai_call'::"text", 'sequence_step'::"text", 'automation'::"text", 'transcribe'::"text", 'analyze'::"text", 'recording_fetch'::"text", 'recording_cleanup'::"text", 'campaign_batch'::"text", 'crm_event'::"text", 'maintenance'::"text", 'noop'::"text", 'time_events'::"text"]))),
    CONSTRAINT "outbound_jobs_status_check" CHECK (("status" = ANY (ARRAY['queued'::"text", 'running'::"text", 'done'::"text", 'failed'::"text", 'dead'::"text"])))
);


ALTER TABLE "public"."outbound_jobs" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_claim_jobs"("p_kinds" "text"[] DEFAULT NULL::"text"[], "p_limit" integer DEFAULT 25, "p_worker" "text" DEFAULT NULL::"text") RETURNS SETOF "public"."outbound_jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- 1) huérfanos (worker muerto > 10 min): re-encolar o matar si agotaron intentos
  UPDATE public.outbound_jobs
     SET status = CASE WHEN attempts >= max_attempts THEN 'dead' ELSE 'queued' END,
         locked_at = NULL, locked_by = NULL,
         last_error = left(COALESCE(last_error,'') || ' [reclaimed: lock expirado]', 4000)
   WHERE status = 'running' AND locked_at < now() - interval '10 minutes'
     AND (p_kinds IS NULL OR kind = ANY (p_kinds));
  -- 2) reclamar
  RETURN QUERY
  UPDATE public.outbound_jobs j
     SET status = 'running', locked_at = now(), locked_by = COALESCE(p_worker, 'unknown'), attempts = j.attempts + 1
   WHERE j.id IN (
     SELECT id FROM public.outbound_jobs
      WHERE status = 'queued' AND run_at <= now() AND (p_kinds IS NULL OR kind = ANY (p_kinds))
      ORDER BY run_at ASC
      FOR UPDATE SKIP LOCKED
      LIMIT GREATEST(1, LEAST(COALESCE(p_limit, 25), 200)))
  RETURNING j.*;
END $$;


ALTER FUNCTION "public"."fn_claim_jobs"("p_kinds" "text"[], "p_limit" integer, "p_worker" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."voice_agent_calls" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" integer NOT NULL,
    "voice_agent_id" "uuid" NOT NULL,
    "campaign_id" "uuid",
    "call_id" "uuid",
    "customer_id" "uuid",
    "opportunity_id" "uuid",
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "outcome" "text",
    "conversation_log" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "turns_count" integer DEFAULT 0 NOT NULL,
    "duration_seconds" integer,
    "scheduled_at" timestamp with time zone,
    "started_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "error_message" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "provider_call_sid" "text",
    "attempts" integer DEFAULT 0 NOT NULL,
    "stage_agent_id" "uuid",
    "claimed_at" timestamp with time zone,
    "locked_by" "text",
    "consent_given" boolean DEFAULT false NOT NULL,
    "last_error_code" "text",
    "credits_reserved" integer DEFAULT 0 NOT NULL,
    "credits_settled_at" timestamp with time zone,
    CONSTRAINT "voice_agent_calls_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'queued'::"text", 'in_progress'::"text", 'completed'::"text", 'failed'::"text", 'transferred'::"text", 'no_answer'::"text", 'voicemail'::"text", 'canceled'::"text", 'skipped'::"text"])))
);


ALTER TABLE "public"."voice_agent_calls" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_claim_voice_agent_call_one"("p_org" integer, "p_call" "uuid", "p_worker" "text") RETURNS SETOF "public"."voice_agent_calls"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH candidato AS (
    SELECT vac.id
      FROM public.voice_agent_calls vac
     WHERE vac.organization_id = p_org
       AND vac.id = p_call
       AND vac.status IN ('pending','queued')
     FOR UPDATE SKIP LOCKED
  ), reclamada AS (
    UPDATE public.voice_agent_calls v
       SET status = 'in_progress',
           claimed_at = now(),
           locked_by = p_worker,
           attempts = v.attempts + 1,
           updated_at = now()
      FROM candidato c
     WHERE v.id = c.id
    RETURNING v.*
  ), registrada AS (
    INSERT INTO public.voice_agent_call_attempts
      (organization_id, voice_agent_call_id, voice_agent_id, campaign_id, customer_id, attempt_no, source, worker)
    SELECT r.organization_id, r.id, r.voice_agent_id, r.campaign_id, r.customer_id, r.attempts, 'manual', p_worker
      FROM reclamada r
    RETURNING voice_agent_call_id
  )
  SELECT r.* FROM reclamada r
   WHERE r.id IN (SELECT voice_agent_call_id FROM registrada);
END $$;


ALTER FUNCTION "public"."fn_claim_voice_agent_call_one"("p_org" integer, "p_call" "uuid", "p_worker" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_claim_voice_agent_calls"("p_org" integer, "p_campaign" "uuid", "p_limit" integer, "p_worker" "text") RETURNS SETOF "public"."voice_agent_calls"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_limit IS NULL OR p_limit <= 0 THEN RETURN; END IF;
  RETURN QUERY
  WITH candidatos AS (
    SELECT vac.id
      FROM public.voice_agent_calls vac
     WHERE vac.organization_id = p_org
       AND vac.campaign_id = p_campaign
       AND vac.status IN ('pending','queued')
       AND (vac.scheduled_at IS NULL OR vac.scheduled_at <= now())
     ORDER BY vac.scheduled_at NULLS FIRST, vac.created_at
     LIMIT p_limit
     FOR UPDATE SKIP LOCKED
  ), reclamadas AS (
    UPDATE public.voice_agent_calls v
       SET status = 'in_progress',
           claimed_at = now(),
           locked_by = p_worker,
           attempts = v.attempts + 1,
           updated_at = now()
      FROM candidatos c
     WHERE v.id = c.id
    RETURNING v.*
  ), registradas AS (
    INSERT INTO public.voice_agent_call_attempts
      (organization_id, voice_agent_call_id, voice_agent_id, campaign_id, customer_id, attempt_no, source, worker)
    SELECT r.organization_id, r.id, r.voice_agent_id, r.campaign_id, r.customer_id, r.attempts, 'campaign', p_worker
      FROM reclamadas r
    RETURNING voice_agent_call_id
  )
  SELECT r.* FROM reclamadas r
   WHERE r.id IN (SELECT voice_agent_call_id FROM registradas);
END $$;


ALTER FUNCTION "public"."fn_claim_voice_agent_calls"("p_org" integer, "p_campaign" "uuid", "p_limit" integer, "p_worker" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_cohort_retention"("p_org_id" integer, "p_start" "date", "p_end" "date") RETURNS TABLE("cohort_month" "date", "cohort_size" bigint, "retained_m1" bigint, "retained_m2" bigint, "retained_m3" bigint, "retained_m6" bigint, "retained_m12" bigint, "retention_m1_pct" numeric, "retention_m2_pct" numeric, "retention_m3_pct" numeric, "retention_m6_pct" numeric, "retention_m12_pct" numeric)
    LANGUAGE "sql" STABLE
    AS $$
  WITH cohort AS (
    SELECT
      DATE_TRUNC('month', c.created_at)::date AS cohort_month,
      COUNT(DISTINCT c.id) AS cohort_size
    FROM customers c
    WHERE c.organization_id = p_org_id
      AND c.lifecycle_stage = 'customer'
      AND c.created_at >= p_start
      AND c.created_at < p_end
    GROUP BY DATE_TRUNC('month', c.created_at)
  ),
  retention AS (
    SELECT
      DATE_TRUNC('month', c.created_at)::date AS cohort_month,
      COUNT(DISTINCT CASE WHEN i.issue_date >= DATE_TRUNC('month', c.created_at) + INTERVAL '1 month'
        AND i.issue_date < DATE_TRUNC('month', c.created_at) + INTERVAL '2 months'
        THEN c.id END) AS retained_m1,
      COUNT(DISTINCT CASE WHEN i.issue_date >= DATE_TRUNC('month', c.created_at) + INTERVAL '2 months'
        AND i.issue_date < DATE_TRUNC('month', c.created_at) + INTERVAL '3 months'
        THEN c.id END) AS retained_m2,
      COUNT(DISTINCT CASE WHEN i.issue_date >= DATE_TRUNC('month', c.created_at) + INTERVAL '3 months'
        AND i.issue_date < DATE_TRUNC('month', c.created_at) + INTERVAL '4 months'
        THEN c.id END) AS retained_m3,
      COUNT(DISTINCT CASE WHEN i.issue_date >= DATE_TRUNC('month', c.created_at) + INTERVAL '6 months'
        AND i.issue_date < DATE_TRUNC('month', c.created_at) + INTERVAL '7 months'
        THEN c.id END) AS retained_m6,
      COUNT(DISTINCT CASE WHEN i.issue_date >= DATE_TRUNC('month', c.created_at) + INTERVAL '12 months'
        AND i.issue_date < DATE_TRUNC('month', c.created_at) + INTERVAL '13 months'
        THEN c.id END) AS retained_m12
    FROM customers c
    LEFT JOIN invoice_sales i ON i.customer_id = c.id
      AND i.organization_id = p_org_id
    WHERE c.organization_id = p_org_id
      AND c.lifecycle_stage = 'customer'
      AND c.created_at >= p_start
      AND c.created_at < p_end
    GROUP BY DATE_TRUNC('month', c.created_at)
  )
  SELECT
    ch.cohort_month,
    ch.cohort_size,
    r.retained_m1,
    r.retained_m2,
    r.retained_m3,
    r.retained_m6,
    r.retained_m12,
    r.retained_m1::numeric / NULLIF(ch.cohort_size, 0) * 100 AS retention_m1_pct,
    r.retained_m2::numeric / NULLIF(ch.cohort_size, 0) * 100 AS retention_m2_pct,
    r.retained_m3::numeric / NULLIF(ch.cohort_size, 0) * 100 AS retention_m3_pct,
    r.retained_m6::numeric / NULLIF(ch.cohort_size, 0) * 100 AS retention_m6_pct,
    r.retained_m12::numeric / NULLIF(ch.cohort_size, 0) * 100 AS retention_m12_pct
  FROM cohort ch
  JOIN retention r ON r.cohort_month = ch.cohort_month
  ORDER BY ch.cohort_month;
$$;


ALTER FUNCTION "public"."fn_cohort_retention"("p_org_id" integer, "p_start" "date", "p_end" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_complete_job"("p_job_id" "uuid", "p_worker" "text", "p_result" "jsonb" DEFAULT NULL::"jsonb") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_n integer;
BEGIN
  UPDATE public.outbound_jobs
     SET status = 'done', result = p_result, locked_at = NULL, locked_by = NULL
   WHERE id = p_job_id AND status = 'running' AND locked_by = p_worker;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n = 1;
END $$;


