CREATE OR REPLACE FUNCTION "public"."fn_consume_ai_credits_on_message"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  current_credits INTEGER;
BEGIN
  -- Solo procesar mensajes de IA
  IF NEW.role = 'ai' THEN
    SELECT credits_remaining INTO current_credits
    FROM ai_settings WHERE organization_id = NEW.organization_id;

    IF current_credits IS NOT NULL AND current_credits > 0 THEN
      -- Actualizar créditos
      UPDATE ai_settings
      SET credits_remaining = current_credits - 1, updated_at = NOW()
      WHERE organization_id = NEW.organization_id;

      -- Log con columnas correctas
      INSERT INTO ai_usage_logs (
        organization_id, 
        credits_consumed,  -- Columna correcta
        credits_before,
        credits_after,
        model, 
        action_type, 
        created_at
      ) VALUES (
        NEW.organization_id, 
        1,
        current_credits,
        current_credits - 1,
        'gpt-4o-mini', 
        'auto_response', 
        NOW()
      );
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_consume_ai_credits_on_message"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_consume_ai_credits_on_message"() IS 'DEPRECADA (Fase 0): su trigger trg_consume_ai_credits_on_message se elimino para acabar con el cobro doble. Se conserva la funcion para poder reactivar el trigger si hiciera falta revertir.';



