CREATE OR REPLACE FUNCTION "public"."fn_create_branch_subaccounts"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $_$
DECLARE
    v_seq integer;
    v_sub_code text;
    v_base_accounts text[] := ARRAY['1405', '6105']; -- Inventario y CMV
    v_base_name text;
    v_base_type text;
    v_base_parent text;
    v_branch_name text;
BEGIN
    -- Solo para organizaciones que ya tienen las cuentas base
    FOR i IN 1..array_length(v_base_accounts, 1) LOOP
        v_sub_code := v_base_accounts[i];

        -- Verificar que la cuenta base existe para esta organización
        SELECT name, type, parent_code INTO v_base_name, v_base_type, v_base_parent
        FROM chart_of_accounts
        WHERE account_code = v_sub_code
          AND organization_id = NEW.organization_id
          AND is_active = true
        LIMIT 1;

        IF v_base_name IS NULL THEN
            CONTINUE; -- Si no existe la cuenta base, saltar
        END IF;

        -- Calcular secuencial: buscar el máximo número de sub-cuenta existente
        SELECT COALESCE(MAX(
            CASE 
                WHEN split_part(sub_account_code, '-', 2) ~ '^[0-9]+$' 
                THEN split_part(sub_account_code, '-', 2)::int 
                ELSE 0 
            END
        ), 0) + 1
        INTO v_seq
        FROM branch_account_mappings
        WHERE organization_id = NEW.organization_id
          AND base_account_code = v_sub_code;

        v_sub_code := v_base_accounts[i] || '-' || lpad(v_seq::text, 2, '0');

        -- Insertar sub-cuenta en chart_of_accounts
        INSERT INTO chart_of_accounts (account_code, organization_id, name, type, parent_code, is_active, description)
        VALUES (
            v_sub_code,
            NEW.organization_id,
            v_base_name || ' - ' || NEW.name,
            v_base_type,
            v_base_accounts[i],
            true,
            'Sub-cuenta automática para sucursal: ' || NEW.name
        )
        ON CONFLICT (account_code, organization_id) DO NOTHING;

        -- Insertar mapeo en branch_account_mappings
        INSERT INTO branch_account_mappings (organization_id, branch_id, base_account_code, sub_account_code)
        VALUES (NEW.organization_id, NEW.id, v_base_accounts[i], v_sub_code)
        ON CONFLICT (organization_id, branch_id, base_account_code) DO NOTHING;

    END LOOP;

    RETURN NEW;
END;
$_$;


ALTER FUNCTION "public"."fn_create_branch_subaccounts"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_create_commission_on_invoice_purchase"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_commission_amount numeric;
    v_payee_name text;
    v_existing_commission_count integer;
BEGIN
    -- Solo si la factura pasa a 'paid' y tiene comisión configurada
    IF NEW.status != 'paid' THEN
        RETURN NEW;
    END IF;

    -- Solo si cambió el status
    IF OLD.status = NEW.status THEN
        RETURN NEW;
    END IF;

    IF NEW.commission_type = 'none' OR NEW.commission_rate IS NULL OR NEW.commission_rate <= 0 THEN
        RETURN NEW;
    END IF;

    IF NEW.salesperson_id IS NULL THEN
        RETURN NEW;
    END IF;

    -- Evitar duplicados
    SELECT COUNT(*) INTO v_existing_commission_count
    FROM commissions
    WHERE source_type = 'invoice_purchase' AND source_id = NEW.id::text;

    IF v_existing_commission_count > 0 THEN
        RETURN NEW;
    END IF;

    v_commission_amount := ROUND(COALESCE(NEW.subtotal, NEW.total, 0) * NEW.commission_rate / 100.0, 2);

    IF v_commission_amount <= 0 THEN
        RETURN NEW;
    END IF;

    -- Obtener nombre del beneficiario (puede ser usuario o proveedor)
    SELECT COALESCE(raw_user_meta_data->>'full_name', raw_user_meta_data->>'name', email, 'Comisionista')
    INTO v_payee_name
    FROM auth.users
    WHERE id = NEW.salesperson_id;

    -- Si no encuentra en auth.users, buscar en suppliers
    IF v_payee_name IS NULL THEN
        SELECT name INTO v_payee_name
        FROM suppliers
        WHERE id::text = NEW.salesperson_id::text;
    END IF;

    v_payee_name := COALESCE(v_payee_name, 'Comisionista');

    INSERT INTO commissions (
        organization_id, branch_id,
        commission_type, source_type, source_id,
        payee_type, payee_id, payee_name,
        base_amount, commission_rate, commission_amount,
        currency, status, notes
    ) VALUES (
        NEW.organization_id, NEW.branch_id,
        NEW.commission_type, 'invoice_purchase', NEW.id::text,
        'employee', NEW.salesperson_id::text, v_payee_name,
        COALESCE(NEW.subtotal, NEW.total, 0), NEW.commission_rate, v_commission_amount,
        COALESCE(NEW.currency, 'USD'), 'accrued',
        'Comisión por factura de compra - ' || COALESCE(NEW.number_ext, NEW.id::text)
    );

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_create_commission_on_invoice_purchase"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_create_commission_on_invoice_sale"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_commission_amount numeric;
    v_salesperson_name text;
    v_existing_commission_count integer;
BEGIN
    -- Solo si la factura pasa a 'paid' y tiene comisión configurada
    IF NEW.status != 'paid' THEN
        RETURN NEW;
    END IF;

    -- Solo si cambió el status (no re-procesar si ya estaba paid)
    IF OLD.status = NEW.status THEN
        RETURN NEW;
    END IF;

    IF NEW.commission_type = 'none' OR NEW.commission_rate IS NULL OR NEW.commission_rate <= 0 THEN
        RETURN NEW;
    END IF;

    IF NEW.salesperson_id IS NULL THEN
        RETURN NEW;
    END IF;

    -- Evitar duplicados: si ya existe comisión para esta factura
    SELECT COUNT(*) INTO v_existing_commission_count
    FROM commissions
    WHERE source_type = 'invoice_sale' AND source_id = NEW.id::text;

    IF v_existing_commission_count > 0 THEN
        RETURN NEW;
    END IF;

    v_commission_amount := ROUND(COALESCE(NEW.subtotal, NEW.total, 0) * NEW.commission_rate / 100.0, 2);

    IF v_commission_amount <= 0 THEN
        RETURN NEW;
    END IF;

    SELECT COALESCE(raw_user_meta_data->>'full_name', raw_user_meta_data->>'name', email, 'Vendedor')
    INTO v_salesperson_name
    FROM auth.users
    WHERE id = NEW.salesperson_id;

    INSERT INTO commissions (
        organization_id, branch_id,
        commission_type, source_type, source_id,
        payee_type, payee_id, payee_name,
        base_amount, commission_rate, commission_amount,
        currency, status, notes
    ) VALUES (
        NEW.organization_id, NEW.branch_id,
        NEW.commission_type, 'invoice_sale', NEW.id::text,
        'employee', NEW.salesperson_id::text, v_salesperson_name,
        COALESCE(NEW.subtotal, NEW.total, 0), NEW.commission_rate, v_commission_amount,
        COALESCE(NEW.currency, 'USD'), 'accrued',
        'Comisión por factura de venta - ' || COALESCE(NEW.number, NEW.id::text)
    );

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_create_commission_on_invoice_sale"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_create_commission_on_opportunity_won"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_commission_amount numeric;
    v_payee_name text;
    v_existing_commission_count integer;
    v_branch_id integer;
BEGIN
    IF NEW.status <> 'won' THEN
        RETURN NEW;
    END IF;

    IF OLD.status IS NOT DISTINCT FROM NEW.status THEN
        RETURN NEW;
    END IF;

    IF NEW.commission_type = 'none' OR NEW.commission_rate IS NULL OR NEW.commission_rate <= 0 THEN
        RETURN NEW;
    END IF;

    IF NEW.salesperson_id IS NULL THEN
        RETURN NEW;
    END IF;

    SELECT COUNT(*) INTO v_existing_commission_count
    FROM commissions
    WHERE source_type = 'opportunity' AND source_id = NEW.id::text;

    IF v_existing_commission_count > 0 THEN
        RETURN NEW;
    END IF;

    v_commission_amount := ROUND(COALESCE(NEW.amount, 0) * NEW.commission_rate / 100.0, 2);

    IF v_commission_amount <= 0 THEN
        RETURN NEW;
    END IF;

    SELECT COALESCE(raw_user_meta_data->>'full_name', raw_user_meta_data->>'name', email, 'Vendedor')
    INTO v_payee_name
    FROM auth.users
    WHERE id = NEW.salesperson_id;

    v_payee_name := COALESCE(v_payee_name, 'Vendedor');

    SELECT id INTO v_branch_id FROM branches WHERE organization_id = NEW.organization_id LIMIT 1;
    IF v_branch_id IS NULL THEN
        v_branch_id := 1;
    END IF;

    INSERT INTO commissions (
        organization_id, branch_id,
        commission_type, source_type, source_id,
        payee_type, payee_id, payee_name,
        base_amount, commission_rate, commission_amount,
        currency, status, notes
    ) VALUES (
        NEW.organization_id, v_branch_id,
        NEW.commission_type, 'opportunity', NEW.id::text,
        'employee', NEW.salesperson_id, v_payee_name,   -- uuid, sin ::text (era el bug)
        COALESCE(NEW.amount, 0), NEW.commission_rate, v_commission_amount,
        COALESCE(NEW.currency, 'USD'), 'accrued',
        'Comisión por oportunidad ganada - ' || NEW.name
    );

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_create_commission_on_opportunity_won"() OWNER TO "postgres";


