CREATE OR REPLACE FUNCTION "public"."fn_create_default_branch_and_period"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_year int := EXTRACT(YEAR FROM CURRENT_DATE)::int;
    v_branch_id integer;
BEGIN
    -- Crear branch principal si no existe
    IF NOT EXISTS (SELECT 1 FROM branches WHERE organization_id = NEW.id) THEN
        INSERT INTO branches (organization_id, name, branch_code, is_main, is_active, created_at, updated_at)
        VALUES (NEW.id, 'Sede Principal', 'MAIN', true, true, now(), now())
        RETURNING id INTO v_branch_id;
    END IF;

    -- Crear periodo fiscal anual si no existe
    IF NOT EXISTS (SELECT 1 FROM fiscal_periods WHERE organization_id = NEW.id AND period_type = 'yearly' AND year = v_year) THEN
        INSERT INTO fiscal_periods (organization_id, year, period_type, start_date, end_date, status, created_at, updated_at)
        VALUES (NEW.id, v_year, 'yearly', make_date(v_year, 1, 1), make_date(v_year, 12, 31), 'open', now(), now());
    END IF;

    -- Crear periodos mensuales
    IF NOT EXISTS (SELECT 1 FROM fiscal_periods WHERE organization_id = NEW.id AND period_type = 'monthly') THEN
        INSERT INTO fiscal_periods (organization_id, year, month, period_type, start_date, end_date, status, created_at, updated_at)
        SELECT NEW.id, v_year, m, 'monthly',
            make_date(v_year, m, 1),
            make_date(v_year, m, 28) + INTERVAL '1 month' - INTERVAL '1 day',
            'open', now(), now()
        FROM generate_series(1, 12) AS m;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_create_default_branch_and_period"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_create_default_chart_of_accounts"("org_id" integer, "country_code" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  -- Evitar duplicados: si ya tiene cuentas, no hacer nada
  IF EXISTS (SELECT 1 FROM public.chart_of_accounts WHERE organization_id = org_id) THEN
    RETURN;
  END IF;

  CASE country_code
    -- ============================================================
    -- COLOMBIA: PUC (Plan Unico de Cuentas) + NIIF
    -- ============================================================
    WHEN 'COL' THEN
      -- Clases principales (nivel 0)
      INSERT INTO public.chart_of_accounts (organization_id, account_code, name, type, parent_code, is_active, description) VALUES
        (org_id, '1', 'Activo', 'asset', NULL, true, 'Clase 1 - Activo segun PUC/NIIF'),
        (org_id, '2', 'Pasivo', 'liability', NULL, true, 'Clase 2 - Pasivo segun PUC/NIIF'),
        (org_id, '3', 'Patrimonio', 'equity', NULL, true, 'Clase 3 - Patrimonio segun PUC/NIIF'),
        (org_id, '4', 'Ingresos', 'income', NULL, true, 'Clase 4 - Ingresos segun PUC/NIIF'),
