CREATE OR REPLACE FUNCTION "public"."fn_create_journal_entry"("p_organization_id" integer, "p_branch_id" integer, "p_entry_date" timestamp with time zone, "p_memo" "text", "p_source" "text", "p_source_id" "text", "p_debit_account" "text", "p_credit_account" "text", "p_amount" numeric, "p_tax_account" "text" DEFAULT NULL::"text", "p_tax_amount" numeric DEFAULT 0, "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_entry_id integer;
    v_period_open boolean;
    v_branch_id integer;
BEGIN
    -- Validar monto: NULL o <= 0 no genera asiento
    IF p_amount IS NULL OR p_amount <= 0 THEN
        RAISE NOTICE 'Monto invalido (NULL o <= 0) para source %. Asiento no creado.', p_source;
        RETURN NULL;
    END IF;

    -- Validar cuentas no vacias
    IF p_debit_account IS NULL OR p_credit_account IS NULL THEN
        RAISE NOTICE 'Cuentas debito/credito vacias para source %. Asiento no creado.', p_source;
        RETURN NULL;
    END IF;

    -- Validar que las cuentas existan en chart_of_accounts para la organizacion
    IF NOT EXISTS (
        SELECT 1 FROM chart_of_accounts
        WHERE organization_id = p_organization_id AND account_code = p_debit_account
    ) THEN
        RAISE NOTICE 'Cuenta debito % no existe en chart_of_accounts para org %. Asiento no creado (source %).', p_debit_account, p_organization_id, p_source;
        RETURN NULL;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM chart_of_accounts
        WHERE organization_id = p_organization_id AND account_code = p_credit_account
    ) THEN
        RAISE NOTICE 'Cuenta credito % no existe en chart_of_accounts para org %. Asiento no creado (source %).', p_credit_account, p_organization_id, p_source;
        RETURN NULL;
    END IF;

    IF p_tax_account IS NOT NULL AND p_tax_amount > 0 AND NOT EXISTS (
        SELECT 1 FROM chart_of_accounts
        WHERE organization_id = p_organization_id AND account_code = p_tax_account
    ) THEN
        RAISE NOTICE 'Cuenta de impuesto % no existe en chart_of_accounts para org %. Asiento no creado (source %).', p_tax_account, p_organization_id, p_source;
        RETURN NULL;
    END IF;

    -- Validar periodo contable abierto
    v_period_open := fn_is_period_open(p_organization_id, p_entry_date::date);
    IF NOT v_period_open THEN
        RAISE NOTICE 'Periodo contable cerrado para fecha %. Asiento no creado.', p_entry_date;
        RETURN NULL;
    END IF;

    -- Validar branch_id: NULL, 0, o que no pertenezca a la organizacion -> fallback
    IF p_branch_id IS NULL OR p_branch_id = 0 OR NOT EXISTS (
        SELECT 1 FROM branches WHERE id = p_branch_id AND organization_id = p_organization_id
    ) THEN
        SELECT MIN(id) INTO v_branch_id
        FROM branches
        WHERE organization_id = p_organization_id;
    ELSE
        v_branch_id := p_branch_id;
    END IF;

    -- Crear cabecera del asiento
    INSERT INTO journal_entries (
        organization_id, branch_id, entry_date, memo,
        source, source_id, posted, created_by
    ) VALUES (
        p_organization_id, v_branch_id, p_entry_date, p_memo,
        p_source, p_source_id, true, p_created_by
    ) RETURNING id INTO v_entry_id;

    -- Linea de debito (principal)
    INSERT INTO journal_lines (journal_entry_id, account_code, description, debit, credit)
    VALUES (v_entry_id, p_debit_account, p_memo, p_amount - COALESCE(p_tax_amount, 0), 0);

    -- Linea de debito (impuesto) si aplica
    IF p_tax_account IS NOT NULL AND p_tax_amount > 0 THEN
        INSERT INTO journal_lines (journal_entry_id, account_code, description, debit, credit)
        VALUES (v_entry_id, p_tax_account, 'IVA - ' || p_memo, p_tax_amount, 0);
    END IF;

    -- Linea de credito
    INSERT INTO journal_lines (journal_entry_id, account_code, description, debit, credit)
    VALUES (v_entry_id, p_credit_account, p_memo, 0, p_amount);

    RETURN v_entry_id;
END;
$$;


ALTER FUNCTION "public"."fn_create_journal_entry"("p_organization_id" integer, "p_branch_id" integer, "p_entry_date" timestamp with time zone, "p_memo" "text", "p_source" "text", "p_source_id" "text", "p_debit_account" "text", "p_credit_account" "text", "p_amount" numeric, "p_tax_account" "text", "p_tax_amount" numeric, "p_created_by" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_create_journal_entry"("p_organization_id" integer, "p_branch_id" integer, "p_entry_date" timestamp with time zone, "p_memo" "text", "p_source" "text", "p_source_id" "text", "p_debit_account" "text", "p_credit_account" "text", "p_amount" numeric, "p_tax_account" "text", "p_tax_amount" numeric, "p_created_by" "uuid") IS 'Función central para crear asientos contables automáticos';



CREATE OR REPLACE FUNCTION "public"."fn_create_journal_entry_with_discount"("p_organization_id" integer, "p_branch_id" integer, "p_entry_date" timestamp with time zone, "p_memo" "text", "p_source" "text", "p_source_id" "text", "p_debit_account" "text", "p_credit_account" "text", "p_amount" numeric, "p_discount_account" "text", "p_discount_amount" numeric, "p_discount_on_debit" boolean, "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_entry_id integer;
    v_period_open boolean;
    v_branch_id integer;
BEGIN
    -- Validar monto principal
    IF p_amount IS NULL OR p_amount <= 0 THEN
        RAISE NOTICE 'Monto invalido (NULL o <= 0) para source %. Asiento no creado.', p_source;
        RETURN NULL;
    END IF;

    -- Validar cuentas principales
    IF p_debit_account IS NULL OR p_credit_account IS NULL THEN
        RAISE NOTICE 'Cuentas debito/credito vacias para source %. Asiento no creado.', p_source;
        RETURN NULL;
    END IF;

    -- Si no hay descuento valido, delegar a la funcion estandar (asiento simple)
    IF p_discount_amount IS NULL OR p_discount_amount <= 0 OR p_discount_account IS NULL THEN
        RETURN fn_create_journal_entry(
            p_organization_id := p_organization_id,
            p_branch_id := p_branch_id,
            p_entry_date := p_entry_date,
            p_memo := p_memo,
            p_source := p_source,
            p_source_id := p_source_id,
            p_debit_account := p_debit_account,
            p_credit_account := p_credit_account,
            p_amount := p_amount,
            p_created_by := p_created_by
        );
    END IF;

    -- Validar que las cuentas existan en chart_of_accounts para la organizacion
    IF NOT EXISTS (
        SELECT 1 FROM chart_of_accounts
        WHERE organization_id = p_organization_id AND account_code = p_debit_account
    ) THEN
        RAISE NOTICE 'Cuenta debito % no existe en chart_of_accounts para org %. Asiento no creado (source %).', p_debit_account, p_organization_id, p_source;
        RETURN NULL;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM chart_of_accounts
        WHERE organization_id = p_organization_id AND account_code = p_credit_account
    ) THEN
        RAISE NOTICE 'Cuenta credito % no existe en chart_of_accounts para org %. Asiento no creado (source %).', p_credit_account, p_organization_id, p_source;
        RETURN NULL;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM chart_of_accounts
        WHERE organization_id = p_organization_id AND account_code = p_discount_account
    ) THEN
        RAISE NOTICE 'Cuenta de descuento % no existe en chart_of_accounts para org %. Asiento no creado (source %).', p_discount_account, p_organization_id, p_source;
        RETURN NULL;
    END IF;

    -- Validar periodo contable abierto
    v_period_open := fn_is_period_open(p_organization_id, p_entry_date::date);
    IF NOT v_period_open THEN
        RAISE NOTICE 'Periodo contable cerrado para fecha %. Asiento no creado.', p_entry_date;
        RETURN NULL;
    END IF;

    -- Validar branch_id con fallback
    IF p_branch_id IS NULL OR p_branch_id = 0 OR NOT EXISTS (
        SELECT 1 FROM branches WHERE id = p_branch_id AND organization_id = p_organization_id
    ) THEN
        SELECT MIN(id) INTO v_branch_id FROM branches WHERE organization_id = p_organization_id;
    ELSE
        v_branch_id := p_branch_id;
    END IF;

    -- Cabecera
    INSERT INTO journal_entries (
        organization_id, branch_id, entry_date, memo,
        source, source_id, posted, created_by
    ) VALUES (
        p_organization_id, v_branch_id, p_entry_date, p_memo,
        p_source, p_source_id, true, p_created_by
    ) RETURNING id INTO v_entry_id;

    IF p_discount_on_debit THEN
        -- COBRO (venta): Caja/Banco (efectivo) + Descuento concedido (debito) = CxC (credito total)
        INSERT INTO journal_lines (journal_entry_id, account_code, description, debit, credit)
        VALUES (v_entry_id, p_debit_account, p_memo, p_amount, 0);

        INSERT INTO journal_lines (journal_entry_id, account_code, description, debit, credit)
        VALUES (v_entry_id, p_discount_account, 'Descuento pronto pago - ' || p_memo, p_discount_amount, 0);

        INSERT INTO journal_lines (journal_entry_id, account_code, description, debit, credit)
        VALUES (v_entry_id, p_credit_account, p_memo, 0, p_amount + p_discount_amount);
    ELSE
        -- PAGO (compra): CxP (debito total) = Caja/Banco (efectivo) + Descuento obtenido (credito)
        INSERT INTO journal_lines (journal_entry_id, account_code, description, debit, credit)
        VALUES (v_entry_id, p_debit_account, p_memo, p_amount + p_discount_amount, 0);

        INSERT INTO journal_lines (journal_entry_id, account_code, description, debit, credit)
        VALUES (v_entry_id, p_credit_account, p_memo, 0, p_amount);

        INSERT INTO journal_lines (journal_entry_id, account_code, description, debit, credit)
        VALUES (v_entry_id, p_discount_account, 'Descuento pronto pago - ' || p_memo, 0, p_discount_amount);
    END IF;

    RETURN v_entry_id;
END;
$$;


ALTER FUNCTION "public"."fn_create_journal_entry_with_discount"("p_organization_id" integer, "p_branch_id" integer, "p_entry_date" timestamp with time zone, "p_memo" "text", "p_source" "text", "p_source_id" "text", "p_debit_account" "text", "p_credit_account" "text", "p_amount" numeric, "p_discount_account" "text", "p_discount_amount" numeric, "p_discount_on_debit" boolean, "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_create_org_notification"("p_organization_id" integer, "p_recipient_user_id" "uuid" DEFAULT NULL::"uuid", "p_channel" "text" DEFAULT 'app'::"text", "p_type" "text" DEFAULT 'info'::"text", "p_title" "text" DEFAULT 'Notificación'::"text", "p_content" "text" DEFAULT ''::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_notification_id uuid;
BEGIN
  INSERT INTO notifications (
    organization_id,
    recipient_user_id,
    channel,
    payload,
    status,
    created_at,
    updated_at
  ) VALUES (
    p_organization_id,
    p_recipient_user_id,
    p_channel,
    jsonb_build_object(
      'type', p_type,
      'title', p_title,
      'content', p_content
    ) || p_metadata,
    'pending',
    now(),
    now()
  )
  RETURNING id INTO v_notification_id;

  RETURN v_notification_id;
END;
$$;


ALTER FUNCTION "public"."fn_create_org_notification"("p_organization_id" integer, "p_recipient_user_id" "uuid", "p_channel" "text", "p_type" "text", "p_title" "text", "p_content" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_crm_cron_post"("p_path" "text" DEFAULT '/api/crm/jobs/run'::"text", "p_body" "jsonb" DEFAULT '{}'::"jsonb") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'vault', 'net'
    AS $$
DECLARE v_secret text; v_url text; v_req bigint;
BEGIN
  SELECT decrypted_secret INTO v_secret FROM vault.decrypted_secrets WHERE name = 'crm_cron_secret' ORDER BY created_at DESC LIMIT 1;
  SELECT decrypted_secret INTO v_url    FROM vault.decrypted_secrets WHERE name = 'crm_app_url' ORDER BY created_at DESC LIMIT 1;
  IF v_secret IS NULL OR v_url IS NULL OR length(v_secret) < 16 THEN
    RAISE EXCEPTION 'fn_crm_cron_post: crm_cron_secret / crm_app_url ausentes en vault (fail-closed)';
  END IF;
  SELECT net.http_post(
    url := rtrim(v_url, '/') || p_path,
    body := COALESCE(p_body, '{}'::jsonb),
    headers := jsonb_build_object('Authorization', 'Bearer ' || v_secret, 'Content-Type', 'application/json', 'X-Cron-Source', 'pg_cron'),
    timeout_milliseconds := 55000) INTO v_req;
  RETURN v_req;
END $$;


ALTER FUNCTION "public"."fn_crm_cron_post"("p_path" "text", "p_body" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_customer_health"("p_org_id" integer, "p_customer_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("customer_id" "uuid", "invoices_12m" bigint, "revenue_12m" numeric, "days_since_last_invoice" integer, "days_since_last_activity" integer, "overdue_balance" numeric, "overdue_ratio" numeric, "score" integer, "band" "text")
    LANGUAGE "sql" STABLE
    AS $$
  WITH base AS (
    SELECT c.id AS customer_id
      FROM customers c
     WHERE c.organization_id = p_org_id
       AND c.lifecycle_stage = 'customer'
       AND (p_customer_id IS NULL OR c.id = p_customer_id)
  ),
  fact AS (
    SELECT
      b.customer_id,
      COUNT(i.id) FILTER (
        WHERE i.issue_date >= now() - INTERVAL '12 months'
          AND i.status IN ('paid','partial','issued')
      ) AS invoices_12m,
      COALESCE(SUM(i.total) FILTER (
        WHERE i.issue_date >= now() - INTERVAL '12 months'
          AND i.status IN ('paid','partial')
      ), 0) AS revenue_12m,
      MAX(i.issue_date) AS last_invoice_at
    FROM base b
    LEFT JOIN invoice_sales i
           ON i.customer_id = b.customer_id
          AND i.organization_id = p_org_id
          AND i.status <> 'void'
    GROUP BY b.customer_id
  ),
  act AS (
    SELECT b.customer_id, MAX(a.occurred_at) AS last_activity_at
      FROM base b
      LEFT JOIN activities a
             ON a.related_id = b.customer_id
            AND a.related_type = 'customer'
            AND a.organization_id = p_org_id
     GROUP BY b.customer_id
  ),
  ar AS (
    SELECT
      b.customer_id,
      COALESCE(SUM(r.balance) FILTER (WHERE r.status = 'overdue'), 0) AS overdue_balance,
      COALESCE(SUM(r.balance), 0) AS total_balance
    FROM base b
    LEFT JOIN accounts_receivable r
           ON r.customer_id = b.customer_id
          AND r.organization_id = p_org_id
     GROUP BY b.customer_id
  ),
  calc AS (
    SELECT
      f.customer_id,
      f.invoices_12m,
      f.revenue_12m,
      EXTRACT(DAY FROM now() - f.last_invoice_at)::integer AS days_since_last_invoice,
      EXTRACT(DAY FROM now() - ac.last_activity_at)::integer AS days_since_last_activity,
      ar.overdue_balance,
      ROUND(ar.overdue_balance / NULLIF(ar.total_balance, 0), 4) AS overdue_ratio,
      GREATEST(0, LEAST(100,
          40
        + LEAST(25, f.invoices_12m * 5)
        - CASE WHEN f.last_invoice_at IS NULL THEN 25
               ELSE LEAST(25, GREATEST(0,
                 (EXTRACT(DAY FROM now() - f.last_invoice_at)::int - 60) / 6))
          END
        - CASE WHEN ac.last_activity_at IS NULL THEN 10
               ELSE LEAST(10, GREATEST(0,
                 (EXTRACT(DAY FROM now() - ac.last_activity_at)::int - 30) / 9))
          END
        - LEAST(30, ROUND(COALESCE(
            ar.overdue_balance / NULLIF(ar.total_balance, 0), 0) * 30))
        + 25
      ))::integer AS score
    FROM fact f
    JOIN act ac ON ac.customer_id = f.customer_id
    JOIN ar ON ar.customer_id = f.customer_id
  )
  SELECT
    customer_id, invoices_12m, revenue_12m,
    days_since_last_invoice, days_since_last_activity,
    overdue_balance, overdue_ratio, score,
    CASE WHEN score >= 70 THEN 'healthy'
         WHEN score >= 40 THEN 'at_risk'
         ELSE 'critical' END AS band
  FROM calc;
$$;


ALTER FUNCTION "public"."fn_customer_health"("p_org_id" integer, "p_customer_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_daily_task_agent"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  org RECORD;
  v_count integer;
  -- Roles fallback: 2 = Admin, 4 = Empleado, 5 = Manager
  admin_first integer[] := ARRAY[2,5];
  ops_first   integer[] := ARRAY[4,5,2];
  mgr_first   integer[] := ARRAY[5,2];
  -- Keywords de departamento por área
  d_finanzas  text[] := ARRAY['finan','contab','cartera','tesorer'];
  d_ventas    text[] := ARRAY['ventas','comercial','tienda'];
  d_servicio  text[] := ARRAY['servicio','atencion','atención','soporte','marketing'];
  d_logistica text[] := ARRAY['logist','logíst','bodega','despacho','transport','almac'];
  d_compras   text[] := ARRAY['compras','abastec','inventar'];
  d_rrhh      text[] := ARRAY['rrhh','recursos humanos','talento','nomina','nómina','gestion humana','gestión humana'];
  d_recepcion text[] := ARRAY['recepcion','recepción','hotel','hospedaje','front'];
  d_ti        text[] := ARRAY['tecnolog','sistemas','ti','informat'];
  d_operacion text[] := ARRAY['operacion','operación','parquead','parking'];
  -- Keywords de cargo por área
  p_finanzas  text[] := ARRAY['contador','contable','cartera','tesorer','cobran','finan','auxiliar contable'];
  p_ventas    text[] := ARRAY['vendedor','comercial','asesor','ejecutivo de venta'];
  p_servicio  text[] := ARRAY['servicio al cliente','atencion','atención','soporte','community','recepcionista'];
  p_cajero    text[] := ARRAY['cajer','punto de venta','administrador de tienda'];
  p_bodega    text[] := ARRAY['bodegu','almacen','almacén','inventar','despach','logist'];
  p_compras   text[] := ARRAY['compras','comprador','abastec'];
  p_conductor text[] := ARRAY['conductor','transport','mensajer','domicili','repartidor'];
  p_rrhh      text[] := ARRAY['rrhh','recursos humanos','talento','nomina','nómina','gestion humana','gestión humana'];
  p_recepcion text[] := ARRAY['recepcionista','anfitrion','anfitrión','botones','camarer','housekeep'];
  p_lider     text[] := ARRAY['gerente','jefe','coordinador','supervisor','director','lider','líder'];
  p_ti        text[] := ARRAY['sistemas','desarroll','tecnolog','soporte tecnico','soporte técnico','ti'];
  p_parking   text[] := ARRAY['parquead','parking','vigilan','portero','operador'];
BEGIN
  FOR org IN SELECT id FROM organizations WHERE status = 'active' LOOP

    -- ── FINANZAS ──────────────────────────────────────────
    -- 1. Cobrar facturas vencidas (CxC)
    SELECT count(*) INTO v_count FROM accounts_receivable
    WHERE organization_id = org.id AND balance > 0 AND due_date < now();
    IF v_count > 0 THEN
      PERFORM fn_agent_upsert_task(org.id, 'agent:cobrar_facturas',
        'Cobrar ' || v_count || ' factura(s) vencida(s)',
        'Hay ' || v_count || ' cuentas por cobrar vencidas con saldo pendiente. Revisa Finanzas → Cuentas por Cobrar y gestiona el recaudo.',
        admin_first, 'high', d_finanzas, p_finanzas, 2.0);
    END IF;

    -- 2. Pagar facturas de proveedores (CxP)
    SELECT count(*) INTO v_count FROM accounts_payable
    WHERE organization_id = org.id AND balance > 0 AND due_date < now();
    IF v_count > 0 THEN
      PERFORM fn_agent_upsert_task(org.id, 'agent:pagar_facturas',
        'Pagar ' || v_count || ' factura(s) de proveedores vencida(s)',
        'Hay ' || v_count || ' cuentas por pagar vencidas. Revisa Finanzas → Cuentas por Pagar para evitar intereses o bloqueos.',
        admin_first, 'high', d_finanzas, p_finanzas, 1.5);
    END IF;

    -- 3. Emitir facturas en borrador
    SELECT count(*) INTO v_count FROM invoice_sales
    WHERE organization_id = org.id AND status = 'draft';
    IF v_count > 0 THEN
      PERFORM fn_agent_upsert_task(org.id, 'agent:facturas_borrador',
        'Emitir ' || v_count || ' factura(s) de venta en borrador',
        'Hay ' || v_count || ' facturas de venta sin emitir. Revisa Finanzas → Facturas de Venta y complétalas.',
        admin_first, 'med', d_finanzas, p_finanzas, 1.0);
    END IF;

    -- ── CHAT / CRM ────────────────────────────────────────
    -- 4. Responder mensajes sin atender
    SELECT count(*) INTO v_count FROM conversations
    WHERE organization_id = org.id AND status = 'open' AND unread_count > 0;
    IF v_count > 0 THEN
      PERFORM fn_agent_upsert_task(org.id, 'agent:responder_mensajes',
        'Responder ' || v_count || ' conversación(es) de clientes',
        'Hay ' || v_count || ' conversaciones abiertas con mensajes sin leer en Chat. Respóndelas para no perder ventas.',
        ops_first, 'high', d_servicio, p_servicio, 1.0);
    END IF;

    -- 5. Asignar conversaciones sin responsable
    SELECT count(*) INTO v_count FROM conversations
    WHERE organization_id = org.id AND status = 'open' AND assigned_member_id IS NULL;
    IF v_count > 0 THEN
      PERFORM fn_agent_upsert_task(org.id, 'agent:asignar_conversaciones',
        'Asignar ' || v_count || ' conversación(es) sin responsable',
        'Hay ' || v_count || ' conversaciones abiertas sin agente asignado en Chat. Distribúyelas entre el equipo.',
        mgr_first, 'med', d_servicio, p_lider, 0.5);
    END IF;

    -- 6. Seguimiento a oportunidades vencidas (CRM)
    SELECT count(*) INTO v_count FROM opportunities
    WHERE organization_id = org.id AND status = 'open' AND expected_close_date < CURRENT_DATE;
    IF v_count > 0 THEN
      PERFORM fn_agent_upsert_task(org.id, 'agent:seguimiento_oportunidades',
        'Hacer seguimiento a ' || v_count || ' oportunidad(es) vencida(s)',
        'Hay ' || v_count || ' oportunidades abiertas con fecha de cierre vencida. Revisa CRM → Pipeline y actualiza su estado.',
        ops_first, 'high', d_ventas, p_ventas, 1.5);
    END IF;

    -- ── POS ───────────────────────────────────────────────
    -- 7. Despachar pedidos online
    SELECT count(*) INTO v_count FROM web_orders
    WHERE organization_id = org.id
      AND status IN ('pending','confirmed','preparing','ready')
      AND delivered_at IS NULL AND cancelled_at IS NULL;
    IF v_count > 0 THEN
      PERFORM fn_agent_upsert_task(org.id, 'agent:despachar_pedidos',
        'Gestionar ' || v_count || ' pedido(s) online pendiente(s)',
        'Hay ' || v_count || ' pedidos online sin entregar. Revisa POS → Pedidos Online para confirmarlos, prepararlos y despacharlos.',
        ops_first, 'high', d_logistica, p_bodega, 2.0);
    END IF;

    -- 8. Cerrar cajas abiertas de días anteriores
    SELECT count(*) INTO v_count FROM cash_sessions
    WHERE organization_id = org.id AND status = 'open' AND opened_at < date_trunc('day', now());
    IF v_count > 0 THEN
      PERFORM fn_agent_upsert_task(org.id, 'agent:cerrar_caja',
        'Cerrar ' || v_count || ' caja(s) abierta(s) de días anteriores',
        'Hay sesiones de caja abiertas desde días anteriores. Ciérralas en POS → Caja para cuadrar la operación.',
        ops_first, 'high', d_ventas, p_cajero, 1.0);
    END IF;

    -- ── INVENTARIO ────────────────────────────────────────
    -- 9. Reponer productos con stock bajo
    SELECT count(*) INTO v_count
    FROM stock_levels sl
    JOIN products p ON p.id = sl.product_id
    WHERE p.organization_id = org.id AND p.status = 'active'
      AND sl.min_level > 0 AND sl.qty_on_hand <= sl.min_level;
    IF v_count > 0 THEN
      PERFORM fn_agent_upsert_task(org.id, 'agent:reponer_inventario',
        'Reponer ' || v_count || ' producto(s) con stock bajo',
        'Hay ' || v_count || ' productos en o por debajo del stock mínimo. Revisa Inventario → Stock y genera órdenes de compra.',
        ops_first, 'high', d_compras, p_bodega, 2.0);
    END IF;

    -- 10. Recibir órdenes de compra atrasadas
    SELECT count(*) INTO v_count FROM purchase_orders
    WHERE organization_id = org.id AND expected_date <= CURRENT_DATE
      AND status NOT IN ('received','cancelled','closed','draft');
    IF v_count > 0 THEN
      PERFORM fn_agent_upsert_task(org.id, 'agent:recibir_compras',
        'Recibir ' || v_count || ' orden(es) de compra atrasada(s)',
        'Hay ' || v_count || ' órdenes de compra con fecha esperada cumplida sin recibir. Revisa Inventario → Órdenes de Compra.',
        ops_first, 'med', d_compras, p_compras, 1.5);
    END IF;

    -- 11. Completar información de productos
    SELECT count(*) INTO v_count FROM products
    WHERE organization_id = org.id AND status = 'active'
      AND (description IS NULL OR description = '');
    IF v_count > 0 THEN
      PERFORM fn_agent_upsert_task(org.id, 'agent:completar_productos',
        'Completar descripción de ' || v_count || ' producto(s)',
        'Hay ' || v_count || ' productos activos sin descripción. Complétalos en Inventario → Productos para mejorar catálogo y ventas online.',
        ops_first, 'low', d_compras, p_bodega, 1.0);
    END IF;

    -- ── PMS ───────────────────────────────────────────────
    -- 12. Check-ins de hoy
    SELECT count(*) INTO v_count FROM reservations
    WHERE organization_id = org.id AND checkin = CURRENT_DATE
      AND actual_checkin_at IS NULL AND status::text NOT IN ('cancelled','no_show','checked_in','checked_out');
    IF v_count > 0 THEN
      PERFORM fn_agent_upsert_task(org.id, 'agent:gestionar_reservas',
        'Gestionar ' || v_count || ' reserva(s) con check-in hoy',
        'Hay ' || v_count || ' reservas que llegan hoy. Prepara los espacios y realiza el check-in en PMS → Reservas.',
        ops_first, 'high', d_recepcion, p_recepcion, 1.5);
    END IF;

    -- 13. Check-outs de hoy
    SELECT count(*) INTO v_count FROM reservations
    WHERE organization_id = org.id AND checkout = CURRENT_DATE
      AND actual_checkout_at IS NULL AND status::text = 'checked_in';
    IF v_count > 0 THEN
      PERFORM fn_agent_upsert_task(org.id, 'agent:gestionar_checkouts',
        'Realizar ' || v_count || ' check-out(s) de hoy',
        'Hay ' || v_count || ' huéspedes que salen hoy. Realiza el check-out y liquida los consumos en PMS → Reservas.',
        ops_first, 'high', d_recepcion, p_recepcion, 1.5);
    END IF;

    -- 14. Vehículos en parqueadero con estadía prolongada
    SELECT count(*) INTO v_count
    FROM parking_sessions ps
    JOIN branches b ON b.id = ps.branch_id
    WHERE b.organization_id = org.id AND ps.exit_at IS NULL
      AND ps.entry_at < date_trunc('day', now());
    IF v_count > 0 THEN
      PERFORM fn_agent_upsert_task(org.id, 'agent:parking_prolongado',
        'Revisar ' || v_count || ' vehículo(s) con estadía prolongada en parking',
        'Hay ' || v_count || ' vehículos dentro del parqueadero desde días anteriores. Verifica en PMS → Parking y gestiona el cobro.',
        ops_first, 'med', d_operacion, p_parking, 1.0);
    END IF;

    -- ── TRANSPORTE ────────────────────────────────────────
    -- 15. Gestionar rutas / envíos pendientes
    SELECT count(*) INTO v_count FROM shipments
    WHERE organization_id = org.id AND delivered_at IS NULL
      AND status NOT IN ('delivered','cancelled','returned');
    IF v_count > 0 THEN
      PERFORM fn_agent_upsert_task(org.id, 'agent:gestionar_rutas',
        'Gestionar ' || v_count || ' envío(s) en ruta o pendientes',
        'Hay ' || v_count || ' envíos sin entregar. Asigna transportista y revisa rutas en Transporte → Envíos.',
        ops_first, 'med', d_logistica, p_conductor, 2.0);
    END IF;

    -- ── HRM ───────────────────────────────────────────────
    -- 16. Liquidar y pagar nómina
    SELECT count(*) INTO v_count FROM payroll_periods
    WHERE organization_id = org.id AND payment_date <= CURRENT_DATE
      AND status NOT IN ('paid','closed','cancelled');
    IF v_count > 0 THEN
      PERFORM fn_agent_upsert_task(org.id, 'agent:pagar_nomina',
        'Liquidar y pagar nómina (' || v_count || ' periodo(s))',
        'Hay ' || v_count || ' periodos de nómina con fecha de pago cumplida sin pagar. Revisa HRM → Nómina para liquidar colillas y pagar.',
        admin_first, 'critical', d_rrhh, p_rrhh, 4.0);
    END IF;

    -- 17. Confirmar turnos de hoy
    SELECT count(*) INTO v_count FROM shift_assignments
    WHERE organization_id = org.id AND work_date = CURRENT_DATE AND status = 'scheduled';
    IF v_count > 0 THEN
      PERFORM fn_agent_upsert_task(org.id, 'agent:registrar_turnos',
        'Registrar/confirmar ' || v_count || ' turno(s) de hoy',
        'Hay ' || v_count || ' turnos programados para hoy. Confirma asistencia y registra novedades en HRM → Turnos.',
        mgr_first, 'med', d_rrhh, p_lider, 1.0);
    END IF;

    -- 18. Aprobar solicitudes de ausencia pendientes
    SELECT count(*) INTO v_count FROM leave_requests
    WHERE organization_id = org.id AND status = 'pending';
    IF v_count > 0 THEN
      PERFORM fn_agent_upsert_task(org.id, 'agent:aprobar_ausencias',
        'Revisar ' || v_count || ' solicitud(es) de ausencia pendiente(s)',
        'Hay ' || v_count || ' solicitudes de vacaciones/permisos sin revisar. Apruébalas o recházalas en HRM → Ausencias.',
        mgr_first, 'med', d_rrhh, p_rrhh, 0.5);
    END IF;

    -- 19. Contratos por vencer (próximos 30 días)
    SELECT count(*) INTO v_count
    FROM employments e
    JOIN organization_members om ON om.id = e.organization_member_id
    WHERE om.organization_id = org.id AND e.status = 'active'
      AND e.contract_end_date BETWEEN CURRENT_DATE AND CURRENT_DATE + 30;
    IF v_count > 0 THEN
      PERFORM fn_agent_upsert_task(org.id, 'agent:contratos_por_vencer',
        'Renovar o cerrar ' || v_count || ' contrato(s) que vencen en 30 días',
        'Hay ' || v_count || ' contratos laborales próximos a vencer. Revisa HRM → Empleados y define renovación o liquidación.',
        admin_first, 'high', d_rrhh, p_rrhh, 1.5);
    END IF;

    -- ── CALENDARIO ────────────────────────────────────────
    -- 20. Preparar eventos de hoy
    SELECT count(*) INTO v_count FROM calendar_events
    WHERE organization_id = org.id
      AND start_at >= date_trunc('day', now()) AND start_at < date_trunc('day', now()) + interval '1 day'
      AND (status IS NULL OR status NOT IN ('cancelled','completed'));
    IF v_count > 0 THEN
      PERFORM fn_agent_upsert_task(org.id, 'agent:eventos_hoy',
        'Preparar ' || v_count || ' evento(s) agendado(s) para hoy',
        'Hay ' || v_count || ' eventos en el Calendario para hoy. Confirma asistentes, lugares y recursos.',
        ops_first, 'med', d_servicio, p_lider, 1.0);
    END IF;

    -- ── INTEGRACIONES ─────────────────────────────────────
    -- 21. Revisar integraciones con errores
    SELECT count(*) INTO v_count FROM integration_connections
    WHERE organization_id = org.id
      AND (status = 'error' OR COALESCE(error_count_24h, 0) > 0);
    IF v_count > 0 THEN
      PERFORM fn_agent_upsert_task(org.id, 'agent:revisar_integraciones',
        'Revisar ' || v_count || ' integración(es) con errores',
        'Hay ' || v_count || ' conexiones de integraciones reportando errores. Revisa Integraciones → Conexiones y reconéctalas.',
        admin_first, 'high', d_ti, p_ti, 1.5);
    END IF;

  END LOOP;
END;
$$;


ALTER FUNCTION "public"."fn_daily_task_agent"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_ei_jobs_status_change"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    IF OLD.status IS DISTINCT FROM NEW.status THEN
        INSERT INTO electronic_invoicing_events (job_id, event_type, event_code, event_message, metadata)
        VALUES (
            NEW.id,
            CASE 
                WHEN NEW.status = 'accepted' THEN 'accepted'
                WHEN NEW.status = 'rejected' THEN 'rejected'
                WHEN NEW.status = 'sent' THEN 'sent'
                WHEN NEW.status = 'failed' THEN 'error'
                WHEN NEW.status = 'cancelled' THEN 'cancelled'
                ELSE 'notification'
            END,
            NEW.error_code,
            COALESCE(NEW.error_message, 'Estado cambiado a ' || NEW.status),
            jsonb_build_object('old_status', OLD.status, 'new_status', NEW.status, 'attempt', NEW.attempt_count)
        );
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_ei_jobs_status_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_emit_crm_event"("p_org" integer, "p_type" "text", "p_entity_type" "text", "p_entity_id" "uuid", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_event_id uuid;
BEGIN
  INSERT INTO public.crm_events (organization_id, event_type, entity_type, entity_id, payload)
  VALUES (p_org, p_type, p_entity_type, p_entity_id, COALESCE(p_payload, '{}'::jsonb))
  RETURNING id INTO v_event_id;
  -- tester #2: el outbox tiene consumidor real: job 'crm_event'
  PERFORM public.fn_enqueue_job(
    p_org, 'crm_event',
    jsonb_build_object('event_id', v_event_id, 'event_type', p_type, 'entity_type', p_entity_type, 'entity_id', p_entity_id),
    now(), 'crm_event:' || v_event_id::text, 5);
  RETURN v_event_id;
END $$;


ALTER FUNCTION "public"."fn_emit_crm_event"("p_org" integer, "p_type" "text", "p_entity_type" "text", "p_entity_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_enqueue_job"("p_org" integer, "p_kind" "text", "p_payload" "jsonb", "p_run_at" timestamp with time zone DEFAULT "now"(), "p_dedupe_key" "text" DEFAULT NULL::"text", "p_max_attempts" integer DEFAULT 5) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_id uuid;
BEGIN
  INSERT INTO public.outbound_jobs (organization_id, kind, payload, run_at, dedupe_key, max_attempts)
  VALUES (p_org, p_kind, COALESCE(p_payload, '{}'::jsonb), COALESCE(p_run_at, now()), p_dedupe_key, COALESCE(p_max_attempts, 5))
  ON CONFLICT (organization_id, dedupe_key) WHERE status IN ('queued','running') AND dedupe_key IS NOT NULL DO NOTHING
  RETURNING id INTO v_id;
  IF v_id IS NULL AND p_dedupe_key IS NOT NULL THEN
    -- tester #5: devolver el job vivo (queued/running), nunca uno done/dead
    SELECT id INTO v_id FROM public.outbound_jobs
     WHERE organization_id = p_org AND dedupe_key = p_dedupe_key AND status IN ('queued','running')
     ORDER BY created_at DESC LIMIT 1;
  END IF;
  RETURN v_id;
END $$;


ALTER FUNCTION "public"."fn_enqueue_job"("p_org" integer, "p_kind" "text", "p_payload" "jsonb", "p_run_at" timestamp with time zone, "p_dedupe_key" "text", "p_max_attempts" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_enroll_in_sequence"("p_org" integer, "p_sequence_id" "uuid", "p_opportunity_id" "uuid" DEFAULT NULL::"uuid", "p_customer_id" "uuid" DEFAULT NULL::"uuid", "p_source" "text" DEFAULT 'manual'::"text", "p_enrolled_by" "uuid" DEFAULT NULL::"uuid", "p_start_at" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_seq         record;
  v_customer    uuid := p_customer_id;
  v_existing    uuid;
  v_enrollment  uuid;
  v_steps       integer := 0;
  v_first       timestamptz;
  v_first_step  uuid;
  v_first_run   uuid;
  r             record;
  v_run_id      uuid;
  v_job_id      uuid;
  v_sched       timestamptz;
BEGIN
  IF p_org IS NULL OR p_sequence_id IS NULL THEN
    RAISE EXCEPTION 'invalid_arguments' USING ERRCODE = 'P0001';
  END IF;
  IF p_opportunity_id IS NULL AND p_customer_id IS NULL THEN
    RAISE EXCEPTION 'opportunity_or_customer_required' USING ERRCODE = 'P0001';
  END IF;

  -- Con sesión de usuario (auth.uid()) exigimos membresía activa: la función es
  -- SECURITY DEFINER y salta RLS. Con service_role auth.uid() es NULL.
  IF auth.uid() IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM organization_members om
     WHERE om.user_id = auth.uid() AND om.organization_id = p_org AND om.is_active = true
  ) THEN
    RAISE EXCEPTION 'forbidden_org' USING ERRCODE = 'P0001';
  END IF;

  SELECT id, is_active INTO v_seq FROM sequences
   WHERE id = p_sequence_id AND organization_id = p_org;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'sequence_not_found' USING ERRCODE = 'P0001';
  END IF;
  IF NOT v_seq.is_active THEN
    RAISE EXCEPTION 'sequence_inactive' USING ERRCODE = 'P0001';
  END IF;

  IF p_opportunity_id IS NOT NULL THEN
    SELECT customer_id INTO v_customer FROM opportunities
     WHERE id = p_opportunity_id AND organization_id = p_org;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'opportunity_not_found' USING ERRCODE = 'P0001';
    END IF;
    v_customer := COALESCE(v_customer, p_customer_id);
  ELSE
    PERFORM 1 FROM customers WHERE id = p_customer_id AND organization_id = p_org;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'customer_not_found' USING ERRCODE = 'P0001';
    END IF;
  END IF;

  -- Inscripción viva (active|paused) ya existente -> no duplicar.
  SELECT id INTO v_existing FROM sequence_enrollments
   WHERE sequence_id = p_sequence_id
     AND organization_id = p_org
     AND status IN ('active','paused')
     AND ((p_opportunity_id IS NOT NULL AND opportunity_id = p_opportunity_id)
       OR (p_opportunity_id IS NULL AND opportunity_id IS NULL AND customer_id = p_customer_id))
   LIMIT 1;
  IF v_existing IS NOT NULL THEN
    RETURN jsonb_build_object('created', false, 'reason', 'already_active', 'enrollment_id', v_existing, 'steps', 0);
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM sequence_steps
     WHERE sequence_id = p_sequence_id AND organization_id = p_org AND is_active = true
  ) THEN
    RAISE EXCEPTION 'sequence_has_no_active_steps' USING ERRCODE = 'P0001';
  END IF;

  INSERT INTO sequence_enrollments (organization_id, sequence_id, opportunity_id, customer_id, status, enrolled_at, source, enrolled_by)
  VALUES (p_org, p_sequence_id, p_opportunity_id, v_customer, 'active', COALESCE(p_start_at, now()), COALESCE(p_source,'manual'), p_enrolled_by)
  RETURNING id INTO v_enrollment;

  FOR r IN
    SELECT id, step_number, delay_days, delay_hours
      FROM sequence_steps
     WHERE sequence_id = p_sequence_id AND organization_id = p_org AND is_active = true
     ORDER BY step_number
  LOOP
    v_sched := COALESCE(p_start_at, now())
             + make_interval(days => COALESCE(r.delay_days, 0), hours => COALESCE(r.delay_hours, 0));

    INSERT INTO sequence_step_runs (organization_id, enrollment_id, step_id, status, scheduled_at)
    VALUES (p_org, v_enrollment, r.id, 'pending', v_sched)
    RETURNING id INTO v_run_id;

    v_steps := v_steps + 1;

    -- Solo el PRIMER paso (por step_number) se encola aquí: el resto lo encola
    -- `processStepRun` al terminar el anterior (programación encadenada, N1).
    IF v_first_run IS NULL THEN
      v_first_run  := v_run_id;
      v_first      := v_sched;
      v_first_step := r.id;
    END IF;
  END LOOP;

  v_job_id := fn_enqueue_job(p_org, 'sequence_step',
                             jsonb_build_object('step_run_id', v_first_run, 'enrollment_id', v_enrollment),
                             v_first, 'seqrun:' || v_first_run::text, 3);
  UPDATE sequence_step_runs SET job_id = v_job_id WHERE id = v_first_run;

  -- Barrido de respaldo por organización (N2): singleton por dedupe_key.
  PERFORM fn_enqueue_job(p_org, 'time_events',
                         jsonb_build_object('scope', 'sequences'),
                         now() + interval '15 minutes',
                         'time_events:' || p_org::text, 3);

  UPDATE sequence_enrollments
     SET next_run_at = v_first, current_step_id = v_first_step
   WHERE id = v_enrollment;

  RETURN jsonb_build_object('created', true, 'enrollment_id', v_enrollment, 'steps', v_steps, 'first_run_at', v_first);
END $$;


