CREATE OR REPLACE FUNCTION "public"."fn_folio_summary"("p_folio_id" "uuid") RETURNS TABLE("folio_id" "uuid", "reservation_id" "uuid", "customer_name" "text", "space_label" "text", "total_items" integer, "pos_charges" numeric, "manual_charges" numeric, "total_balance" numeric, "status" "text")
    LANGUAGE "plpgsql" STABLE
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    f.id AS folio_id,
    f.reservation_id,
    c.name AS customer_name,
    s.label AS space_label,
    COUNT(fi.id)::INTEGER AS total_items,
    COALESCE(SUM(CASE WHEN fi.source = 'pos' THEN fi.amount ELSE 0 END), 0) AS pos_charges,
    COALESCE(SUM(CASE WHEN fi.source = 'manual' THEN fi.amount ELSE 0 END), 0) AS manual_charges,
    f.balance AS total_balance,
    f.status::TEXT AS status
  FROM folios f
  JOIN reservations r ON f.reservation_id = r.id
  LEFT JOIN customers c ON r.customer_id = c.id
  LEFT JOIN spaces s ON r.space_id = s.id
  LEFT JOIN folio_items fi ON f.id = fi.folio_id
  WHERE f.id = p_folio_id
  GROUP BY f.id, f.reservation_id, c.name, s.label, f.balance, f.status;
END;
$$;


