CREATE OR REPLACE FUNCTION "public"."fn_get_campaign_metrics"("p_campaign_id" "uuid") RETURNS TABLE("total_contacts" integer, "sent" integer, "opened" integer, "clicked" integer, "replied" integer, "bounced" integer, "open_rate" numeric, "click_rate" numeric, "reply_rate" numeric, "bounce_rate" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    COUNT(*)::int as total_contacts,
    COUNT(*) FILTER (WHERE sent_at IS NOT NULL)::int as sent,
    COUNT(*) FILTER (WHERE opened_at IS NOT NULL)::int as opened,
    COUNT(*) FILTER (WHERE clicked_at IS NOT NULL)::int as clicked,
    COUNT(*) FILTER (WHERE replied_at IS NOT NULL)::int as replied,
    COUNT(*) FILTER (WHERE bounced_at IS NOT NULL)::int as bounced,
    CASE WHEN COUNT(*) FILTER (WHERE sent_at IS NOT NULL) > 0 
      THEN ROUND(COUNT(*) FILTER (WHERE opened_at IS NOT NULL)::numeric / 
           COUNT(*) FILTER (WHERE sent_at IS NOT NULL) * 100, 2)
      ELSE 0 
    END as open_rate,
    CASE WHEN COUNT(*) FILTER (WHERE opened_at IS NOT NULL) > 0 
      THEN ROUND(COUNT(*) FILTER (WHERE clicked_at IS NOT NULL)::numeric / 
           COUNT(*) FILTER (WHERE opened_at IS NOT NULL) * 100, 2)
      ELSE 0 
    END as click_rate,
    CASE WHEN COUNT(*) FILTER (WHERE sent_at IS NOT NULL) > 0 
      THEN ROUND(COUNT(*) FILTER (WHERE replied_at IS NOT NULL)::numeric / 
           COUNT(*) FILTER (WHERE sent_at IS NOT NULL) * 100, 2)
      ELSE 0 
    END as reply_rate,
    CASE WHEN COUNT(*) FILTER (WHERE sent_at IS NOT NULL) > 0 
      THEN ROUND(COUNT(*) FILTER (WHERE bounced_at IS NOT NULL)::numeric / 
           COUNT(*) FILTER (WHERE sent_at IS NOT NULL) * 100, 2)
      ELSE 0 
    END as bounce_rate
  FROM campaign_contacts
  WHERE campaign_id = p_campaign_id;
END;
$$;


