CREATE OR REPLACE FUNCTION "public"."fn_get_conversation_for_summary"("p_conversation_id" "uuid") RETURNS TABLE("conversation_id" "uuid", "customer_name" "text", "messages_text" "text", "message_count" integer, "duration_minutes" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    c.id as conversation_id,
    COALESCE(cu.first_name || ' ' || cu.last_name, cu.email, 'Cliente') as customer_name,
    STRING_AGG(
      CASE m.role 
        WHEN 'customer' THEN '🧑 Cliente: ' 
        WHEN 'agent' THEN '👤 Agente: '
        WHEN 'bot' THEN '🤖 Bot: '
        ELSE ''
      END || m.content, 
      E'\n' ORDER BY m.created_at
    ) as messages_text,
    COUNT(m.id)::int as message_count,
    EXTRACT(EPOCH FROM (MAX(m.created_at) - MIN(m.created_at)))::int / 60 as duration_minutes
  FROM conversations c
  JOIN customers cu ON c.customer_id = cu.id
  JOIN messages m ON m.conversation_id = c.id
  WHERE c.id = p_conversation_id
  GROUP BY c.id, cu.first_name, cu.last_name, cu.email;
END;
$$;


