CREATE OR REPLACE FUNCTION "public"."fn_get_or_create_folio"("p_reservation_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_folio_id UUID;
BEGIN
  -- Buscar folio abierto existente
  SELECT id INTO v_folio_id
  FROM folios
  WHERE reservation_id = p_reservation_id
    AND status = 'open'
  LIMIT 1;
  
  -- Si no existe, crear uno nuevo
  IF v_folio_id IS NULL THEN
    INSERT INTO folios (reservation_id, balance, status)
    VALUES (p_reservation_id, 0, 'open')
    RETURNING id INTO v_folio_id;
    
    RAISE NOTICE 'Nuevo folio creado: %', v_folio_id;
  END IF;
  
  RETURN v_folio_id;
END;
$$;


