CREATE OR REPLACE FUNCTION "public"."fn_get_trip_available_seats"("p_trip_id" "uuid") RETURNS TABLE("seat_id" "uuid", "seat_label" "text", "seat_row" integer, "seat_column" "text", "seat_type" "text", "status" "text", "price_modifier" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    ts.id,
    ts.seat_label,
    vs.seat_row,
    vs.seat_column,
    vs.seat_type,
    ts.status,
    vs.price_modifier
  FROM trip_seats ts
  JOIN vehicle_seats vs ON ts.vehicle_seat_id = vs.id
  WHERE ts.trip_id = p_trip_id
  ORDER BY vs.seat_row, vs.seat_column;
END;
$$;


