CREATE OR REPLACE FUNCTION "public"."fn_initialize_trip_seats"("p_trip_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_vehicle_id UUID;
  v_org_id INTEGER;
  v_count INTEGER := 0;
BEGIN
  SELECT vehicle_id, organization_id INTO v_vehicle_id, v_org_id
  FROM trips WHERE id = p_trip_id;
  
  IF v_vehicle_id IS NULL THEN
    RETURN 0;
  END IF;
  
  INSERT INTO trip_seats (organization_id, trip_id, vehicle_seat_id, seat_label, status)
  SELECT v_org_id, p_trip_id, vs.id, vs.seat_label, 'available'
  FROM vehicle_seats vs
  WHERE vs.vehicle_id = v_vehicle_id
    AND vs.is_available = true
    AND vs.seat_type = 'passenger'
  ON CONFLICT (trip_id, vehicle_seat_id) DO NOTHING;
  
  GET DIAGNOSTICS v_count = ROW_COUNT;
  
  UPDATE trips SET available_seats = (
    SELECT COUNT(*) FROM trip_seats WHERE trip_id = p_trip_id AND status = 'available'
  ) WHERE id = p_trip_id;
  
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."fn_initialize_trip_seats"("p_trip_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_invoice_sales_paid"("p_invoice_id" "uuid") RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    AS $$
  SELECT COALESCE((
    SELECT SUM(p.amount)
    FROM payments p, invoice_sales i
    WHERE i.id = p_invoice_id
      AND p.status = 'completed'
      AND (
        (p.source = 'invoice_sales' AND p.source_id = i.id::text)
        OR (p.source = 'sale' AND i.sale_id IS NOT NULL AND p.source_id = i.sale_id::text)
        OR (p.source = 'account_receivable' AND p.source_id IN (
            SELECT ar.id::text FROM accounts_receivable ar WHERE ar.invoice_id = i.id
          ))
      )
  ), 0);
$$;


