CREATE OR REPLACE FUNCTION "public"."fn_invoice_stock_shortages"("p_invoice_id" "uuid") RETURNS TABLE("product_id" integer, "product_name" "text", "required" numeric, "available" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    AS $$
  WITH inv AS (
    SELECT branch_id FROM invoice_sales WHERE id = p_invoice_id
  ),
  items AS (
    SELECT ii.product_id, SUM(ii.qty) AS qty
    FROM invoice_items ii
    WHERE (ii.invoice_sales_id = p_invoice_id
           OR (ii.invoice_id = p_invoice_id AND ii.invoice_type = 'sale'))
      AND ii.product_id IS NOT NULL
    GROUP BY ii.product_id
  ),
  needs AS (
    -- Ingredientes de los productos que tienen receta activa
    SELECT ri.ingredient_product_id AS pid, ri.quantity * i.qty AS qty
    FROM items i
    JOIN product_recipes pr ON pr.product_id = i.product_id AND pr.is_active = true
    JOIN recipe_ingredients ri ON ri.recipe_id = pr.id
    UNION ALL
    -- El producto vendido (solo cuenta si rastrea inventario, se filtra abajo)
    SELECT i.product_id, i.qty FROM items i
  ),
  req AS (
    SELECT n.pid, SUM(n.qty) AS required
    FROM needs n
    JOIN products p ON p.id = n.pid
    WHERE p.track_stock = true
    GROUP BY n.pid
  ),
  avail AS (
    SELECT s.owner_id AS product_id, SUM(s.qty) AS qty
    FROM (
      -- Existencias propias del producto
      SELECT sl.product_id AS owner_id, sl.qty_on_hand AS qty
      FROM stock_levels sl, inv
      WHERE sl.branch_id = inv.branch_id
      UNION ALL
      -- Existencias de cada variante, atribuidas a su producto padre
      SELECT v.parent_product_id AS owner_id, sl.qty_on_hand AS qty
      FROM stock_levels sl
      JOIN products v ON v.id = sl.product_id
      CROSS JOIN inv
      WHERE sl.branch_id = inv.branch_id
        AND v.parent_product_id IS NOT NULL
    ) s
    GROUP BY s.owner_id
  )
  SELECT r.pid, p.name, r.required, COALESCE(a.qty, 0)
  FROM req r
  JOIN products p ON p.id = r.pid
  LEFT JOIN avail a ON a.product_id = r.pid
  WHERE r.required > COALESCE(a.qty, 0)
  ORDER BY p.name;
$$;


ALTER FUNCTION "public"."fn_invoice_stock_shortages"("p_invoice_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_is_period_open"("p_organization_id" integer, "p_date" "date") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_status text;
BEGIN
    SELECT status INTO v_status
    FROM fiscal_periods
    WHERE organization_id = p_organization_id
      AND p_date BETWEEN start_date AND end_date
      AND period_type = 'monthly'
    LIMIT 1;
    
    -- Si no existe periodo, se considera abierto
    IF v_status IS NULL THEN
        RETURN true;
    END IF;
    
    RETURN v_status = 'open';
END;
$$;


