CREATE OR REPLACE FUNCTION "public"."fn_meta_product_price_sync"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_org_id int;
  v_has_meta boolean;
BEGIN
  SELECT organization_id INTO v_org_id
  FROM products WHERE id = NEW.product_id;

  IF v_org_id IS NULL THEN RETURN NEW; END IF;

  SELECT EXISTS(
    SELECT 1
    FROM integration_connections ic
    JOIN integration_connectors conn ON conn.id = ic.connector_id
    WHERE ic.organization_id = v_org_id
      AND ic.status = 'active'
      AND conn.code = 'meta_marketing'
  ) INTO v_has_meta;

  IF NOT v_has_meta THEN RETURN NEW; END IF;

  INSERT INTO integration_events (connection_id, event_type, payload, status)
  SELECT ic.id, 'catalog.price_changed',
    jsonb_build_object(
      'organization_id', v_org_id,
      'product_id', NEW.product_id,
      'new_price', NEW.price,
      'action', 'upsert',
      'changed_at', now()
    ),
    'pending'
  FROM integration_connections ic
  JOIN integration_connectors conn ON conn.id = ic.connector_id
  WHERE ic.organization_id = v_org_id
    AND ic.status = 'active'
    AND conn.code = 'meta_marketing'
  LIMIT 1;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_meta_product_price_sync"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_meta_product_sync"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_org_id int;
  v_product_id int;
  v_action text;
  v_has_meta boolean;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_org_id := OLD.organization_id;
    v_product_id := OLD.id;
    v_action := 'delete';
  ELSE
    v_org_id := NEW.organization_id;
    v_product_id := NEW.id;
    v_action := 'upsert';
  END IF;

  SELECT EXISTS(
    SELECT 1
    FROM integration_connections ic
    JOIN integration_connectors conn ON conn.id = ic.connector_id
    WHERE ic.organization_id = v_org_id
      AND ic.status = 'active'
      AND conn.code = 'meta_marketing'
  ) INTO v_has_meta;

  IF NOT v_has_meta THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;

  INSERT INTO integration_events (connection_id, event_type, payload, status)
  SELECT ic.id, 'catalog.product_changed',
    jsonb_build_object(
      'organization_id', v_org_id,
      'product_id', v_product_id,
      'action', v_action,
      'trigger_op', TG_OP,
      'changed_at', now()
    ),
    'pending'
  FROM integration_connections ic
  JOIN integration_connectors conn ON conn.id = ic.connector_id
  WHERE ic.organization_id = v_org_id
    AND ic.status = 'active'
    AND conn.code = 'meta_marketing'
  LIMIT 1;

  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_meta_product_sync"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_normalize_domain_host"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $_$
BEGIN
  -- Normalizar a lowercase y trim
  NEW.host = lower(trim(NEW.host));
  
  -- Remover protocolo si alguien lo pone por error
  NEW.host = regexp_replace(NEW.host, '^https?://', '');
  
  -- Remover trailing slash
  NEW.host = regexp_replace(NEW.host, '/$', '');
  
  RETURN NEW;
END;
$_$;


ALTER FUNCTION "public"."fn_normalize_domain_host"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_normalize_payment_status"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  -- Normalizar el estado canónico del ERP: el website (goadmin-websites) y
  -- algunas integraciones externas insertan pagos con status='paid', pero el
  -- ERP usa internamente status='completed' en TODOS sus cálculos
  -- (fn_invoice_sales_paid, fn_recalc_invoice_balance_from_payments,
  -- reportes de caja, revenue OS, etc.). Sin esta normalización, un pago
  -- 'paid' vinculado a una factura NO se cuenta en el balance, dejando la
  -- factura con balance=total y generando una cuenta por cobrar fantasma.
  -- Esta función centraliza la normalización para que cualquier flujo
  -- (presente o futuro) que inserte 'paid' quede automáticamente como
  -- 'completed'.
  IF NEW.status = 'paid' THEN
    NEW.status := 'completed';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_normalize_payment_status"() OWNER TO "postgres";


