CREATE OR REPLACE FUNCTION "public"."fn_notify_opportunity_changed"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$
DECLARE
  v_stage_name TEXT;
  v_owner_id UUID;
BEGIN
  -- Resolver el "dueño" de la oportunidad: salesperson si existe, sino created_by
  v_owner_id := COALESCE(NEW.salesperson_id, NEW.created_by);

  -- Cambio de etapa
  IF OLD.stage_id IS DISTINCT FROM NEW.stage_id THEN
    SELECT name INTO v_stage_name FROM stages WHERE id = NEW.stage_id;

    PERFORM fn_create_org_notification(
      NEW.organization_id,
      v_owner_id,
      'app',
      'opportunity_stage_change',
      'Oportunidad avanzó de etapa',
      'La oportunidad "' || COALESCE(NEW.name, '#' || NEW.id) || '" pasó a: ' || COALESCE(v_stage_name, 'nueva etapa'),
      jsonb_build_object('opportunity_id', NEW.id::text, 'stage', COALESCE(v_stage_name, ''))
    );
  END IF;

  -- Ganada
  IF OLD.status IS DISTINCT FROM NEW.status AND NEW.status = 'won' THEN
    PERFORM fn_create_org_notification(
      NEW.organization_id, NULL, 'app', 'opportunity_won',
      '¡Oportunidad ganada!',
      '"' || COALESCE(NEW.name, '#' || NEW.id) || '" por $' || COALESCE(NEW.amount::text, '0'),
      jsonb_build_object('opportunity_id', NEW.id::text, 'amount', COALESCE(NEW.amount, 0)::text)
    );
  END IF;

  -- Perdida
  IF OLD.status IS DISTINCT FROM NEW.status AND NEW.status = 'lost' THEN
    PERFORM fn_create_org_notification(
      NEW.organization_id, v_owner_id, 'app', 'opportunity_lost',
      'Oportunidad perdida',
      '"' || COALESCE(NEW.name, '#' || NEW.id) || '" ha sido marcada como perdida.',
      jsonb_build_object('opportunity_id', NEW.id::text)
    );
  END IF;

  RETURN NEW;
END;
$_$;


ALTER FUNCTION "public"."fn_notify_opportunity_changed"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_notify_payment_registered"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$
DECLARE
  v_method text;
  v_existing_count int;
BEGIN
  -- No notificar pagos que no estén completados/pagos (ignora 'failed', 'pending', etc.)
  IF NEW.status NOT IN ('paid', 'completed') THEN
    RETURN NEW;
  END IF;

  -- Mapear submétodos de Wompi a la pasarela real
  v_method := NEW.method;
  IF v_method IN ('nequi', 'card', 'pse', 'bancolombia_transfer', 'bancolombia_collect', 'daviplata', 'wompi') THEN
    v_method := 'wompi';
  END IF;

  -- Evitar duplicados: si ya existe una notificación de pago para el mismo monto
  -- en los últimos 5 minutos para esta organización, no crear otra.
  -- (El flujo web inserta un payment 'web_order' y luego el ERP inserta otro 'invoice_sales'
  --  para el mismo pedido — ambos dispararían el trigger y duplicarían la notificación)
  SELECT COUNT(*) INTO v_existing_count
  FROM notifications
  WHERE organization_id = NEW.organization_id
    AND payload->>'type' = 'payment_registered'
    AND payload->>'amount' = COALESCE(NEW.amount, 0)::text
    AND created_at > now() - interval '5 minutes';

  IF v_existing_count > 0 THEN
    RETURN NEW;
  END IF;

  PERFORM fn_create_org_notification(
    NEW.organization_id, NULL, 'app', 'payment_registered',
    'Pago registrado',
    'Se registró un pago de $' || COALESCE(NEW.amount::text, '0') || ' — Método: ' || COALESCE(v_method, 'N/A'),
    jsonb_build_object('payment_id', NEW.id::text, 'amount', COALESCE(NEW.amount, 0)::text, 'method', v_method)
  );
  RETURN NEW;
END;
$_$;


ALTER FUNCTION "public"."fn_notify_payment_registered"() OWNER TO "postgres";


