CREATE OR REPLACE FUNCTION "public"."fn_notify_stock_low"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_product_name TEXT;
  v_org_id INT;
BEGIN
  -- Solo si qty_on_hand bajó
  IF NEW.qty_on_hand < OLD.qty_on_hand THEN
    SELECT p.name, p.organization_id 
    INTO v_product_name, v_org_id
    FROM products p WHERE p.id = NEW.product_id;

    IF v_org_id IS NOT NULL THEN
      -- Stock agotado
      IF NEW.qty_on_hand <= 0 THEN
        PERFORM fn_create_org_notification(
          v_org_id, NULL, 'app', 'stock_depleted',
          'Stock agotado: ' || COALESCE(v_product_name, 'Producto #' || NEW.product_id),
          'El producto se ha quedado sin existencias en la sucursal.',
          jsonb_build_object('product_id', NEW.product_id::text, 'branch_id', COALESCE(NEW.branch_id::text, ''), 'qty', NEW.qty_on_hand::text)
        );
      -- Stock bajo (por debajo del mínimo)
      ELSIF NEW.min_level IS NOT NULL AND NEW.qty_on_hand <= NEW.min_level THEN
        PERFORM fn_create_org_notification(
          v_org_id, NULL, 'app', 'stock_low',
          'Stock bajo: ' || COALESCE(v_product_name, 'Producto #' || NEW.product_id),
          'Quedan ' || NEW.qty_on_hand || ' unidades (mínimo: ' || NEW.min_level || ').',
          jsonb_build_object('product_id', NEW.product_id::text, 'branch_id', COALESCE(NEW.branch_id::text, ''), 'qty', NEW.qty_on_hand::text, 'min_level', NEW.min_level::text)
        );
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_notify_stock_low"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_notify_subscription_changed"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_owner_id UUID;
BEGIN
  -- Obtener el owner de la organización
  SELECT owner_user_id INTO v_owner_id FROM organizations WHERE id = NEW.organization_id;

  -- Suscripción cancelada
  IF OLD.status IS DISTINCT FROM NEW.status AND NEW.status = 'canceled' THEN
    PERFORM fn_create_org_notification(
      NEW.organization_id, v_owner_id, 'app', 'subscription_cancelled',
      'Suscripción cancelada',
      'Tu suscripción ha sido cancelada. Tus servicios continuarán hasta el final del período actual.',
      jsonb_build_object('subscription_id', NEW.id::text)
    );
  END IF;

  -- Trial terminó
  IF OLD.status IS DISTINCT FROM NEW.status AND OLD.status = 'trialing' AND NEW.status = 'active' THEN
    PERFORM fn_create_org_notification(
      NEW.organization_id, v_owner_id, 'app', 'trial_ended',
      'Período de prueba finalizado',
      'Tu período de prueba ha terminado. Tu plan activo ahora está vigente.',
      jsonb_build_object('subscription_id', NEW.id::text)
    );
  END IF;

  -- Pago fallido
  IF OLD.status IS DISTINCT FROM NEW.status AND NEW.status = 'past_due' THEN
    PERFORM fn_create_org_notification(
      NEW.organization_id, v_owner_id, 'app', 'payment_failed',
      'Pago de suscripción fallido',
      'No se pudo procesar el pago de tu suscripción. Por favor actualiza tu método de pago.',
      jsonb_build_object('subscription_id', NEW.id::text)
    );
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_notify_subscription_changed"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_notify_task_assigned"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  -- Solo si se asignó a alguien
  IF NEW.assigned_to IS NOT NULL AND (TG_OP = 'INSERT' OR OLD.assigned_to IS DISTINCT FROM NEW.assigned_to) THEN
    PERFORM fn_create_org_notification(
      NEW.organization_id,
      NEW.assigned_to,
      'app',
      'task_assigned',
      'Nueva tarea asignada: ' || COALESCE(NEW.title, 'Sin título'),
      COALESCE(NEW.description, 'Se te ha asignado una nueva tarea.'),
      jsonb_build_object('task_id', NEW.id::text, 'priority', COALESCE(NEW.priority, 'normal'))
    );
  END IF;

  -- Tarea completada → notificar al creador
  IF TG_OP = 'UPDATE' AND OLD.status IS DISTINCT FROM NEW.status AND NEW.status = 'done' AND NEW.created_by IS NOT NULL THEN
    PERFORM fn_create_org_notification(
      NEW.organization_id,
      NEW.created_by,
      'app',
      'task_completed',
      'Tarea completada: ' || COALESCE(NEW.title, 'Sin título'),
      'La tarea ha sido marcada como completada.',
      jsonb_build_object('task_id', NEW.id::text)
    );
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_notify_task_assigned"() OWNER TO "postgres";


