CREATE OR REPLACE FUNCTION "public"."fn_notify_transfer_status"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  IF OLD.status IS DISTINCT FROM NEW.status AND NEW.status IN ('approved', 'rejected', 'completed') THEN
    PERFORM fn_create_org_notification(
      NEW.organization_id, 
      NEW.created_by,
      'app', 
      'transfer_' || NEW.status,
      'Transferencia ' || CASE NEW.status WHEN 'approved' THEN 'aprobada' WHEN 'rejected' THEN 'rechazada' WHEN 'completed' THEN 'completada' ELSE NEW.status END,
      'La transferencia #' || NEW.id || ' ha sido ' || CASE NEW.status WHEN 'approved' THEN 'aprobada' WHEN 'rejected' THEN 'rechazada' WHEN 'completed' THEN 'completada' ELSE NEW.status END || '.',
      jsonb_build_object('transfer_id', NEW.id::text, 'status', NEW.status)
    );
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_notify_transfer_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_occupancy_rate"("p_date" "date", "p_space_type_id" "uuid" DEFAULT NULL::"uuid", "p_branch_id" integer DEFAULT NULL::integer) RETURNS TABLE("space_type_name" "text", "total_spaces" integer, "occupied_spaces" integer, "occupancy_percentage" numeric)
    LANGUAGE "plpgsql" STABLE
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    st.name AS space_type_name,
    COUNT(DISTINCT s.id)::INTEGER AS total_spaces,
    COUNT(DISTINCT CASE 
      WHEN EXISTS (
        SELECT 1 
        FROM reservation_spaces rs
        JOIN reservations r ON rs.reservation_id = r.id
        WHERE rs.space_id = s.id
          AND r.status IN ('confirmed', 'checked_in')
          AND p_date >= r.checkin 
          AND p_date < r.checkout
      ) THEN s.id 
    END)::INTEGER AS occupied_spaces,
    ROUND(
      (COUNT(DISTINCT CASE 
        WHEN EXISTS (
          SELECT 1 
          FROM reservation_spaces rs
          JOIN reservations r ON rs.reservation_id = r.id
          WHERE rs.space_id = s.id
            AND r.status IN ('confirmed', 'checked_in')
            AND p_date >= r.checkin 
            AND p_date < r.checkout
        ) THEN s.id 
      END)::NUMERIC / NULLIF(COUNT(DISTINCT s.id), 0)) * 100, 
      2
    ) AS occupancy_percentage
  FROM spaces s
  JOIN space_types st ON s.space_type_id = st.id
  WHERE 
    s.status NOT IN ('out_of_order', 'maintenance')
    AND (p_space_type_id IS NULL OR s.space_type_id = p_space_type_id)
    AND (p_branch_id IS NULL OR s.branch_id = p_branch_id)
  GROUP BY st.name;
END;
$$;


ALTER FUNCTION "public"."fn_occupancy_rate"("p_date" "date", "p_space_type_id" "uuid", "p_branch_id" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_occupancy_rate"("p_date" "date", "p_space_type_id" "uuid", "p_branch_id" integer) IS 'Calcula el porcentaje de ocupación por tipo de espacio en una fecha específica.
Uso: SELECT * FROM fn_occupancy_rate(CURRENT_DATE);';



