    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.status IN ('won','lost') AND (OLD.status IS DISTINCT FROM NEW.status) THEN
    NEW.closed_at := COALESCE(NEW.closed_at, now());
  ELSIF NEW.status NOT IN ('won','lost') THEN
    NEW.closed_at := NULL;
  END IF;
  RETURN NEW;
END;
$$;


