CREATE OR REPLACE FUNCTION "public"."fn_organization_domains_before_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  -- Generar token y value de verificación si no existe
  IF NEW.verification_token IS NULL AND NEW.domain_type != 'system_subdomain' THEN
    NEW.verification_token = fn_generate_domain_verification_token();
    NEW.verification_record = '_go-admin-verify.' || split_part(NEW.host, '.', 1);
    NEW.verification_value = NEW.verification_token; -- El valor TXT es el mismo token
  END IF;
  
  -- Si es system_subdomain, marcar como verificado automáticamente
  IF NEW.domain_type = 'system_subdomain' THEN
    NEW.status = 'verified';
    NEW.verified_at = now();
  END IF;
  
  RETURN NEW;
END;
$$;


