CREATE OR REPLACE FUNCTION "public"."fn_pause_sequences_on_reply"("p_org" integer, "p_opportunity_id" "uuid", "p_customer_id" "uuid", "p_channel" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE n integer;
BEGIN
  IF (select auth.uid()) IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.organization_members om
     WHERE om.organization_id = p_org
       AND om.user_id = (select auth.uid())
       AND om.is_active
  ) THEN
    RAISE EXCEPTION 'no pertenece a la organizacion %', p_org USING ERRCODE = '42501';
  END IF;

  UPDATE sequence_enrollments e
     SET status = 'paused', paused_reason = 'customer_replied_' || COALESCE(p_channel,'unknown'), paused_at = now()
    FROM sequences s
   WHERE e.sequence_id = s.id
     AND e.organization_id = p_org
     AND e.status = 'active'
     AND s.pause_on_reply
     AND ((p_opportunity_id IS NOT NULL AND e.opportunity_id = p_opportunity_id)
       OR (p_opportunity_id IS NULL AND p_customer_id IS NOT NULL AND e.customer_id = p_customer_id));
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END $$;


ALTER FUNCTION "public"."fn_pause_sequences_on_reply"("p_org" integer, "p_opportunity_id" "uuid", "p_customer_id" "uuid", "p_channel" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_pipeline_funnel"("p_org_id" integer) RETURNS TABLE("stage_id" "uuid", "stage_name" "text", "position" integer, "opportunity_count" bigint, "total_amount" numeric, "avg_amount" numeric)
    LANGUAGE "sql" STABLE
    AS $$
  SELECT
    s.id AS stage_id,
    s.name AS stage_name,
    s."position",
    COUNT(o.id) AS opportunity_count,
    COALESCE(SUM(o.amount), 0) AS total_amount,
    AVG(o.amount) AS avg_amount
  FROM stages s
  JOIN pipelines pl ON s.pipeline_id = pl.id
  LEFT JOIN opportunities o ON o.stage_id = s.id AND o.organization_id = p_org_id
  WHERE pl.organization_id = p_org_id
  GROUP BY s.id, s.name, s."position"
  ORDER BY s."position";
$$;


ALTER FUNCTION "public"."fn_pipeline_funnel"("p_org_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_recalc_invoice_balance_from_payments"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$
DECLARE
  r RECORD;
  v_invoice_id uuid;
  v_paid numeric;
  v_total numeric;
  v_balance numeric;
  v_status text;
  v_new_status text;
BEGIN
  -- Se recalcula el destino nuevo y el anterior: un UPDATE puede mover el pago
  -- de una factura a otra, y ambas quedarian desactualizadas.
  FOR r IN
    SELECT DISTINCT src, sid
    FROM (VALUES
      (CASE WHEN TG_OP <> 'DELETE' THEN NEW.source END,
       CASE WHEN TG_OP <> 'DELETE' THEN NEW.source_id END),
      (CASE WHEN TG_OP <> 'INSERT' THEN OLD.source END,
       CASE WHEN TG_OP <> 'INSERT' THEN OLD.source_id END)
    ) AS t(src, sid)
    WHERE src IN ('invoice_sales', 'invoice_purchase', 'sale')
      AND sid ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  LOOP
    IF r.src = 'invoice_purchase' THEN
      SELECT total, status INTO v_total, v_status
      FROM invoice_purchase WHERE id = r.sid::uuid;

      CONTINUE WHEN v_total IS NULL;
      CONTINUE WHEN v_status IN ('draft', 'void', 'voided');

      SELECT COALESCE(SUM(amount), 0) INTO v_paid
      FROM payments
      WHERE source = 'invoice_purchase' AND source_id = r.sid AND status = 'completed';

      v_balance := GREATEST(v_total - v_paid, 0);

      -- Solo el balance: el status de compras mezcla la recepcion de inventario
      -- ('received') con el estado de pago, y derivarlo aqui pisaria informacion.
      UPDATE invoice_purchase
      SET balance = v_balance, updated_at = NOW()
      WHERE id = r.sid::uuid AND balance IS DISTINCT FROM v_balance;

      CONTINUE;
    END IF;

    -- Facturas de venta: el pago puede venir referenciado a la factura (POS) o a
    -- la venta (mesas), asi que se resuelve el id de factura en ambos casos.
    IF r.src = 'invoice_sales' THEN
      v_invoice_id := r.sid::uuid;
    ELSE
      SELECT id INTO v_invoice_id FROM invoice_sales WHERE sale_id = r.sid::uuid LIMIT 1;
    END IF;

    CONTINUE WHEN v_invoice_id IS NULL;

    SELECT total, status INTO v_total, v_status
    FROM invoice_sales WHERE id = v_invoice_id;

    CONTINUE WHEN v_total IS NULL;
    -- Anuladas y borradores quedan intactas.
    CONTINUE WHEN v_status IN ('draft', 'void', 'voided');

    v_paid := fn_invoice_sales_paid(v_invoice_id);
    v_balance := GREATEST(v_total - v_paid, 0);

    -- El status solo se deriva cuando hay dinero recibido. Si no hay pagos no se
    -- fuerza nada: una factura marcada como pagada a mano (cobro fuera del
    -- sistema) es una decision del operador que no corresponde revertir aqui.
    v_new_status := v_status;
    IF v_paid > 0 THEN
      v_new_status := CASE WHEN v_balance = 0 THEN 'paid' ELSE 'partial' END;
    END IF;

    UPDATE invoice_sales
    SET balance = v_balance,
        status = v_new_status,
        updated_at = NOW()
    WHERE id = v_invoice_id
      AND (balance IS DISTINCT FROM v_balance OR status IS DISTINCT FROM v_new_status);
  END LOOP;

  RETURN NULL;
END;
$_$;


ALTER FUNCTION "public"."fn_recalc_invoice_balance_from_payments"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_recalc_invoice_totals"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_sales_id uuid;
  v_purchase_id uuid;
  v_subtotal numeric;
  v_total numeric;
  v_tax numeric;
  v_paid numeric;
  v_new_balance numeric;
  v_status text;
  v_tax_included boolean;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_sales_id := COALESCE(OLD.invoice_sales_id, CASE WHEN OLD.invoice_type = 'sale' THEN OLD.invoice_id END);
    v_purchase_id := COALESCE(OLD.invoice_purchase_id, CASE WHEN OLD.invoice_type = 'purchase' THEN OLD.invoice_id END);
  ELSE
    v_sales_id := COALESCE(NEW.invoice_sales_id, CASE WHEN NEW.invoice_type = 'sale' THEN NEW.invoice_id END);
    v_purchase_id := COALESCE(NEW.invoice_purchase_id, CASE WHEN NEW.invoice_type = 'purchase' THEN OLD.invoice_id END);
  END IF;

  -- ===== FACTURA DE VENTA =====
  IF v_sales_id IS NOT NULL THEN
    -- Obtener tax_included de la factura
    SELECT tax_included INTO v_tax_included FROM invoice_sales WHERE id = v_sales_id;

    IF v_tax_included THEN
      -- Si los impuestos están incluidos en el precio:
      -- total_line incluye el impuesto, hay que separar la base del impuesto
      SELECT
        COALESCE(SUM(
          CASE
            WHEN tax_rate > 0 THEN (qty * unit_price - COALESCE(discount_amount, 0)) / (1 + tax_rate / 100)
            ELSE (qty * unit_price - COALESCE(discount_amount, 0))
          END
        ), 0),
        COALESCE(SUM(total_line), 0)
      INTO v_subtotal, v_total
      FROM invoice_items
      WHERE invoice_sales_id = v_sales_id
         OR (invoice_id = v_sales_id AND invoice_type = 'sale');
    ELSE
      -- Si los impuestos NO están incluidos:
      -- subtotal = qty * unit_price - discount, total = total_line
      SELECT
        COALESCE(SUM(qty * unit_price - COALESCE(discount_amount, 0)), 0),
        COALESCE(SUM(total_line), 0)
      INTO v_subtotal, v_total
      FROM invoice_items
      WHERE invoice_sales_id = v_sales_id
         OR (invoice_id = v_sales_id AND invoice_type = 'sale');
    END IF;

    v_tax := GREATEST(v_total - v_subtotal, 0);

    -- Cuenta los pagos de ambas fuentes (POS y mesas).
    v_paid := fn_invoice_sales_paid(v_sales_id);

    v_new_balance := GREATEST(v_total - v_paid, 0);

    SELECT status INTO v_status FROM invoice_sales WHERE id = v_sales_id;

    -- Las anuladas conservan su balance en 0: no se les revive la deuda.
    IF v_status IN ('void', 'voided') THEN
      UPDATE invoice_sales
      SET subtotal = v_subtotal,
          tax_total = v_tax,
          total = v_total,
          updated_at = NOW()
      WHERE id = v_sales_id
        AND (total IS DISTINCT FROM v_total
          OR subtotal IS DISTINCT FROM v_subtotal
          OR tax_total IS DISTINCT FROM v_tax);
    ELSE
      UPDATE invoice_sales
      SET subtotal = v_subtotal,
          tax_total = v_tax,
          total = v_total,
          balance = v_new_balance,
          updated_at = NOW()
      WHERE id = v_sales_id
        AND (total IS DISTINCT FROM v_total
          OR subtotal IS DISTINCT FROM v_subtotal
          OR tax_total IS DISTINCT FROM v_tax
          OR balance IS DISTINCT FROM v_new_balance);
    END IF;
  END IF;

  -- ===== FACTURA DE COMPRA =====
  IF v_purchase_id IS NOT NULL THEN
    SELECT
      COALESCE(SUM(qty * unit_price - COALESCE(discount_amount, 0)), 0),
      COALESCE(SUM(total_line), 0)
    INTO v_subtotal, v_total
    FROM invoice_items
    WHERE invoice_purchase_id = v_purchase_id
       OR (invoice_id = v_purchase_id AND invoice_type = 'purchase');

    v_tax := GREATEST(v_total - v_subtotal, 0);

    SELECT COALESCE(SUM(amount), 0) INTO v_paid
    FROM payments
    WHERE source = 'invoice_purchase' AND source_id = v_purchase_id::text AND status = 'completed';

    v_new_balance := GREATEST(v_total - v_paid, 0);

    UPDATE invoice_purchase
    SET subtotal = v_subtotal,
        tax_total = v_tax,
        total = v_total,
        balance = v_new_balance,
        updated_at = NOW()
    WHERE id = v_purchase_id
      AND (total IS DISTINCT FROM v_total
        OR subtotal IS DISTINCT FROM v_subtotal
        OR tax_total IS DISTINCT FROM v_tax
        OR balance IS DISTINCT FROM v_new_balance);
  END IF;

  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."fn_recalc_invoice_totals"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_release_job"("p_job_id" "uuid", "p_worker" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_id uuid;
BEGIN
  UPDATE public.outbound_jobs
     SET status = 'queued',
         attempts = GREATEST(attempts - 1, 0),
         locked_at = NULL,
         locked_by = NULL,
         run_at = now()
   WHERE id = p_job_id AND status = 'running' AND locked_by = p_worker
   RETURNING id INTO v_id;
  RETURN v_id IS NOT NULL;
END $$;


ALTER FUNCTION "public"."fn_release_job"("p_job_id" "uuid", "p_worker" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_release_seat"("p_trip_id" "uuid", "p_seat_label" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_released BOOLEAN := false;
BEGIN
  UPDATE trip_seats
  SET status = 'available',
      ticket_id = NULL,
      reserved_until = NULL,
      updated_at = now()
  WHERE trip_id = p_trip_id
    AND seat_label = p_seat_label
    AND status IN ('reserved', 'sold')
  RETURNING true INTO v_released;
  
  IF v_released THEN
    UPDATE trips SET available_seats = available_seats + 1 WHERE id = p_trip_id;
  END IF;
  
  RETURN COALESCE(v_released, false);
END;
$$;


ALTER FUNCTION "public"."fn_release_seat"("p_trip_id" "uuid", "p_seat_label" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_reporte_balance_general"("p_organization_id" bigint, "p_as_of" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_activos numeric;
  v_pasivos numeric;
  v_patrimonio numeric;
  v_detalle jsonb;
BEGIN
  -- Sumar saldos acumulados hasta la fecha
  SELECT
    COALESCE(SUM(CASE WHEN ca.type = 'asset' THEN jl.debit_base - jl.credit_base ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN ca.type = 'liability' THEN jl.credit_base - jl.debit_base ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN ca.type = 'equity' THEN jl.credit_base - jl.debit_base ELSE 0 END), 0)
  INTO v_activos, v_pasivos, v_patrimonio
  FROM journal_lines jl
  JOIN journal_entries je ON jl.journal_entry_id = je.id
  JOIN chart_of_accounts ca ON jl.account_code = ca.account_code
  WHERE je.organization_id = p_organization_id
    AND je.entry_date <= p_as_of
    AND je.posted = true
    AND ca.organization_id = p_organization_id
    AND ca.type IN ('asset', 'liability', 'equity');

  -- Detalle por cuenta
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'cuenta', d.account_code,
    'nombre', d.name,
    'tipo', d.type,
    'saldo', d.saldo
  )), '[]'::jsonb) INTO v_detalle
  FROM (
    SELECT ca.account_code, ca.name, ca.type,
           CASE WHEN ca.type = 'asset' THEN COALESCE(SUM(jl.debit_base - jl.credit_base), 0)
                ELSE COALESCE(SUM(jl.credit_base - jl.debit_base), 0) END AS saldo
    FROM journal_lines jl
    JOIN journal_entries je ON jl.journal_entry_id = je.id
    JOIN chart_of_accounts ca ON jl.account_code = ca.account_code
    WHERE je.organization_id = p_organization_id
      AND je.entry_date <= p_as_of
      AND je.posted = true
      AND ca.organization_id = p_organization_id
      AND ca.type IN ('asset', 'liability', 'equity')
    GROUP BY ca.account_code, ca.name, ca.type
    HAVING CASE WHEN ca.type = 'asset' THEN COALESCE(SUM(jl.debit_base - jl.credit_base), 0)
                ELSE COALESCE(SUM(jl.credit_base - jl.debit_base), 0) END <> 0
    ORDER BY ca.type, ca.account_code
  ) d;

  RETURN jsonb_build_object(
    'activos', v_activos,
    'pasivos', v_pasivos,
    'patrimonio', v_patrimonio,
    'total_pasivo_patrimonio', v_pasivos + v_patrimonio,
    'detalle', v_detalle
  );
END;
$$;


ALTER FUNCTION "public"."fn_reporte_balance_general"("p_organization_id" bigint, "p_as_of" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_reporte_chat_sla"("p_organization_id" bigint, "p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_total_conversaciones integer;
  v_promedio_primera_respuesta numeric;
  v_promedio_resolucion numeric;
  v_por_estado jsonb;
BEGIN
  SELECT COUNT(*) INTO v_total_conversaciones
  FROM conversations c
  WHERE c.organization_id = p_organization_id
    AND c.created_at >= p_from AND c.created_at <= p_to;

  SELECT COALESCE(AVG(c.first_response_time_seconds), 0) INTO v_promedio_primera_respuesta
  FROM conversations c
  WHERE c.organization_id = p_organization_id
    AND c.created_at >= p_from AND c.created_at <= p_to
    AND c.first_response_time_seconds IS NOT NULL;

  SELECT COALESCE(AVG(c.avg_response_time_seconds), 0) INTO v_promedio_resolucion
  FROM conversations c
  WHERE c.organization_id = p_organization_id
    AND c.created_at >= p_from AND c.created_at <= p_to
    AND c.avg_response_time_seconds IS NOT NULL;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'estado', e.status,
    'cantidad', e.cantidad
  )), '[]'::jsonb) INTO v_por_estado
  FROM (
    SELECT c.status, COUNT(*) AS cantidad
    FROM conversations c
    WHERE c.organization_id = p_organization_id
      AND c.created_at >= p_from AND c.created_at <= p_to
    GROUP BY c.status
    ORDER BY cantidad DESC
  ) e;

  RETURN jsonb_build_object(
    'total_conversaciones', v_total_conversaciones,
    'promedio_primera_respuesta_seg', v_promedio_primera_respuesta,
    'promedio_resolucion_seg', v_promedio_resolucion,
    'por_estado', v_por_estado
  );
END;
$$;


ALTER FUNCTION "public"."fn_reporte_chat_sla"("p_organization_id" bigint, "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_reporte_cierre_caja"("p_organization_id" bigint, "p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_sesiones jsonb;
  v_por_metodo jsonb;
  v_descuentos numeric;
  v_devoluciones numeric;
  v_propinas numeric;
  v_total_ventas numeric;
  v_total_esperado numeric;
  v_total_real numeric;
BEGIN
  -- Sesiones de caja del período
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', cs.id,
    'sucursal_id', cs.branch_id,
    'abierta_por', cs.opened_by,
    'abierta_en', cs.opened_at,
    'cerrada_en', cs.closed_at,
    'monto_inicial', cs.initial_amount,
    'monto_final', cs.final_amount,
    'diferencia', cs.difference,
    'estado', cs.status
  )), '[]'::jsonb) INTO v_sesiones
  FROM cash_sessions cs
  WHERE cs.organization_id = p_organization_id
    AND cs.opened_at >= p_from AND cs.opened_at <= p_to;

  -- Totales por método de pago
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'metodo', pm.method,
    'cantidad', pm.cantidad,
    'total', pm.total
  )), '[]'::jsonb) INTO v_por_metodo
  FROM (
    SELECT p.method, COUNT(*) AS cantidad, COALESCE(SUM(p.amount), 0) AS total
    FROM payments p
    WHERE p.organization_id = p_organization_id
      AND p.created_at >= p_from AND p.created_at <= p_to
      AND p.status = 'completed'
    GROUP BY p.method
  ) pm;

  -- Descuentos del período
  SELECT COALESCE(SUM(s.discount_total), 0) INTO v_descuentos
  FROM sales s
  WHERE s.organization_id = p_organization_id
    AND s.sale_date >= p_from AND s.sale_date <= p_to
    AND s.status NOT IN ('cancelled', 'void');

  -- Devoluciones (returns usa total_refund)
  SELECT COALESCE(SUM(r.total_refund), 0) INTO v_devoluciones
  FROM returns r
  WHERE r.organization_id = p_organization_id
    AND r.return_date >= p_from AND r.return_date <= p_to;

  -- Propinas
  SELECT COALESCE(SUM(s.tip_amount), 0) INTO v_propinas
  FROM sales s
  WHERE s.organization_id = p_organization_id
    AND s.sale_date >= p_from AND s.sale_date <= p_to
    AND s.status NOT IN ('cancelled', 'void');

  -- Total ventas
  SELECT COALESCE(SUM(s.total), 0) INTO v_total_ventas
  FROM sales s
  WHERE s.organization_id = p_organization_id
    AND s.sale_date >= p_from AND s.sale_date <= p_to
    AND s.status NOT IN ('cancelled', 'void');

  -- Total esperado (suma de pagos completados)
  SELECT COALESCE(SUM(p.amount), 0) INTO v_total_esperado
  FROM payments p
  WHERE p.organization_id = p_organization_id
    AND p.created_at >= p_from AND p.created_at <= p_to
    AND p.status = 'completed';

  -- Total real (suma de montos finales de sesiones cerradas)
  SELECT COALESCE(SUM(cs.final_amount), 0) INTO v_total_real
  FROM cash_sessions cs
  WHERE cs.organization_id = p_organization_id
    AND cs.opened_at >= p_from AND cs.opened_at <= p_to
    AND cs.status = 'closed';

  RETURN jsonb_build_object(
    'sesiones', v_sesiones,
    'por_metodo', v_por_metodo,
    'descuentos', v_descuentos,
    'devoluciones', v_devoluciones,
    'propinas', v_propinas,
    'total_ventas', v_total_ventas,
    'esperado_vs_real', jsonb_build_object(
      'esperado', v_total_esperado,
      'real', v_total_real,
      'diferencia', v_total_real - v_total_esperado
    )
  );
END;
$$;


ALTER FUNCTION "public"."fn_reporte_cierre_caja"("p_organization_id" bigint, "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_reporte_clientes_crecimiento"("p_organization_id" bigint, "p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_por_mes jsonb;
  v_total_acumulado integer;
  v_nuevos integer;
BEGIN
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'mes', m.mes,
    'nuevos', m.nuevos,
    'acumulado', m.acumulado
  )), '[]'::jsonb) INTO v_por_mes
  FROM (
    SELECT DATE_TRUNC('month', c.created_at) AS mes,
           COUNT(*) AS nuevos,
           SUM(COUNT(*)) OVER (ORDER BY DATE_TRUNC('month', c.created_at)) AS acumulado
    FROM customers c
    WHERE c.organization_id = p_organization_id
      AND c.created_at >= p_from AND c.created_at <= p_to
    GROUP BY DATE_TRUNC('month', c.created_at)
    ORDER BY mes
  ) m;

  SELECT COUNT(*) INTO v_total_acumulado
  FROM customers c
  WHERE c.organization_id = p_organization_id
    AND c.created_at <= p_to;

  SELECT COUNT(*) INTO v_nuevos
  FROM customers c
  WHERE c.organization_id = p_organization_id
    AND c.created_at >= p_from AND c.created_at <= p_to;

  RETURN jsonb_build_object(
    'por_mes', v_por_mes,
    'total_acumulado', v_total_acumulado,
    'nuevos_en_periodo', v_nuevos
  );
END;
$$;


ALTER FUNCTION "public"."fn_reporte_clientes_crecimiento"("p_organization_id" bigint, "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_reporte_crm_funnel"("p_organization_id" bigint, "p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_por_etapa jsonb;
  v_total_pipeline numeric;
  v_forecast numeric;
BEGIN
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'etapa_id', e.stage_id,
    'etapa_nombre', e.name,
    'cantidad', e.cantidad,
    'monto_total', e.monto,
    'probabilidad', e.probability
  )), '[]'::jsonb) INTO v_por_etapa
  FROM (
    SELECT o.stage_id, s.name, s.probability, s.position,
           COUNT(*) AS cantidad,
           COALESCE(SUM(o.amount), 0) AS monto
    FROM opportunities o
    JOIN stages s ON o.stage_id = s.id
    WHERE o.organization_id = p_organization_id
      AND o.status = 'open'
      AND o.created_at >= p_from AND o.created_at <= p_to
    GROUP BY o.stage_id, s.name, s.probability, s.position
    ORDER BY s.position
  ) e;

  SELECT COALESCE(SUM(o.amount), 0) INTO v_total_pipeline
  FROM opportunities o
  WHERE o.organization_id = p_organization_id
    AND o.status = 'open'
    AND o.created_at >= p_from AND o.created_at <= p_to;

  SELECT COALESCE(SUM(o.amount * s.probability / 100.0), 0) INTO v_forecast
  FROM opportunities o
  JOIN stages s ON o.stage_id = s.id
  WHERE o.organization_id = p_organization_id
    AND o.status = 'open'
    AND o.created_at >= p_from AND o.created_at <= p_to;

  RETURN jsonb_build_object(
    'por_etapa', v_por_etapa,
    'total_pipeline', v_total_pipeline,
    'forecast', v_forecast
  );
END;
$$;


ALTER FUNCTION "public"."fn_reporte_crm_funnel"("p_organization_id" bigint, "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_reporte_crm_ranking_vendedores"("p_organization_id" bigint, "p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_ranking jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'vendedor_id', r.salesperson_id,
    'oportunidades_abiertas', r.abiertas,
    'oportunidades_ganadas', r.ganadas,
    'monto_ganado', r.monto_ganado,
    'tasa_cierre', r.tasa
  )), '[]'::jsonb) INTO v_ranking
  FROM (
    SELECT o.salesperson_id,
           COUNT(CASE WHEN o.status = 'open' THEN 1 END) AS abiertas,
           COUNT(CASE WHEN o.status = 'won' THEN 1 END) AS ganadas,
           COALESCE(SUM(CASE WHEN o.status = 'won' THEN o.amount ELSE 0 END), 0) AS monto_ganado,
           CASE WHEN COUNT(*) > 0 THEN round(COUNT(CASE WHEN o.status = 'won' THEN 1 END)::numeric / COUNT(*) * 100, 2) ELSE 0 END AS tasa
    FROM opportunities o
    WHERE o.organization_id = p_organization_id
      AND o.created_at >= p_from AND o.created_at <= p_to
      AND o.salesperson_id IS NOT NULL
    GROUP BY o.salesperson_id
    ORDER BY monto_ganado DESC
  ) r;

  RETURN jsonb_build_object('ranking', v_ranking);
END;
$$;


ALTER FUNCTION "public"."fn_reporte_crm_ranking_vendedores"("p_organization_id" bigint, "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_reporte_cxc_aging"("p_organization_id" bigint, "p_as_of" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_buckets jsonb;
  v_total numeric;
BEGIN
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'bucket', b.bucket,
    'total', b.total,
    'cantidad', b.cantidad
  )), '[]'::jsonb) INTO v_buckets
  FROM (
    SELECT
      CASE
        WHEN COALESCE(ar.days_overdue, 0) = 0 THEN 'corriente'
        WHEN ar.days_overdue BETWEEN 1 AND 30 THEN '1-30'
        WHEN ar.days_overdue BETWEEN 31 AND 60 THEN '31-60'
        WHEN ar.days_overdue BETWEEN 61 AND 90 THEN '61-90'
        ELSE '+90'
      END AS bucket,
      COALESCE(SUM(ar.balance), 0) AS total,
      COUNT(*) AS cantidad
    FROM accounts_receivable ar
    WHERE ar.organization_id = p_organization_id
      AND ar.status NOT IN ('paid', 'cancelled')
      AND ar.due_date <= p_as_of + INTERVAL '90 days'
    GROUP BY bucket
    ORDER BY bucket
  ) b;

  SELECT COALESCE(SUM(ar.balance), 0) INTO v_total
  FROM accounts_receivable ar
  WHERE ar.organization_id = p_organization_id
    AND ar.status NOT IN ('paid', 'cancelled');

  RETURN jsonb_build_object('buckets', v_buckets, 'total', v_total);
END;
$$;


ALTER FUNCTION "public"."fn_reporte_cxc_aging"("p_organization_id" bigint, "p_as_of" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_reporte_cxp_aging"("p_organization_id" bigint, "p_as_of" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_buckets jsonb;
  v_total numeric;
BEGIN
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'bucket', b.bucket,
    'total', b.total,
    'cantidad', b.cantidad
  )), '[]'::jsonb) INTO v_buckets
  FROM (
    SELECT
      CASE
        WHEN COALESCE(ap.days_overdue, 0) = 0 THEN 'corriente'
        WHEN ap.days_overdue BETWEEN 1 AND 30 THEN '1-30'
        WHEN ap.days_overdue BETWEEN 31 AND 60 THEN '31-60'
        WHEN ap.days_overdue BETWEEN 61 AND 90 THEN '61-90'
        ELSE '+90'
      END AS bucket,
      COALESCE(SUM(ap.balance), 0) AS total,
      COUNT(*) AS cantidad
    FROM accounts_payable ap
    WHERE ap.organization_id = p_organization_id
      AND ap.status NOT IN ('paid', 'cancelled')
      AND ap.due_date <= p_as_of + INTERVAL '90 days'
    GROUP BY bucket
    ORDER BY bucket
  ) b;

  SELECT COALESCE(SUM(ap.balance), 0) INTO v_total
  FROM accounts_payable ap
  WHERE ap.organization_id = p_organization_id
    AND ap.status NOT IN ('paid', 'cancelled');

  RETURN jsonb_build_object('buckets', v_buckets, 'total', v_total);
END;
$$;


