CREATE OR REPLACE FUNCTION "public"."fn_reporte_estado_resultados"("p_organization_id" bigint, "p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_ingresos numeric;
  v_costos numeric;
  v_gastos numeric;
  v_utilidad_bruta numeric;
  v_utilidad_operativa numeric;
  v_utilidad_neta numeric;
  v_detalle jsonb;
BEGIN
  -- Sumar débitos/créditos por tipo de cuenta
  SELECT
    COALESCE(SUM(CASE WHEN ca.type = 'income' THEN jl.credit_base - jl.debit_base ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN ca.type = 'cost' THEN jl.debit_base - jl.credit_base ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN ca.type = 'expense' THEN jl.debit_base - jl.credit_base ELSE 0 END), 0)
  INTO v_ingresos, v_costos, v_gastos
  FROM journal_lines jl
  JOIN journal_entries je ON jl.journal_entry_id = je.id
  JOIN chart_of_accounts ca ON jl.account_code = ca.account_code
  WHERE je.organization_id = p_organization_id
    AND je.entry_date >= p_from AND je.entry_date <= p_to
    AND je.posted = true
    AND ca.organization_id = p_organization_id;

  v_utilidad_bruta := v_ingresos - v_costos;
  v_utilidad_operativa := v_utilidad_bruta - v_gastos;
  v_utilidad_neta := v_utilidad_operativa;

  -- Detalle por cuenta
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'cuenta', d.account_code,
    'nombre', d.name,
    'tipo', d.type,
    'monto', d.monto
  )), '[]'::jsonb) INTO v_detalle
  FROM (
    SELECT ca.account_code, ca.name, ca.type,
           CASE WHEN ca.type = 'income' THEN COALESCE(SUM(jl.credit_base - jl.debit_base), 0)
                ELSE COALESCE(SUM(jl.debit_base - jl.credit_base), 0) END AS monto
    FROM journal_lines jl
    JOIN journal_entries je ON jl.journal_entry_id = je.id
    JOIN chart_of_accounts ca ON jl.account_code = ca.account_code
    WHERE je.organization_id = p_organization_id
      AND je.entry_date >= p_from AND je.entry_date <= p_to
      AND je.posted = true
      AND ca.organization_id = p_organization_id
      AND ca.type IN ('income', 'cost', 'expense')
    GROUP BY ca.account_code, ca.name, ca.type
    ORDER BY ca.type, ca.account_code
  ) d;

  RETURN jsonb_build_object(
    'ingresos', v_ingresos,
    'costos', v_costos,
    'gastos', v_gastos,
    'utilidad_bruta', v_utilidad_bruta,
    'utilidad_operativa', v_utilidad_operativa,
    'utilidad_neta', v_utilidad_neta,
    'detalle', v_detalle
  );
END;
$$;


ALTER FUNCTION "public"."fn_reporte_estado_resultados"("p_organization_id" bigint, "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_reporte_flujo_efectivo"("p_organization_id" bigint, "p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_operativo numeric;
  v_inversion numeric;
  v_financiacion numeric;
  v_entradas numeric;
  v_salidas numeric;
BEGIN
  -- Entradas operativas (pagos recibidos)
  SELECT COALESCE(SUM(p.amount), 0) INTO v_entradas
  FROM payments p
  WHERE p.organization_id = p_organization_id
    AND p.created_at >= p_from AND p.created_at <= p_to
    AND p.status = 'completed'
    AND p.source NOT IN ('account_payable');

  -- Salidas operativas (pagos a proveedores)
  SELECT COALESCE(SUM(p.amount), 0) INTO v_salidas
  FROM payments p
  WHERE p.organization_id = p_organization_id
    AND p.created_at >= p_from AND p.created_at <= p_to
    AND p.status = 'completed'
    AND p.source = 'account_payable';

  v_operativo := v_entradas - v_salidas;
  v_inversion := 0;
  v_financiacion := 0;

  RETURN jsonb_build_object(
    'operativo', v_operativo,
    'inversion', v_inversion,
    'financiacion', v_financiacion,
    'entradas', v_entradas,
    'salidas', v_salidas,
    'neto', v_operativo + v_inversion + v_financiacion
  );
END;
$$;


ALTER FUNCTION "public"."fn_reporte_flujo_efectivo"("p_organization_id" bigint, "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_reporte_impuestos"("p_organization_id" bigint, "p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_iva_generado numeric;
  v_iva_descontable numeric;
  v_iva_neto numeric;
  v_total_facturado numeric;
  v_por_codigo jsonb;
BEGIN
  -- IVA generado (ventas)
  SELECT COALESCE(SUM(inv.tax_total), 0) INTO v_iva_generado
  FROM invoice_sales inv
  WHERE inv.organization_id = p_organization_id
    AND inv.issue_date >= p_from AND inv.issue_date <= p_to
    AND inv.status NOT IN ('cancelled', 'void');

  -- Total facturado
  SELECT COALESCE(SUM(inv.total), 0) INTO v_total_facturado
  FROM invoice_sales inv
  WHERE inv.organization_id = p_organization_id
    AND inv.issue_date >= p_from AND inv.issue_date <= p_to
    AND inv.status NOT IN ('cancelled', 'void');

  -- IVA descontable (compras) - invoice_purchase
  SELECT COALESCE(SUM(ip.tax_total), 0) INTO v_iva_descontable
  FROM invoice_purchase ip
  WHERE ip.organization_id = p_organization_id
    AND ip.issue_date >= p_from AND ip.issue_date <= p_to
    AND ip.status NOT IN ('cancelled', 'void');

  v_iva_neto := v_iva_generado - v_iva_descontable;

  -- Desglose por código de impuesto (invoice_applied_taxes)
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'codigo', t.tax_code,
    'tasa', t.tax_rate,
    'base', t.base,
    'monto', t.monto
  )), '[]'::jsonb) INTO v_por_codigo
  FROM (
    SELECT iat.tax_code, iat.tax_rate,
           COALESCE(SUM(inv.subtotal), 0) AS base,
           COALESCE(SUM(inv.tax_total), 0) AS monto
    FROM invoice_applied_taxes iat
    JOIN invoice_sales inv ON iat.invoice_id = inv.id
    WHERE inv.organization_id = p_organization_id
      AND inv.issue_date >= p_from AND inv.issue_date <= p_to
      AND inv.status NOT IN ('cancelled', 'void')
    GROUP BY iat.tax_code, iat.tax_rate
    ORDER BY iat.tax_code
  ) t;

  RETURN jsonb_build_object(
    'iva_generado', v_iva_generado,
    'iva_descontable', v_iva_descontable,
    'iva_neto', v_iva_neto,
    'total_facturado', v_total_facturado,
    'por_codigo', v_por_codigo
  );
END;
$$;


ALTER FUNCTION "public"."fn_reporte_impuestos"("p_organization_id" bigint, "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_reporte_integraciones_estado"("p_organization_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_conexiones jsonb;
  v_activas integer;
  v_error integer;
  v_pausadas integer;
BEGIN
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', c.id,
    'nombre', c.name,
    'estado', c.status,
    'errores_24h', c.error_count_24h,
    'ultimo_error', c.last_error_message,
    'ultima_actividad', c.last_activity_at
  )), '[]'::jsonb) INTO v_conexiones
  FROM (
    SELECT id, name, status, error_count_24h, last_error_message, last_activity_at
    FROM integration_connections
    WHERE organization_id = p_organization_id
    ORDER BY status, name
  ) c;

  SELECT COUNT(*) FILTER (WHERE status = 'active') INTO v_activas
  FROM integration_connections WHERE organization_id = p_organization_id;

  SELECT COUNT(*) FILTER (WHERE status = 'error' OR error_count_24h > 0) INTO v_error
  FROM integration_connections WHERE organization_id = p_organization_id;

  SELECT COUNT(*) FILTER (WHERE status = 'paused') INTO v_pausadas
  FROM integration_connections WHERE organization_id = p_organization_id;

  RETURN jsonb_build_object(
    'conexiones', v_conexiones,
    'activas', v_activas,
    'con_error', v_error,
    'pausadas', v_pausadas
  );
END;
$$;


ALTER FUNCTION "public"."fn_reporte_integraciones_estado"("p_organization_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_reporte_movimientos_inventario"("p_organization_id" bigint, "p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_por_tipo jsonb;
  v_por_sucursal jsonb;
  v_detalle jsonb;
  v_total_entradas numeric;
  v_total_salidas numeric;
BEGIN
  -- Por tipo (direction)
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'direccion', t.direction,
    'cantidad', t.cantidad,
    'valor', t.valor,
    'num_movimientos', t.num
  )), '[]'::jsonb) INTO v_por_tipo
  FROM (
    SELECT sm.direction,
           COALESCE(SUM(sm.qty), 0) AS cantidad,
           COALESCE(SUM(sm.qty * sm.unit_cost), 0) AS valor,
           COUNT(*) AS num
    FROM stock_movements sm
    WHERE sm.organization_id = p_organization_id
      AND sm.created_at >= p_from AND sm.created_at <= p_to
    GROUP BY sm.direction
    ORDER BY sm.direction
  ) t;

  -- Por sucursal
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'sucursal_id', s.branch_id,
    'entradas', s.entradas,
    'salidas', s.salidas,
    'num_movimientos', s.num
  )), '[]'::jsonb) INTO v_por_sucursal
  FROM (
    SELECT sm.branch_id,
           COALESCE(SUM(CASE WHEN sm.direction = 'in' THEN sm.qty ELSE 0 END), 0) AS entradas,
           COALESCE(SUM(CASE WHEN sm.direction = 'out' THEN sm.qty ELSE 0 END), 0) AS salidas,
           COUNT(*) AS num
    FROM stock_movements sm
    WHERE sm.organization_id = p_organization_id
      AND sm.created_at >= p_from AND sm.created_at <= p_to
    GROUP BY sm.branch_id
    ORDER BY sm.branch_id
  ) s;

  -- Detalle (últimos 100 movimientos)
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', m.id,
    'producto_id', m.product_id,
    'sucursal_id', m.branch_id,
    'direccion', m.direction,
    'cantidad', m.qty,
    'costo_unitario', m.unit_cost,
    'fuente', m.source,
    'nota', m.note,
    'fecha', m.created_at
  )), '[]'::jsonb) INTO v_detalle
  FROM (
    SELECT sm.*
    FROM stock_movements sm
    WHERE sm.organization_id = p_organization_id
      AND sm.created_at >= p_from AND sm.created_at <= p_to
    ORDER BY sm.created_at DESC
    LIMIT 100
  ) m;

  SELECT COALESCE(SUM(CASE WHEN sm.direction = 'in' THEN sm.qty ELSE 0 END), 0),
         COALESCE(SUM(CASE WHEN sm.direction = 'out' THEN sm.qty ELSE 0 END), 0)
  INTO v_total_entradas, v_total_salidas
  FROM stock_movements sm
  WHERE sm.organization_id = p_organization_id
    AND sm.created_at >= p_from AND sm.created_at <= p_to;

  RETURN jsonb_build_object(
    'por_tipo', v_por_tipo,
    'por_sucursal', v_por_sucursal,
    'detalle', v_detalle,
    'total_entradas', v_total_entradas,
    'total_salidas', v_total_salidas
  );
END;
$$;


ALTER FUNCTION "public"."fn_reporte_movimientos_inventario"("p_organization_id" bigint, "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_reporte_notificaciones_enviadas"("p_organization_id" bigint, "p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_por_canal jsonb;
  v_total integer;
BEGIN
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'canal', c.channel,
    'enviadas', c.enviadas,
    'leidas', c.leidas
  )), '[]'::jsonb) INTO v_por_canal
  FROM (
    SELECT n.channel,
           COUNT(*) AS enviadas,
           COUNT(*) FILTER (WHERE n.read_at IS NOT NULL) AS leidas
    FROM notifications n
    WHERE n.organization_id = p_organization_id
      AND n.created_at >= p_from AND n.created_at <= p_to
    GROUP BY n.channel
    ORDER BY enviadas DESC
  ) c;

  SELECT COUNT(*) INTO v_total
  FROM notifications n
  WHERE n.organization_id = p_organization_id
    AND n.created_at >= p_from AND n.created_at <= p_to;

  RETURN jsonb_build_object('por_canal', v_por_canal, 'total', v_total);
END;
$$;


ALTER FUNCTION "public"."fn_reporte_notificaciones_enviadas"("p_organization_id" bigint, "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_reporte_operaciones_actividad"("p_organization_id" bigint, "p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_por_modulo jsonb;
  v_por_usuario jsonb;
  v_total integer;
BEGIN
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'modulo', m.module,
    'cantidad', m.cantidad
  )), '[]'::jsonb) INTO v_por_modulo
  FROM (
    SELECT a.entity_type AS module, COUNT(*) AS cantidad
    FROM ops_audit_log a
    WHERE a.organization_id = p_organization_id
      AND a.created_at >= p_from AND a.created_at <= p_to
    GROUP BY a.entity_type
    ORDER BY cantidad DESC
  ) m;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'usuario_id', u.user_id,
    'cantidad', u.cantidad
  )), '[]'::jsonb) INTO v_por_usuario
  FROM (
    SELECT a.user_id, COUNT(*) AS cantidad
    FROM ops_audit_log a
    WHERE a.organization_id = p_organization_id
      AND a.created_at >= p_from AND a.created_at <= p_to
      AND a.user_id IS NOT NULL
    GROUP BY a.user_id
    ORDER BY cantidad DESC
    LIMIT 20
  ) u;

  SELECT COUNT(*) INTO v_total
  FROM ops_audit_log a
  WHERE a.organization_id = p_organization_id
    AND a.created_at >= p_from AND a.created_at <= p_to;

  RETURN jsonb_build_object(
    'por_modulo', v_por_modulo,
    'por_usuario', v_por_usuario,
    'total_eventos', v_total
  );
END;
$$;


ALTER FUNCTION "public"."fn_reporte_operaciones_actividad"("p_organization_id" bigint, "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_reporte_presupuesto_vs_real"("p_organization_id" bigint, "p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_tiene_presupuesto boolean;
  v_detalle jsonb;
BEGIN
  -- Verificar si hay presupuestos
  SELECT EXISTS(
    SELECT 1 FROM budgets b
    WHERE b.organization_id = p_organization_id
  ) INTO v_tiene_presupuesto;

  IF NOT v_tiene_presupuesto THEN
    -- Sin presupuestos: retornar solo reales
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'cuenta', d.account_code,
      'nombre', d.name,
      'tipo', d.type,
      'presupuesto', 0,
      'real', d.real,
      'diferencia', d.real,
      'variacion', null
    )), '[]'::jsonb) INTO v_detalle
    FROM (
      SELECT ca.account_code, ca.name, ca.type,
             CASE WHEN ca.type IN ('income') THEN COALESCE(SUM(jl.credit_base - jl.debit_base), 0)
                  ELSE COALESCE(SUM(jl.debit_base - jl.credit_base), 0) END AS real
      FROM journal_lines jl
      JOIN journal_entries je ON jl.journal_entry_id = je.id
      JOIN chart_of_accounts ca ON jl.account_code = ca.account_code
      WHERE je.organization_id = p_organization_id
        AND je.entry_date >= p_from AND je.entry_date <= p_to
        AND je.posted = true
        AND ca.organization_id = p_organization_id
      GROUP BY ca.account_code, ca.name, ca.type
      ORDER BY ca.account_code
    ) d;

    RETURN jsonb_build_object('tiene_presupuesto', false, 'detalle', v_detalle);
  END IF;

  -- Con presupuestos: comparar
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'cuenta', d.account_code,
    'nombre', d.name,
    'presupuesto', d.presupuesto,
    'real', d.real,
    'diferencia', d.real - d.presupuesto,
    'variacion', CASE WHEN d.presupuesto <> 0 THEN round(((d.real - d.presupuesto) / d.presupuesto * 100)::numeric, 2) ELSE null END
  )), '[]'::jsonb) INTO v_detalle
  FROM (
    SELECT ca.account_code, ca.name,
           COALESCE(SUM(bl.amount), 0) AS presupuesto,
           CASE WHEN ca.type = 'income' THEN COALESCE(SUM(jl.credit_base - jl.debit_base), 0)
                ELSE COALESCE(SUM(jl.debit_base - jl.credit_base), 0) END AS real
    FROM chart_of_accounts ca
    LEFT JOIN budget_lines bl ON bl.account_code = ca.account_code
    LEFT JOIN budgets b ON bl.budget_id = b.id AND b.organization_id = p_organization_id
    LEFT JOIN journal_lines jl ON jl.account_code = ca.account_code
    LEFT JOIN journal_entries je ON jl.journal_entry_id = je.id 
      AND je.organization_id = p_organization_id
      AND je.entry_date >= p_from AND je.entry_date <= p_to
      AND je.posted = true
    WHERE ca.organization_id = p_organization_id
    GROUP BY ca.account_code, ca.name
    HAVING COALESCE(SUM(bl.amount), 0) <> 0 
        OR COALESCE(SUM(jl.debit_base), 0) + COALESCE(SUM(jl.credit_base), 0) <> 0
    ORDER BY ca.account_code
  ) d;

  RETURN jsonb_build_object('tiene_presupuesto', true, 'detalle', v_detalle);
END;
$$;


ALTER FUNCTION "public"."fn_reporte_presupuesto_vs_real"("p_organization_id" bigint, "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_reporte_roles_auditoria"("p_organization_id" bigint, "p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_por_accion jsonb;
  v_total integer;
BEGIN
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'accion', a.action,
    'cantidad', a.cantidad
  )), '[]'::jsonb) INTO v_por_accion
  FROM (
    SELECT r.action, COUNT(*) AS cantidad
    FROM roles_audit_log r
    WHERE r.organization_id = p_organization_id
      AND r.logged_at >= p_from AND r.logged_at <= p_to
    GROUP BY r.action
    ORDER BY cantidad DESC
  ) a;

  SELECT COUNT(*) INTO v_total
  FROM roles_audit_log r
  WHERE r.organization_id = p_organization_id
    AND r.logged_at >= p_from AND r.logged_at <= p_to;

  RETURN jsonb_build_object('por_accion', v_por_accion, 'total', v_total);
END;
$$;


ALTER FUNCTION "public"."fn_reporte_roles_auditoria"("p_organization_id" bigint, "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_reporte_rotacion_inventario"("p_organization_id" bigint, "p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_top_vendidos jsonb;
  v_dead_stock jsonb;
  v_total_vendido numeric;
  v_num_productos_vendidos integer;
BEGIN
  -- Top vendidos
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'producto_id', t.product_id,
    'nombre', t.name,
    'sku', t.sku,
    'cantidad_vendida', t.cantidad,
    'total_ventas', t.total
  )), '[]'::jsonb) INTO v_top_vendidos
  FROM (
    SELECT si.product_id, p.name, p.sku,
           COALESCE(SUM(si.quantity), 0) AS cantidad,
           COALESCE(SUM(si.total), 0) AS total
    FROM sale_items si
    JOIN sales s ON si.sale_id = s.id
    JOIN products p ON si.product_id = p.id
    WHERE s.organization_id = p_organization_id
      AND s.sale_date >= p_from AND s.sale_date <= p_to
      AND s.status NOT IN ('cancelled', 'void')
    GROUP BY si.product_id, p.name, p.sku
    ORDER BY cantidad DESC
    LIMIT 20
  ) t;

  -- Dead stock (productos sin movimientos en el período)
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'producto_id', d.product_id,
    'nombre', d.name,
    'sku', d.sku,
    'stock_actual', d.qty_on_hand,
    'ultimo_movimiento', d.ultimo_mov
  )), '[]'::jsonb) INTO v_dead_stock
  FROM (
    SELECT p.id AS product_id, p.name, p.sku,
           COALESCE(sl.qty_on_hand, 0) AS qty_on_hand,
           MAX(sm.created_at) AS ultimo_mov
    FROM products p
    LEFT JOIN stock_levels sl ON sl.product_id = p.id
    LEFT JOIN stock_movements sm ON sm.product_id = p.id 
      AND sm.organization_id = p_organization_id
      AND sm.created_at >= p_from AND sm.created_at <= p_to
    WHERE p.organization_id = p_organization_id
      AND p.status = 'active'
    GROUP BY p.id, p.name, p.sku, sl.qty_on_hand
    HAVING MAX(sm.created_at) IS NULL
       OR MAX(sm.created_at) < p_from
    ORDER BY sl.qty_on_hand DESC
    LIMIT 20
  ) d;

  SELECT COALESCE(SUM(si.total), 0), COUNT(DISTINCT si.product_id)
  INTO v_total_vendido, v_num_productos_vendidos
  FROM sale_items si
  JOIN sales s ON si.sale_id = s.id
  WHERE s.organization_id = p_organization_id
    AND s.sale_date >= p_from AND s.sale_date <= p_to
    AND s.status NOT IN ('cancelled', 'void');

  RETURN jsonb_build_object(
    'top_vendidos', v_top_vendidos,
    'dead_stock', v_dead_stock,
    'total_vendido', v_total_vendido,
    'num_productos_vendidos', v_num_productos_vendidos
  );
END;
$$;


ALTER FUNCTION "public"."fn_reporte_rotacion_inventario"("p_organization_id" bigint, "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_reporte_stock_critico"("p_organization_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_items jsonb;
  v_total_criticos integer;
BEGIN
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'producto_id', i.product_id,
    'sku', i.sku,
    'nombre', i.name,
    'sucursal_id', i.branch_id,
    'stock_actual', i.qty_on_hand,
    'stock_minimo', i.min_level,
    'faltante', i.min_level - i.qty_on_hand
  )), '[]'::jsonb) INTO v_items
  FROM (
    SELECT sl.product_id, p.sku, p.name, sl.branch_id,
           sl.qty_on_hand, sl.min_level
    FROM stock_levels sl
    JOIN products p ON sl.product_id = p.id
    WHERE p.organization_id = p_organization_id
      AND sl.qty_on_hand <= sl.min_level
      AND p.status = 'active'
    ORDER BY (sl.min_level - sl.qty_on_hand) DESC
  ) i;

  SELECT COUNT(*) INTO v_total_criticos FROM jsonb_array_elements(v_items);

  RETURN jsonb_build_object('items', v_items, 'total_criticos', v_total_criticos);
END;
$$;


ALTER FUNCTION "public"."fn_reporte_stock_critico"("p_organization_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_reporte_ventas_por_hora"("p_organization_id" bigint, "p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_por_hora jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'hora', h.hora,
    'total', h.total,
    'num_ventas', h.cantidad
  )), '[]'::jsonb) INTO v_por_hora
  FROM (
    SELECT EXTRACT(HOUR FROM s.sale_date)::int AS hora,
           COALESCE(SUM(s.total), 0) AS total,
           COUNT(*) AS cantidad
    FROM sales s
    WHERE s.organization_id = p_organization_id
      AND s.sale_date >= p_from AND s.sale_date <= p_to
      AND s.status NOT IN ('cancelled', 'void')
    GROUP BY EXTRACT(HOUR FROM s.sale_date)
    ORDER BY hora
  ) h;

  RETURN jsonb_build_object('por_hora', v_por_hora);
END;
$$;


ALTER FUNCTION "public"."fn_reporte_ventas_por_hora"("p_organization_id" bigint, "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_reporte_ventas_resumen"("p_organization_id" bigint, "p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_por_dia jsonb;
  v_por_sucursal jsonb;
  v_por_vendedor jsonb;
  v_por_categoria jsonb;
  v_total_ventas numeric;
  v_num_ventas integer;
BEGIN
  -- Por día
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'fecha', d.dia,
    'total', d.total,
    'num_ventas', d.cantidad
  )), '[]'::jsonb) INTO v_por_dia
  FROM (
    SELECT DATE(s.sale_date) AS dia,
           COALESCE(SUM(s.total), 0) AS total,
           COUNT(*) AS cantidad
    FROM sales s
    WHERE s.organization_id = p_organization_id
      AND s.sale_date >= p_from AND s.sale_date <= p_to
      AND s.status NOT IN ('cancelled', 'void')
    GROUP BY DATE(s.sale_date)
    ORDER BY dia
  ) d;

  -- Por sucursal
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'sucursal_id', s.branch_id,
    'total', s.total,
    'num_ventas', s.cantidad
  )), '[]'::jsonb) INTO v_por_sucursal
  FROM (
    SELECT s.branch_id,
           COALESCE(SUM(s.total), 0) AS total,
           COUNT(*) AS cantidad
    FROM sales s
    WHERE s.organization_id = p_organization_id
      AND s.sale_date >= p_from AND s.sale_date <= p_to
      AND s.status NOT IN ('cancelled', 'void')
    GROUP BY s.branch_id
    ORDER BY total DESC
  ) s;

  -- Por vendedor (fallback a user_id cuando salesperson_id es NULL)
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'vendedor_id', v.vendedor_id,
    'total', v.total,
    'num_ventas', v.cantidad
  )), '[]'::jsonb) INTO v_por_vendedor
  FROM (
    SELECT COALESCE(s.salesperson_id, s.user_id) AS vendedor_id,
           COALESCE(SUM(s.total), 0) AS total,
           COUNT(*) AS cantidad
    FROM sales s
    WHERE s.organization_id = p_organization_id
      AND s.sale_date >= p_from AND s.sale_date <= p_to
      AND s.status NOT IN ('cancelled', 'void')
      AND COALESCE(s.salesperson_id, s.user_id) IS NOT NULL
    GROUP BY COALESCE(s.salesperson_id, s.user_id)
    ORDER BY total DESC
  ) v;

  -- Por categoría (join sale_items -> products)
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'categoria_id', c.category_id,
    'total', c.total,
    'cantidad_items', c.cantidad
  )), '[]'::jsonb) INTO v_por_categoria
  FROM (
    SELECT p.category_id,
           COALESCE(SUM(si.total), 0) AS total,
           COALESCE(SUM(si.quantity), 0) AS cantidad
    FROM sale_items si
    JOIN sales s ON si.sale_id = s.id
    JOIN products p ON si.product_id = p.id
    WHERE s.organization_id = p_organization_id
      AND s.sale_date >= p_from AND s.sale_date <= p_to
      AND s.status NOT IN ('cancelled', 'void')
    GROUP BY p.category_id
    ORDER BY total DESC
  ) c;

  SELECT COALESCE(SUM(s.total), 0), COUNT(*) INTO v_total_ventas, v_num_ventas
  FROM sales s
  WHERE s.organization_id = p_organization_id
    AND s.sale_date >= p_from AND s.sale_date <= p_to
    AND s.status NOT IN ('cancelled', 'void');

  RETURN jsonb_build_object(
    'por_dia', v_por_dia,
    'por_sucursal', v_por_sucursal,
    'por_vendedor', v_por_vendedor,
    'por_categoria', v_por_categoria,
    'total_ventas', v_total_ventas,
    'num_ventas', v_num_ventas
  );
END;
$$;


ALTER FUNCTION "public"."fn_reporte_ventas_resumen"("p_organization_id" bigint, "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_reschedule_overdue_tasks"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_task RECORD;
  v_assignee uuid;
  v_estimated numeric;
  v_capacity numeric := 8.0;  -- 8 horas por día
  v_new_due timestamptz;
  v_day_date date;
  v_loaded numeric;
  v_found boolean;
  v_goal_id uuid;
  v_count integer := 0;
BEGIN
  -- Recorrer tareas vencidas pendientes, ordenadas por prioridad y fecha de vencimiento
  FOR v_task IN
    SELECT t.id, t.organization_id, t.assigned_to, t.estimated_hours,
           t.title, t.priority, t.due_date
    FROM tasks t
    WHERE t.status IN ('open','in_progress')
      AND t.due_date IS NOT NULL
      AND t.due_date < now()
      AND t.assigned_to IS NOT NULL
    ORDER BY
      CASE t.priority
        WHEN 'critical' THEN 0
        WHEN 'high' THEN 1
        WHEN 'med' THEN 2
        WHEN 'low' THEN 3
        ELSE 4
      END,
      t.due_date ASC
  LOOP
    v_assignee := v_task.assigned_to;
    v_estimated := COALESCE(v_task.estimated_hours, 1.0);  -- default 1h si no tiene estimación
    v_found := false;
    v_day_date := CURRENT_DATE + 1;  -- empezar desde mañana

    -- Buscar el primer día con capacidad disponible (máximo 30 días)
    WHILE NOT v_found AND v_day_date <= CURRENT_DATE + 30 LOOP
      -- Sumar horas ya asignadas a este usuario para ese día
      SELECT COALESCE(SUM(COALESCE(estimated_hours, 1.0)), 0)
      INTO v_loaded
      FROM tasks
      WHERE assigned_to = v_assignee
        AND status IN ('open','in_progress')
        AND due_date >= date_trunc('day', v_day_date::timestamptz)
        AND due_date < date_trunc('day', v_day_date::timestamptz) + interval '1 day'
        AND id != v_task.id;

      IF v_loaded + v_estimated <= v_capacity THEN
        v_found := true;
      ELSE
        v_day_date := v_day_date + 1;
      END IF;
    END LOOP;

    -- Si no encontró espacio en 30 días, poner en 30 días igual
    IF NOT v_found THEN
      v_day_date := CURRENT_DATE + 30;
    END IF;

    -- Hora de vencimiento: 18:00 de ese día
    v_new_due := date_trunc('day', v_day_date::timestamptz) + interval '18 hours';

    -- Asegurar goal_id operativo
    v_goal_id := fn_agent_ensure_operational_goal(v_task.organization_id);

    -- Reprogramar
    UPDATE tasks
    SET due_date = v_new_due,
        goal_id = COALESCE(goal_id, v_goal_id),
        updated_at = now()
    WHERE id = v_task.id;

    -- Notificar al responsable
    PERFORM fn_create_org_notification(
      v_task.organization_id,
      v_assignee,
      'app',
      'task_rescheduled',
      'Tarea reprogramada: ' || v_task.title,
      'La tarea estaba vencida desde el ' || to_char(v_task.due_date, 'DD/MM/YYYY HH24:MI') ||
      ' y se reprogramó para el ' || to_char(v_new_due, 'DD/MM/YYYY HH24:MI') ||
      ' respetando tu capacidad de 8h/día. Horas estimadas: ' || v_estimated::text || 'h.',
      jsonb_build_object('task_id', v_task.id, 'source', 'agent_reschedule', 'old_due', v_task.due_date, 'new_due', v_new_due)
    );

    v_count := v_count + 1;
  END LOOP;

  -- Notificación resumen si hubo reprogramaciones
  IF v_count > 0 THEN
    PERFORM fn_create_org_notification(
      NULL::integer,
      NULL::uuid,
      'app',
      'task_reschedule_summary',
      'Reprogramación automática completada',
      'Se reprogramaron ' || v_count || ' tarea(s) vencida(s) respetando la capacidad de 8h/día por responsable.',
      jsonb_build_object('source', 'agent_reschedule', 'count', v_count)
    );
  END IF;
END;
$$;


ALTER FUNCTION "public"."fn_reschedule_overdue_tasks"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_reserve_seat"("p_trip_id" "uuid", "p_seat_label" "text", "p_ticket_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_trip_seat_id UUID;
BEGIN
  UPDATE trip_seats
  SET status = CASE WHEN p_ticket_id IS NOT NULL THEN 'sold' ELSE 'reserved' END,
      ticket_id = p_ticket_id,
      reserved_until = CASE WHEN p_ticket_id IS NULL THEN now() + interval '15 minutes' ELSE NULL END,
      updated_at = now()
  WHERE trip_id = p_trip_id
    AND seat_label = p_seat_label
    AND status = 'available'
  RETURNING id INTO v_trip_seat_id;
  
  IF v_trip_seat_id IS NOT NULL THEN
    UPDATE trips SET available_seats = available_seats - 1 WHERE id = p_trip_id AND available_seats > 0;
  END IF;
  
  RETURN v_trip_seat_id;
END;
$$;


ALTER FUNCTION "public"."fn_reserve_seat"("p_trip_id" "uuid", "p_seat_label" "text", "p_ticket_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_reset_monthly_ai_credits"() RETURNS TABLE("organization_id_updated" integer, "monthly_credits" integer, "rollover_applied" integer, "purchased_preserved" integer, "new_total" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  rec RECORD;
  monthly_credits integer;
  max_rollover integer;
  purchased_credits integer;
  current_remaining integer;
  unused_monthly integer;
  rollover_amount integer;
  new_credits_total integer;
BEGIN
  -- Iterar sobre todas las organizaciones con ai_settings
  FOR rec IN
    SELECT 
      s.organization_id,
      s.credits_remaining,
      s.purchased_credits,
      s.credits_reset_at,
      COALESCE(p.ai_credits_monthly, 0) as plan_monthly,
      COALESCE(p.ai_credits_max_rollover, 0) as plan_max_rollover,
      COALESCE(sub.metadata->'custom_config'->>'ai_credits', '') as enterprise_ai_credits
    FROM ai_settings s
    LEFT JOIN subscriptions sub ON sub.organization_id = s.organization_id
    LEFT JOIN plans p ON p.id = sub.plan_id
  LOOP
    -- Determinar créditos mensuales (enterprise usa custom_config)
    IF rec.enterprise_ai_credits IS NOT NULL AND rec.enterprise_ai_credits != '' THEN
      monthly_credits := rec.enterprise_ai_credits::integer;
      max_rollover := LEAST(monthly_credits * 2, 100000);
    ELSE
      monthly_credits := COALESCE(rec.plan_monthly, 0);
      max_rollover := COALESCE(rec.plan_max_rollover, 0);
    END IF;

    -- Skip si no tiene créditos mensuales y no tiene purchased
    IF monthly_credits = 0 AND COALESCE(rec.purchased_credits, 0) = 0 THEN
      CONTINUE;
    END IF;

    purchased_credits := COALESCE(rec.purchased_credits, 0);
    current_remaining := COALESCE(rec.credits_remaining, 0);
    
    -- Separar créditos mensuales no usados de los comprados
    unused_monthly := GREATEST(0, current_remaining - purchased_credits);
    
    -- Aplicar rollover limitado
    rollover_amount := LEAST(unused_monthly, max_rollover);
    
    -- Nuevo total = mensual + rollover + comprados (preservados)
    new_credits_total := monthly_credits + rollover_amount + purchased_credits;

    -- Actualizar ai_settings
    UPDATE ai_settings
    SET 
      credits_remaining = new_credits_total,
      credits_reset_at = NOW(),
      last_rollover_amount = rollover_amount,
      updated_at = NOW()
    WHERE organization_id = rec.organization_id;

    -- Retornar resultado
    organization_id_updated := rec.organization_id;
    monthly_credits := monthly_credits;
    rollover_applied := rollover_amount;
    purchased_preserved := purchased_credits;
    new_total := new_credits_total;
    
    RETURN NEXT;
    
    RAISE NOTICE 'Org %: monthly=%, rollover=%, purchased=%, total=%', 
      rec.organization_id, monthly_credits, rollover_amount, purchased_credits, new_credits_total;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."fn_reset_monthly_ai_credits"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_reset_monthly_ai_credits"() IS 'Resetea créditos IA mensualmente. Preserva purchased_credits. Aplica rollover según plan.';



CREATE OR REPLACE FUNCTION "public"."fn_resume_sequence_enrollment"("p_org" integer, "p_enrollment_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_enroll   record;
  v_next     record;
  v_sched    timestamptz;
  v_job_id   uuid;
BEGIN
  IF p_org IS NULL OR p_enrollment_id IS NULL THEN
    RAISE EXCEPTION 'invalid_arguments' USING ERRCODE = 'P0001';
  END IF;

  IF auth.uid() IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM organization_members om
     WHERE om.user_id = auth.uid() AND om.organization_id = p_org AND om.is_active = true
  ) THEN
    RAISE EXCEPTION 'forbidden_org' USING ERRCODE = 'P0001';
  END IF;

  SELECT id, status INTO v_enroll FROM sequence_enrollments
   WHERE id = p_enrollment_id AND organization_id = p_org;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'enrollment_not_found' USING ERRCODE = 'P0001';
  END IF;
  IF v_enroll.status <> 'paused' THEN
    RETURN jsonb_build_object('resumed', false, 'reason', 'not_paused', 'status', v_enroll.status);
  END IF;

  SELECT sr.id, sr.scheduled_at, s.id AS step_id
    INTO v_next
    FROM sequence_step_runs sr
    JOIN sequence_steps s ON s.id = sr.step_id
   WHERE sr.enrollment_id = p_enrollment_id
     AND sr.organization_id = p_org
     AND sr.status = 'pending'
   ORDER BY s.step_number
   LIMIT 1;

  IF NOT FOUND THEN
    UPDATE sequence_enrollments
       SET status = 'completed', paused_reason = NULL, paused_at = NULL,
           exited_at = now(), exit_reason = 'all_steps_completed'
     WHERE id = p_enrollment_id AND organization_id = p_org;
    RETURN jsonb_build_object('resumed', false, 'reason', 'no_pending_steps', 'status', 'completed');
  END IF;

  -- Un paso cuya hora ya pasó se reprograma a ahora (no se dispara "en el pasado").
  v_sched := GREATEST(v_next.scheduled_at, now());
  UPDATE sequence_step_runs SET scheduled_at = v_sched
   WHERE id = v_next.id AND organization_id = p_org;

  UPDATE sequence_enrollments
     SET status = 'active', paused_reason = NULL, paused_at = NULL,
         next_run_at = v_sched, current_step_id = v_next.step_id
   WHERE id = p_enrollment_id AND organization_id = p_org;

  v_job_id := fn_enqueue_job(p_org, 'sequence_step',
                             jsonb_build_object('step_run_id', v_next.id, 'enrollment_id', p_enrollment_id),
                             v_sched, 'seqrun:' || v_next.id::text, 3);
  UPDATE sequence_step_runs SET job_id = v_job_id WHERE id = v_next.id AND organization_id = p_org;

  PERFORM fn_enqueue_job(p_org, 'time_events',
                         jsonb_build_object('scope', 'sequences'),
                         now() + interval '15 minutes',
                         'time_events:' || p_org::text, 3);

  RETURN jsonb_build_object('resumed', true, 'enrollment_id', p_enrollment_id,
                            'step_run_id', v_next.id, 'next_run_at', v_sched, 'status', 'active');
END $$;


ALTER FUNCTION "public"."fn_resume_sequence_enrollment"("p_org" integer, "p_enrollment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_retro_journal_ap"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_ap RECORD;
    v_rule RECORD;
    v_entry_id integer;
    v_count integer := 0;
    v_default_branch integer;
BEGIN
    SELECT MIN(id) INTO v_default_branch FROM branches WHERE organization_id = 2;

    FOR v_ap IN
        SELECT ap.id, ap.organization_id, ap.amount, ap.balance, ap.status, ap.created_at
        FROM accounts_payable ap
        WHERE NOT EXISTS (
            SELECT 1 FROM journal_entries je 
            WHERE je.source = 'accounts_payable' 
              AND je.source_id = ap.id::text
              AND je.organization_id = ap.organization_id
        )
        AND COALESCE(ap.amount, 0) > 0
    LOOP
        SELECT * INTO v_rule
        FROM accounting_rules
        WHERE organization_id = v_ap.organization_id
          AND source_type = 'purchase'
          AND event_type = 'created'
          AND is_active = true
        ORDER BY priority
        LIMIT 1;

        IF v_rule IS NULL THEN
            SELECT * INTO v_rule
            FROM accounting_rules
            WHERE organization_id = v_ap.organization_id
              AND source_type = 'purchase'
              AND is_active = true
            ORDER BY priority
            LIMIT 1;
        END IF;

        IF v_rule IS NULL THEN
            CONTINUE;
        END IF;

        v_entry_id := fn_create_journal_entry(
            p_organization_id := v_ap.organization_id,
            p_branch_id := v_default_branch,
            p_entry_date := COALESCE(v_ap.created_at, now()),
            p_memo := 'CxP - ' || v_ap.id::text,
            p_source := 'accounts_payable',
            p_source_id := v_ap.id::text,
            p_debit_account := v_rule.debit_account_code,
            p_credit_account := v_rule.credit_account_code,
            p_amount := v_ap.amount
        );

        v_count := v_count + 1;
    END LOOP;

    RAISE NOTICE 'Cuentas por pagar contabilizadas: %', v_count;
END;
$$;


ALTER FUNCTION "public"."fn_retro_journal_ap"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_retro_journal_ar"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_ar RECORD;
    v_rule RECORD;
    v_entry_id integer;
    v_count integer := 0;
    v_default_branch integer;
BEGIN
    -- Obtener branch_id por defecto (el menor de la organización)
    SELECT MIN(id) INTO v_default_branch FROM branches WHERE organization_id = 2;

    FOR v_ar IN
        SELECT ar.id, ar.organization_id, ar.amount, ar.balance, ar.status, ar.created_at
        FROM accounts_receivable ar
        WHERE NOT EXISTS (
            SELECT 1 FROM journal_entries je 
            WHERE je.source = 'accounts_receivable' 
              AND je.source_id = ar.id::text
              AND je.organization_id = ar.organization_id
        )
        AND COALESCE(ar.amount, 0) > 0
    LOOP
        SELECT * INTO v_rule
        FROM accounting_rules
        WHERE organization_id = v_ar.organization_id
          AND source_type = 'sale'
          AND event_type = 'created'
          AND is_active = true
        ORDER BY priority
        LIMIT 1;

        IF v_rule IS NULL THEN
            SELECT * INTO v_rule
            FROM accounting_rules
            WHERE organization_id = v_ar.organization_id
              AND source_type = 'sale'
              AND is_active = true
            ORDER BY priority
            LIMIT 1;
        END IF;

        IF v_rule IS NULL THEN
            CONTINUE;
        END IF;

        v_entry_id := fn_create_journal_entry(
            p_organization_id := v_ar.organization_id,
            p_branch_id := v_default_branch,
            p_entry_date := COALESCE(v_ar.created_at, now()),
            p_memo := 'CxC - ' || v_ar.id::text,
            p_source := 'accounts_receivable',
            p_source_id := v_ar.id::text,
            p_debit_account := v_rule.debit_account_code,
            p_credit_account := v_rule.credit_account_code,
            p_amount := v_ar.amount
        );

        v_count := v_count + 1;
    END LOOP;

    RAISE NOTICE 'Cuentas por cobrar contabilizadas: %', v_count;
END;
$$;


ALTER FUNCTION "public"."fn_retro_journal_ar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_retro_journal_invoices"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_invoice RECORD;
    v_rule RECORD;
    v_entry_id integer;
    v_existing integer;
    v_count integer := 0;
BEGIN
    -- Procesar facturas de venta (invoice_sales) que no tienen asiento
    FOR v_invoice IN
        SELECT inv.id, inv.organization_id, inv.branch_id, inv.number, 
               inv.issue_date, inv.subtotal, inv.tax_total, inv.total,
               inv.document_type, inv.created_at
        FROM invoice_sales inv
        WHERE NOT EXISTS (
            SELECT 1 FROM journal_entries je 
            WHERE je.source = 'invoice_sales' 
              AND je.source_id = inv.id::text
              AND je.organization_id = inv.organization_id
        )
        AND inv.document_type = 'invoice'
    LOOP
        -- Buscar regla
        SELECT * INTO v_rule
        FROM accounting_rules
        WHERE organization_id = v_invoice.organization_id
          AND source_type = 'sale'
          AND event_type = 'created'
          AND is_active = true
        ORDER BY priority
        LIMIT 1;

        IF v_rule IS NULL THEN
            CONTINUE;
        END IF;

        -- Crear asiento
        v_entry_id := fn_create_journal_entry(
            p_organization_id := v_invoice.organization_id,
            p_branch_id := v_invoice.branch_id,
            p_entry_date := COALESCE(v_invoice.issue_date, v_invoice.created_at),
            p_memo := 'Venta ' || COALESCE(v_invoice.number, v_invoice.id::text),
            p_source := 'invoice_sales',
            p_source_id := v_invoice.id::text,
            p_debit_account := v_rule.debit_account_code,
            p_credit_account := v_rule.credit_account_code,
            p_amount := v_invoice.total,
            p_tax_account := v_rule.tax_account_code,
            p_tax_amount := CASE WHEN v_rule.use_tax_from_document THEN v_invoice.tax_total ELSE 0 END
        );

        v_count := v_count + 1;
    END LOOP;

    RAISE NOTICE 'Facturas de venta contabilizadas: %', v_count;
END;
$$;


ALTER FUNCTION "public"."fn_retro_journal_invoices"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_retro_journal_payments"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_payment RECORD;
    v_rule RECORD;
    v_entry_id integer;
    v_source_type text;
    v_event_type text;
    v_memo text;
    v_count integer := 0;
BEGIN
    -- Procesar pagos que no tienen asiento
    FOR v_payment IN
        SELECT p.id, p.organization_id, p.branch_id, p.amount, 
               p.source, p.source_id, p.status, p.reference, 
               p.created_at, p.created_by
        FROM payments p
        WHERE NOT EXISTS (
            SELECT 1 FROM journal_entries je 
            WHERE je.source = 'payments' 
              AND je.source_id = p.id::text
              AND je.organization_id = p.organization_id
        )
        AND p.status = 'completed'
    LOOP
        -- Determinar tipo de fuente
        IF v_payment.source = 'invoice_sales' OR v_payment.source = 'account_receivable' THEN
            v_source_type := 'sale_payment';
            v_memo := 'Cobro recibido';
            v_event_type := 'paid';
        ELSIF v_payment.source = 'invoice_purchase' OR v_payment.source = 'account_payable' THEN
            v_source_type := 'purchase_payment';
            v_memo := 'Pago a proveedor';
            v_event_type := 'paid';
        ELSE
            CONTINUE;
        END IF;

        -- Buscar regla
        SELECT * INTO v_rule
        FROM accounting_rules
        WHERE organization_id = v_payment.organization_id
          AND source_type = v_source_type
          AND event_type = v_event_type
          AND is_active = true
        ORDER BY priority
        LIMIT 1;

        -- Fallback
        IF v_rule IS NULL THEN
            SELECT * INTO v_rule
            FROM accounting_rules
            WHERE organization_id = v_payment.organization_id
              AND source_type = v_source_type
              AND is_active = true
            ORDER BY priority
            LIMIT 1;
        END IF;

        IF v_rule IS NULL THEN
            CONTINUE;
        END IF;

        -- Crear asiento
        v_entry_id := fn_create_journal_entry(
            p_organization_id := v_payment.organization_id,
            p_branch_id := v_payment.branch_id,
            p_entry_date := v_payment.created_at,
            p_memo := v_memo || ' - Ref: ' || COALESCE(v_payment.reference, v_payment.id::text),
            p_source := 'payments',
            p_source_id := v_payment.id::text,
            p_debit_account := v_rule.debit_account_code,
            p_credit_account := v_rule.credit_account_code,
            p_amount := v_payment.amount,
            p_created_by := v_payment.created_by
        );

        v_count := v_count + 1;
    END LOOP;

    RAISE NOTICE 'Pagos contabilizados: %', v_count;
END;
$$;


ALTER FUNCTION "public"."fn_retro_journal_payments"() OWNER TO "postgres";


