CREATE OR REPLACE FUNCTION "public"."fn_retro_journal_sales"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_sale RECORD;
    v_rule RECORD;
    v_entry_id integer;
    v_count integer := 0;
BEGIN
    FOR v_sale IN
        SELECT s.id, s.organization_id, s.branch_id, s.total, s.tax_total,
               s.subtotal, s.status, s.sale_date, s.created_at
        FROM sales s
        WHERE NOT EXISTS (
            SELECT 1 FROM journal_entries je 
            WHERE je.source = 'sales' 
              AND je.source_id = s.id::text
              AND je.organization_id = s.organization_id
        )
        AND s.status IN ('paid', 'confirmed', 'completed')
    LOOP
        SELECT * INTO v_rule
        FROM accounting_rules
        WHERE organization_id = v_sale.organization_id
          AND source_type = 'sale'
          AND event_type = 'created'
          AND is_active = true
        ORDER BY priority
        LIMIT 1;

        IF v_rule IS NULL THEN
            SELECT * INTO v_rule
            FROM accounting_rules
            WHERE organization_id = v_sale.organization_id
              AND source_type = 'sale'
              AND is_active = true
            ORDER BY priority
            LIMIT 1;
        END IF;

        IF v_rule IS NULL THEN
            CONTINUE;
        END IF;

        v_entry_id := fn_create_journal_entry(
            p_organization_id := v_sale.organization_id,
            p_branch_id := COALESCE(v_sale.branch_id, 0),
            p_entry_date := COALESCE(v_sale.sale_date, v_sale.created_at),
            p_memo := 'Venta POS ' || v_sale.id::text,
            p_source := 'sales',
            p_source_id := v_sale.id::text,
            p_debit_account := v_rule.debit_account_code,
            p_credit_account := v_rule.credit_account_code,
            p_amount := v_sale.total,
            p_tax_account := v_rule.tax_account_code,
            p_tax_amount := CASE WHEN v_rule.use_tax_from_document THEN v_sale.tax_total ELSE 0 END
        );

        v_count := v_count + 1;
    END LOOP;

    RAISE NOTICE 'Ventas POS contabilizadas: %', v_count;
END;
$$;


ALTER FUNCTION "public"."fn_retro_journal_sales"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_revenue_metrics"("p_org_id" integer, "p_start" "date", "p_end" "date") RETURNS TABLE("month" "date", "deals_won" bigint, "deals_lost" bigint, "deals_open" bigint, "revenue_won_pipeline" numeric, "revenue_lost" numeric, "revenue_pipeline" numeric, "arpa" numeric, "avg_sales_cycle_days" numeric, "win_rate" numeric, "revenue_collected" numeric, "commissions_paid" numeric)
    LANGUAGE "sql" STABLE
    AS $$
  WITH pipeline AS (
    SELECT
      DATE_TRUNC('month', o.created_at)::date AS month,
      COUNT(*) FILTER (WHERE o.status = 'won') AS deals_won,
      COUNT(*) FILTER (WHERE o.status = 'lost') AS deals_lost,
      COUNT(*) FILTER (WHERE o.status NOT IN ('won','lost')) AS deals_open,
      COALESCE(SUM(o.amount) FILTER (WHERE o.status = 'won'), 0) AS revenue_won_pipeline,
      COALESCE(SUM(o.amount) FILTER (WHERE o.status = 'lost'), 0) AS revenue_lost,
      COALESCE(SUM(o.amount) FILTER (WHERE o.status NOT IN ('won','lost')), 0) AS revenue_pipeline,
      AVG(EXTRACT(EPOCH FROM (o.closed_at - o.created_at))/86400)
        FILTER (WHERE o.status = 'won') AS avg_sales_cycle_days,
      COUNT(*) FILTER (WHERE o.status = 'won')::float /
        NULLIF(COUNT(*) FILTER (WHERE o.status IN ('won','lost')), 0) AS win_rate
    FROM opportunities o
    WHERE o.organization_id = p_org_id
      AND o.created_at >= p_start
      AND o.created_at < p_end
    GROUP BY DATE_TRUNC('month', o.created_at)
  ),
  arpa_period AS (
    SELECT
      DATE_TRUNC('month', i.issue_date)::date AS month,
      AVG(i.total) AS arpa
    FROM invoice_sales i
    WHERE i.organization_id = p_org_id
      AND i.status = 'paid'
      AND i.issue_date >= p_start
      AND i.issue_date < p_end
    GROUP BY DATE_TRUNC('month', i.issue_date)
  ),
  revenue AS (
    SELECT
      DATE_TRUNC('month', p.payment_date)::date AS month,
      COALESCE(SUM(p.amount) FILTER (WHERE p.status = 'completed'
        AND i.opportunity_id IS NOT NULL), 0) AS revenue_collected
    FROM payments p
    JOIN invoice_sales i ON p.source_id = i.id::text AND p.source = 'invoice_sales'
    WHERE i.organization_id = p_org_id
      AND p.payment_date >= p_start
      AND p.payment_date < p_end
    GROUP BY DATE_TRUNC('month', p.payment_date)
  ),
  commissions_paid AS (
    SELECT
      DATE_TRUNC('month', c.paid_at)::date AS month,
      COALESCE(SUM(c.commission_amount), 0) AS commissions_paid
    FROM commissions c
    WHERE c.organization_id = p_org_id
      AND c.status = 'paid'
      AND c.paid_at >= p_start
      AND c.paid_at < p_end
    GROUP BY DATE_TRUNC('month', c.paid_at)
  )
  SELECT
    p.month,
    p.deals_won,
    p.deals_lost,
    p.deals_open,
    p.revenue_won_pipeline,
    p.revenue_lost,
    p.revenue_pipeline,
    a.arpa,
    p.avg_sales_cycle_days,
    p.win_rate,
    COALESCE(r.revenue_collected, 0) AS revenue_collected,
    COALESCE(cp.commissions_paid, 0) AS commissions_paid
  FROM pipeline p
  LEFT JOIN arpa_period a ON a.month = p.month
  LEFT JOIN revenue r ON r.month = p.month
  LEFT JOIN commissions_paid cp ON cp.month = p.month
  ORDER BY p.month;
$$;


ALTER FUNCTION "public"."fn_revenue_metrics"("p_org_id" integer, "p_start" "date", "p_end" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_save_conversation_summary"("p_conversation_id" "uuid", "p_summary" "text", "p_key_points" "text"[], "p_sentiment" "text" DEFAULT 'neutral'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_org_id int;
  v_summary_id uuid;
BEGIN
  -- Obtener organization_id de la conversación
  SELECT organization_id INTO v_org_id FROM conversations WHERE id = p_conversation_id;
  
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Conversación no encontrada: %', p_conversation_id;
  END IF;
  
  -- Insertar o actualizar el resumen
  INSERT INTO conversation_summaries (
    organization_id,
    conversation_id,
    summary,
    key_points,
    sentiment,
    generated_by,
    created_at,
    updated_at
  ) VALUES (
    v_org_id,
    p_conversation_id,
    p_summary,
    p_key_points,
    p_sentiment,
    'ai',
    NOW(),
    NOW()
  )
  ON CONFLICT (conversation_id) 
  DO UPDATE SET
    summary = EXCLUDED.summary,
    key_points = EXCLUDED.key_points,
    sentiment = EXCLUDED.sentiment,
    updated_at = NOW()
  RETURNING id INTO v_summary_id;
  
  RETURN v_summary_id;
END;
$$;


ALTER FUNCTION "public"."fn_save_conversation_summary"("p_conversation_id" "uuid", "p_summary" "text", "p_key_points" "text"[], "p_sentiment" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_save_conversation_summary"("p_conversation_id" "uuid", "p_summary" "text", "p_key_points" "text"[], "p_sentiment" "text") IS 'Guarda el resumen generado por IA para una conversación';



CREATE OR REPLACE FUNCTION "public"."fn_seed_comm_settings"("p_org" integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_n integer := 0;
BEGIN
  INSERT INTO public.comm_settings (
    organization_id, sms_remaining, whatsapp_remaining, voice_minutes_remaining,
    is_active, credits_reset_at
  )
  SELECT o.id,
         COALESCE(pl.comm_sms_monthly, 0),
         COALESCE(pl.comm_whatsapp_monthly, 0),
         COALESCE(pl.comm_voice_minutes_monthly, 0),
         true,
         date_trunc('month', now()) + interval '1 month'
    FROM public.organizations o
    LEFT JOIN public.plans pl ON pl.id = o.plan_id
   WHERE o.id = p_org
  ON CONFLICT (organization_id) DO NOTHING;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END $$;


ALTER FUNCTION "public"."fn_seed_comm_settings"("p_org" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_seed_comm_settings"("p_org" integer) IS 'Crea comm_settings para una org con el cupo de su plan (0 si el plan no lo define). No pisa filas existentes.';



CREATE OR REPLACE FUNCTION "public"."fn_seed_comm_settings_on_org"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  BEGIN
    PERFORM public.fn_seed_comm_settings(NEW.id);
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'fn_seed_comm_settings_on_org(%) falló: %', NEW.id, SQLERRM;
  END;
  RETURN NEW;
END $$;


ALTER FUNCTION "public"."fn_seed_comm_settings_on_org"() OWNER TO "postgres";


