CREATE OR REPLACE FUNCTION "public"."fn_seed_default_rules"("p_org_id" integer) RETURNS "void"
    LANGUAGE "plpgsql"
    AS $_$
BEGIN
  -- Solo insertar si la organización no tiene reglas aún
  IF EXISTS (SELECT 1 FROM alert_rules WHERE organization_id = p_org_id) THEN
    RETURN;
  END IF;

  INSERT INTO alert_rules (organization_id, name, source_module, sql_condition, channels, severity, active) VALUES
    (p_org_id, 'Stock Crítico', 'inventario',
     'SELECT COUNT(*) FROM products WHERE stock_quantity < 5 AND organization_id = $1',
     ARRAY['email', 'app'], 'critical', true),

    (p_org_id, 'Stock Bajo en Productos', 'inventario',
     'SELECT COUNT(*) FROM products WHERE stock_quantity <= minimum_stock AND active = true',
     ARRAY['email', 'push', 'app'], 'warning', true),

    (p_org_id, 'Productos Agotados', 'inventario',
     'SELECT COUNT(*) FROM products WHERE stock_quantity = 0 AND active = true',
     ARRAY['email', 'push', 'app'], 'critical', true),

    (p_org_id, 'Facturas Vencidas', 'finanzas',
     'SELECT COUNT(*) FROM invoices WHERE due_date < NOW() AND status = ''pending'' AND organization_id = $1',
     ARRAY['email', 'app', 'push'], 'warning', true),

    (p_org_id, 'Tareas Vencidas CRM', 'crm',
     'SELECT COUNT(*) FROM tasks WHERE due_date < NOW() AND status != ''completed'' AND organization_id = $1',
     ARRAY['app', 'push'], 'warning', true),

    (p_org_id, 'Usuarios Inactivos', 'sistema',
     'SELECT COUNT(*) FROM users WHERE last_login < NOW() - INTERVAL ''30 days'' AND organization_id = $1',
     ARRAY['app'], 'info', true),

    (p_org_id, 'Información del Sistema', 'sistema',
     'SELECT COUNT(*) FROM system_logs WHERE level = ''INFO'' AND created_at > NOW() - INTERVAL ''1 hour''',
     ARRAY['email'], 'info', false);
END;
$_$;


ALTER FUNCTION "public"."fn_seed_default_rules"("p_org_id" integer) OWNER TO "postgres";


