CREATE OR REPLACE FUNCTION "public"."fn_seed_org_project_for"("p_org_id" integer) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org RECORD;
  v_project_id uuid;
  v_goal_setup uuid;
  v_goal_ops uuid;
  v_goal_sales uuid;
  v_owner uuid;
BEGIN
  SELECT * INTO v_org FROM organizations WHERE id = p_org_id;
  IF v_org.id IS NULL THEN RETURN NULL; END IF;
  v_owner := COALESCE(v_org.owner_user_id, v_org.created_by);

  -- No duplicar si ya tiene proyecto
  SELECT id INTO v_project_id FROM projects WHERE organization_id = p_org_id ORDER BY created_at LIMIT 1;
  IF v_project_id IS NOT NULL THEN RETURN v_project_id; END IF;

  INSERT INTO projects (organization_id, name, description, status, priority, start_date, owner_id, created_by)
  VALUES (p_org_id, v_org.name,
          'Proyecto principal de ' || v_org.name || ' creado automáticamente por GO Admin.',
          'active', 'high', now(), v_owner, v_owner)
  RETURNING id INTO v_project_id;

  INSERT INTO goals (organization_id, project_id, title, description, type, status, target_date, progress, owner_id, created_by)
  VALUES (p_org_id, v_project_id, 'Poner en marcha ' || v_org.name,
          'Completar la configuración inicial: sucursales, productos, equipo y métodos de pago.',
          'goal', 'active', now() + interval '30 days', 0, v_owner, v_owner)
  RETURNING id INTO v_goal_setup;

  INSERT INTO goals (organization_id, project_id, title, description, type, status, target_date, progress, owner_id, created_by)
  VALUES (p_org_id, v_project_id, 'Operación diaria al día',
          'Mantener la operación sin pendientes: caja cerrada, mensajes respondidos, pedidos despachados y facturas cobradas.',
          'goal', 'active', now() + interval '90 days', 0, v_owner, v_owner)
  RETURNING id INTO v_goal_ops;

  INSERT INTO goals (organization_id, project_id, title, description, type, status, target_date, progress, owner_id, created_by)
  VALUES (p_org_id, v_project_id, 'Conseguir las primeras 100 ventas',
          'Impulsar ventas con POS, pedidos online y canales conectados (WhatsApp, Instagram, Messenger).',
          'goal', 'active', now() + interval '90 days', 0, v_owner, v_owner)
  RETURNING id INTO v_goal_sales;

  INSERT INTO tasks (organization_id, project_id, goal_id, title, description, type, status, priority, due_date, assigned_to, created_by, tags, estimated_hours)
  VALUES
    (p_org_id, v_project_id, v_goal_setup, 'Configurar datos de la empresa y sucursal',
     'Completa nombre legal, NIT, dirección, logo y crea tu primera sucursal en Organización.',
     'onboarding', 'open', 'high', now() + interval '2 days', v_owner, v_owner, ARRAY['onboarding','agente'], 1),
    (p_org_id, v_project_id, v_goal_setup, 'Configurar moneda e impuestos',
     'Define la moneda base y las plantillas de impuestos de tu país en Finanzas.',
     'onboarding', 'open', 'high', now() + interval '3 days', v_owner, v_owner, ARRAY['onboarding','agente'], 1),
    (p_org_id, v_project_id, v_goal_setup, 'Cargar productos al inventario',
     'Crea o importa tus productos con precios e imágenes en Inventario.',
     'onboarding', 'open', 'high', now() + interval '5 days', v_owner, v_owner, ARRAY['onboarding','agente'], 3),
    (p_org_id, v_project_id, v_goal_setup, 'Invitar a tu equipo y asignar roles',
     'Invita a los miembros de tu organización y asigna roles (Admin, Manager, Empleado).',
     'onboarding', 'open', 'med', now() + interval '4 days', v_owner, v_owner, ARRAY['onboarding','agente'], 1),
    (p_org_id, v_project_id, v_goal_setup, 'Configurar métodos de pago',
     'Conecta Wompi, Stripe u otros métodos de pago en Integraciones para cobrar online.',
     'onboarding', 'open', 'med', now() + interval '7 days', v_owner, v_owner, ARRAY['onboarding','agente'], 2),
    (p_org_id, v_project_id, v_goal_sales, 'Conectar canales de chat (WhatsApp, Instagram, Messenger)',
     'Conecta tus canales en Chat → Canales para responder clientes desde GO Admin.',
     'onboarding', 'open', 'med', now() + interval '10 days', v_owner, v_owner, ARRAY['onboarding','agente'], 2),
    (p_org_id, v_project_id, v_goal_sales, 'Registrar tu primera venta en el POS',
     'Abre caja y registra tu primera venta para validar el flujo completo.',
     'onboarding', 'open', 'med', now() + interval '14 days', v_owner, v_owner, ARRAY['onboarding','agente'], 1);

  PERFORM fn_create_org_notification(
    p_org_id, v_owner, 'app', 'pm_project_created',
    'Proyecto "' || v_org.name || '" creado',
    'Se creó automáticamente tu proyecto con 3 metas y 7 tareas iniciales. Revísalas en el módulo PM.',
    jsonb_build_object('project_id', v_project_id, 'source', 'agent')
  );

  RETURN v_project_id;
END;
$$;


