CREATE OR REPLACE FUNCTION "public"."fn_sync_address_to_customer"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  -- Solo sincronizar si es la dirección default
  IF NEW.is_default = true THEN
    UPDATE customers SET
      address = NEW.address_line1,
      city = NEW.city,
      fiscal_municipality_id = COALESCE(NEW.municipality_id, fiscal_municipality_id),
      updated_at = NOW()
    WHERE id = NEW.customer_id
      -- Evitar loop: solo actualizar si los datos son diferentes
      AND (
        address IS DISTINCT FROM NEW.address_line1
        OR city IS DISTINCT FROM NEW.city
        OR (NEW.municipality_id IS NOT NULL AND fiscal_municipality_id IS DISTINCT FROM NEW.municipality_id)
      );
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_sync_address_to_customer"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_sync_customer_to_address"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_muni_name text;
  v_state_name text;
  v_country_code text;
  v_postal_code text;
  v_address_exists boolean;
BEGIN
  -- Solo actuar si cambió address, city o fiscal_municipality_id
  IF TG_OP = 'UPDATE' AND 
     NEW.address IS NOT DISTINCT FROM OLD.address AND 
     NEW.city IS NOT DISTINCT FROM OLD.city AND
     NEW.fiscal_municipality_id IS NOT DISTINCT FROM OLD.fiscal_municipality_id THEN
    RETURN NEW;
  END IF;

  -- Resolver datos del municipio si hay fiscal_municipality_id
  IF NEW.fiscal_municipality_id IS NOT NULL THEN
    SELECT m.name, m.state_name, m.country_code, m.code
    INTO v_muni_name, v_state_name, v_country_code, v_postal_code
    FROM municipalities m
    WHERE m.id = NEW.fiscal_municipality_id;
  END IF;

  -- Verificar si ya existe una dirección default
  SELECT EXISTS(
    SELECT 1 FROM customer_addresses 
    WHERE customer_id = NEW.id AND is_default = true
  ) INTO v_address_exists;

  IF v_address_exists THEN
    -- Actualizar la dirección default existente
    UPDATE customer_addresses SET
      address_line1 = COALESCE(NEW.address, address_line1),
      city = COALESCE(v_muni_name, NEW.city, city),
      department = COALESCE(v_state_name, department),
      country_code = COALESCE(v_country_code, country_code),
      postal_code = COALESCE(v_postal_code, postal_code),
      municipality_id = COALESCE(NEW.fiscal_municipality_id, municipality_id),
      updated_at = NOW()
    WHERE customer_id = NEW.id AND is_default = true;
  ELSE
    -- Crear dirección default si hay al menos address o municipio
    IF NEW.address IS NOT NULL OR NEW.fiscal_municipality_id IS NOT NULL THEN
      INSERT INTO customer_addresses (
        organization_id, customer_id, label, address_line1, city, 
        department, country_code, postal_code, municipality_id, is_default
      ) VALUES (
        NEW.organization_id,
        NEW.id,
        'Principal',
        COALESCE(NEW.address, ''),
        COALESCE(v_muni_name, NEW.city, ''),
        COALESCE(v_state_name, ''),
        COALESCE(v_country_code, 'CO'),
        v_postal_code,
        NEW.fiscal_municipality_id,
        true
      );
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_sync_customer_to_address"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_sync_invoice_items_from_sale"("p_invoice_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_sale_id uuid;
  v_inserted integer := 0;
BEGIN
  -- Obtener el sale_id de la factura
  SELECT sale_id INTO v_sale_id FROM invoice_sales WHERE id = p_invoice_id;
  IF v_sale_id IS NULL THEN
    RETURN 0;
  END IF;

  -- Solo sincronizar si la factura NO tiene items (evita duplicados)
  PERFORM 1 FROM invoice_items WHERE invoice_sales_id = p_invoice_id LIMIT 1;
  IF FOUND THEN
    RETURN 0;
  END IF;

  -- Insertar invoice_items desde sale_items
  INSERT INTO invoice_items (invoice_id, invoice_sales_id, invoice_type, product_id, description, qty, unit_price, tax_rate, total_line, discount_amount, tax_included)
  SELECT
    p_invoice_id,
    p_invoice_id,
    'sale',
    si.product_id,
    COALESCE(p.name, 'Producto'),
    si.quantity,
    si.unit_price,
    COALESCE(si.tax_rate, 0),
    si.total,
    COALESCE(si.discount_amount, 0),
    inv.tax_included
  FROM sale_items si
  LEFT JOIN products p ON p.id = si.product_id
  JOIN invoice_sales inv ON inv.id = p_invoice_id
  WHERE si.sale_id = v_sale_id;

  GET DIAGNOSTICS v_inserted = ROW_COUNT;

  -- El trigger fn_recalc_invoice_totals recalcula subtotal/total/balance automaticamente
  RETURN v_inserted;
END;
$$;


ALTER FUNCTION "public"."fn_sync_invoice_items_from_sale"("p_invoice_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_sync_invoice_items_from_sale"("p_invoice_id" "uuid") IS 'Sincroniza invoice_items desde sale_items cuando la factura no tiene items. Usa SECURITY DEFINER para bypassar RLS. El trigger fn_recalc_invoice_totals recalcula los totales automaticamente.';



CREATE OR REPLACE FUNCTION "public"."fn_sync_status_from_stage"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_new_won  boolean;
  v_new_lost boolean;
  v_old_won  boolean;
  v_old_lost boolean;
  v_target   text;
BEGIN
  IF NEW.stage_id IS NOT DISTINCT FROM OLD.stage_id THEN
    RETURN NEW;
  END IF;

  SELECT COALESCE(s.is_won, false), COALESCE(s.is_lost, false)
    INTO v_new_won, v_new_lost
    FROM stages s WHERE s.id = NEW.stage_id;

  IF NOT FOUND THEN
    RETURN NEW;                       -- etapa inexistente: no se inventa nada
  END IF;

  IF v_new_won AND v_new_lost THEN
    RAISE WARNING 'fn_sync_status_from_stage: stage % marcada is_won e is_lost a la vez; no se toca el status de la oportunidad %',
      NEW.stage_id, NEW.id;
    RETURN NEW;
  END IF;

  IF v_new_won THEN
    -- Sin datos de venta no se cierra: cerrar aquí crearía una comisión devengada
    -- sobre una venta vacía (F9-31).
    IF NEW.win_data IS NULL OR NEW.win_data = '{}'::jsonb THEN
      RAISE WARNING 'fn_sync_status_from_stage: oportunidad % movida a etapa ganada % sin win_data; se deja en % y el cierre debe hacerse con datos',
        NEW.id, NEW.stage_id, COALESCE(NEW.status, 'open');
      RETURN NEW;
    END IF;
    v_target := 'won';
  ELSIF v_new_lost THEN
    -- Simétrico: sin motivo de pérdida no se marca como perdida.
    IF COALESCE(NULLIF(btrim(NEW.loss_reason), ''), NULLIF(btrim(NEW.loss_reason_value), '')) IS NULL THEN
      RAISE WARNING 'fn_sync_status_from_stage: oportunidad % movida a etapa perdida % sin motivo; se deja en %',
        NEW.id, NEW.stage_id, COALESCE(NEW.status, 'open');
      RETURN NEW;
    END IF;
    v_target := 'lost';
  ELSE
    -- Etapa no terminal: solo se reabre lo que cerró la etapa anterior.
    SELECT COALESCE(s.is_won, false), COALESCE(s.is_lost, false)
      INTO v_old_won, v_old_lost
      FROM stages s WHERE s.id = OLD.stage_id;

    IF COALESCE(v_old_won, false) OR COALESCE(v_old_lost, false) THEN
      v_target := 'open';
    ELSE
      RETURN NEW;                     -- ni status ni closed_at se tocan
    END IF;
  END IF;

  IF NEW.status IS DISTINCT FROM v_target THEN
    UPDATE opportunities
       SET status = v_target
     WHERE id = NEW.id
       AND status IS DISTINCT FROM v_target;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_sync_status_from_stage"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_track_conversation_assignment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_assigner_member_id bigint;
BEGIN
  -- Solo registrar si el assigned_member_id cambió
  IF OLD.assigned_member_id IS DISTINCT FROM NEW.assigned_member_id THEN
    -- Obtener el member_id del usuario que hace la asignación
    SELECT id INTO v_assigner_member_id 
    FROM organization_members 
    WHERE user_id = auth.uid() 
    AND organization_id = NEW.organization_id 
    AND is_active = true 
    LIMIT 1;
    
    INSERT INTO conversation_assignments (
      organization_id,
      conversation_id,
      assigned_member_id,
      assigned_by_member_id,
      reason,
      created_at
    ) VALUES (
      NEW.organization_id,
      NEW.id,
      NEW.assigned_member_id,
      v_assigner_member_id,
      CASE 
        WHEN OLD.assigned_member_id IS NULL THEN 'Primera asignación'
        WHEN NEW.assigned_member_id IS NULL THEN 'Desasignación'
        ELSE 'Reasignación de agente'
      END,
      NOW()
    );
  END IF;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_track_conversation_assignment"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_track_conversation_assignment"() IS 'Registra automáticamente el historial de asignaciones de conversaciones a agentes';



CREATE OR REPLACE FUNCTION "public"."fn_track_conversation_status_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  -- Solo registrar si el status cambió
  IF OLD.status IS DISTINCT FROM NEW.status THEN
    INSERT INTO conversation_status_history (
      organization_id,
      conversation_id,
      from_status,
      to_status,
      changed_by_member_id,
      reason,
      created_at
    ) VALUES (
      NEW.organization_id,
      NEW.id,
      OLD.status,
      NEW.status,
      -- Intentar obtener el member_id del usuario actual
      (SELECT id FROM organization_members 
       WHERE user_id = auth.uid() 
       AND organization_id = NEW.organization_id 
       AND is_active = true 
       LIMIT 1),
      'Cambio automático de estado',
      NOW()
    );
  END IF;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_track_conversation_status_change"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_track_conversation_status_change"() IS 'Registra automáticamente todos los cambios de estado en conversaciones para auditoría';



CREATE OR REPLACE FUNCTION "public"."fn_unit_cost"("p_provider" "text", "p_sku" "text", "p_at" "date" DEFAULT CURRENT_DATE) RETURNS numeric
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT unit_cost_usd FROM public.provider_pricing
   WHERE provider = p_provider
     AND sku = p_sku
     AND valid_from <= p_at
     AND (valid_to IS NULL OR valid_to >= p_at)
   ORDER BY valid_from DESC
   LIMIT 1;
$$;


