CREATE OR REPLACE FUNCTION "public"."fn_void_purchase_invoice"("p_invoice_id" "uuid", "p_reason" "text" DEFAULT NULL::"text", "p_user" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_inv public.invoice_purchase%ROWTYPE;
  v_pay_count int;
  v_item RECORD;
  v_sl RECORD;
  v_orig_entry RECORD;
  v_new_entry_id integer;
BEGIN
  SELECT * INTO v_inv FROM public.invoice_purchase WHERE id = p_invoice_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Factura de compra no encontrada'; END IF;
  IF v_inv.status = 'void' THEN RAISE EXCEPTION 'La factura ya está anulada'; END IF;

  -- Bloquear si hay pagos registrados
  SELECT COUNT(*) INTO v_pay_count FROM public.payments
   WHERE (source = 'invoice_purchase' AND source_id::text = p_invoice_id::text)
      OR (source = 'account_payable' AND source_id::text IN (
            SELECT id::text FROM public.accounts_payable WHERE invoice_id = p_invoice_id));
  IF v_pay_count > 0 THEN
    RAISE EXCEPTION 'No se puede anular: la factura tiene pagos registrados';
  END IF;

  -- Reversar inventario si la factura fue recibida
  IF v_inv.status = 'received' THEN
    FOR v_item IN
      SELECT product_id, qty, unit_price FROM public.invoice_items
      WHERE (invoice_id = p_invoice_id OR invoice_purchase_id = p_invoice_id)
        AND product_id IS NOT NULL AND COALESCE(qty, 0) > 0
    LOOP
      SELECT id, qty_on_hand INTO v_sl FROM public.stock_levels
       WHERE product_id = v_item.product_id AND branch_id = v_inv.branch_id;
      IF FOUND THEN
        UPDATE public.stock_levels
          SET qty_on_hand = qty_on_hand - v_item.qty, updated_at = now()
          WHERE id = v_sl.id;
      END IF;
      INSERT INTO public.stock_movements(
        organization_id, branch_id, product_id, direction, qty, unit_cost, source, source_id, note, updated_by)
      VALUES (
        v_inv.organization_id, v_inv.branch_id, v_item.product_id, 'out', v_item.qty, v_item.unit_price,
        'purchase_void', p_invoice_id::text, 'Anulación factura ' || COALESCE(v_inv.number_ext, ''), p_user);
    END LOOP;
  END IF;

  -- Cuenta por pagar a 0
  UPDATE public.accounts_payable SET balance = 0, updated_at = now() WHERE invoice_id = p_invoice_id;

  -- Reversa contable ESPEJO del asiento de compra original (incluye IVA)
  SELECT je.id, je.organization_id, je.branch_id
    INTO v_orig_entry
  FROM public.journal_entries je
  WHERE je.source = 'invoice_purchase'
    AND je.source_id = p_invoice_id::text
    AND je.memo LIKE 'Compra %'
  ORDER BY je.id DESC
  LIMIT 1;

  IF v_orig_entry.id IS NOT NULL THEN
    -- Cabecera de la reversa
    INSERT INTO public.journal_entries(
      organization_id, branch_id, entry_date, memo, source, source_id, posted, created_by)
    VALUES (
      v_orig_entry.organization_id, v_orig_entry.branch_id, now(),
      'Anulación factura de compra ' || COALESCE(v_inv.number_ext, ''),
      'invoice_purchase', p_invoice_id::text, true, p_user)
    RETURNING id INTO v_new_entry_id;

    -- Líneas espejo (débito<->crédito) del asiento original
    INSERT INTO public.journal_lines(journal_entry_id, account_code, description, debit, credit)
    SELECT v_new_entry_id, jl.account_code,
           'Reversa - ' || jl.description,
           jl.credit, jl.debit
    FROM public.journal_lines jl
    WHERE jl.journal_entry_id = v_orig_entry.id;
  END IF;

  -- Anular la factura
  UPDATE public.invoice_purchase
  SET status = 'void',
      balance = 0,
      notes = COALESCE(notes, '') ||
        CASE WHEN p_reason IS NOT NULL AND p_reason <> '' THEN E'\n[ANULADA] ' || p_reason ELSE E'\n[ANULADA]' END,
      updated_at = now()
  WHERE id = p_invoice_id;
END;
$$;


ALTER FUNCTION "public"."fn_void_purchase_invoice"("p_invoice_id" "uuid", "p_reason" "text", "p_user" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_missing_currencies"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  org_record RECORD;
  currency_record RECORD;
  currency_exists BOOLEAN;
  currencies_added INTEGER := 0;
  org_count INTEGER := 0;
  result JSONB;
BEGIN
  -- Recorrer todas las organizaciones activas
  FOR org_record IN 
    SELECT id, name FROM organizations WHERE status = 'active'
  LOOP
    org_count := org_count + 1;
    
    -- Para cada organización, recorrer todas las monedas globales activas
    FOR currency_record IN 
      SELECT code, name, symbol, decimal_places AS decimals FROM currencies WHERE is_active = true
    LOOP
      -- Verificar si la moneda ya está asociada a esta organización
      SELECT EXISTS(
        SELECT 1 FROM organization_currencies 
        WHERE organization_id = org_record.id AND currency_code = currency_record.code
      ) INTO currency_exists;
      
      -- Si no existe, crearla en organization_currencies
      IF NOT currency_exists THEN
        INSERT INTO organization_currencies (
          organization_id,
          currency_code,
          is_base,
          auto_update,
          created_at,
          updated_at
        ) VALUES (
          org_record.id,
          currency_record.code,
          false,  -- No establecerla como base por defecto
          true,   -- Habilitada para actualización automática
          NOW(),
          NOW()
        );
        
        currencies_added := currencies_added + 1;
      END IF;
    END LOOP;
  END LOOP;
  
  -- Retornar estadísticas
  RETURN jsonb_build_object(
    'success', true,
    'organizations_processed', org_count,
    'currencies_added', currencies_added
  );
END;
$$;


ALTER FUNCTION "public"."generate_missing_currencies"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_subdomain_from_name"("org_name" "text") RETURNS "text"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  base_subdomain TEXT;
  final_subdomain TEXT;
  counter INTEGER := 0;
BEGIN
  base_subdomain := lower(
    regexp_replace(
      regexp_replace(
        unaccent(trim(org_name)),
        '[^a-zA-Z0-9]+', '', 'g'
      ),
      '\s+', '', 'g'
    )
  );
  
  IF length(base_subdomain) < 3 THEN
    base_subdomain := base_subdomain || 'org';
  END IF;
  
  IF length(base_subdomain) > 30 THEN
    base_subdomain := left(base_subdomain, 30);
  END IF;
  
  final_subdomain := base_subdomain;
  
  WHILE EXISTS (SELECT 1 FROM organizations WHERE subdomain = final_subdomain) LOOP
    counter := counter + 1;
    final_subdomain := base_subdomain || counter::TEXT;
  END LOOP;
  
  RETURN final_subdomain;
END;
$$;


ALTER FUNCTION "public"."generate_subdomain_from_name"("org_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_web_order_number"("org_id" integer) RETURNS "text"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  today_date TEXT;
  seq_num INTEGER;
  order_num TEXT;
BEGIN
  today_date := TO_CHAR(NOW(), 'YYYYMMDD');
  
  SELECT COALESCE(MAX(
    CAST(SUBSTRING(order_number FROM 'WO-[0-9]+-([0-9]+)') AS INTEGER)
  ), 0) + 1
  INTO seq_num
  FROM web_orders
  WHERE organization_id = org_id
  AND order_number LIKE 'WO-' || today_date || '-%';
  
  order_num := 'WO-' || today_date || '-' || LPAD(seq_num::TEXT, 4, '0');
  
  RETURN order_num;
END;
$$;


ALTER FUNCTION "public"."generate_web_order_number"("org_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_account_receivable_detail"("account_id" "uuid", "org_id" integer) RETURNS TABLE("id" "uuid", "customer_id" "uuid", "organization_id" integer, "invoice_id" "uuid", "sale_id" "uuid", "amount" numeric, "balance" numeric, "due_date" timestamp with time zone, "status" "text", "days_overdue" integer, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "customer_name" "text", "customer_email" "text", "customer_phone" "text", "customer_address" "text", "payment_history" "jsonb", "last_reminder_date" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    ar.id,
    ar.customer_id,
    ar.organization_id,
    ar.invoice_id,
    ar.sale_id,
    ar.amount,
    ar.balance,
    ar.due_date,
    ar.status,
    ar.days_overdue,
    ar.created_at,
    ar.updated_at,
    COALESCE(c.full_name, CONCAT(c.first_name, ' ', c.last_name)) as customer_name,
    c.email as customer_email,
    c.phone as customer_phone,
    c.address as customer_address,
    COALESCE(
      (
        SELECT jsonb_agg(
          jsonb_build_object(
            'id', p.id,
            'amount', p.amount,
            'method', p.method,
            'reference', p.reference,
            'status', p.status,
            'created_at', p.created_at
          ) ORDER BY p.created_at DESC
        )
        FROM payments p
        WHERE p.source = 'invoice_sales'
          AND p.source_id::uuid IN (
            SELECT inv.id 
            FROM invoice_sales inv 
            WHERE inv.customer_id = ar.customer_id 
              AND inv.organization_id = ar.organization_id
          )
      ),
      '[]'::jsonb
    ) as payment_history,
    ar.last_reminder_date
  FROM accounts_receivable ar
  JOIN customers c ON ar.customer_id = c.id
  WHERE ar.id = account_id 
    AND ar.organization_id = org_id;  -- ⭐ Filtro de seguridad mantenido
END;
$$;


ALTER FUNCTION "public"."get_account_receivable_detail"("account_id" "uuid", "org_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_accounts_receivable_by_day"("p_organization_id" integer, "p_timezone" "text", "p_start" timestamp with time zone, "p_end" timestamp with time zone, "p_branch_id" integer DEFAULT NULL::integer) RETURNS TABLE("fecha" "date", "total" numeric)
    LANGUAGE "sql" STABLE
    AS $$
  SELECT (created_at AT TIME ZONE p_timezone)::date AS fecha,
         COALESCE(SUM(balance), 0)::numeric AS total
  FROM public.accounts_receivable
  WHERE organization_id = p_organization_id
    AND created_at >= p_start AND created_at < p_end
    AND (p_branch_id IS NULL OR branch_id = p_branch_id)
  GROUP BY 1 ORDER BY 1;
$$;


