CREATE OR REPLACE FUNCTION "public"."get_branch_usage"("org_id" integer) RETURNS TABLE("current_branches" integer, "max_branches" integer, "remaining_branches" integer, "is_unlimited" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    (SELECT COUNT(*)::INTEGER 
     FROM branches 
     WHERE organization_id = org_id AND is_active = true
    ) as current_branches,
    p.max_branches,
    CASE 
      WHEN p.max_branches IS NULL THEN NULL
      ELSE p.max_branches - (SELECT COUNT(*)::INTEGER 
                             FROM branches 
                             WHERE organization_id = org_id AND is_active = true)
    END as remaining_branches,
    (p.max_branches IS NULL) as is_unlimited
  FROM subscriptions s
  JOIN plans p ON s.plan_id = p.id
  WHERE s.organization_id = org_id
    AND s.status IN ('active', 'trialing')
  ORDER BY s.created_at DESC
  LIMIT 1;
END;
$$;


