CREATE OR REPLACE FUNCTION "public"."get_catalogo_productos"("p_organization_id" integer, "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 50, "p_search" "text" DEFAULT NULL::"text", "p_category_id" integer DEFAULT NULL::integer, "p_status" "text" DEFAULT NULL::"text", "p_branch_id" integer DEFAULT NULL::integer, "p_sort_by" "text" DEFAULT 'name'::"text", "p_sort_dir" "text" DEFAULT 'asc'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_offset INTEGER;
  v_total BIGINT;
  v_items JSONB;
BEGIN
  v_offset := (p_page - 1) * p_page_size;

  -- Conteo total
  SELECT COUNT(*) INTO v_total
  FROM products p
  WHERE p.organization_id = p_organization_id
    AND p.parent_product_id IS NULL
    AND (p_status IS NULL OR p_status = 'todos' OR p.status = p_status)
    AND (p_status IS NULL AND p.status != 'deleted' OR p_status IS NOT NULL)
    AND (p_category_id IS NULL OR p.category_id = p_category_id)
    AND (
      p_search IS NULL OR p_search = '' OR
      p.name ILIKE '%' || p_search || '%' OR
      p.sku ILIKE '%' || p_search || '%' OR
      p.barcode ILIKE '%' || p_search || '%'
    );

  -- Items paginados
  WITH filtered AS (
    SELECT
      p.id, p.uuid, p.organization_id, p.sku, p.name, p.description,
      p.category_id, p.unit_code, p.barcode, p.status, p.track_stock,
      p.parent_product_id, p.is_parent, p.product_type, p.brand, p.reference,
      p.variant_data, p.station, p.tax_id, p.is_composite, p.production_type,
      p.created_at, p.updated_at,
      c.name AS category_name,
      COALESCE(pp.price, 0) AS out_price,
      COALESCE(pp.compare_price, 0) AS out_compare_price,
      COALESCE(pc.cost, 0) AS out_cost,
      CASE WHEN p.track_stock = false THEN NULL
           ELSE COALESCE(sl.stock_total, 0) END AS out_stock,
      CASE WHEN p.track_stock = false THEN NULL
           ELSE COALESCE(sl.stock_branch, 0) END AS out_stock_branch
    FROM products p
    LEFT JOIN categories c ON c.id = p.category_id
    LEFT JOIN LATERAL (
      SELECT price, compare_price
      FROM product_prices
      WHERE product_id = p.id
        AND (effective_to IS NULL OR effective_to > NOW())
        AND (effective_from IS NULL OR effective_from <= NOW())
      ORDER BY effective_from DESC
      LIMIT 1
    ) pp ON true
    LEFT JOIN LATERAL (
      SELECT cost
      FROM product_costs
      WHERE product_id = p.id
        AND (effective_to IS NULL OR effective_to > NOW())
        AND (effective_from IS NULL OR effective_from <= NOW())
      ORDER BY effective_from DESC
      LIMIT 1
    ) pc ON true
    LEFT JOIN LATERAL (
      SELECT
        COALESCE(SUM(qty_on_hand - qty_reserved), 0) AS stock_total,
        COALESCE(SUM(CASE WHEN branch_id = p_branch_id THEN (qty_on_hand - qty_reserved) ELSE 0 END), 0) AS stock_branch
      FROM stock_levels
      WHERE product_id = p.id
    ) sl ON true
    WHERE p.organization_id = p_organization_id
      AND p.parent_product_id IS NULL
      AND (p_status IS NULL OR p_status = 'todos' OR p.status = p_status)
      AND (p_status IS NULL AND p.status != 'deleted' OR p_status IS NOT NULL)
      AND (p_category_id IS NULL OR p.category_id = p_category_id)
      AND (
        p_search IS NULL OR p_search = '' OR
        p.name ILIKE '%' || p_search || '%' OR
        p.sku ILIKE '%' || p_search || '%' OR
        p.barcode ILIKE '%' || p_search || '%'
      )
  ),
  sorted AS (
    SELECT * FROM filtered
    ORDER BY
      CASE WHEN p_sort_dir = 'asc' AND p_sort_by = 'name' THEN name END ASC NULLS LAST,
      CASE WHEN p_sort_dir = 'asc' AND p_sort_by = 'sku' THEN sku END ASC NULLS LAST,
      CASE WHEN p_sort_dir = 'asc' AND p_sort_by = 'price' THEN out_price END ASC NULLS LAST,
      CASE WHEN p_sort_dir = 'asc' AND p_sort_by = 'created_at' THEN created_at END ASC NULLS LAST,
      CASE WHEN p_sort_dir = 'asc' AND p_sort_by = 'updated_at' THEN updated_at END ASC NULLS LAST,
      CASE WHEN p_sort_dir = 'desc' AND p_sort_by = 'name' THEN name END DESC NULLS LAST,
      CASE WHEN p_sort_dir = 'desc' AND p_sort_by = 'sku' THEN sku END DESC NULLS LAST,
      CASE WHEN p_sort_dir = 'desc' AND p_sort_by = 'price' THEN out_price END DESC NULLS LAST,
      CASE WHEN p_sort_dir = 'desc' AND p_sort_by = 'created_at' THEN created_at END DESC NULLS LAST,
      CASE WHEN p_sort_dir = 'desc' AND p_sort_by = 'updated_at' THEN updated_at END DESC NULLS LAST,
      name ASC
    LIMIT p_page_size OFFSET v_offset
  )
  SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb)
  INTO v_items
  FROM sorted t;

  RETURN jsonb_build_object(
    'items', COALESCE(v_items, '[]'::jsonb),
    'total', v_total,
    'page', p_page,
    'page_size', p_page_size,
    'total_pages', CASE WHEN p_page_size > 0 THEN CEIL(v_total::numeric / p_page_size) ELSE 0 END
  );
END;
$$;


