CREATE OR REPLACE FUNCTION "public"."get_conversation_stats"("p_organization_id" integer, "p_start_date" timestamp with time zone DEFAULT ("now"() - '30 days'::interval), "p_end_date" timestamp with time zone DEFAULT "now"()) RETURNS TABLE("total_conversations" bigint, "open_conversations" bigint, "closed_conversations" bigint, "avg_response_time_seconds" numeric, "avg_messages_per_conversation" numeric, "ai_response_rate" numeric, "agent_response_rate" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    COUNT(*)::bigint as total_conversations,
    COUNT(*) FILTER (WHERE c.status = 'open')::bigint as open_conversations,
    COUNT(*) FILTER (WHERE c.status = 'closed')::bigint as closed_conversations,
    ROUND(AVG(c.first_response_time_seconds), 2) as avg_response_time_seconds,
    ROUND(AVG(c.message_count), 2) as avg_messages_per_conversation,
    ROUND(
      COUNT(*) FILTER (
        WHERE EXISTS (
          SELECT 1 FROM messages m 
          WHERE m.conversation_id = c.id AND m.role = 'ai'
        )
      )::numeric / NULLIF(COUNT(*)::numeric, 0) * 100, 
      2
    ) as ai_response_rate,
    ROUND(
      COUNT(*) FILTER (
        WHERE EXISTS (
          SELECT 1 FROM messages m 
          WHERE m.conversation_id = c.id AND m.role = 'agent'
        )
      )::numeric / NULLIF(COUNT(*)::numeric, 0) * 100, 
      2
    ) as agent_response_rate
  FROM conversations c
  WHERE c.organization_id = p_organization_id
    AND c.created_at BETWEEN p_start_date AND p_end_date;
END;
$$;


ALTER FUNCTION "public"."get_conversation_stats"("p_organization_id" integer, "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_conversation_stats"("p_organization_id" integer, "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone) IS 'Obtiene estadísticas de conversaciones para un período';



