CREATE OR REPLACE FUNCTION "public"."get_currency_templates"("p_organization_id" integer) RETURNS TABLE("code" character, "name" "text", "symbol" "text", "decimals" integer, "auto_update" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    c.code,
    c.name,
    c.symbol,
    c.decimals,
    c.auto_update
  FROM 
    currencies c
  WHERE 
    NOT EXISTS (
      SELECT 1 
      FROM organization_currencies oc 
      WHERE oc.currency_code = c.code AND oc.organization_id = p_organization_id
    )
  ORDER BY 
    c.code ASC;
END;
$$;


