CREATE OR REPLACE FUNCTION "public"."get_current_plan"("org_id" integer) RETURNS TABLE("plan_id" integer, "plan_code" "text", "plan_name" "text", "price_usd_month" numeric, "price_usd_year" numeric, "trial_days" integer, "max_modules" integer, "max_branches" integer, "max_users" integer, "features" "jsonb", "subscription_status" "text", "subscription_id" "uuid", "current_period_start" timestamp with time zone, "current_period_end" timestamp with time zone, "trial_start" timestamp with time zone, "trial_end" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    p.id as plan_id,
    p.code as plan_code,
    p.name as plan_name,
    p.price_usd_month,
    p.price_usd_year,
    p.trial_days,
    p.max_modules,
    p.max_branches,
    p.max_users,
    p.features,
    s.status as subscription_status,
    s.id as subscription_id,
    s.current_period_start,
    s.current_period_end,
    s.trial_start,
    s.trial_end
  FROM subscriptions s
  JOIN plans p ON s.plan_id = p.id
  WHERE s.organization_id = org_id
    AND s.status IN ('active', 'trialing', 'past_due')
  ORDER BY s.created_at DESC, s.updated_at DESC
  LIMIT 1;
  
  IF NOT FOUND THEN
    RETURN QUERY
    SELECT 
      p.id as plan_id,
      p.code as plan_code,
      p.name as plan_name,
      p.price_usd_month,
      p.price_usd_year,
      p.trial_days,
      p.max_modules,
      p.max_branches,
      p.max_users,
      p.features,
      'active'::TEXT as subscription_status,
      NULL::UUID as subscription_id,
      NULL::TIMESTAMPTZ as current_period_start,
      NULL::TIMESTAMPTZ as current_period_end,
      NULL::TIMESTAMPTZ as trial_start,
      NULL::TIMESTAMPTZ as trial_end
    FROM plans p
    WHERE p.code = 'free'
    LIMIT 1;
  END IF;
END;
$$;


ALTER FUNCTION "public"."get_current_plan"("org_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_customer_accounts_receivable"("customer_ids" "uuid"[], "org_id" integer) RETURNS TABLE("customer_id" "uuid", "total_balance" numeric)
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    ar.customer_id,
    SUM(ar.balance) as total_balance
  FROM 
    accounts_receivable ar
  WHERE 
    ar.customer_id = ANY(customer_ids)
    AND ar.organization_id = org_id::text
    AND ar.balance > 0
  GROUP BY 
    ar.customer_id;
END;
$$;


