CREATE OR REPLACE FUNCTION "public"."get_invoice_payments"("target_invoice_id" "uuid", "org_id" integer) RETURNS TABLE("id" "uuid", "source" "text", "source_id" "text", "method" "text", "amount" numeric, "currency" character, "reference" "text", "processor_response" "jsonb", "status" "text", "created_at" timestamp with time zone, "created_by" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  -- 1. Pagos directos a la factura
  SELECT 
    p.id,
    p.source,
    p.source_id,
    p.method,
    p.amount,
    p.currency,
    p.reference,
    p.processor_response,
    p.status,
    p.created_at,
    p.created_by
  FROM payments p
  WHERE p.organization_id = org_id
    AND p.source = 'invoice_sales'
    AND p.source_id = target_invoice_id::text
    
  UNION ALL
  
  -- 2. Pagos a cuentas por cobrar vinculadas a esta factura  
  SELECT 
    p.id,
    p.source,
    p.source_id,
    p.method,
    p.amount,
    p.currency,
    p.reference,
    p.processor_response,
    p.status,
    p.created_at,
    p.created_by
  FROM payments p
  JOIN accounts_receivable ar ON p.source_id = ar.id::text
  WHERE p.organization_id = org_id
    AND p.source = 'account_receivable'
    AND ar.invoice_id = target_invoice_id
    AND ar.organization_id = org_id
    
  ORDER BY created_at DESC;
END;
$$;


ALTER FUNCTION "public"."get_invoice_payments"("target_invoice_id" "uuid", "org_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_invoice_sales_by_day"("p_organization_id" integer, "p_timezone" "text", "p_start" timestamp with time zone, "p_end" timestamp with time zone) RETURNS TABLE("fecha" "date", "total" bigint)
    LANGUAGE "sql" STABLE
    AS $$
  SELECT (issue_date AT TIME ZONE p_timezone)::date AS fecha,
         COUNT(*)::bigint AS total
  FROM public.invoice_sales
  WHERE organization_id = p_organization_id
    AND issue_date >= p_start AND issue_date < p_end
  GROUP BY 1 ORDER BY 1;
$$;


ALTER FUNCTION "public"."get_invoice_sales_by_day"("p_organization_id" integer, "p_timezone" "text", "p_start" timestamp with time zone, "p_end" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_invoice_sales_by_day"("p_organization_id" integer, "p_timezone" "text", "p_start" timestamp with time zone, "p_end" timestamp with time zone, "p_branch_id" integer DEFAULT NULL::integer) RETURNS TABLE("fecha" "date", "total" bigint)
    LANGUAGE "sql" STABLE
    AS $$
  SELECT (issue_date AT TIME ZONE p_timezone)::date AS fecha,
         COUNT(*)::bigint AS total
  FROM public.invoice_sales
  WHERE organization_id = p_organization_id
    AND issue_date >= p_start AND issue_date < p_end
    AND (p_branch_id IS NULL OR branch_id = p_branch_id)
  GROUP BY 1 ORDER BY 1;
$$;


ALTER FUNCTION "public"."get_invoice_sales_by_day"("p_organization_id" integer, "p_timezone" "text", "p_start" timestamp with time zone, "p_end" timestamp with time zone, "p_branch_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_invoice_sales_by_hour"("p_organization_id" integer, "p_timezone" "text", "p_start" timestamp with time zone, "p_end" timestamp with time zone, "p_branch_id" integer DEFAULT NULL::integer) RETURNS TABLE("hora" integer, "total" bigint)
    LANGUAGE "sql" STABLE
    AS $$
  WITH agg AS (
    SELECT EXTRACT(HOUR FROM issue_date AT TIME ZONE p_timezone)::int AS hora,
           COUNT(*)::bigint AS total
    FROM public.invoice_sales
    WHERE organization_id = p_organization_id
      AND issue_date >= p_start AND issue_date < p_end
      AND (p_branch_id IS NULL OR branch_id = p_branch_id)
    GROUP BY 1
  )
  SELECT h.hora::int, COALESCE(a.total, 0)::bigint AS total
  FROM generate_series(0, 23) AS h(hora)
  LEFT JOIN agg a ON a.hora = h.hora
  ORDER BY h.hora;
$$;


ALTER FUNCTION "public"."get_invoice_sales_by_hour"("p_organization_id" integer, "p_timezone" "text", "p_start" timestamp with time zone, "p_end" timestamp with time zone, "p_branch_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_module_usage"("org_id" integer) RETURNS TABLE("current_modules" integer, "max_modules" integer, "remaining_modules" integer, "is_unlimited" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    (SELECT COUNT(*)::INTEGER 
     FROM organization_modules 
     WHERE organization_id = org_id AND is_active = true
    ) as current_modules,
    p.max_modules,
    CASE 
      WHEN p.max_modules IS NULL THEN NULL
      ELSE p.max_modules - (SELECT COUNT(*)::INTEGER 
                            FROM organization_modules 
                            WHERE organization_id = org_id AND is_active = true)
    END as remaining_modules,
    (p.max_modules IS NULL) as is_unlimited
  FROM subscriptions s
  JOIN plans p ON s.plan_id = p.id
  WHERE s.organization_id = org_id
    AND s.status IN ('active', 'trialing')
  ORDER BY s.created_at DESC
  LIMIT 1;
END;
$$;


ALTER FUNCTION "public"."get_module_usage"("org_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_org_finance_settings"("org_id" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    org_settings JSONB;
    default_finance_settings JSONB := '{
        "currency_format": "#,##0.00",
        "decimal_separator": ".",
        "thousands_separator": ",",
        "date_format": "YYYY-MM-DD",
        "default_currency": "USD"
    }';
BEGIN
    -- Obtener configuración actual
    SELECT settings->'finance' INTO org_settings
    FROM public.organization_preferences
    WHERE organization_id = org_id;
    
    -- Si no existe, devolver valores predeterminados
    IF org_settings IS NULL THEN
        RETURN default_finance_settings;
    END IF;
    
    -- Combinar valores predeterminados con valores existentes (los existentes tienen prioridad)
    RETURN default_finance_settings || org_settings;
END;
$$;


ALTER FUNCTION "public"."get_org_finance_settings"("org_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_org_members_by_day"("p_organization_id" integer, "p_timezone" "text", "p_start" timestamp with time zone, "p_end" timestamp with time zone) RETURNS TABLE("fecha" "date", "total" bigint)
    LANGUAGE "sql" STABLE
    AS $$
  SELECT (created_at AT TIME ZONE p_timezone)::date AS fecha,
         COUNT(*)::bigint AS total
  FROM public.organization_members
  WHERE organization_id = p_organization_id
    AND created_at >= p_start AND created_at < p_end
  GROUP BY 1 ORDER BY 1;
$$;


