CREATE OR REPLACE FUNCTION "public"."get_organization_currencies"("p_organization_id" integer) RETURNS TABLE("code" character, "name" "text", "symbol" "text", "decimals" integer, "auto_update" boolean, "is_base" boolean, "org_auto_update" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    c.code,
    c.name,
    c.symbol,
    c.decimals,
    c.auto_update,
    oc.is_base,
    oc.auto_update as org_auto_update
  FROM 
    currencies c
  JOIN 
    organization_currencies oc ON c.code = oc.currency_code
  WHERE 
    oc.organization_id = p_organization_id
  ORDER BY 
    oc.is_base DESC, 
    c.code ASC;
END;
$$;


