CREATE OR REPLACE FUNCTION "public"."get_organization_payment_methods"("p_organization_id" integer) RETURNS TABLE("code" "text", "name" "text", "requires_reference" boolean, "is_active" boolean, "is_system" boolean, "organization_settings" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    pm.code,
    pm.name,
    pm.requires_reference,
    pm.is_active,
    pm.is_system,
    CASE 
      WHEN opm.id IS NOT NULL THEN
        jsonb_build_object(
          'is_active', opm.is_active,
          'accounting_account', opm.settings->>'accounting_account',
          'gateway', opm.settings->>'gateway',
          'settings', opm.settings
        )
      ELSE NULL
    END AS organization_settings
  FROM 
    payment_methods pm
  LEFT JOIN 
    organization_payment_methods opm ON pm.code = opm.payment_method_code 
    AND opm.organization_id = p_organization_id
  ORDER BY pm.name;
END;
$$;


