CREATE OR REPLACE FUNCTION "public"."get_parent_product_stock_summary"("parent_product_id" integer) RETURNS TABLE("total_variations" integer, "total_stock" numeric, "avg_price" numeric, "min_price" numeric, "max_price" numeric)
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        COUNT(p.id)::INTEGER as total_variations,
        COALESCE(SUM(sl.qty_on_hand), 0) as total_stock,
        COALESCE(AVG(pp.price), 0) as avg_price,
        COALESCE(MIN(pp.price), 0) as min_price,
        COALESCE(MAX(pp.price), 0) as max_price
    FROM products p
    LEFT JOIN stock_levels sl ON p.id = sl.product_id
    LEFT JOIN product_prices pp ON p.id = pp.product_id 
        AND pp.effective_to IS NULL
    WHERE p.parent_product_id = get_parent_product_stock_summary.parent_product_id
        AND p.is_parent = false;
END;
$$;


