CREATE OR REPLACE FUNCTION "public"."get_payment_method_gateway_config"("p_organization_id" integer, "p_payment_method_code" character varying) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_settings JSONB;
BEGIN
  -- Obtener la configuración del método de pago para esta organización
  SELECT settings FROM organization_payment_methods
  WHERE organization_id = p_organization_id 
    AND payment_method_code = p_payment_method_code
  INTO v_settings;
  
  IF v_settings IS NULL THEN
    RETURN jsonb_build_object(
      'success', true,
      'gateway', NULL,
      'gateway_config', '{}'::JSONB
    );
  END IF;
  
  RETURN jsonb_build_object(
    'success', true,
    'gateway', v_settings->'gateway',
    'gateway_config', COALESCE(v_settings->'gateway_config', '{}'::JSONB)
  );
END;
$$;


ALTER FUNCTION "public"."get_payment_method_gateway_config"("p_organization_id" integer, "p_payment_method_code" character varying) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_payments_filtered"("account_id" "uuid", "org_id" integer, "show_all_customer_payments" boolean DEFAULT false, "search_term" "text" DEFAULT ''::"text", "payment_limit" integer DEFAULT 10, "payment_offset" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "amount" numeric, "method" "text", "reference" "text", "status" "text", "created_at" timestamp with time zone, "source_id" "text", "invoice_number" "text", "total_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  target_customer_id uuid;
  target_organization_id integer;
  target_invoice_id uuid;
BEGIN
  -- Obtener customer_id, organization_id e invoice_id de la cuenta por cobrar
  SELECT ar.customer_id, ar.organization_id, ar.invoice_id
  INTO target_customer_id, target_organization_id, target_invoice_id
  FROM accounts_receivable ar
  WHERE ar.id = account_id AND ar.organization_id = org_id;
  
  IF target_customer_id IS NULL THEN
    RETURN;
  END IF;
  
  RETURN QUERY
  WITH filtered_payments AS (
    -- Pagos directos a facturas (comportamiento original)
    SELECT 
      p.id,
      p.amount,
      p.method,
      p.reference,
      p.status,
      p.created_at,
      p.source_id,
      inv.number as invoice_number,
      COUNT(*) OVER() as total_count
    FROM payments p
    JOIN invoice_sales inv ON p.source_id = inv.id::text
    WHERE p.source = 'invoice_sales'
      AND inv.organization_id = target_organization_id
      AND (
        CASE 
          WHEN show_all_customer_payments THEN 
            -- Mostrar todos los pagos del cliente
            inv.customer_id = target_customer_id
          ELSE 
            -- Mostrar solo los pagos de la factura específica de esta cuenta por cobrar
            inv.id = target_invoice_id
        END
      )
      AND (
        search_term = '' OR
        LOWER(COALESCE(p.reference, '')) LIKE LOWER('%' || search_term || '%') OR
        LOWER(p.method) LIKE LOWER('%' || search_term || '%') OR
        LOWER(inv.number) LIKE LOWER('%' || search_term || '%')
      )
    
    UNION ALL
    
    -- Pagos directos a cuentas por cobrar (nueva funcionalidad)
    SELECT 
      p.id,
      p.amount,
      p.method,
      p.reference,
      p.status,
      p.created_at,
      p.source_id,
      COALESCE(inv.number, 'N/A') as invoice_number,
      COUNT(*) OVER() as total_count
    FROM payments p
    JOIN accounts_receivable ar ON p.source_id = ar.id::text
    LEFT JOIN invoice_sales inv ON ar.invoice_id = inv.id
    WHERE p.source = 'account_receivable'
      AND ar.organization_id = target_organization_id
      AND (
        CASE 
          WHEN show_all_customer_payments THEN 
            -- Mostrar todos los pagos del cliente
            ar.customer_id = target_customer_id
          ELSE 
            -- Mostrar solo los pagos de la cuenta específica
            ar.id = account_id
        END
      )
      AND (
        search_term = '' OR
        LOWER(COALESCE(p.reference, '')) LIKE LOWER('%' || search_term || '%') OR
        LOWER(p.method) LIKE LOWER('%' || search_term || '%') OR
        LOWER(COALESCE(inv.number, '')) LIKE LOWER('%' || search_term || '%')
      )
  )
  SELECT * FROM filtered_payments
  ORDER BY created_at DESC
  LIMIT payment_limit
  OFFSET payment_offset;
END;
$$;


ALTER FUNCTION "public"."get_payments_filtered"("account_id" "uuid", "org_id" integer, "show_all_customer_payments" boolean, "search_term" "text", "payment_limit" integer, "payment_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_payments_for_account"("account_id" "uuid", "org_id" integer, "show_all_customer_payments" boolean DEFAULT false, "page_size" integer DEFAULT 10, "page_number" integer DEFAULT 1) RETURNS TABLE("id" "uuid", "amount" numeric, "method" "text", "reference" "text", "status" "text", "created_at" timestamp with time zone, "source_type" "text", "source_id" "text", "total_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  target_customer_id uuid;
  offset_val integer;
  account_amount numeric;
  account_due_date date;
BEGIN
  -- Obtener datos de la cuenta
  SELECT ar.customer_id, ar.amount, ar.due_date::date 
  INTO target_customer_id, account_amount, account_due_date
  FROM accounts_receivable ar
  WHERE ar.id = account_id AND ar.organization_id = org_id;

  -- Calcular offset para paginación
  offset_val := (page_number - 1) * page_size;

  -- Si show_all_customer_payments es false, intentar mostrar solo pagos relacionados con la cuenta específica
  -- Si es true, mostrar todos los pagos del cliente
  RETURN QUERY
  SELECT 
    p.id,
    p.amount,
    p.method,
    p.reference,
    p.status,
    p.created_at,
    p.source as source_type,
    p.source_id,
    COUNT(*) OVER() as total_count
  FROM payments p
  JOIN invoice_sales inv ON p.source_id = inv.id::text
  WHERE inv.customer_id = target_customer_id
    AND inv.organization_id = org_id
    AND (
      show_all_customer_payments = true 
      OR 
      (
        show_all_customer_payments = false 
        AND (
          -- Intentar relacionar por fecha y monto similar (aproximación)
          inv.due_date::date = account_due_date
          OR 
          inv.total = account_amount
        )
      )
    )
  ORDER BY p.created_at DESC
  LIMIT page_size
  OFFSET offset_val;
END;
$$;


ALTER FUNCTION "public"."get_payments_for_account"("account_id" "uuid", "org_id" integer, "show_all_customer_payments" boolean, "page_size" integer, "page_number" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_permanent_image_url"("storage_path" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    bucket_name TEXT;
    file_path TEXT;
    url TEXT;
BEGIN
    -- Extraer nombre del bucket y ruta del archivo
    bucket_name := SPLIT_PART(storage_path, '/', 1);
    file_path := SUBSTRING(storage_path FROM POSITION('/' IN storage_path) + 1);
    
    -- Generar URL permanente (no firmada)
    url := CONCAT(
        'https://', 
        (SELECT net.get_host_by_this_request()),
        '/storage/v1/object/public/',
        bucket_name, 
        '/', 
        file_path
    );
    
    RETURN url;
END;
$$;


ALTER FUNCTION "public"."get_permanent_image_url"("storage_path" "text") OWNER TO "postgres";


