CREATE OR REPLACE FUNCTION "public"."get_product_variations"("parent_product_id" integer) RETURNS TABLE("id" integer, "name" "text", "sku" "text", "current_price" numeric, "current_cost" numeric, "total_stock" numeric, "variant_attributes" "jsonb")
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        p.id,
        p.name,
        p.sku,
        COALESCE(pp.price, 0) as current_price,
        COALESCE(pc.cost, 0) as current_cost,
        COALESCE(SUM(sl.qty_on_hand), 0) as total_stock,
        p.variant_data as variant_attributes
    FROM products p
    LEFT JOIN product_prices pp ON p.id = pp.product_id 
        AND pp.effective_to IS NULL
    LEFT JOIN product_costs pc ON p.id = pc.product_id 
        AND pc.effective_to IS NULL  
    LEFT JOIN stock_levels sl ON p.id = sl.product_id
    WHERE p.parent_product_id = get_product_variations.parent_product_id
        AND p.is_parent = false
    GROUP BY p.id, p.name, p.sku, pp.price, pc.cost, p.variant_data
    ORDER BY p.name;
END;
$$;


ALTER FUNCTION "public"."get_product_variations"("parent_product_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_products_below_min_level"("p_organization_id" integer) RETURNS TABLE("id" integer, "product_id" integer, "sku" "text", "name" "text", "branch_id" integer, "branch_name" "text", "qty_on_hand" numeric, "min_level" numeric)
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        sl.id,
        p.id as product_id,
        COALESCE(p.sku, 'N/A') as sku,
        p.name,
        sl.branch_id,
        b.name as branch_name,
        sl.qty_on_hand,
        sl.min_level
    FROM stock_levels sl
    INNER JOIN products p ON p.id = sl.product_id
    INNER JOIN branches b ON b.id = sl.branch_id
    WHERE p.organization_id = p_organization_id
        AND sl.min_level > 0
        AND sl.qty_on_hand < sl.min_level
    ORDER BY (sl.min_level - sl.qty_on_hand) DESC, p.name;
END;
$$;


ALTER FUNCTION "public"."get_products_below_min_level"("p_organization_id" integer) OWNER TO "postgres";


