CREATE OR REPLACE FUNCTION "public"."get_products_min_stock_config"("p_organization_id" integer) RETURNS TABLE("product_id" integer, "sku" "text", "name" "text", "branch_id" integer, "branch_name" character varying, "min_level" numeric)
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        p.id as product_id,
        COALESCE(p.sku, 'N/A') as sku,
        p.name,
        sl.branch_id,
        b.name as branch_name,
        COALESCE(sl.min_level, 0) as min_level
    FROM products p
    CROSS JOIN branches b
    LEFT JOIN stock_levels sl ON sl.product_id = p.id AND sl.branch_id = b.id
    WHERE p.organization_id = p_organization_id
        AND b.organization_id = p_organization_id
        AND (p.status IS NULL OR p.status != 'inactive')
    ORDER BY p.name, b.name;
END;
$$;


