CREATE OR REPLACE FUNCTION "public"."get_products_with_latest_costs"("org_id" integer) RETURNS TABLE("id" integer, "name" "text", "sku" "text", "description" "text", "cost" numeric, "price" numeric, "tax_id" "uuid", "tax_code" "text", "tax_name" "text", "tax_rate" numeric, "is_parent" boolean, "parent_product_id" integer, "track_stock" boolean)
    LANGUAGE "sql" SECURITY DEFINER
    AS $$
    WITH latest_costs AS (
        SELECT DISTINCT ON (product_id) 
            product_id, 
            cost
        FROM product_costs
        WHERE effective_to IS NULL OR effective_to > NOW()
        ORDER BY product_id, effective_from DESC
    ),
    latest_prices AS (
        SELECT DISTINCT ON (product_id) 
            product_id, 
            price
        FROM product_prices
        WHERE effective_to IS NULL OR effective_to > NOW()
        ORDER BY product_id, effective_from DESC
    ),
    product_taxes AS (
        SELECT 
            ptr.product_id,
            ot.id AS tax_id,
            tt.code AS tax_code,
            ot.name AS tax_name,
            ot.rate AS tax_rate
        FROM product_tax_relations ptr
        JOIN organization_taxes ot ON ptr.tax_id = ot.id
        JOIN tax_templates tt ON ot.template_id = tt.id
        WHERE ot.organization_id = org_id
    )
    SELECT 
        p.id,
        p.name,
        p.sku,
        p.description,
        COALESCE(lc.cost, 0) AS cost,
        COALESCE(lp.price, 0) AS price,
        pt.tax_id,
        pt.tax_code,
        pt.tax_name,
        pt.tax_rate,
        p.is_parent,
        p.parent_product_id,
        p.track_stock
    FROM products p
    LEFT JOIN latest_costs lc ON p.id = lc.product_id
    LEFT JOIN latest_prices lp ON p.id = lp.product_id
    LEFT JOIN product_taxes pt ON p.id = pt.product_id
    WHERE p.organization_id = org_id
        AND p.status = 'active'
    ORDER BY p.name ASC;
$$;


ALTER FUNCTION "public"."get_products_with_latest_costs"("org_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_products_with_latest_prices"("org_id" integer) RETURNS TABLE("id" integer, "name" "text", "sku" "text", "description" "text", "price" numeric, "tax_id" "uuid", "tax_code" "text", "tax_name" "text", "tax_rate" numeric, "is_parent" boolean, "parent_product_id" integer, "track_stock" boolean)
    LANGUAGE "sql" SECURITY DEFINER
    AS $$
    WITH latest_prices AS (
        SELECT DISTINCT ON (product_id) 
            product_id, 
            price
        FROM product_prices
        ORDER BY product_id, effective_from DESC
    ),
    product_taxes AS (
        SELECT 
            ptr.product_id,
            ot.id AS tax_id,
            tt.code AS tax_code,
            ot.name AS tax_name,
            ot.rate AS tax_rate
        FROM product_tax_relations ptr
        JOIN organization_taxes ot ON ptr.tax_id = ot.id
        JOIN tax_templates tt ON ot.template_id = tt.id
        WHERE ot.organization_id = org_id
    )
    SELECT 
        p.id,
        p.name,
        p.sku,
        p.description,
        COALESCE(lp.price, 0) as price,
        pt.tax_id,
        pt.tax_code,
        pt.tax_name,
        pt.tax_rate,
        p.is_parent,
        p.parent_product_id,
        p.track_stock
    FROM products p
    LEFT JOIN latest_prices lp ON p.id = lp.product_id
    LEFT JOIN product_taxes pt ON p.id = pt.product_id
    WHERE p.organization_id = org_id
    ORDER BY p.name ASC;
$$;


ALTER FUNCTION "public"."get_products_with_latest_prices"("org_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_profiles_by_organization"("org_id" integer) RETURNS TABLE("id" bigint, "created_at" timestamp with time zone, "first_name" "text", "last_name" "text", "email" "text", "avatar_url" "text", "role_name" "text", "role_id" integer, "is_active" boolean, "is_super_admin" boolean, "branch_id" integer, "branch_name" "text", "job_position_id" "uuid", "job_position_name" "text")
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    om.id, 
    p.created_at, 
    p.first_name::text, 
    p.last_name::text, 
    p.email::text, 
    p.avatar_url::text,
    r.name::text as role_name,
    om.role_id,
    om.is_active,
    om.is_super_admin,
    mb.branch_id,
    b.name::text as branch_name,
    COALESCE(e.position_id, om.job_position_id) as job_position_id,
    jp.name::text as job_position_name
  FROM profiles p
  JOIN organization_members om ON p.id = om.user_id
  LEFT JOIN roles r ON r.id = om.role_id
  LEFT JOIN member_branches mb ON mb.organization_member_id = om.id
  LEFT JOIN branches b ON b.id = mb.branch_id
  LEFT JOIN employments e ON e.organization_member_id = om.id AND e.status = 'active'
  LEFT JOIN job_positions jp ON jp.id = COALESCE(e.position_id, om.job_position_id)
  WHERE om.organization_id = org_id;
END;
$$;


ALTER FUNCTION "public"."get_profiles_by_organization"("org_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_rate_for_date"("p_organization_id" integer, "p_space_type_id" "uuid", "p_date" "date", "p_plan" "text" DEFAULT NULL::"text") RETURNS TABLE("rate_id" "uuid", "price" numeric, "restrictions" "jsonb", "is_from_rates" boolean, "priority" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    r.id as rate_id,
    r.price,
    r.restrictions,
    true as is_from_rates,
    r.priority
  FROM rates r
  WHERE r.organization_id = p_organization_id
    AND r.space_type_id = p_space_type_id
    AND r.is_active = true
    AND p_date BETWEEN r.date_from AND r.date_to
    AND (p_plan IS NULL OR r.restrictions->>'plan' = p_plan OR r.restrictions->>'plan' IS NULL)
  ORDER BY 
    r.priority DESC,
    CASE WHEN r.restrictions->>'plan' = p_plan THEN 0 ELSE 1 END,
    r.created_at DESC
  LIMIT 1;
  
  IF NOT FOUND THEN
    RETURN QUERY
    SELECT 
      NULL::uuid as rate_id,
      st.base_rate as price,
      NULL::jsonb as restrictions,
      false as is_from_rates,
      0 as priority
    FROM space_types st
    WHERE st.id = p_space_type_id
      AND st.organization_id = p_organization_id;
  END IF;
END;
$$;


ALTER FUNCTION "public"."get_rate_for_date"("p_organization_id" integer, "p_space_type_id" "uuid", "p_date" "date", "p_plan" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_recommended_payment_methods"("country_code" "text") RETURNS TABLE("code" "text", "name" "text", "requires_reference" boolean, "is_active" boolean, "is_system" boolean, "display_order" integer, "settings" "jsonb")
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        pm.code,
        pm.name,
        pm.requires_reference,
        pm.is_active,
        pm.is_system,
        cpm.display_order,
        cpm.default_settings as settings
    FROM country_payment_methods cpm
    JOIN payment_methods pm ON cpm.payment_method_code = pm.code
    WHERE cpm.country_code = get_recommended_payment_methods.country_code
    AND cpm.is_active = true
    AND cpm.is_recommended = true
    ORDER BY cpm.display_order;
END;
$$;


ALTER FUNCTION "public"."get_recommended_payment_methods"("country_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_recommended_payment_methods"("country_code_param" character varying) RETURNS TABLE("code" "text", "name" "text", "requires_reference" boolean, "default_settings" "jsonb", "display_order" integer)
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    pm.code,
    pm.name,
    pm.requires_reference,
    cpmd.default_settings,
    cpmd.display_order
  FROM country_payment_method_defaults cpmd
  JOIN payment_methods pm ON pm.code = cpmd.payment_method_code
  WHERE cpmd.country_code = country_code_param
    AND cpmd.is_recommended = true
    AND pm.is_active = true
  ORDER BY cpmd.display_order;
END;
$$;


ALTER FUNCTION "public"."get_recommended_payment_methods"("country_code_param" character varying) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_reservations_by_day"("p_organization_id" integer, "p_timezone" "text", "p_start" timestamp with time zone, "p_end" timestamp with time zone, "p_branch_id" integer DEFAULT NULL::integer) RETURNS TABLE("fecha" "date", "total" bigint)
    LANGUAGE "sql" STABLE
    AS $$
  SELECT (created_at AT TIME ZONE p_timezone)::date AS fecha,
         COUNT(*)::bigint AS total
  FROM public.reservations
  WHERE organization_id = p_organization_id
    AND created_at >= p_start AND created_at < p_end
    AND (p_branch_id IS NULL OR branch_id = p_branch_id)
  GROUP BY 1 ORDER BY 1;
$$;


ALTER FUNCTION "public"."get_reservations_by_day"("p_organization_id" integer, "p_timezone" "text", "p_start" timestamp with time zone, "p_end" timestamp with time zone, "p_branch_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_restaurant_availability"("p_organization_id" integer, "p_date" "date", "p_party_size" integer DEFAULT 2, "p_zone" "text" DEFAULT NULL::"text", "p_slot_interval" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_settings        record;
  v_turn_duration   integer := 90;
  v_buffer          integer := 15;
  v_slot_interval   integer := 30;
  v_service_hours   jsonb;
  v_weekday         text;
  v_shifts          jsonb;
  v_shift           jsonb;
  v_from_min        integer;
  v_to_min          integer;
  v_slot_min        integer;
  v_slots           jsonb := '[]'::jsonb;
  v_free_count      integer;
  v_suggested       jsonb := '[]'::jsonb;
  v_now             timestamptz := now();
  v_now_min         integer;
  v_is_today        boolean;
  v_min_advance     integer := 60;
BEGIN
  SELECT * INTO v_settings
  FROM public.restaurant_booking_settings
  WHERE organization_id = p_organization_id
    AND is_enabled = true
  ORDER BY branch_id NULLS LAST
  LIMIT 1;

  IF v_settings IS NOT NULL THEN
    v_turn_duration := COALESCE(v_settings.turn_duration_minutes, 90);
    v_buffer := COALESCE(v_settings.buffer_minutes, 15);
    v_slot_interval := COALESCE(p_slot_interval, v_settings.slot_interval_minutes, 30);
    v_min_advance := COALESCE(v_settings.min_advance_minutes, 60);
    v_service_hours := v_settings.service_hours;
  END IF;

  v_weekday := lower(to_char(p_date, 'Dy'));
  v_is_today := (p_date = current_date);
  v_now_min := EXTRACT(hour FROM v_now) * 60 + EXTRACT(minute FROM v_now);

  IF v_service_hours IS NOT NULL AND v_service_hours != '{}'::jsonb AND v_service_hours ? v_weekday THEN
    v_shifts := v_service_hours->v_weekday;
  ELSE
    v_shifts := '[{"from":"12:00","to":"15:00"},{"from":"18:00","to":"22:30"}]'::jsonb;
  END IF;

  FOR v_shift IN SELECT * FROM jsonb_array_elements(v_shifts)
  LOOP
    v_from_min := (substring(v_shift->>'from' from 1 for 2))::integer * 60
                + (substring(v_shift->>'from' from 4 for 2))::integer;
    v_to_min := (substring(v_shift->>'to' from 1 for 2))::integer * 60
              + (substring(v_shift->>'to' from 4 for 2))::integer;

    v_slot_min := v_from_min;
    WHILE v_slot_min + v_turn_duration <= v_to_min LOOP
      IF NOT (v_is_today AND v_slot_min <= v_now_min + v_min_advance) THEN
        SELECT count(*) INTO v_free_count
        FROM public.restaurant_tables t
        WHERE t.organization_id = p_organization_id
          AND COALESCE(t.capacity, 4) >= p_party_size
          AND (p_zone IS NULL OR t.zone = p_zone)
          AND NOT EXISTS (
            SELECT 1
            FROM public.restaurant_reservations r
            WHERE r.restaurant_table_id = t.id
              AND r.reservation_date = p_date
              AND r.status IN ('pending', 'confirmed', 'seated')
              AND (
                (EXTRACT(hour FROM r.reservation_time) * 60 + EXTRACT(minute FROM r.reservation_time))
                  < v_slot_min + v_turn_duration + v_buffer
                AND
                (EXTRACT(hour FROM r.reservation_time) * 60 + EXTRACT(minute FROM r.reservation_time)
                  + COALESCE(r.duration_minutes, v_turn_duration) + v_buffer)
                  > v_slot_min
              )
          );

        v_slots := v_slots || jsonb_build_array(jsonb_build_object(
          'time', lpad((v_slot_min / 60)::text, 2, '0') || ':' || lpad((v_slot_min % 60)::text, 2, '0'),
          'available', v_free_count > 0,
          'remaining', v_free_count
        ));

        IF v_free_count > 0 AND jsonb_array_length(v_suggested) < 5 THEN
          v_suggested := v_suggested || jsonb_build_array(
            lpad((v_slot_min / 60)::text, 2, '0') || ':' || lpad((v_slot_min % 60)::text, 2, '0')
          );
        END IF;
      END IF;

      v_slot_min := v_slot_min + v_slot_interval;
    END LOOP;
  END LOOP;

  RETURN jsonb_build_object(
    'date', p_date,
    'partySize', p_party_size,
    'slots', v_slots,
    'suggestedTimes', v_suggested,
    'available', EXISTS(SELECT 1 FROM jsonb_array_elements(v_slots) WHERE (value->>'available')::boolean)
  );
END;
$$;


ALTER FUNCTION "public"."get_restaurant_availability"("p_organization_id" integer, "p_date" "date", "p_party_size" integer, "p_zone" "text", "p_slot_interval" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_restaurant_availability"("p_organization_id" integer, "p_date" "date", "p_party_size" integer, "p_zone" "text", "p_slot_interval" integer) IS 'FASE 8: Consulta slots disponibles para una fecha.';



CREATE OR REPLACE FUNCTION "public"."get_sales_by_day"("p_organization_id" integer, "p_timezone" "text", "p_start" timestamp with time zone, "p_end" timestamp with time zone, "p_branch_id" integer DEFAULT NULL::integer) RETURNS TABLE("fecha" "date", "total" numeric)
    LANGUAGE "sql" STABLE
    AS $$
  SELECT (sale_date AT TIME ZONE p_timezone)::date AS fecha,
         COALESCE(SUM(total), 0)::numeric AS total
  FROM public.sales
  WHERE organization_id = p_organization_id
    AND sale_date >= p_start AND sale_date < p_end
    AND status IN ('paid','completed')
    AND (p_branch_id IS NULL OR branch_id = p_branch_id)
  GROUP BY 1 ORDER BY 1;
$$;


ALTER FUNCTION "public"."get_sales_by_day"("p_organization_id" integer, "p_timezone" "text", "p_start" timestamp with time zone, "p_end" timestamp with time zone, "p_branch_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_sales_by_hour"("p_organization_id" integer, "p_timezone" "text", "p_start" timestamp with time zone, "p_end" timestamp with time zone, "p_branch_id" integer DEFAULT NULL::integer) RETURNS TABLE("hora" integer, "total" numeric)
    LANGUAGE "sql" STABLE
    AS $$
  WITH agg AS (
    SELECT EXTRACT(HOUR FROM sale_date AT TIME ZONE p_timezone)::int AS hora,
           COALESCE(SUM(total), 0)::numeric AS total
    FROM public.sales
    WHERE organization_id = p_organization_id
      AND sale_date >= p_start AND sale_date < p_end
      AND status IN ('paid','completed')
      AND (p_branch_id IS NULL OR branch_id = p_branch_id)
    GROUP BY 1
  )
  SELECT h.hora::int, COALESCE(a.total, 0)::numeric AS total
  FROM generate_series(0, 23) AS h(hora)
  LEFT JOIN agg a ON a.hora = h.hora
  ORDER BY h.hora;
$$;


ALTER FUNCTION "public"."get_sales_by_hour"("p_organization_id" integer, "p_timezone" "text", "p_start" timestamp with time zone, "p_end" timestamp with time zone, "p_branch_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_section_default_content"("p_section_type" "text", "p_section_variant" "text", "p_type_id" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE SECURITY DEFINER
    AS $$
BEGIN
  RETURN CASE p_section_type

  -- ======================== HERO ========================
  WHEN 'hero' THEN
    CASE p_type_id
      WHEN 1 THEN -- restaurant
        CASE p_section_variant
          WHEN 'fullscreen' THEN '{"title":"Sabor Auténtico en Cada Plato","subtitle":"Descubre nuestra cocina con ingredientes frescos y recetas tradicionales","cta_text":"Ver Menú","cta_url":"/menu"}'::jsonb
          WHEN 'split' THEN '{"title":"Una Experiencia Gastronómica Única","subtitle":"Ingredientes frescos, sabor inigualable","cta_text":"Reservar Mesa","cta_url":"/reservas"}'::jsonb
          WHEN 'minimal' THEN '{"title":"Nuestra Carta","subtitle":"Explora todos nuestros platos"}'::jsonb
          ELSE '{"title":"Bienvenido a Nuestro Restaurante","subtitle":"Una experiencia culinaria inolvidable"}'::jsonb
        END
      WHEN 2 THEN -- hotel
        CASE p_section_variant
          WHEN 'fullscreen' THEN '{"title":"Tu Destino de Descanso Perfecto","subtitle":"Vive una experiencia única de confort y lujo","cta_text":"Reservar Ahora","cta_url":"/reservas"}'::jsonb
          WHEN 'split' THEN '{"title":"Donde el Lujo y la Comodidad se Encuentran","subtitle":"Habitaciones diseñadas para tu máximo confort","cta_text":"Reservar","cta_url":"/reservas"}'::jsonb
          WHEN 'minimal' THEN '{"title":"Nuestras Habitaciones","subtitle":"Confort y elegancia en cada detalle"}'::jsonb
          ELSE '{"title":"Bienvenido a Nuestro Hotel","subtitle":"Tu hogar lejos de casa"}'::jsonb
        END
      WHEN 3 THEN -- retail
        CASE p_section_variant
          WHEN 'slider' THEN '{"title":"Descubre Nuestra Colección","subtitle":"Los mejores productos con la mejor calidad","cta_text":"Comprar Ahora","cta_url":"/productos","slides":[{"title":"Nueva Colección","subtitle":"Descubre las últimas tendencias","cta_text":"Ver Productos","cta_url":"/productos"},{"title":"Ofertas Especiales","subtitle":"Aprovecha nuestros descuentos en productos seleccionados","cta_text":"Ver Ofertas","cta_url":"/ofertas"}]}'::jsonb
          WHEN 'fullscreen' THEN '{"title":"Tu Tienda de Confianza","subtitle":"Productos de calidad al mejor precio","cta_text":"Comprar","cta_url":"/productos"}'::jsonb
          WHEN 'minimal' THEN '{"title":"Productos","subtitle":"Explora nuestro catálogo completo"}'::jsonb
          ELSE '{"title":"Bienvenido a Nuestra Tienda","subtitle":"Descubre nuestros productos"}'::jsonb
        END
      WHEN 4 THEN -- services
        CASE p_section_variant
          WHEN 'split' THEN '{"title":"Soluciones Profesionales a Tu Medida","subtitle":"Expertos comprometidos con tu éxito","cta_text":"Solicitar Cotización","cta_url":"/cotizar"}'::jsonb
          WHEN 'fullscreen' THEN '{"title":"Impulsamos Tu Negocio","subtitle":"Servicios profesionales de alta calidad","cta_text":"Comenzar","cta_url":"/cotizar"}'::jsonb
          WHEN 'minimal' THEN '{"title":"Nuestros Servicios","subtitle":"Conoce lo que podemos hacer por ti"}'::jsonb
          ELSE '{"title":"Bienvenido","subtitle":"Soluciones que transforman"}'::jsonb
        END
      WHEN 5 THEN -- gym
        CASE p_section_variant
          WHEN 'video' THEN '{"title":"Transforma Tu Cuerpo y Tu Vida","subtitle":"El mejor gimnasio con equipos de última generación","cta_text":"Únete Ahora","cta_url":"/membresias"}'::jsonb
          WHEN 'fullscreen' THEN '{"title":"Supera Tus Límites","subtitle":"Entrena con los mejores profesionales","cta_text":"Comenzar","cta_url":"/membresias"}'::jsonb
          WHEN 'minimal' THEN '{"title":"Nuestras Clases","subtitle":"Entrena con los mejores"}'::jsonb
          ELSE '{"title":"Bienvenido al Gym","subtitle":"Tu mejor versión comienza aquí"}'::jsonb
        END
      WHEN 6 THEN -- transport
        CASE p_section_variant
          WHEN 'split' THEN '{"title":"Viaja Seguro y Cómodo","subtitle":"Rutas a los mejores destinos con la mejor flota","cta_text":"Buscar Viajes","cta_url":"/viajes"}'::jsonb
          WHEN 'fullscreen' THEN '{"title":"Conectamos Destinos","subtitle":"Viaja con comodidad y seguridad","cta_text":"Ver Rutas","cta_url":"/rutas"}'::jsonb
          WHEN 'minimal' THEN '{"title":"Nuestros Servicios","subtitle":"Soluciones de transporte confiables"}'::jsonb
          ELSE '{"title":"Bienvenido","subtitle":"Tu viaje comienza aquí"}'::jsonb
        END
      WHEN 7 THEN -- parking
        CASE p_section_variant
          WHEN 'split' THEN '{"title":"Estacionamiento Seguro las 24 Horas","subtitle":"La mejor opción para tu vehículo en el centro de la ciudad","cta_text":"Ver Tarifas","cta_url":"/tarifas"}'::jsonb
          WHEN 'fullscreen' THEN '{"title":"Tu Vehículo en Buenas Manos","subtitle":"Seguridad, comodidad y accesibilidad","cta_text":"Reservar","cta_url":"/reservas"}'::jsonb
          WHEN 'minimal' THEN '{"title":"Nuestras Zonas","subtitle":"Amplias opciones de estacionamiento"}'::jsonb
          ELSE '{"title":"Bienvenido","subtitle":"Estacionamiento seguro y accesible"}'::jsonb
        END
      ELSE '{"title":"Bienvenido","subtitle":"Descubre todo lo que tenemos para ti"}'::jsonb
    END

  -- ======================== TESTIMONIALS ========================
  WHEN 'testimonials' THEN
    '{"title":"Lo Que Dicen Nuestros Clientes","subtitle":"La opinión de quienes confían en nosotros","items":[{"name":"María García","role":"Cliente frecuente","text":"Excelente servicio y atención. Superaron todas mis expectativas. Lo recomiendo totalmente.","rating":5},{"name":"Carlos López","role":"Cliente","text":"Muy profesionales y atentos en todo momento. Sin duda volveré.","rating":5},{"name":"Ana Martínez","role":"Cliente","text":"Una experiencia increíble de principio a fin. El mejor servicio que he recibido.","rating":5}]}'::jsonb

  -- ======================== STATS ========================
  WHEN 'stats' THEN
    '{"items":[{"value":"500+","label":"Clientes Satisfechos"},{"value":"10+","label":"Años de Experiencia"},{"value":"50+","label":"Profesionales"},{"value":"99%","label":"Satisfacción"}]}'::jsonb

  -- ======================== FAQ ========================
  WHEN 'faq' THEN
    '{"title":"Preguntas Frecuentes","items":[{"question":"¿Cuáles son los horarios de atención?","answer":"Estamos disponibles de lunes a sábado de 8:00 AM a 6:00 PM. Los domingos y festivos tenemos horario especial."},{"question":"¿Cuáles son los métodos de pago aceptados?","answer":"Aceptamos efectivo, tarjetas de crédito y débito, y transferencias bancarias."},{"question":"¿Cómo puedo contactarlos?","answer":"Puede contactarnos a través de nuestro formulario de contacto, por teléfono o visitándonos en nuestra sede."},{"question":"¿Ofrecen servicio a domicilio?","answer":"Sí, contamos con servicio a domicilio en toda la ciudad. Consulta las condiciones."}]}'::jsonb

  -- ======================== NEWSLETTER ========================
  WHEN 'newsletter' THEN
    '{"title":"Suscríbete a Nuestro Boletín","subtitle":"Recibe las últimas novedades y ofertas exclusivas directamente en tu correo","cta_text":"Suscribirse"}'::jsonb

  -- ======================== CTA ========================
  WHEN 'cta' THEN
    '{"title":"¿Listo para Comenzar?","subtitle":"Contáctanos hoy y descubre todo lo que tenemos para ofrecerte","cta_text":"Contáctanos","cta_url":"/contacto"}'::jsonb

  -- ======================== TEXT_BLOCK ========================
  WHEN 'text_block' THEN
    '{"title":"Sobre Nosotros","content":"Somos una empresa comprometida con la excelencia y la satisfacción de nuestros clientes. Con años de experiencia en el sector, ofrecemos soluciones de calidad que se adaptan a las necesidades de cada persona. Nuestro equipo de profesionales trabaja día a día para superar tus expectativas."}'::jsonb

  -- ======================== TEAM ========================
  WHEN 'team' THEN
    '{"title":"Nuestro Equipo","subtitle":"Profesionales comprometidos con tu satisfacción"}'::jsonb

  -- ======================== CONTACT_FORM ========================
  WHEN 'contact_form' THEN
    '{"title":"Contáctanos","subtitle":"Estamos aquí para ayudarte. Envíanos un mensaje y te responderemos lo antes posible."}'::jsonb

  -- ======================== MAP ========================
  WHEN 'map' THEN
    '{"title":"Encuéntranos","subtitle":"Visítanos en nuestra sede"}'::jsonb

  -- ======================== GALLERY ========================
  WHEN 'gallery' THEN
    '{"title":"Galería","subtitle":"Conoce nuestras instalaciones y espacios"}'::jsonb

  -- ======================== BRANDS / PARTNERS ========================
  WHEN 'brands' THEN '{"title":"Marcas que Confían en Nosotros"}'::jsonb
  WHEN 'partners' THEN '{"title":"Nuestros Aliados Estratégicos"}'::jsonb

  -- ======================== IMAGE_TEXT ========================
  WHEN 'image_text' THEN
    '{"title":"Nuestra Historia","content":"Desde nuestros inicios, hemos trabajado con pasión y dedicación para ofrecer el mejor servicio. Cada día nos esforzamos por innovar y mejorar la experiencia de nuestros clientes.","cta_text":"Conocer Más","cta_url":"/nosotros"}'::jsonb

  -- ======================== WHY_CHOOSE_US ========================
  WHEN 'why_choose_us' THEN
    '{"title":"¿Por Qué Elegirnos?","items":[{"title":"Experiencia","description":"Años de trayectoria nos respaldan"},{"title":"Calidad","description":"Los más altos estándares en cada servicio"},{"title":"Atención Personalizada","description":"Servicio dedicado a tus necesidades"},{"title":"Mejor Precio","description":"Tarifas competitivas y transparentes"}]}'::jsonb

  -- ======================== RESTAURANT-SPECIFIC ========================
  WHEN 'specialties' THEN '{"title":"Nuestras Especialidades","subtitle":"Lo mejor de nuestra cocina, preparado con los ingredientes más frescos"}'::jsonb
