  -- ======================== GYM-SPECIFIC ========================
  WHEN 'membership_plans' THEN '{"title":"Planes de Membresía","subtitle":"Elige el plan ideal para alcanzar tus metas"}'::jsonb
  WHEN 'gym_features' THEN '{"title":"Nuestras Instalaciones","items":[{"title":"Equipos Modernos","description":"Tecnología fitness de última generación"},{"title":"Zona de Peso Libre","description":"Espacio amplio y completamente equipado"},{"title":"Zona Cardio","description":"Las mejores máquinas para tu entrenamiento"},{"title":"Área de Stretching","description":"Espacio dedicado a flexibilidad y recuperación"}]}'::jsonb
