  -- ======================== TRANSPORT-SPECIFIC ========================
  WHEN 'trip_search' THEN '{"title":"Busca Tu Viaje","subtitle":"Encuentra las mejores rutas y horarios disponibles"}'::jsonb
  WHEN 'routes' THEN '{"title":"Nuestras Rutas","subtitle":"Conectamos los principales destinos del país"}'::jsonb
  WHEN 'fleet_showcase' THEN '{"title":"Nuestra Flota","subtitle":"Vehículos modernos, seguros y cómodos"}'::jsonb
  WHEN 'coverage_map' THEN '{"title":"Cobertura Nacional","subtitle":"Conoce todos nuestros destinos y rutas"}'::jsonb

  -- ======================== PARKING-SPECIFIC ========================
  WHEN 'parking_zones' THEN '{"title":"Zonas de Estacionamiento","subtitle":"Amplias opciones para tu vehículo"}'::jsonb
  WHEN 'parking_pricing' THEN '{"title":"Tarifas","subtitle":"Precios competitivos y transparentes"}'::jsonb
  WHEN 'parking_features' THEN '{"title":"¿Por Qué Elegirnos?","items":[{"title":"Seguridad 24/7","description":"Vigilancia permanente con cámaras y personal"},{"title":"Acceso Rápido","description":"Entrada y salida ágil sin filas"},{"title":"Ubicación Céntrica","description":"En el corazón de la ciudad"}]}'::jsonb
  WHEN 'parking_availability' THEN '{"title":"Disponibilidad en Tiempo Real","subtitle":"Consulta los espacios disponibles ahora"}'::jsonb
  WHEN 'parking_pass_plans' THEN '{"title":"Pases Mensuales","subtitle":"Ahorra con nuestros planes de estacionamiento"}'::jsonb

  -- ======================== DEFAULT ========================
  ELSE '{}'::jsonb
  END;
END;
$$;


