CREATE OR REPLACE FUNCTION "public"."get_tax_templates_by_organization_country"("org_id" integer) RETURNS TABLE("id" integer, "country" character varying, "code" "text", "name" character varying, "rate" numeric, "description" "text", "valid_from" timestamp with time zone, "valid_to" timestamp with time zone, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE 
  org_country_code varchar(3);
BEGIN
  -- Obtener el código de país de la organización
  SELECT country_code INTO org_country_code
  FROM organizations 
  WHERE organizations.id = org_id
  LIMIT 1;
  
  -- Si no se encuentra la organización o no tiene país, devolver vacío
  IF org_country_code IS NULL THEN
    RETURN;
  END IF;
  
  -- Retornar plantillas del país de la organización
  RETURN QUERY
  SELECT 
    tt.id,
    tt.country,
    tt.code,
    tt.name,
    tt.rate,
    tt.description,
    tt.valid_from,
    tt.valid_to,
    tt.created_at,
    tt.updated_at
  FROM 
    tax_templates tt
  WHERE 
    tt.country = org_country_code
  ORDER BY 
    tt.name;
END;
$$;


ALTER FUNCTION "public"."get_tax_templates_by_organization_country"("org_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_unread_notifications_count"("p_organization_id" integer, "p_scope" "text" DEFAULT 'all'::"text", "p_exclude_task_types" boolean DEFAULT false) RETURNS integer
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_count integer;
  v_uid   uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RETURN 0;
  END IF;

  IF p_scope NOT IN ('mine', 'all') THEN
    RAISE EXCEPTION 'p_scope debe ser ''mine'' o ''all''';
  END IF;

  SELECT count(*) INTO v_count
  FROM notifications n
  WHERE n.organization_id = p_organization_id
    AND n.status <> 'deleted'
    -- p_scope='mine' restringe a las dirigidas al usuario.
    -- p_scope='all' deja que la RLS de notifications decida
    -- (propias + admin ve todas las de la org).
    AND (
      p_scope = 'all'
      OR n.recipient_user_id = v_uid
    )
    -- No leída por este usuario
    AND NOT EXISTS (
      SELECT 1 FROM notification_reads nr
      WHERE nr.notification_id = n.id
        AND nr.user_id = v_uid
    )
    -- Filtro PM: excluir tipos de tarea si el módulo está inactivo.
    -- COALESCE para que NULL no excluya la fila.
    AND (
      NOT p_exclude_task_types
      OR COALESCE(n.payload->>'type', '') NOT IN (
        'task_assigned','task_completed','task_agent',
        'task_rescheduled','task_reschedule_summary'
      )
    );

  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."get_unread_notifications_count"("p_organization_id" integer, "p_scope" "text", "p_exclude_task_types" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_user_notification_preferences"("p_user_id" "uuid", "p_channel" "text") RETURNS "json"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  prefs json;
BEGIN
  SELECT json_build_object(
    'user_id', unp.user_id,
    'channel', unp.channel,
    'mute', unp.mute,
    'allowed_types', unp.allowed_types,
    'dnd_start', unp.dnd_start,
    'dnd_end', unp.dnd_end,
    'created_at', unp.created_at,
    'updated_at', unp.updated_at
  ) INTO prefs
  FROM public.user_notification_preferences unp
  WHERE unp.user_id = p_user_id AND unp.channel = p_channel;
  
  -- Si no encontramos preferencias, devolvemos valores por defecto
  IF prefs IS NULL THEN
    RETURN json_build_object(
      'user_id', p_user_id,
      'channel', p_channel,
      'mute', false,
      'allowed_types', ARRAY['all']::text[],
      'created_at', now(),
      'updated_at', now()
    );
  END IF;
  
  RETURN prefs;
END;
$$;


