CREATE OR REPLACE FUNCTION "public"."get_user_permission_codes"("p_user_id" "uuid", "p_organization_id" integer) RETURNS "text"[]
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_role_id INTEGER;
  v_job_position_id UUID;
  v_is_super_admin BOOLEAN;
  v_permissions TEXT[];
BEGIN
  -- Obtener datos del miembro
  SELECT om.role_id, om.job_position_id, om.is_super_admin
  INTO v_role_id, v_job_position_id, v_is_super_admin
  FROM organization_members om
  WHERE om.user_id = p_user_id
    AND om.organization_id = p_organization_id
    AND om.is_active = true
  LIMIT 1;

  -- Super admin tiene todos los permisos
  IF v_is_super_admin = true THEN
    SELECT ARRAY_AGG(p.code)
    INTO v_permissions
    FROM permissions p;
    RETURN v_permissions;
  END IF;

  -- Combinar ROL + CARGO con precedencia
  WITH role_perms AS (
    SELECT p.id, p.code, rp.allowed
    FROM role_permissions rp
    JOIN permissions p ON p.id = rp.permission_id
    WHERE rp.role_id = v_role_id
  ),
  job_perms AS (
    SELECT p.id, p.code, jpp.allowed
    FROM job_position_permissions jpp
    JOIN permissions p ON p.id = jpp.permission_id
    WHERE jpp.job_position_id = v_job_position_id
      AND v_job_position_id IS NOT NULL
  ),
  combined AS (
    SELECT DISTINCT
      COALESCE(jp.id, rp.id) AS permission_id,
      COALESCE(jp.code, rp.code) AS code,
      CASE 
        WHEN jp.id IS NOT NULL THEN jp.allowed  -- Cargo tiene precedencia
        ELSE rp.allowed
      END AS final_allowed
    FROM role_perms rp
    FULL OUTER JOIN job_perms jp ON jp.id = rp.id
  )
  SELECT ARRAY_AGG(c.code)
  INTO v_permissions
  FROM combined c
  WHERE c.final_allowed = true;

  RETURN COALESCE(v_permissions, ARRAY[]::TEXT[]);
END;
$$;


ALTER FUNCTION "public"."get_user_permission_codes"("p_user_id" "uuid", "p_organization_id" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_user_permission_codes"("p_user_id" "uuid", "p_organization_id" integer) IS 'Retorna un array con los códigos de permisos del usuario.
Usa la lógica de precedencia: Cargo > Rol';



CREATE OR REPLACE FUNCTION "public"."get_user_permissions"("p_user_id" "uuid", "p_organization_id" integer) RETURNS TABLE("permission_code" "text", "permission_name" "text", "permission_description" "text", "module" "text", "category" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  -- Opción 2: ROL + CARGO (Unión)
  -- El usuario obtiene permisos del rol Y del cargo
  RETURN QUERY
  SELECT DISTINCT
    p.code::TEXT,
    p.name::TEXT,
    p.description::TEXT,
    p.module::TEXT,
    p.category::TEXT
  FROM (
    -- Permisos del ROL principal
    SELECT 
      perm.id,
      perm.code,
      perm.name,
      perm.description,
      perm.module,
      perm.category
    FROM organization_members om
    JOIN role_permissions rp ON rp.role_id = om.role_id
    JOIN permissions perm ON perm.id = rp.permission_id
    WHERE om.user_id = p_user_id
      AND om.organization_id = p_organization_id
      AND om.is_active = true
      AND rp.allowed = true
    
    UNION
    
    -- Permisos del CARGO (si tiene cargo asignado)
    SELECT 
      perm.id,
      perm.code,
      perm.name,
      perm.description,
      perm.module,
      perm.category
    FROM organization_members om
    JOIN job_position_permissions jpp ON jpp.job_position_id = om.job_position_id
    JOIN permissions perm ON perm.id = jpp.permission_id
    WHERE om.user_id = p_user_id
      AND om.organization_id = p_organization_id
      AND om.is_active = true
      AND om.job_position_id IS NOT NULL
      AND jpp.allowed = true
  ) AS p
  ORDER BY p.module, p.category, p.code;
END;
$$;


ALTER FUNCTION "public"."get_user_permissions"("p_user_id" "uuid", "p_organization_id" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_user_permissions"("p_user_id" "uuid", "p_organization_id" integer) IS 'Obtiene permisos del usuario: ROL (base) + CARGO (específicos). Si no tiene cargo, solo obtiene permisos del rol.';



CREATE OR REPLACE FUNCTION "public"."get_user_permissions_with_precedence"("p_user_id" "uuid", "p_organization_id" integer) RETURNS TABLE("permission_code" "text", "permission_name" "text", "permission_description" "text", "permission_module" "text", "permission_category" "text", "source" "text", "is_granted" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_role_id INTEGER;
  v_job_position_id UUID;
  v_is_super_admin BOOLEAN;
BEGIN
  -- Obtener datos del miembro
  SELECT om.role_id, om.job_position_id, om.is_super_admin
  INTO v_role_id, v_job_position_id, v_is_super_admin
  FROM organization_members om
  WHERE om.user_id = p_user_id
    AND om.organization_id = p_organization_id
    AND om.is_active = true
  LIMIT 1;

  -- Si es super admin, devolver TODOS los permisos
  IF v_is_super_admin = true THEN
    RETURN QUERY
    SELECT 
      p.code::TEXT,
      p.name::TEXT,
      p.description::TEXT,
      p.module::TEXT,
      p.category::TEXT,
      'super_admin'::TEXT,
      true
    FROM permissions p
    ORDER BY p.module, p.category, p.code;
    RETURN;
  END IF;

  -- Lógica de precedencia:
  -- 1. Si el cargo tiene el permiso definido (allowed=true o false), usa ese valor
  -- 2. Si el cargo NO tiene el permiso definido, usa el valor del rol
  RETURN QUERY
  WITH role_perms AS (
    -- Permisos del ROL
    SELECT 
      perm.id AS permission_id,
      perm.code,
      perm.name,
      perm.description,
      perm.module,
      perm.category,
      rp.allowed
    FROM role_permissions rp
    JOIN permissions perm ON perm.id = rp.permission_id
    WHERE rp.role_id = v_role_id
  ),
  job_perms AS (
    -- Permisos del CARGO (solo si tiene cargo asignado)
    SELECT 
      perm.id AS permission_id,
      perm.code,
      perm.name,
      perm.description,
      perm.module,
      perm.category,
      jpp.allowed
    FROM job_position_permissions jpp
    JOIN permissions perm ON perm.id = jpp.permission_id
    WHERE jpp.job_position_id = v_job_position_id
      AND v_job_position_id IS NOT NULL
  ),
  combined AS (
    -- Combinar con precedencia del cargo
    SELECT DISTINCT
      COALESCE(jp.permission_id, rp.permission_id) AS permission_id,
      COALESCE(jp.code, rp.code) AS code,
      COALESCE(jp.name, rp.name) AS name,
      COALESCE(jp.description, rp.description) AS description,
      COALESCE(jp.module, rp.module) AS module,
      COALESCE(jp.category, rp.category) AS category,
      CASE 
        -- Si está en cargo, el cargo tiene precedencia
        WHEN jp.permission_id IS NOT NULL THEN jp.allowed
        -- Si solo está en rol, usar rol
        ELSE rp.allowed
      END AS final_allowed,
      CASE
        WHEN jp.permission_id IS NOT NULL AND rp.permission_id IS NOT NULL THEN 'both'
        WHEN jp.permission_id IS NOT NULL THEN 'job_position'
        ELSE 'role'
      END AS source
    FROM role_perms rp
    FULL OUTER JOIN job_perms jp ON jp.permission_id = rp.permission_id
  )
  SELECT 
    c.code::TEXT,
    c.name::TEXT,
    c.description::TEXT,
    c.module::TEXT,
    c.category::TEXT,
    c.source::TEXT,
    c.final_allowed
  FROM combined c
  WHERE c.final_allowed = true  -- Solo devolver permisos concedidos
  ORDER BY c.module, c.category, c.code;
END;
$$;


ALTER FUNCTION "public"."get_user_permissions_with_precedence"("p_user_id" "uuid", "p_organization_id" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_user_permissions_with_precedence"("p_user_id" "uuid", "p_organization_id" integer) IS 'Obtiene permisos combinados de ROL + CARGO con precedencia del cargo.
Si un permiso está definido en el cargo (allowed=true/false), ese valor prevalece.
Si no está en el cargo, se usa el valor del rol.
Ejemplo: Si rol permite "inventory.edit" pero cargo lo deniega → DENEGADO
         Si rol deniega "hrm.view" pero cargo lo permite → PERMITIDO';



CREATE OR REPLACE FUNCTION "public"."get_web_conversion_stats"("p_organization_id" integer, "p_date_from" "text", "p_date_to" "text") RETURNS TABLE("total_orders" bigint, "confirmed_orders" bigint, "cancelled_orders" bigint, "pending_orders" bigint, "total_revenue" numeric, "conversion_rate" numeric)
    LANGUAGE "sql" SECURITY DEFINER
    AS $$
  SELECT
    COUNT(*) AS total_orders,
    COUNT(*) FILTER (WHERE payment_status = 'paid' OR status = 'delivered') AS confirmed_orders,
    COUNT(*) FILTER (WHERE status IN ('cancelled', 'rejected')) AS cancelled_orders,
    COUNT(*) FILTER (
      WHERE NOT (payment_status = 'paid' OR status = 'delivered')
        AND status NOT IN ('cancelled', 'rejected')
    ) AS pending_orders,
    COALESCE(SUM(total) FILTER (WHERE payment_status = 'paid' OR status = 'delivered'), 0) AS total_revenue,
    CASE
      WHEN COUNT(*) > 0
      THEN ROUND((COUNT(*) FILTER (WHERE payment_status = 'paid' OR status = 'delivered')::numeric / COUNT(*)::numeric) * 100, 1)
      ELSE 0
    END AS conversion_rate
  FROM web_orders
  WHERE organization_id = p_organization_id
    AND created_at >= (p_date_from::date)::timestamp AT TIME ZONE 'America/Bogota'
    AND created_at < ((p_date_to::date) + 1)::timestamp AT TIME ZONE 'America/Bogota';
$$;


ALTER FUNCTION "public"."get_web_conversion_stats"("p_organization_id" integer, "p_date_from" "text", "p_date_to" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_web_orders_all_by_day"("p_organization_id" integer, "p_timezone" "text", "p_start" timestamp with time zone, "p_end" timestamp with time zone) RETURNS TABLE("fecha" "date", "pedidos" bigint, "pendientes" bigint, "pagados" bigint, "cancelados" bigint, "completados" bigint)
    LANGUAGE "sql" STABLE
    AS $$
  SELECT (created_at AT TIME ZONE p_timezone)::date AS fecha,
         COUNT(*)::bigint AS pedidos,
         COUNT(*) FILTER (WHERE status IN ('pending','confirmed','preparing','ready','in_delivery'))::bigint AS pendientes,
         COUNT(*) FILTER (WHERE payment_status = 'paid')::bigint AS pagados,
         COUNT(*) FILTER (WHERE status IN ('cancelled','rejected','expired'))::bigint AS cancelados,
         COUNT(*) FILTER (
           WHERE payment_status = 'paid'
              OR (payment_method IN ('transfer','cash','bancolombia_transfer','bancolombia_collect','pse')
                  AND status IN ('confirmed','delivered'))
         )::bigint AS completados
  FROM public.web_orders
  WHERE organization_id = p_organization_id
    AND created_at >= p_start AND created_at < p_end
  GROUP BY 1 ORDER BY 1;
$$;


ALTER FUNCTION "public"."get_web_orders_all_by_day"("p_organization_id" integer, "p_timezone" "text", "p_start" timestamp with time zone, "p_end" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_web_orders_all_by_hour"("p_organization_id" integer, "p_timezone" "text", "p_start" timestamp with time zone, "p_end" timestamp with time zone) RETURNS TABLE("hora" integer, "pedidos" bigint, "pendientes" bigint, "pagados" bigint, "cancelados" bigint, "completados" bigint)
    LANGUAGE "sql" STABLE
    AS $$
  WITH agg AS (
    SELECT EXTRACT(HOUR FROM created_at AT TIME ZONE p_timezone)::int AS hora,
           COUNT(*)::bigint AS pedidos,
           COUNT(*) FILTER (WHERE status IN ('pending','confirmed','preparing','ready','in_delivery'))::bigint AS pendientes,
           COUNT(*) FILTER (WHERE payment_status = 'paid')::bigint AS pagados,
           COUNT(*) FILTER (WHERE status IN ('cancelled','rejected','expired'))::bigint AS cancelados,
           COUNT(*) FILTER (
             WHERE payment_status = 'paid'
                OR (payment_method IN ('transfer','cash','bancolombia_transfer','bancolombia_collect','pse')
                    AND status IN ('confirmed','delivered'))
           )::bigint AS completados
    FROM public.web_orders
    WHERE organization_id = p_organization_id
      AND created_at >= p_start AND created_at < p_end
    GROUP BY 1
  )
  SELECT h.hora::int,
         COALESCE(a.pedidos, 0)::bigint AS pedidos,
         COALESCE(a.pendientes, 0)::bigint AS pendientes,
         COALESCE(a.pagados, 0)::bigint AS pagados,
         COALESCE(a.cancelados, 0)::bigint AS cancelados,
         COALESCE(a.completados, 0)::bigint AS completados
  FROM generate_series(0, 23) AS h(hora)
  LEFT JOIN agg a ON a.hora = h.hora
  ORDER BY h.hora;
$$;


ALTER FUNCTION "public"."get_web_orders_all_by_hour"("p_organization_id" integer, "p_timezone" "text", "p_start" timestamp with time zone, "p_end" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_web_orders_revenue_by_day"("p_organization_id" integer, "p_timezone" "text", "p_start" timestamp with time zone, "p_end" timestamp with time zone) RETURNS TABLE("fecha" "date", "total" numeric)
    LANGUAGE "sql" STABLE
    AS $$
  SELECT (created_at AT TIME ZONE p_timezone)::date AS fecha,
         COALESCE(SUM(total), 0)::numeric AS total
  FROM public.web_orders
  WHERE organization_id = p_organization_id
    AND created_at >= p_start AND created_at < p_end
    AND (payment_status = 'paid' OR status = 'delivered')
    AND status NOT IN ('cancelled','rejected','expired')
    AND sale_id IS NULL
  GROUP BY 1 ORDER BY 1;
$$;


ALTER FUNCTION "public"."get_web_orders_revenue_by_day"("p_organization_id" integer, "p_timezone" "text", "p_start" timestamp with time zone, "p_end" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_web_orders_revenue_by_hour"("p_organization_id" integer, "p_timezone" "text", "p_start" timestamp with time zone, "p_end" timestamp with time zone) RETURNS TABLE("hora" integer, "total" numeric)
    LANGUAGE "sql" STABLE
    AS $$
  WITH agg AS (
    SELECT EXTRACT(HOUR FROM created_at AT TIME ZONE p_timezone)::int AS hora,
           COALESCE(SUM(total), 0)::numeric AS total
    FROM public.web_orders
    WHERE organization_id = p_organization_id
      AND created_at >= p_start AND created_at < p_end
      AND (payment_status = 'paid' OR status = 'delivered')
      AND status NOT IN ('cancelled','rejected','expired')
      AND sale_id IS NULL
    GROUP BY 1
  )
  SELECT h.hora::int, COALESCE(a.total, 0)::numeric AS total
  FROM generate_series(0, 23) AS h(hora)
  LEFT JOIN agg a ON a.hora = h.hora
  ORDER BY h.hora;
$$;


ALTER FUNCTION "public"."get_web_orders_revenue_by_hour"("p_organization_id" integer, "p_timezone" "text", "p_start" timestamp with time zone, "p_end" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_web_top_products"("p_organization_id" integer, "p_date_from" "text", "p_date_to" "text", "p_limit" integer DEFAULT 10) RETURNS TABLE("product_name" "text", "total_qty" numeric, "total_revenue" numeric, "orders_count" bigint)
    LANGUAGE "sql" SECURITY DEFINER
    AS $$
  SELECT
    woi.product_name,
    SUM(woi.quantity) as total_qty,
    SUM(woi.total) as total_revenue,
    COUNT(DISTINCT woi.web_order_id) as orders_count
  FROM web_order_items woi
  JOIN web_orders wo ON wo.id = woi.web_order_id
  WHERE wo.organization_id = p_organization_id
    AND wo.status NOT IN ('cancelled', 'rejected')
    AND wo.created_at >= (p_date_from::date)::timestamp AT TIME ZONE 'America/Bogota'
    AND wo.created_at < ((p_date_to::date) + 1)::timestamp AT TIME ZONE 'America/Bogota'
  GROUP BY woi.product_name
  ORDER BY total_qty DESC
  LIMIT p_limit;
$$;


ALTER FUNCTION "public"."get_web_top_products"("p_organization_id" integer, "p_date_from" "text", "p_date_to" "text", "p_limit" integer) OWNER TO "postgres";


