ALTER FUNCTION "public"."get_website_visits_by_day"("p_organization_id" integer, "p_timezone" "text", "p_start" timestamp with time zone, "p_end" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_website_visits_by_hour"("p_organization_id" integer, "p_timezone" "text", "p_start" timestamp with time zone, "p_end" timestamp with time zone) RETURNS TABLE("hora" integer, "total" bigint)
    LANGUAGE "sql" STABLE
    AS $$
  WITH visitas AS (
    SELECT
      EXTRACT(HOUR FROM created_at AT TIME ZONE p_timezone)::integer AS hora,
      COUNT(*)::bigint AS total
    FROM public.website_visits
    WHERE organization_id = p_organization_id
      AND created_at >= p_start
      AND created_at < p_end
    GROUP BY 1
  )
  SELECT
    h.hora::integer,
    COALESCE(v.total, 0)::bigint AS total
  FROM generate_series(0, 23) AS h(hora)
  LEFT JOIN visitas v ON v.hora = h.hora
  ORDER BY h.hora;
$$;


ALTER FUNCTION "public"."get_website_visits_by_hour"("p_organization_id" integer, "p_timezone" "text", "p_start" timestamp with time zone, "p_end" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_email_confirmation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$BEGIN
  DECLARE
    signup_data_raw TEXT;
    signup_data_json JSONB;
    join_type_var TEXT;
    org_id INTEGER;
    branch_id INTEGER;
    member_id BIGINT;
    debug_log_id INTEGER;
    country_name TEXT;
    subscription_plan_code TEXT;
    plan_id_var INTEGER;
    subscription_id UUID;
    avatar_url_value TEXT;
    preferred_language_value TEXT;
    process_success BOOLEAN := FALSE;
    cleanup_attempted BOOLEAN := FALSE;
    
    -- Variables específicas para invitaciones
    is_invitation BOOLEAN := FALSE;
    invitation_code TEXT;
    role_id_var INTEGER;
    organization_id_var INTEGER;
    organization_name_var TEXT;
    
    -- Variables para generar valores únicos
    generated_subdomain TEXT;
    generated_branch_code TEXT;
    subdomain_counter INTEGER := 0;
    branch_code_counter INTEGER := 0;
    base_subdomain TEXT;
    base_branch_code TEXT;
BEGIN
    -- Establecer search_path explícitamente
    PERFORM set_config('search_path', 'public, auth', true);

    -- Solo procesar cuando el email se confirma por primera vez
    IF NOT (OLD.email_confirmed_at IS NULL AND NEW.email_confirmed_at IS NOT NULL) THEN
        RETURN NEW;
    END IF;

    -- Verificar si el usuario ya tiene perfil
    IF EXISTS (SELECT 1 FROM public.profiles WHERE id = NEW.id) THEN
        -- LIMPIAR signup_data incluso si ya tiene perfil
        UPDATE auth.users 
        SET raw_user_meta_data = raw_user_meta_data - 'signup_data'
        WHERE id = NEW.id;
        
        INSERT INTO public.signup_debug_logs (
            user_id, email, error_message
        ) VALUES (
            NEW.id, NEW.email, 'Usuario ya tiene perfil - saltando trigger pero limpiando signup_data'
        );
        RETURN NEW;
    END IF;

    -- Verificar si el email ya existe en profiles (evitar duplicados)
    IF EXISTS (SELECT 1 FROM public.profiles WHERE email = NEW.email) THEN
        INSERT INTO public.signup_debug_logs (
            user_id, email, error_message
        ) VALUES (
            NEW.id, NEW.email, 'Email ya existe en profiles - saltando creación'
        );
        RETURN NEW;
    END IF;

    -- ============= LÓGICA PARA INVITACIONES =============
    -- Verificar si es una invitación revisando raw_user_meta_data
    is_invitation := COALESCE((NEW.raw_user_meta_data->>'is_invitation')::BOOLEAN, FALSE);
    
    IF is_invitation THEN
        -- Extraer datos de la invitación de raw_user_meta_data
        invitation_code := NEW.raw_user_meta_data->>'invitation_code';
        role_id_var := (NEW.raw_user_meta_data->>'role_id')::INTEGER;
        organization_id_var := (NEW.raw_user_meta_data->>'organization_id')::INTEGER;
        organization_name_var := NEW.raw_user_meta_data->>'organization_name';
        
        -- Log de inicio del proceso de invitación
        INSERT INTO public.signup_debug_logs (
            user_id, email, raw_metadata, error_message
        ) VALUES (
            NEW.id, NEW.email, NEW.raw_user_meta_data, 
            'INVITACIÓN: Procesando invitación con código ' || COALESCE(invitation_code, 'NULL')
        ) RETURNING id INTO debug_log_id;
        
        BEGIN
            -- Validar que tenemos los datos mínimos necesarios
            IF invitation_code IS NULL OR role_id_var IS NULL OR organization_id_var IS NULL THEN
                UPDATE public.signup_debug_logs
                SET error_message = 'INVITACIÓN ERROR: Faltan datos en metadata - code:' || COALESCE(invitation_code, 'NULL') || ' role:' || COALESCE(role_id_var::TEXT, 'NULL') || ' org:' || COALESCE(organization_id_var::TEXT, 'NULL')
                WHERE id = debug_log_id;
                RETURN NEW;
            END IF;
            
            -- Obtener branch principal de la organización
            SELECT id INTO branch_id 
            FROM public.branches 
            WHERE organization_id = organization_id_var AND is_main = true 
            LIMIT 1;
            
            -- Crear perfil básico para la invitación (SIN branch_id que no existe)
            INSERT INTO public.profiles (
                id,
                email,
                status,
                last_org_id
            ) VALUES (
                NEW.id,
                NEW.email,
                'active',
                organization_id_var
            );
            
            -- Crear membresía en la organización
            INSERT INTO public.organization_members (
                organization_id,
                user_id,
                role_id,
                is_super_admin,
                is_active
            ) VALUES (
                organization_id_var,
                NEW.id,
                role_id_var,
                false,
                true
            ) RETURNING id INTO member_id;
            
            -- Marcar la invitación como usada
            UPDATE public.invitations 
            SET status = 'half', used_at = NOW()
            WHERE code = invitation_code;
            
            process_success := TRUE;
            UPDATE public.signup_debug_logs
            SET error_message = 'INVITACIÓN ÉXITO: Perfil básico creado, member_id:' || member_id || ', necesita completar datos'
            WHERE id = debug_log_id;
            
        EXCEPTION WHEN OTHERS THEN
            UPDATE public.signup_debug_logs
            SET error_message = 'INVITACIÓN ERROR: ' || SQLERRM
            WHERE id = debug_log_id;
        END;
        
    ELSE
        -- ============= LÓGICA PARA REGISTROS NORMALES =============
        INSERT INTO public.signup_debug_logs (
            user_id, email, raw_metadata, error_message
        ) VALUES (
            NEW.id, NEW.email, NEW.raw_user_meta_data, 'Iniciando proceso de signup tras confirmación de email'
        ) RETURNING id INTO debug_log_id;

        -- Extraer signup_data
        signup_data_raw := NEW.raw_user_meta_data->>'signup_data';
        
        IF signup_data_raw IS NOT NULL THEN
            BEGIN
                signup_data_json := signup_data_raw::JSONB;
                join_type_var := signup_data_json->>'joinType';
                
                -- Solo procesar si es creación de organización
                IF join_type_var = 'create' THEN
                    -- Extraer valores de avatar y idioma
                    avatar_url_value := signup_data_json->>'avatarUrl';
                    preferred_language_value := COALESCE(signup_data_json->>'preferredLanguage', 'es');
                    
                    -- Obtener el nombre del país - SIMPLIFICADO para evitar errores de schema
                    country_name := COALESCE(signup_data_json->>'organizationCountry', 'Colombia');
                    
                    -- Intentar obtener desde la tabla countries si es posible
                    BEGIN
                        SELECT public.countries.name INTO country_name 
                        FROM public.countries 
                        WHERE public.countries.code = (signup_data_json->>'organizationCountryCode')
                        LIMIT 1;
                    EXCEPTION WHEN OTHERS THEN
                        -- Si falla, usar el valor por defecto ya asignado
                        country_name := COALESCE(signup_data_json->>'organizationCountry', 'Colombia');
                    END;
                    
                    -- Generar subdomain único si está vacío
                    base_subdomain := COALESCE(signup_data_json->>'organizationSubdomain', '');
                    IF base_subdomain = '' THEN
                        base_subdomain := LOWER(REGEXP_REPLACE(signup_data_json->>'organizationName', '[^a-zA-Z0-9]', '', 'g'));
                    END IF;
                    
                    generated_subdomain := base_subdomain;
                    WHILE EXISTS (SELECT 1 FROM public.organizations WHERE subdomain = generated_subdomain) LOOP
                        subdomain_counter := subdomain_counter + 1;
                        generated_subdomain := base_subdomain || subdomain_counter::TEXT;
                    END LOOP;
                    
                    -- Crear la organización
                    INSERT INTO public.organizations (
                        name, legal_name, description, email, phone, address, city, state, country, 
                        postal_code, tax_id, nit, website, primary_color, secondary_color, subdomain,
                        type_id, owner_user_id, created_by, status, logo_url
                    ) VALUES (
                        signup_data_json->>'organizationName',
                        signup_data_json->>'organizationLegalName',
                        signup_data_json->>'organizationDescription',
                        signup_data_json->>'organizationEmail',
                        signup_data_json->>'organizationPhone',
                        signup_data_json->>'organizationAddress',
                        signup_data_json->>'organizationCity',
                        signup_data_json->>'organizationState',
                        country_name,
                        signup_data_json->>'organizationPostalCode',
                        signup_data_json->>'organizationTaxId',
                        signup_data_json->>'organizationNit',
                        signup_data_json->>'organizationWebsite',
                        signup_data_json->>'organizationPrimaryColor',
                        signup_data_json->>'organizationSecondaryColor',
                        generated_subdomain,
                        (signup_data_json->>'organizationTypeId')::INTEGER,
                        NEW.id,
                        NEW.id,
                        'active',
                        signup_data_json->>'logoUrl'
                    ) RETURNING id INTO org_id;
                    
                    -- Generar código único para la sucursal
                    base_branch_code := COALESCE(signup_data_json->>'branchCode', 'MAIN-001');
                    generated_branch_code := base_branch_code;
                    WHILE EXISTS (SELECT 1 FROM public.branches WHERE organization_id = org_id AND branch_code = generated_branch_code) LOOP
                        branch_code_counter := branch_code_counter + 1;
                        generated_branch_code := 'MAIN-' || LPAD(branch_code_counter::TEXT, 3, '0');
                    END LOOP;
                    
                    -- Crear la sucursal principal (CORREGIDO: usar country_name consistente)
                    INSERT INTO public.branches (
                        organization_id, name, branch_code, address, city, state, country, postal_code,
                        phone, email, tax_identification, opening_hours, features, is_main, is_active
                    ) VALUES (
                        org_id,
                        COALESCE(signup_data_json->>'branchName', 'Sucursal Principal'),
                        generated_branch_code,
                        signup_data_json->>'branchAddress',
                        signup_data_json->>'branchCity',
                        signup_data_json->>'branchState',
                        country_name,  -- CORREGIDO: usar country_name en lugar de branch_country
                        signup_data_json->>'branchPostalCode',
                        signup_data_json->>'branchPhone',
                        signup_data_json->>'branchEmail',
                        signup_data_json->>'branchTaxIdentification',
                        COALESCE(signup_data_json->>'branchOpeningHours', '{}')::JSONB,
                        COALESCE(signup_data_json->>'branchFeatures', '{}')::JSONB,
                        true,
                        true
                    ) RETURNING id INTO branch_id;
                    
                    -- Crear el perfil del usuario (CORREGIDO: sin branch_id, con last_org_id)
                    INSERT INTO public.profiles (
                        id, email, first_name, last_name, phone, avatar_url, 
                        preferred_language, last_org_id, status
                    ) VALUES (
                        NEW.id,
                        NEW.email,
                        signup_data_json->>'firstName',
                        signup_data_json->>'lastName',
                        signup_data_json->>'phone',
                        avatar_url_value,
                        preferred_language_value,
                        org_id,
                        'active'
                    );
                    
                    -- Crear membresía del usuario como super admin
                    INSERT INTO public.organization_members (
                        organization_id, user_id, role_id, is_super_admin, is_active
                    ) VALUES (
                        org_id, NEW.id, 1, true, true
                    ) RETURNING id INTO member_id;
                    
                    -- Obtener el plan de suscripción
                    subscription_plan_code := COALESCE(signup_data_json->>'subscriptionPlan', 'free');
                    SELECT id INTO plan_id_var FROM public.plans WHERE code = subscription_plan_code LIMIT 1;
                    
                    -- Crear suscripción (CORREGIDO: solo campos que existen)
                    IF plan_id_var IS NOT NULL THEN
                        INSERT INTO public.subscriptions (
                            organization_id, plan_id, status
                        ) VALUES (
                            org_id, plan_id_var, 'active'
                        ) RETURNING id INTO subscription_id;
                    END IF;
                    
                    -- Activar módulos core para la organización (CORREGIDO: usar module_code)
                    INSERT INTO public.organization_modules (organization_id, module_code, is_active)
                    SELECT org_id, code, true
                    FROM public.modules
                    WHERE is_core = true;
                    
                    process_success := TRUE;
                    UPDATE public.signup_debug_logs
                    SET error_message = 'ÉXITO COMPLETO: Org ID: ' || org_id || ', Branch ID: ' || branch_id || ', Member ID: ' || member_id || ', Country: ' || country_name
                    WHERE id = debug_log_id;
                    
                END IF;
                
            EXCEPTION WHEN OTHERS THEN
                UPDATE public.signup_debug_logs
                SET error_message = 'Error en proceso normal: ' || SQLERRM
                WHERE id = debug_log_id;
            END;
        END IF;
    END IF;

    -- LIMPIEZA OBLIGATORIA - SE EJECUTA SIEMPRE
    BEGIN
        UPDATE auth.users 
        SET raw_user_meta_data = raw_user_meta_data - 'signup_data'
        WHERE id = NEW.id;
        
        cleanup_attempted := TRUE;
        
        UPDATE public.signup_debug_logs
        SET error_message = COALESCE(error_message, 'Proceso completado') || ' | LIMPIEZA: signup_data eliminado'
        WHERE id = debug_log_id;
        
    EXCEPTION WHEN OTHERS THEN
        INSERT INTO public.signup_debug_logs (user_id, email, error_message)
        VALUES (NEW.id, NEW.email, 'ERROR CRÍTICO: No se pudo limpiar signup_data - ' || SQLERRM);
    END;

    RETURN NEW;
END;
END;$$;


ALTER FUNCTION "public"."handle_email_confirmation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."hrm_generate_loan_installments"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_installment_date date;
  i int;
BEGIN
  -- Solo procesar si se aprobó el préstamo
  IF NEW.status = 'active' AND (OLD.status IS NULL OR OLD.status != 'active') THEN
    -- Generar las cuotas
    v_installment_date := COALESCE(NEW.first_payment_date, CURRENT_DATE + INTERVAL '1 month');
    
    FOR i IN 1..NEW.installments_total LOOP
      INSERT INTO loan_installments (
        loan_id, installment_number, due_date, amount, 
        principal_portion, interest_portion, status
      ) VALUES (
        NEW.id,
        i,
        v_installment_date,
        NEW.installment_amount,
        NEW.principal / NEW.installments_total,
        NEW.total_interest / NEW.installments_total,
        'pending'
      );
      
      -- Siguiente mes
      v_installment_date := v_installment_date + INTERVAL '1 month';
    END LOOP;
  END IF;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."hrm_generate_loan_installments"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."hrm_generate_loan_installments"() IS 'Genera automáticamente las cuotas cuando se activa un préstamo';



CREATE OR REPLACE FUNCTION "public"."hrm_process_attendance_event"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_work_date date;
  v_timesheet_id uuid;
  v_first_check_in timestamptz;
  v_last_check_out timestamptz;
  v_total_worked int;
  v_total_break int;
BEGIN
  -- Obtener la fecha del evento
  v_work_date := date(NEW.event_at AT TIME ZONE 'America/Bogota');
  
  -- Crear timesheet si no existe
  INSERT INTO timesheets (organization_id, branch_id, employment_id, work_date)
  VALUES (NEW.organization_id, NEW.branch_id, NEW.employment_id, v_work_date)
  ON CONFLICT (employment_id, work_date) DO NOTHING;
  
  -- Obtener el ID del timesheet
  SELECT id INTO v_timesheet_id
  FROM timesheets
  WHERE employment_id = NEW.employment_id AND work_date = v_work_date;
  
  -- Calcular primera entrada del día
  SELECT MIN(event_at) INTO v_first_check_in
  FROM attendance_events
  WHERE employment_id = NEW.employment_id
    AND date(event_at AT TIME ZONE 'America/Bogota') = v_work_date
    AND event_type = 'check_in';
  
  -- Calcular última salida del día
  SELECT MAX(event_at) INTO v_last_check_out
  FROM attendance_events
  WHERE employment_id = NEW.employment_id
    AND date(event_at AT TIME ZONE 'America/Bogota') = v_work_date
    AND event_type = 'check_out';
  
  -- Calcular minutos trabajados (simplificado: última salida - primera entrada)
  IF v_first_check_in IS NOT NULL AND v_last_check_out IS NOT NULL THEN
    v_total_worked := EXTRACT(EPOCH FROM (v_last_check_out - v_first_check_in)) / 60;
  ELSE
    v_total_worked := 0;
  END IF;
  
  -- TODO: Calcular breaks desde break_start/break_end
  v_total_break := 0;
  
  -- Actualizar timesheet
  UPDATE timesheets
  SET 
    first_check_in = v_first_check_in,
    last_check_out = v_last_check_out,
    worked_minutes = GREATEST(0, v_total_worked),
    break_minutes = v_total_break,
    net_worked_minutes = GREATEST(0, v_total_worked - v_total_break),
    updated_at = now()
  WHERE id = v_timesheet_id;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."hrm_process_attendance_event"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."hrm_process_attendance_event"() IS 'Crea/actualiza timesheet automáticamente cuando se registra un evento de asistencia';



CREATE OR REPLACE FUNCTION "public"."hrm_update_leave_balance_on_request"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_year int;
BEGIN
  v_year := EXTRACT(YEAR FROM NEW.start_date);
  
  -- Si se aprueba la solicitud, mover de 'available' a 'pending'
  IF NEW.status = 'approved' AND (OLD.status IS NULL OR OLD.status != 'approved') THEN
    -- Asegurar que existe el balance
    INSERT INTO leave_balances (organization_id, employment_id, leave_type_id, year)
    VALUES (NEW.organization_id, NEW.employment_id, NEW.leave_type_id, v_year)
    ON CONFLICT (employment_id, leave_type_id, year) DO NOTHING;
    
    -- Incrementar pending
    UPDATE leave_balances
    SET pending = pending + NEW.total_days,
        updated_at = now()
    WHERE employment_id = NEW.employment_id 
      AND leave_type_id = NEW.leave_type_id 
      AND year = v_year;
  END IF;
  
  -- Si se marca como 'taken', mover de 'pending' a 'used'
  IF NEW.status = 'taken' AND OLD.status = 'approved' THEN
    UPDATE leave_balances
    SET pending = pending - NEW.total_days,
        used = used + NEW.total_days,
        updated_at = now()
    WHERE employment_id = NEW.employment_id 
      AND leave_type_id = NEW.leave_type_id 
      AND year = v_year;
  END IF;
  
  -- Si se cancela una solicitud aprobada, devolver días a available
  IF NEW.status = 'cancelled' AND OLD.status = 'approved' THEN
    UPDATE leave_balances
    SET pending = pending - NEW.total_days,
        updated_at = now()
    WHERE employment_id = NEW.employment_id 
      AND leave_type_id = NEW.leave_type_id 
      AND year = v_year;
  END IF;
  
  -- Si se rechaza, no hacer nada (los días no se habían reservado)
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."hrm_update_leave_balance_on_request"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."hrm_update_leave_balance_on_request"() IS 'Actualiza automáticamente el saldo de ausencias cuando cambia el estado de una solicitud';



CREATE OR REPLACE FUNCTION "public"."hrm_update_loan_on_installment_payment"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_total_paid numeric;
  v_installments_paid int;
BEGIN
  -- Solo procesar si se marcó como pagada
  IF NEW.status = 'paid' AND (OLD.status IS NULL OR OLD.status != 'paid') THEN
    -- Calcular total pagado y cuotas pagadas
    SELECT 
      COALESCE(SUM(amount_paid), 0),
      COUNT(*) FILTER (WHERE status = 'paid')
    INTO v_total_paid, v_installments_paid
    FROM loan_installments
    WHERE loan_id = NEW.loan_id;
    
    -- Actualizar préstamo
    UPDATE employee_loans
    SET 
      balance = total_amount - v_total_paid,
      installments_paid = v_installments_paid,
      last_payment_date = CURRENT_DATE,
      status = CASE 
        WHEN total_amount - v_total_paid <= 0 THEN 'paid'
        ELSE status
      END,
      updated_at = now()
    WHERE id = NEW.loan_id;
  END IF;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."hrm_update_loan_on_installment_payment"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."hrm_update_loan_on_installment_payment"() IS 'Actualiza automáticamente el saldo del préstamo cuando se paga una cuota';



