CREATE OR REPLACE FUNCTION "public"."initialize_org_preferences"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  country_data RECORD;
  default_settings JSONB;
  timezone_value TEXT;
  language_value TEXT;
  currency_value TEXT;
BEGIN
  -- Obtener datos del país de la organización
  SELECT 
    default_currency_code,
    locale
  INTO country_data
  FROM countries 
  WHERE code = NEW.country_code;
  
  -- Establecer valores predeterminados basados en el país
  IF country_data IS NOT NULL THEN
    currency_value := country_data.default_currency_code;
    language_value := country_data.locale;
    
    -- Mapear zona horaria basada en el país
    timezone_value := CASE NEW.country_code
      WHEN 'COL' THEN 'America/Bogota'
      WHEN 'USA' THEN 'America/New_York'
      WHEN 'MEX' THEN 'America/Mexico_City'
      WHEN 'ESP' THEN 'Europe/Madrid'
      WHEN 'BRA' THEN 'America/Sao_Paulo'
      WHEN 'ARG' THEN 'America/Argentina/Buenos_Aires'
      WHEN 'CHL' THEN 'America/Santiago'
      WHEN 'PER' THEN 'America/Lima'
      WHEN 'ECU' THEN 'America/Guayaquil'
      WHEN 'VEN' THEN 'America/Caracas'
      WHEN 'CAN' THEN 'America/Toronto'
      WHEN 'GBR' THEN 'Europe/London'
      WHEN 'FRA' THEN 'Europe/Paris'
      WHEN 'DEU' THEN 'Europe/Berlin'
      WHEN 'ITA' THEN 'Europe/Rome'
      WHEN 'JPN' THEN 'Asia/Tokyo'
      WHEN 'CHN' THEN 'Asia/Shanghai'
      WHEN 'AUS' THEN 'Australia/Sydney'
      ELSE 'UTC'
    END;
  ELSE
    -- Valores predeterminados si no se encuentra el país
    currency_value := 'USD';
    language_value := 'en-US';
    timezone_value := 'UTC';
  END IF;
  
  -- Construir el JSON de configuraciones predeterminadas
  default_settings := jsonb_build_object(
    'finance', jsonb_build_object(
      'currency_format', '#,##0.00',
      'decimal_separator', '.',
      'thousands_separator', ',',
      'date_format', 'YYYY-MM-DD',
      'default_currency', currency_value,
      'tax_included_by_default', false,
      'auto_calculate_taxes', true
    ),
    'ui', jsonb_build_object(
      'theme', 'light',
      'compact_mode', false,
      'show_help_tips', true,
      'sidebar_collapsed', false,
      'default_page_size', 25,
      'date_picker_format', 'DD/MM/YYYY'
    ),
    'system', jsonb_build_object(
      'timezone', timezone_value,
      'language', language_value,
      'notifications_enabled', true,
      'email_notifications', true,
      'sms_notifications', false,
      'auto_logout_minutes', 480,
      'session_timeout_warning', true
    ),
    'business', jsonb_build_object(
      'business_hours', jsonb_build_object(
        'monday', jsonb_build_object('open', '08:00', 'close', '18:00', 'closed', false),
        'tuesday', jsonb_build_object('open', '08:00', 'close', '18:00', 'closed', false),
        'wednesday', jsonb_build_object('open', '08:00', 'close', '18:00', 'closed', false),
        'thursday', jsonb_build_object('open', '08:00', 'close', '18:00', 'closed', false),
        'friday', jsonb_build_object('open', '08:00', 'close', '18:00', 'closed', false),
        'saturday', jsonb_build_object('open', '09:00', 'close', '15:00', 'closed', false),
        'sunday', jsonb_build_object('closed', true)
      ),
      'default_payment_terms', 30,
      'invoice_numbering_format', 'INV-{YYYY}-{####}',
      'quote_numbering_format', 'QUO-{YYYY}-{####}'
    ),
    'integrations', jsonb_build_object(
      'email_provider', null,
      'sms_provider', null,
      'payment_gateways', jsonb_build_array(),
      'accounting_software', null,
      'backup_frequency', 'daily'
    ),
    'security', jsonb_build_object(
      'password_policy', jsonb_build_object(
        'min_length', 8,
        'require_uppercase', true,
        'require_lowercase', true,
        'require_numbers', true,
        'require_symbols', false,
        'password_expiry_days', 90
      ),
      'two_factor_auth_required', false,
      'ip_whitelist_enabled', false,
      'login_attempt_limit', 5,
      'account_lockout_duration', 30
    )
  );
  
  -- Insertar las preferencias iniciales
  INSERT INTO organization_preferences (organization_id, settings)
  VALUES (NEW.id, default_settings);
  
  RETURN NEW;
END;
$$;


