CREATE OR REPLACE FUNCTION "public"."initialize_organization_taxes"("org_id" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    -- Insertar impuestos predefinidos para la nueva organización
    INSERT INTO public.organization_taxes (
        organization_id,
        template_id,
        name,
        rate,
        description,
        is_default,
        is_active
    )
    SELECT 
        org_id,
        tt.id,
        tt.name,
        tt.rate,
        tt.description,
        CASE WHEN tt.code = 'IVA_19' THEN true ELSE false END,
        true
    FROM 
        public.tax_templates tt
    WHERE 
        tt.country = 'CO' 
        AND (tt.valid_to IS NULL OR tt.valid_to > NOW());
END;
$$;


