CREATE OR REPLACE FUNCTION "public"."insert_fallback_rates"() RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  today_date TEXT;
  rates_inserted INTEGER := 0;
BEGIN
  today_date := CURRENT_DATE::TEXT;
  
  -- Verificar si ya existen datos para hoy
  IF EXISTS (SELECT 1 FROM currency_rates WHERE rate_date = today_date) THEN
    RETURN jsonb_build_object(
      'success', true,
      'message', 'Ya existen datos para hoy',
      'rates_inserted', 0
    );
  END IF;
  
  -- Insertar tasas de respaldo basadas en datos más recientes + variación aleatoria
  INSERT INTO currency_rates (code, rate, rate_date, source, base_currency_code, created_at, updated_at)
  SELECT 
    code,
    rate * (1 + (random() - 0.5) * 0.02), -- Variación ±1%
    today_date,
    'automatic-fallback',
    base_currency_code,
    NOW(),
    NOW()
  FROM currency_rates 
  WHERE rate_date = (
    SELECT MAX(rate_date) FROM currency_rates WHERE rate_date < today_date
  );
  
  GET DIAGNOSTICS rates_inserted = ROW_COUNT;
  
  RETURN jsonb_build_object(
    'success', true,
    'message', 'Datos de respaldo insertados',
    'rates_inserted', rates_inserted
  );
END;
$$;


ALTER FUNCTION "public"."insert_fallback_rates"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."insert_shared_image_bypass_rls"("p_image_url" "text", "p_storage_path" "text", "p_file_name" "text", "p_file_size" integer, "p_mime_type" "text", "p_organization_id" integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_image_id INTEGER;
BEGIN
    -- Con SECURITY DEFINER esta función se ejecuta con los permisos del OWNER
    -- y SET search_path para evitar ataques de confusión de dependencias
    
    -- Insertar la imagen directamente, saltándose RLS por ser SECURITY DEFINER
    INSERT INTO public.shared_images (
        image_url, 
        storage_path, 
        file_name, 
        file_size, 
        mime_type, 
        organization_id,
        is_public,
        created_at
    ) VALUES (
        p_image_url, 
        p_storage_path, 
        p_file_name, 
        p_file_size, 
        p_mime_type, 
        p_organization_id,
        false,  -- no es pública por defecto
        now()   -- timestamp actual
    )
    RETURNING id INTO v_image_id;
    
    RETURN v_image_id;
END;
$$;


ALTER FUNCTION "public"."insert_shared_image_bypass_rls"("p_image_url" "text", "p_storage_path" "text", "p_file_name" "text", "p_file_size" integer, "p_mime_type" "text", "p_organization_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."insert_shared_image_simple"("p_image_url" "text", "p_storage_path" "text", "p_file_name" "text", "p_file_size" integer, "p_mime_type" "text", "p_organization_id" integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_image_id INTEGER;
BEGIN
    -- Desactivar temporalmente todas las políticas RLS para esta función
    ALTER TABLE shared_images DISABLE ROW LEVEL SECURITY;
    
    -- Insertar la imagen de forma simple
    INSERT INTO shared_images (
        image_url, 
        storage_path, 
        file_name, 
        file_size, 
        mime_type, 
        organization_id
    ) VALUES (
        p_image_url, 
        p_storage_path, 
        p_file_name, 
        p_file_size, 
        p_mime_type, 
        p_organization_id
    )
    RETURNING id INTO v_image_id;
    
    -- Volver a activar RLS
    ALTER TABLE shared_images ENABLE ROW LEVEL SECURITY;
    
    RETURN v_image_id;
END;
$$;


