CREATE OR REPLACE FUNCTION "public"."issue_invoice"("invoice_id_param" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  invoice_record RECORD;
BEGIN
  -- Verificar que la factura exista y esté en draft
  SELECT * INTO invoice_record FROM invoice_sales WHERE id = invoice_id_param::UUID;
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Factura no encontrada con ID: %', invoice_id_param;
  END IF;
  
  IF invoice_record.status != 'draft' THEN
    RAISE EXCEPTION 'La factura con ID: % no está en estado borrador', invoice_id_param;
  END IF;
  
  -- Actualizar la factura a issued
  UPDATE invoice_sales
  SET 
    status = 'issued',
    updated_at = NOW()
  WHERE id = invoice_id_param::UUID;
  
  -- Llamamos manualmente a la función para crear la cuenta por cobrar
  -- ya que esto garantiza que se cree aún si la factura estaba en draft
  -- Convertimos explícitamente el parámetro a texto
  PERFORM create_account_receivable(invoice_id_param::TEXT);
  
  RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."issue_invoice"("invoice_id_param" "uuid") OWNER TO "postgres";


