CREATE OR REPLACE FUNCTION "public"."log_role_changes"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  org_id INTEGER;
  change_type TEXT;
  change_data JSONB;
  entity_uuid UUID;
  current_user_id UUID;
BEGIN
  current_user_id := coalesce(auth.uid(), '00000000-0000-0000-0000-000000000000'::UUID);
  
  -- Obtener organization_id del usuario actual
  SELECT organization_id INTO org_id
  FROM organization_members
  WHERE user_id = current_user_id
  AND is_active = true
  LIMIT 1;
  
  -- Si no se encuentra, usar organization_id = 1 como fallback
  IF org_id IS NULL THEN
    org_id := 1;
  END IF;
  
  IF TG_OP = 'INSERT' THEN
    change_type := 'create';
    change_data := to_jsonb(NEW);
    entity_uuid := gen_random_uuid();
    
  ELSIF TG_OP = 'UPDATE' THEN
    change_type := 'update';
    change_data := jsonb_build_object('old', to_jsonb(OLD), 'new', to_jsonb(NEW));
    entity_uuid := gen_random_uuid();
    
  ELSIF TG_OP = 'DELETE' THEN
    change_type := 'delete';
    change_data := to_jsonb(OLD);
    entity_uuid := gen_random_uuid();
  END IF;
  
  INSERT INTO roles_audit_log (
    organization_id, entity, entity_id, action, user_id, diff, logged_at
  ) VALUES (
    org_id, TG_TABLE_NAME, entity_uuid, change_type, current_user_id, change_data, now()
  );
  
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  ELSE
    RETURN NEW;
  END IF;
END;
$$;


ALTER FUNCTION "public"."log_role_changes"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."manage_organization_tax"("p_organization_id" integer, "p_name" "text", "p_rate" numeric, "p_description" "text", "p_is_default" boolean, "p_is_active" boolean, "p_template_id" integer, "p_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_result JSONB;
    v_tax_id TEXT;
    v_user_id UUID;
    v_user_has_access BOOLEAN;
    v_current_timestamp TIMESTAMPTZ := NOW();
    v_is_update BOOLEAN := p_id IS NOT NULL;
    v_id_as_uuid UUID;
BEGIN
    -- Obtener el ID del usuario autenticado y convertirlo explícitamente a UUID
    v_user_id := (auth.uid())::UUID;
    
    -- Si hay un ID, convertirlo a UUID para comparaciones posteriores
    IF v_is_update THEN
        BEGIN
            v_id_as_uuid := p_id::UUID;
        EXCEPTION WHEN others THEN
            RETURN jsonb_build_object(
                'success', FALSE,
                'message', 'ID de impuesto inválido',
                'code', 'INVALID_ID'
            );
        END;
    END IF;
    
    -- Verificar si el usuario tiene acceso a la organización usando la tabla correcta (organization_members)
    SELECT EXISTS (
        SELECT 1 
        FROM public.organization_members 
        WHERE 
            user_id = v_user_id AND 
            organization_id = p_organization_id AND 
            is_active = TRUE
    ) INTO v_user_has_access;
    
    -- Si el usuario no tiene acceso, abortar
    IF NOT v_user_has_access THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'message', 'No tiene permisos para administrar impuestos en esta organización',
            'code', 'PERMISSION_DENIED'
        );
    END IF;
    
    -- Si es una actualización
    IF v_is_update THEN
        -- Verificar que el impuesto exista y pertenezca a la organización
        -- Aquí usamos v_id_as_uuid en lugar de p_id para comparar correctamente con la columna UUID
        IF NOT EXISTS (
            SELECT 1 
            FROM public.organization_taxes 
            WHERE id = v_id_as_uuid AND organization_id = p_organization_id
        ) THEN
            RETURN jsonb_build_object(
                'success', FALSE,
                'message', 'El impuesto no existe o no pertenece a esta organización',
                'code', 'TAX_NOT_FOUND'
            );
        END IF;
        
        -- Actualizar el impuesto
        -- Usamos v_id_as_uuid en lugar de p_id
        UPDATE public.organization_taxes
        SET 
            name = p_name,
            rate = p_rate,
            description = p_description,
            is_default = p_is_default,
            is_active = p_is_active,
            template_id = p_template_id,
            updated_at = v_current_timestamp
        WHERE id = v_id_as_uuid
        RETURNING id::text INTO v_tax_id;
        
    -- Si es una creación
    ELSE
        -- Insertar el nuevo impuesto
        INSERT INTO public.organization_taxes(
            organization_id,
            name,
            rate,
            description,
            is_default,
            is_active,
            template_id,
            created_at,
            updated_at
        )
        VALUES (
            p_organization_id,
            p_name,
            p_rate,
            p_description,
            p_is_default,
            p_is_active,
            p_template_id,
            v_current_timestamp,
            v_current_timestamp
        )
        RETURNING id::text INTO v_tax_id;
    END IF;
    
    -- Si el impuesto es marcado como predeterminado, actualizar otros impuestos
    IF p_is_default THEN
        UPDATE public.organization_taxes
        SET is_default = FALSE
        WHERE 
            organization_id = p_organization_id AND 
            id != v_tax_id::UUID AND
            is_default = TRUE;
    END IF;
    
    -- Construir el resultado
    v_result := jsonb_build_object(
        'success', TRUE,
        'id', v_tax_id,
        'message', CASE WHEN v_is_update THEN 'Impuesto actualizado correctamente' ELSE 'Impuesto creado correctamente' END
    );
    
    RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."manage_organization_tax"("p_organization_id" integer, "p_name" "text", "p_rate" numeric, "p_description" "text", "p_is_default" boolean, "p_is_active" boolean, "p_template_id" integer, "p_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."manage_organization_tax"("p_organization_id" integer, "p_name" "text", "p_rate" numeric, "p_description" "text" DEFAULT NULL::"text", "p_is_default" boolean DEFAULT false, "p_is_active" boolean DEFAULT true, "p_template_id" integer DEFAULT NULL::integer, "p_id" "text" DEFAULT NULL::"text", "p_tax_included" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_result JSONB;
    v_tax_id TEXT;
    v_user_id UUID;
    v_user_has_access BOOLEAN;
    v_current_timestamp TIMESTAMPTZ := NOW();
    v_is_update BOOLEAN := p_id IS NOT NULL;
    v_id_as_uuid UUID;
BEGIN
    v_user_id := (auth.uid())::UUID;
    
    IF v_is_update THEN
        BEGIN
            v_id_as_uuid := p_id::UUID;
        EXCEPTION WHEN others THEN
            RETURN jsonb_build_object(
                'success', FALSE,
                'message', 'ID de impuesto inválido',
                'code', 'INVALID_ID'
            );
        END;
    END IF;
    
    SELECT EXISTS (
        SELECT 1 
        FROM public.organization_members 
        WHERE 
            user_id = v_user_id AND 
            organization_id = p_organization_id AND 
            is_active = TRUE
    ) INTO v_user_has_access;
    
    IF NOT v_user_has_access THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'message', 'No tiene permisos para administrar impuestos en esta organización',
            'code', 'PERMISSION_DENIED'
        );
    END IF;
    
    IF v_is_update THEN
        IF NOT EXISTS (
            SELECT 1 
            FROM public.organization_taxes 
            WHERE id = v_id_as_uuid AND organization_id = p_organization_id
        ) THEN
            RETURN jsonb_build_object(
                'success', FALSE,
                'message', 'El impuesto no existe o no pertenece a esta organización',
                'code', 'TAX_NOT_FOUND'
            );
        END IF;
        
        UPDATE public.organization_taxes
        SET 
            name = p_name,
            rate = p_rate,
            description = p_description,
            is_default = p_is_default,
            is_active = p_is_active,
            template_id = p_template_id,
            tax_included = p_tax_included,
            updated_at = v_current_timestamp
        WHERE id = v_id_as_uuid
        RETURNING id::text INTO v_tax_id;
        
    ELSE
        INSERT INTO public.organization_taxes(
            organization_id, name, rate, description,
            is_default, is_active, template_id, tax_included,
            created_at, updated_at
        )
        VALUES (
            p_organization_id, p_name, p_rate, p_description,
            p_is_default, p_is_active, p_template_id, p_tax_included,
            v_current_timestamp, v_current_timestamp
        )
        RETURNING id::text INTO v_tax_id;
    END IF;
    
    IF p_is_default THEN
        UPDATE public.organization_taxes
        SET is_default = FALSE
        WHERE 
            organization_id = p_organization_id AND 
            id != v_tax_id::UUID AND
            is_default = TRUE;
    END IF;
    
    v_result := jsonb_build_object(
        'success', TRUE,
        'id', v_tax_id,
        'message', CASE WHEN v_is_update THEN 'Impuesto actualizado correctamente' ELSE 'Impuesto creado correctamente' END
    );
    
    RETURN v_result;
END;
$$;


