CREATE OR REPLACE FUNCTION "public"."mark_all_notifications_as_read"("p_organization_id" integer, "p_scope" "text" DEFAULT 'all'::"text") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_inserted integer;
  v_uid      uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado';
  END IF;
  IF p_scope NOT IN ('mine', 'all') THEN
    RAISE EXCEPTION 'p_scope debe ser ''mine'' o ''all''';
  END IF;
  WITH inserted AS (
    INSERT INTO notification_reads (notification_id, user_id, read_at)
    SELECT n.id, v_uid, now()
    FROM notifications n
    WHERE n.organization_id = p_organization_id
      AND n.status <> 'deleted'
      AND (p_scope = 'all' OR n.recipient_user_id = v_uid)
      AND NOT EXISTS (
        SELECT 1 FROM notification_reads nr
        WHERE nr.notification_id = n.id AND nr.user_id = v_uid
      )
    ON CONFLICT (notification_id, user_id) DO NOTHING
    RETURNING 1
  )
  SELECT count(*) INTO v_inserted FROM inserted;
  RETURN v_inserted;
END;
$$;


ALTER FUNCTION "public"."mark_all_notifications_as_read"("p_organization_id" integer, "p_scope" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_conversation_messages_as_read"("p_conversation_id" "uuid", "p_member_id" bigint) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  updated_count integer;
BEGIN
  WITH updated AS (
    UPDATE messages
    SET 
      is_read = true,
      read_at = now()
    WHERE conversation_id = p_conversation_id
      AND is_read = false
      AND role = 'customer'
    RETURNING 1
  )
  SELECT COUNT(*) INTO updated_count FROM updated;
  
  -- Resetear contador de no leídos
  UPDATE conversations
  SET 
    unread_count = 0,
    updated_at = now()
  WHERE id = p_conversation_id;
  
  RETURN updated_count;
END;
$$;


ALTER FUNCTION "public"."mark_conversation_messages_as_read"("p_conversation_id" "uuid", "p_member_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."migrate_public_images"() RETURNS TABLE("id" integer, "old_url" "text", "new_url" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    r RECORD;
    updated_count INTEGER := 0;
    new_url TEXT;
BEGIN
    FOR r IN 
        SELECT i.id, i.image_url, i.storage_path 
        FROM public.shared_images i 
        WHERE i.is_public = true
    LOOP
        -- Generar nueva URL permanente
        new_url := public.get_permanent_image_url(r.storage_path);
        
        -- Actualizar URL en la tabla
        UPDATE public.shared_images 
        SET image_url = new_url 
        WHERE id = r.id;
        
        -- Devolver información sobre la actualización
        id := r.id;
        old_url := r.image_url;
        new_url := new_url;
        
        updated_count := updated_count + 1;
        RETURN NEXT;
    END LOOP;
    
    -- Si no se actualizó ninguna fila, devolver mensaje
    IF updated_count = 0 THEN
        id := 0;
        old_url := 'No hay imágenes públicas para actualizar';
        new_url := 'No hay imágenes públicas para actualizar';
        RETURN NEXT;
    END IF;
    
    RETURN;
END;
$$;


ALTER FUNCTION "public"."migrate_public_images"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."monitor_cron_jobs"() RETURNS TABLE("job_name" "text", "last_run" timestamp with time zone, "status" "text", "run_count" bigint)
    LANGUAGE "sql"
    AS $$
    SELECT 
        j.jobname,
        MAX(r.start_time) as last_run,
        CASE 
            WHEN MAX(r.start_time) > NOW() - INTERVAL '25 hours' THEN 'RECENT'
            WHEN MAX(r.start_time) IS NULL THEN 'NEVER_RUN'
            ELSE 'DELAYED'
        END as status,
        COUNT(r.runid) as run_count
    FROM cron.job j
    LEFT JOIN cron.job_run_details r ON j.jobid = r.jobid
    WHERE j.active = true
    GROUP BY j.jobid, j.jobname
    ORDER BY j.jobname;
$$;


ALTER FUNCTION "public"."monitor_cron_jobs"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalizar_busqueda"("p_texto" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    AS $$
  select trim(regexp_replace(
           regexp_replace(
             replace(replace(
               lower(public.f_unaccent(coalesce(p_texto, ''))),
             '''', ''), '’', ''),
           '[^a-z0-9]+', ' ', 'g'),
         '\s+', ' ', 'g'))
$$;


ALTER FUNCTION "public"."normalizar_busqueda"("p_texto" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."normalizar_busqueda"("p_texto" "text") IS 'Minusculas, sin tildes, sin apostrofos y con el resto de signos convertidos en espacios. Se aplica IGUAL al catalogo y a lo que escribe el cliente.';



CREATE OR REPLACE FUNCTION "public"."notify_forecast_update"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  record_jsonb JSONB;
BEGIN
  -- Convertir el registro a JSON para incluirlo en la notificación
  IF TG_OP = 'DELETE' THEN
    record_jsonb = to_jsonb(OLD);
  ELSE
    record_jsonb = to_jsonb(NEW);
  END IF;
  
  -- Agregar información sobre la operación y tabla
  record_jsonb = jsonb_set(
    record_jsonb, 
    '{operation}', 
    to_jsonb(TG_OP)
  );
  
  -- Notificar a través del canal específico del pipeline
  IF TG_TABLE_NAME = 'opportunities' THEN
    IF TG_OP = 'DELETE' THEN
      PERFORM pg_notify(
        'forecast_update_pipeline_' || OLD.pipeline_id, 
        record_jsonb::text
      );
      
      PERFORM pg_notify(
        'forecast_update_org_' || OLD.organization_id, 
        record_jsonb::text
      );
    ELSE
      PERFORM pg_notify(
        'forecast_update_pipeline_' || NEW.pipeline_id, 
        record_jsonb::text
      );
      
      PERFORM pg_notify(
        'forecast_update_org_' || NEW.organization_id, 
        record_jsonb::text
      );
    END IF;
  ELSIF TG_TABLE_NAME = 'stages' THEN
    IF TG_OP = 'DELETE' THEN
      PERFORM pg_notify(
        'forecast_update_pipeline_' || OLD.pipeline_id, 
        record_jsonb::text
      );
    ELSE
      PERFORM pg_notify(
        'forecast_update_pipeline_' || NEW.pipeline_id, 
        record_jsonb::text
      );
    END IF;
  END IF;
  
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."notify_forecast_update"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_push"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_supabase_url text;
  v_service_role_key text;
BEGIN
  -- Solo procesar notificaciones con canal 'push' o 'app' (in-app)
  IF new.channel NOT IN ('push', 'app') THEN
    RETURN new;
  END IF;

  -- Leer configuracion de forma segura (true => NULL si no existe el setting)
  v_supabase_url := current_setting('app.settings.supabase_url', true);
  v_service_role_key := current_setting('app.settings.service_role_key', true);

  -- Fallback: si los settings no estan configurados, usar valores por defecto.
  -- Esto permite que el push funcione sin necesidad de ALTER DATABASE (que
  -- requiere superuser). Los settings de BD siguen siendo preferidos si existen.
  IF v_supabase_url IS NULL THEN
    v_supabase_url := 'https://jgmgphmzusbluqhuqihj.supabase.co';
  END IF;
  IF v_service_role_key IS NULL THEN
    v_service_role_key := '<SERVICE_ROLE_KEY>';
  END IF;

  -- Caso 1: notificacion dirigida a un usuario especifico
  IF new.recipient_user_id IS NOT NULL THEN
    BEGIN
      PERFORM net.http_post(
        url := v_supabase_url || '/functions/v1/push',
        body := json_build_object(
          'type', 'INSERT',
          'table', 'notifications',
          'record', row_to_json(new),
          'old_record', null
        )::jsonb,
        headers := json_build_object(
          'Authorization', 'Bearer ' || v_service_role_key,
          'Content-Type', 'application/json'
        )::jsonb
      );
    EXCEPTION WHEN OTHERS THEN
      -- Push es best-effort: nunca debe bloquear la operacion principal.
      RETURN new;
    END;
    RETURN new;
  END IF;

  -- Caso 2: notificacion de organizacion (recipient_user_id IS NULL)
  IF new.recipient_user_id IS NULL AND new.organization_id IS NOT NULL THEN
    BEGIN
      PERFORM net.http_post(
        url := v_supabase_url || '/functions/v1/push',
        body := json_build_object(
          'type', 'INSERT',
          'table', 'notifications',
          'record', row_to_json(new),
          'old_record', null
        )::jsonb,
        headers := json_build_object(
          'Authorization', 'Bearer ' || v_service_role_key,
          'Content-Type', 'application/json'
        )::jsonb
      );
    EXCEPTION WHEN OTHERS THEN
      -- Push es best-effort: nunca debe bloquear la operacion principal.
      RETURN new;
    END;
    RETURN new;
  END IF;

  RETURN new;
END;
$$;


ALTER FUNCTION "public"."notify_push"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_waiter_on_ticket_ready"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_server_id uuid;
  v_org_id integer;
  v_table_name text;
  v_ticket_id integer;
BEGIN
  -- Solo cuando el status cambia a 'ready' (y no era 'ready' antes)
  IF NEW.status = 'ready' AND (OLD.status IS NULL OR OLD.status <> 'ready') THEN
    -- Obtener server_id y organization_id desde table_sessions
    SELECT ts.server_id, ts.organization_id
    INTO v_server_id, v_org_id
    FROM table_sessions ts
    WHERE ts.id = NEW.table_session_id;

    -- Si hay un mesero asignado, crear notificación
    IF v_server_id IS NOT NULL THEN
      -- Obtener nombre de la mesa para el mensaje
      SELECT rt.name INTO v_table_name
      FROM table_sessions ts
      JOIN restaurant_tables rt ON rt.id = ts.restaurant_table_id
      WHERE ts.id = NEW.table_session_id;

      v_ticket_id := NEW.id;

      INSERT INTO notifications (organization_id, recipient_user_id, channel, status, payload)
      VALUES (
        v_org_id,
        v_server_id,
        'app',
        'pending',
        jsonb_build_object(
          'type', 'kitchen_ticket_ready',
          'title', 'Comanda lista para servir',
          'message', CASE 
            WHEN v_table_name IS NOT NULL THEN 'La comanda #' || v_ticket_id || ' de la mesa ' || v_table_name || ' está lista para servir'
            ELSE 'La comanda #' || v_ticket_id || ' está lista para servir'
          END,
          'kitchen_ticket_id', v_ticket_id,
          'table_session_id', NEW.table_session_id,
          'table_name', v_table_name
        )
      );
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."notify_waiter_on_ticket_ready"() OWNER TO "postgres";


