CREATE OR REPLACE FUNCTION "public"."obtener_pagos_estacionamiento"("p_organization_id" integer, "p_parking_session_id" "uuid" DEFAULT NULL::"uuid", "p_parking_pass_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("payment_id" integer, "parking_payment_id" "uuid", "parking_session_id" "uuid", "parking_pass_id" "uuid", "method" "text", "amount" numeric, "currency" character, "reference" "text", "status" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        p.id AS payment_id,
        pp.id AS parking_payment_id,
        pp.parking_session_id,
        pp.parking_pass_id,
        p.method,
        p.amount,
        p.currency,
        p.reference,
        p.status,
        p.created_at,
        p.updated_at
    FROM 
        payments p
    JOIN 
        parking_payments pp ON p.id = pp.payment_id
    WHERE 
        p.organization_id = p_organization_id
        AND p.source = 'parking'
        AND (p_parking_session_id IS NULL OR pp.parking_session_id = p_parking_session_id)
        AND (p_parking_pass_id IS NULL OR pp.parking_pass_id = p_parking_pass_id)
    ORDER BY 
        p.created_at DESC;
END;
$$;


