CREATE OR REPLACE FUNCTION "public"."palabras_de_catalogo"("p_org" integer, "p_palabras" "text"[], "p_umbral_similitud" real DEFAULT 0.6) RETURNS TABLE("palabra_cliente" "text", "palabra_catalogo" "text", "exacta" boolean)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  with entrada as (
    select distinct public.normalizar_busqueda(w) as w
    from unnest(coalesce(p_palabras, '{}'::text[])) as w
  ),
  filtrada as (
    select w from entrada where length(w) >= 3
  )
  select f.w,
         coalesce(exacta.palabra, aprox.palabra),
         exacta.palabra is not null
  from filtrada f
  left join lateral (
    select v.palabra from public.org_vocabulario v
    where v.organization_id = p_org and v.palabra = f.w
    limit 1
  ) exacta on true
  left join lateral (
    select v.palabra from public.org_vocabulario v
    where v.organization_id = p_org
      and exacta.palabra is null
      and public.similarity(v.palabra, f.w) >= p_umbral_similitud
    order by public.similarity(v.palabra, f.w) desc, v.frecuencia desc
    limit 1
  ) aprox on true
  where coalesce(exacta.palabra, aprox.palabra) is not null;
$$;


ALTER FUNCTION "public"."palabras_de_catalogo"("p_org" integer, "p_palabras" "text"[], "p_umbral_similitud" real) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_product_ranking"("p_org_id" integer, "p_search" "text" DEFAULT NULL::"text", "p_category_id" integer DEFAULT NULL::integer, "p_status" "text" DEFAULT 'active'::"text", "p_include_variants" boolean DEFAULT false, "p_page" integer DEFAULT 1, "p_limit" integer DEFAULT 12) RETURNS TABLE("product_id" integer, "total_count" bigint, "is_favorite" boolean, "sales_count_90d" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_offset integer;
  v_sales_window timestamptz := now() - interval '90 days';
  v_has_search boolean := (p_search IS NOT NULL AND p_search <> '');
BEGIN
  v_offset := (p_page - 1) * p_limit;

  RETURN QUERY
  WITH
  -- IDs de productos (padre/simple) que coinciden con el término de búsqueda.
  -- Incluye coincidencias directas (sku/name/description/barcode del producto),
  -- variantes hijas (sku/name/barcode) -> su producto padre, y
  -- modificadores (grupo u opción por nombre) -> su producto asociado.
  matched_ids AS (
    SELECT p.id
    FROM public.products p
    WHERE p.organization_id = p_org_id
      AND p.parent_product_id IS NULL
      AND (
        p.sku ILIKE '%' || p_search || '%'
        OR p.name ILIKE '%' || p_search || '%'
        OR COALESCE(p.description, '') ILIKE '%' || p_search || '%'
        OR p.barcode = p_search
      )
    UNION
    SELECT parent.id
    FROM public.products variant
    JOIN public.products parent ON parent.id = variant.parent_product_id
    WHERE variant.organization_id = p_org_id
      AND parent.organization_id = p_org_id
      AND parent.parent_product_id IS NULL
      AND (
        variant.sku ILIKE '%' || p_search || '%'
        OR variant.name ILIKE '%' || p_search || '%'
        OR variant.barcode = p_search
      )
    UNION
    SELECT g.product_id
    FROM public.product_modifier_groups g
    JOIN public.products p ON p.id = g.product_id
    WHERE g.organization_id = p_org_id
      AND p.organization_id = p_org_id
      AND p.parent_product_id IS NULL
      AND g.name ILIKE '%' || p_search || '%'
    UNION
    SELECT g.product_id
    FROM public.product_modifiers m
    JOIN public.product_modifier_groups g ON g.id = m.group_id
    JOIN public.products p ON p.id = g.product_id
    WHERE g.organization_id = p_org_id
      AND p.organization_id = p_org_id
      AND p.parent_product_id IS NULL
      AND m.is_active = true
      AND m.name ILIKE '%' || p_search || '%'
  ),
  ranked AS (
    SELECT
      p.id AS product_id,
      (pf.product_id IS NOT NULL) AS is_favorite,
      COALESCE(si.sales_count, 0) AS sales_count_90d
    FROM public.products p
    LEFT JOIN public.product_favorites pf
      ON pf.product_id = p.id AND pf.organization_id = p.organization_id
    LEFT JOIN (
      SELECT si.product_id, SUM(si.quantity)::bigint AS sales_count
      FROM public.sale_items si
      JOIN public.sales s ON s.id = si.sale_id
      WHERE s.organization_id = p_org_id
        AND si.created_at >= v_sales_window
        AND s.status <> 'cancelled'
      GROUP BY si.product_id
    ) si ON si.product_id = p.id
    WHERE p.organization_id = p_org_id
      AND (p_status = 'all' OR p.status = p_status)
      AND (p_include_variants OR p.parent_product_id IS NULL)
      AND (p_category_id IS NULL OR p.category_id = p_category_id)
      AND (
        NOT v_has_search OR p.id IN (SELECT id FROM matched_ids)
      )
  )
  SELECT
    r.product_id,
    COUNT(*) OVER () AS total_count,
    r.is_favorite,
    r.sales_count_90d
  FROM ranked r
  ORDER BY r.is_favorite DESC, r.sales_count_90d DESC, r.product_id ASC
  LIMIT p_limit OFFSET v_offset;
END;
$$;


ALTER FUNCTION "public"."pos_product_ranking"("p_org_id" integer, "p_search" "text", "p_category_id" integer, "p_status" "text", "p_include_variants" boolean, "p_page" integer, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prepare_invitation_email"("p_email" "text", "p_organization_id" integer, "p_role_id" integer, "p_invitation_code" "text") RETURNS "json"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  org_name text;
  role_name text;
  invite_url text;
  current_user_name text;
  result json;
BEGIN
  -- Verificar que el usuario actual tenga permisos
  IF NOT EXISTS (
    SELECT 1 FROM organization_members 
    WHERE user_id = auth.uid() 
    AND organization_id = p_organization_id 
    AND (is_super_admin = true OR role_id = 2)
    AND is_active = true
  ) THEN
    RETURN json_build_object('error', 'No tienes permisos para enviar invitaciones en esta organización');
  END IF;

  -- Obtener nombre de la organización
  SELECT name INTO org_name
  FROM organizations 
  WHERE id = p_organization_id;

  -- Obtener nombre del rol
  SELECT name INTO role_name
  FROM roles 
  WHERE id = p_role_id;

  -- Obtener nombre del usuario actual
  SELECT COALESCE(first_name || ' ' || last_name, email) INTO current_user_name
  FROM profiles 
  WHERE id = auth.uid();

  -- Construir URL de invitación
  invite_url := 'https://go-admin-erp.vercel.app/auth/invite?code=' || p_invitation_code;

  -- Preparar datos para el email
  result := json_build_object(
    'success', true,
    'email_data', json_build_object(
      'to_email', p_email,
      'organization_name', COALESCE(org_name, 'la organización'),
      'role_name', COALESCE(role_name, 'miembro'),
      'invite_url', invite_url,
      'invited_by', COALESCE(current_user_name, 'un administrador'),
      'invitation_code', p_invitation_code
    )
  );

  RETURN result;
END;
$$;


ALTER FUNCTION "public"."prepare_invitation_email"("p_email" "text", "p_organization_id" integer, "p_role_id" integer, "p_invitation_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_credit_note"("invoice_id_param" "uuid", "credit_note_amount" numeric) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  ar_record RECORD;
BEGIN
  -- Buscar la cuenta por cobrar asociada
  SELECT * INTO ar_record FROM accounts_receivable WHERE invoice_id = invoice_id_param;
  
  IF NOT FOUND THEN
    -- Si no existe cuenta por cobrar, crearla primero
    PERFORM create_account_receivable(invoice_id_param);
    SELECT * INTO ar_record FROM accounts_receivable WHERE invoice_id = invoice_id_param;
  END IF;
  
  -- Actualizar el balance restando el monto de la nota de crédito
  UPDATE accounts_receivable
  SET 
    balance = GREATEST(0, balance - credit_note_amount), -- Nunca permitir balance negativo
    updated_at = NOW(),
    status = CASE
      WHEN balance - credit_note_amount <= 0 THEN 'paid'
      WHEN due_date < NOW() THEN 'overdue'
      ELSE 'current'
    END
  WHERE id = ar_record.id;
  
  RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."process_credit_note"("invoice_id_param" "uuid", "credit_note_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recalc_product_review_stats"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
declare
  affected_product_id integer;
begin
  affected_product_id := coalesce(new.product_id, old.product_id);
  if affected_product_id is not null then
    update public.products set
      rating_avg = (
        select round(avg(rating)::numeric, 2)
        from public.product_reviews
        where product_id = affected_product_id
          and status = 'approved'
      ),
      reviews_count = (
        select count(*)
        from public.product_reviews
        where product_id = affected_product_id
          and status = 'approved'
      )
    where id = affected_product_id;
  end if;
  return coalesce(new, old);
end;
$$;


