CREATE OR REPLACE FUNCTION "public"."refund_ai_credits"("p_org_id" integer, "p_amount" integer) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_remaining integer;
  v_purchased integer;
  v_cap       integer;
  v_ceiling   integer;
  v_amount    integer := GREATEST(COALESCE(p_amount, 0), 0);
  v_target    integer;
BEGIN
  IF p_org_id IS NULL THEN
    RETURN false;
  END IF;

  SELECT credits_remaining, COALESCE(purchased_credits, 0)
    INTO v_remaining, v_purchased
    FROM public.ai_settings
   WHERE organization_id = p_org_id
   FOR UPDATE; -- mismo bloqueo de fila que decrement_ai_credits

  IF NOT FOUND THEN
    RETURN false; -- sin ai_settings no hay saldo que reembolsar
  END IF;

  IF v_amount = 0 THEN
    RETURN true;
  END IF;

  v_remaining := COALESCE(v_remaining, 0);
  v_target    := v_remaining + v_amount;

  SELECT pl.ai_credits_max_rollover
    INTO v_cap
    FROM public.organizations o
    JOIN public.plans pl ON pl.id = o.plan_id
   WHERE o.id = p_org_id;

  IF v_cap IS NOT NULL THEN
    v_ceiling := v_cap + v_purchased;
    -- Solo se aplica si el saldo actual todavía no supera el techo.
    IF v_remaining <= v_ceiling THEN
      v_target := LEAST(v_target, v_ceiling);
    END IF;
  END IF;

  UPDATE public.ai_settings
     SET credits_remaining = v_target,
         updated_at = now()
   WHERE organization_id = p_org_id;

  RETURN true;
END;
$$;


ALTER FUNCTION "public"."refund_ai_credits"("p_org_id" integer, "p_amount" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."refund_ai_credits"("p_org_id" integer, "p_amount" integer) IS 'Reembolsa créditos de IA tras un fallo del proveedor. Atómica (FOR UPDATE sobre ai_settings). Tope = plans.ai_credits_max_rollover + ai_settings.purchased_credits, aplicado solo si el saldo actual no lo supera ya. p_amount<=0 = no-op. Devuelve false si la org no tiene ai_settings. Solo service_role.';



CREATE OR REPLACE FUNCTION "public"."register_price_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    user_name TEXT;
BEGIN
    -- Obtener el nombre del usuario
    SELECT first_name || ' ' || last_name INTO user_name 
    FROM public.profiles 
    WHERE id = auth.uid();

    -- Solo registrar si el precio ha cambiado
    IF OLD.price IS DISTINCT FROM NEW.price THEN
        INSERT INTO public.price_history (
            product_id,
            old_price,
            new_price,
            changed_by_id,
            notes
        ) VALUES (
            NEW.id,
            OLD.price,
            NEW.price,
            auth.uid(),
            'Precio actualizado por ' || COALESCE(user_name, 'usuario del sistema')
        );
    END IF;
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."register_price_change"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."register_price_change"() IS 'Registra automáticamente los cambios de precio de productos en la tabla price_history';



CREATE OR REPLACE FUNCTION "public"."register_quick_reply_use"("p_quick_reply_id" "uuid", "p_conversation_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_org integer;
  v_member bigint;
begin
  select organization_id into v_org from quick_replies where id = p_quick_reply_id;
  if v_org is null then
    raise exception 'Respuesta rapida no encontrada';
  end if;

  select id into v_member
  from organization_members
  where user_id = auth.uid() and organization_id = v_org and is_active = true
  order by id limit 1;

  if v_member is null then
    raise exception 'El usuario no pertenece a la organizacion de la respuesta rapida';
  end if;

  update quick_replies
     set usage_count = coalesce(usage_count, 0) + 1, updated_at = now()
   where id = p_quick_reply_id;

  insert into quick_replies_usage (quick_reply_id, member_id, conversation_id)
  values (p_quick_reply_id, v_member, p_conversation_id);
end;
$$;


