CREATE OR REPLACE FUNCTION "public"."register_shared_image"("p_image_url" "text", "p_storage_path" "text", "p_file_name" "text", "p_file_size" integer, "p_mime_type" "text", "p_dimensions" "jsonb", "p_is_public" boolean DEFAULT false, "p_tags" "text"[] DEFAULT '{}'::"text"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_organization_id INTEGER;
    v_image_id INTEGER;
BEGIN
    -- Obtener la organización del token JWT
    v_organization_id := (auth.jwt() ->> 'organization_id')::INTEGER;
    
    -- Insertar la imagen
    INSERT INTO shared_images (
        image_url, 
        storage_path, 
        file_name, 
        file_size, 
        mime_type, 
        dimensions, 
        organization_id, 
        is_public, 
        tags
    ) VALUES (
        p_image_url, 
        p_storage_path, 
        p_file_name, 
        p_file_size, 
        p_mime_type, 
        p_dimensions, 
        v_organization_id, 
        p_is_public, 
        p_tags
    )
    RETURNING id INTO v_image_id;
    
    -- Crear automáticamente una asociación para la organización que sube la imagen
    INSERT INTO organization_images (organization_id, shared_image_id, permission_level)
    VALUES (v_organization_id, v_image_id, 'owner');
    
    RETURN v_image_id;
END;
$$;


