CREATE OR REPLACE FUNCTION "public"."reserve_stock_for_web_order"("p_organization_id" integer, "p_branch_id" integer, "p_order_id" "uuid", "p_items" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_item jsonb;
  v_available numeric;
  v_shortages jsonb := '[]'::jsonb;
  v_qty numeric;
  v_pid integer;
BEGIN
  -- 1) Bloquear filas en orden determinista de product_id (evita deadlocks)
  FOR v_item IN
    SELECT * FROM jsonb_array_elements(p_items)
    ORDER BY (value->>'product_id')::int
  LOOP
    v_pid := (v_item->>'product_id')::int;
    v_qty := (v_item->>'quantity')::numeric;

    SELECT COALESCE(qty_on_hand, 0) - COALESCE(qty_reserved, 0)
    INTO v_available
    FROM stock_levels
    WHERE branch_id = p_branch_id
      AND product_id = v_pid
      AND lot_id IS NULL
    FOR UPDATE;

    IF v_available IS NULL OR v_available < v_qty THEN
      v_shortages := v_shortages || jsonb_build_object(
        'product_id', v_pid,
        'available', COALESCE(v_available, 0),
        'requested', v_qty
      );
    END IF;
  END LOOP;

  -- 2) Todo o nada: si hay shortages, no reservar nada
  IF jsonb_array_length(v_shortages) > 0 THEN
    RETURN jsonb_build_object('ok', false, 'shortages', v_shortages);
  END IF;

  -- 3) Reservar: incrementar qty_reserved
  FOR v_item IN
    SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    v_pid := (v_item->>'product_id')::int;
    v_qty := (v_item->>'quantity')::numeric;

    UPDATE stock_levels
       SET qty_reserved = COALESCE(qty_reserved, 0) + v_qty,
           updated_at = now()
     WHERE branch_id = p_branch_id
       AND product_id = v_pid
       AND lot_id IS NULL;
  END LOOP;

  RETURN jsonb_build_object('ok', true);
END;
$$;


ALTER FUNCTION "public"."reserve_stock_for_web_order"("p_organization_id" integer, "p_branch_id" integer, "p_order_id" "uuid", "p_items" "jsonb") OWNER TO "postgres";


