CREATE OR REPLACE FUNCTION "public"."revoke_other_sessions"("current_session_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  current_token_id bigint;
BEGIN
  -- Obtener el token ID asociado con la sesión actual
  SELECT refresh_token_id INTO current_token_id
  FROM public.user_devices
  WHERE id = current_session_id AND user_id = auth.uid();

  -- Eliminar todos los tokens excepto el actual
  IF current_token_id IS NOT NULL THEN
    DELETE FROM auth.refresh_tokens
    WHERE user_id = auth.uid()
    AND id != current_token_id;
    
    -- Las entradas en user_devices se eliminarán por trigger cascade
  END IF;
END;
$$;


ALTER FUNCTION "public"."revoke_other_sessions"("current_session_id" "uuid") OWNER TO "postgres";


