  -- Verificar que el usuario solo revoque sus propios tokens
  DELETE FROM auth.refresh_tokens
  WHERE id = token_id 
  AND user_id = auth.uid();

  -- No es necesario borrar de user_devices, se eliminará por trigger cascade
END;
$$;


