CREATE OR REPLACE FUNCTION "public"."save_exchange_rates"("org_id" integer, "base_currency_id" "uuid", "rates" "jsonb", "source" "text" DEFAULT 'openexchangerates'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  currency_record RECORD;
  rate_value NUMERIC;
  updated_count INTEGER := 0;
  skipped_count INTEGER := 0;
  rate_date DATE := CURRENT_DATE;
BEGIN
  -- Iterar sobre todas las monedas de la organización
  FOR currency_record IN 
    SELECT c.id, c.code, c.template_code
    FROM currencies c
    WHERE c.organization_id = org_id
      AND c.id <> base_currency_id  -- Excluir la moneda base
  LOOP
    -- Verificar si tenemos una tasa para esta moneda
    IF rates ? currency_record.template_code THEN
      -- Extraer el valor de la tasa desde el JSON
      rate_value := (rates ->> currency_record.template_code)::NUMERIC;
      
      -- Verificar si ya existe una tasa para esta fecha
      BEGIN
        -- Intentar actualizar primero
        WITH updated AS (
          UPDATE currency_rates
          SET rate = rate_value,
              source = source,
              api_data = rates,
              updated_at = CURRENT_TIMESTAMP
          WHERE currency_id = currency_record.id
            AND organization_id = org_id
            AND rate_date = rate_date
          RETURNING id
        )
        SELECT COUNT(*) INTO updated_count FROM updated;
        
        -- Si no se actualizó ninguna fila, insertar nueva
        IF updated_count = 0 THEN
          INSERT INTO currency_rates (
            organization_id,
            currency_id,
            code,
            rate_date,
            rate,
            source,
            api_data,
            created_at,
            updated_at
          ) VALUES (
            org_id,
            currency_record.id,
            currency_record.code,
            rate_date,
            rate_value,
            source,
            rates,
            CURRENT_TIMESTAMP,
            CURRENT_TIMESTAMP
          );
          updated_count := updated_count + 1;
        END IF;
      EXCEPTION WHEN OTHERS THEN
        skipped_count := skipped_count + 1;
        RAISE NOTICE 'Error al actualizar tasa para %: %', currency_record.code, SQLERRM;
      END;
    ELSE
      skipped_count := skipped_count + 1;
    END IF;
  END LOOP;
  
  RETURN jsonb_build_object(
    'success', true,
    'message', 'Tasas de cambio actualizadas exitosamente',
    'updated_count', updated_count,
    'skipped_count', skipped_count
  );
END;
$$;


ALTER FUNCTION "public"."save_exchange_rates"("org_id" integer, "base_currency_id" "uuid", "rates" "jsonb", "source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_exchange_rates"("org_id" integer, "base_currency_id" "uuid", "rates" "jsonb", "source" "text" DEFAULT 'openexchangerates'::"text", "api_timestamp" bigint DEFAULT NULL::bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  current_date date := CURRENT_DATE;
  updated_count integer := 0;
  skipped_count integer := 0;
  currency_record RECORD;
  base_currency_code VARCHAR(3);
BEGIN
  -- Obtener el código de la moneda base
  SELECT code INTO base_currency_code
  FROM currencies
  WHERE id = base_currency_id;
  
  IF base_currency_code IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'No se encontró la moneda base especificada',
      'updated_count', 0
    );
  END IF;
  
  -- Preparar los datos de la API para el campo JSONB
  -- Si el timestamp es NULL, usar el tiempo actual
  IF api_timestamp IS NULL THEN
    api_timestamp := EXTRACT(EPOCH FROM CURRENT_TIMESTAMP)::bigint;
  END IF;
  
  -- Para cada moneda en rates, actualizar o insertar tasa
  FOR currency_record IN 
    SELECT c.id, c.code, c.template_code
    FROM currencies c 
    WHERE c.organization_id = org_id 
    AND c.id <> base_currency_id  -- No insertar la tasa para la moneda base
    AND (c.auto_update = true OR source <> 'openexchangerates') -- Solo actualizar automáticamente si está configurado
  LOOP
    -- Solo si existe la tasa en el objeto rates y usando template_code como clave
    IF rates ? currency_record.template_code THEN
      INSERT INTO currency_rates(
        organization_id, currency_id, code, rate_date, 
        rate, source, base_currency_code, api_data
      )
      VALUES (
        org_id, 
        currency_record.id, 
        currency_record.code, 
        current_date, 
        (rates->>currency_record.template_code)::numeric, 
        source, 
        base_currency_code,
        jsonb_build_object('timestamp', api_timestamp, 'data', rates)
      )
      ON CONFLICT (organization_id, code, rate_date)
      DO UPDATE SET 
        rate = EXCLUDED.rate,
        updated_at = now(),
        source = EXCLUDED.source,
        base_currency_code = EXCLUDED.base_currency_code,
        api_data = EXCLUDED.api_data;
        
      updated_count := updated_count + 1;
    ELSE
      skipped_count := skipped_count + 1;
    END IF;
  END LOOP;
  
  RETURN jsonb_build_object(
    'success', true,
    'message', 'Tasas de cambio actualizadas exitosamente',
    'updated_count', updated_count,
    'skipped_count', skipped_count,
    'base_currency', base_currency_code
  );
END;
$$;


ALTER FUNCTION "public"."save_exchange_rates"("org_id" integer, "base_currency_id" "uuid", "rates" "jsonb", "source" "text", "api_timestamp" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_exchange_rates"("rates" "jsonb", "rate_date" "date", "source" "text" DEFAULT 'openexchangerates'::"text", "api_timestamp" bigint DEFAULT NULL::bigint, "base_currency_code" "text" DEFAULT 'USD'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  org_record RECORD;
  currency_code TEXT;
  rate_value NUMERIC;
  updated_count INTEGER := 0;
  skipped_count INTEGER := 0;
BEGIN
  -- Para cada organización en organization_currencies
  FOR org_record IN 
    SELECT DISTINCT organization_id 
    FROM organization_currencies
    WHERE auto_update = true
  LOOP
    -- Para cada moneda en rates
    FOR currency_code, rate_value IN 
      SELECT key::text, (value::text)::numeric FROM jsonb_each(rates)
    LOOP
      -- Verificar si existe la moneda en el catálogo global de currencies
      IF EXISTS (SELECT 1 FROM currencies WHERE code = currency_code) THEN
        BEGIN
          -- Primero eliminar tasa anterior si existe (mismo código y fecha)
          DELETE FROM currency_rates 
          WHERE code = currency_code 
            AND rate_date = rate_date
            AND organization_id = org_record.organization_id;
          
          -- Insertar la tasa para esta organización
          INSERT INTO currency_rates (
            organization_id,
            code,
            rate_date,
            rate,
            source,
            base_currency_code,
            api_data
          ) VALUES (
            org_record.organization_id,
            currency_code,
            rate_date,
            rate_value,
            source,
            base_currency_code,
            jsonb_build_object(
              'timestamp', api_timestamp,
              'base', base_currency_code,
              'code', currency_code,
              'rate', rate_value
            )
          );
          
          updated_count := updated_count + 1;
        EXCEPTION WHEN OTHERS THEN
          skipped_count := skipped_count + 1;
        END;
      ELSE
        skipped_count := skipped_count + 1;
      END IF;
    END LOOP;
  END LOOP;
  
  RETURN jsonb_build_object(
    'success', true,
    'message', 'Tasas de cambio globales actualizadas exitosamente',
    'updated_count', updated_count,
    'skipped_count', skipped_count,
    'base_currency', base_currency_code
  );
END;
$$;


ALTER FUNCTION "public"."save_exchange_rates"("rates" "jsonb", "rate_date" "date", "source" "text", "api_timestamp" bigint, "base_currency_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_exchange_rates"("org_id" integer, "base_currency_id" "uuid", "rates" "jsonb", "source" "text" DEFAULT 'openexchangerates'::"text", "api_timestamp" bigint DEFAULT NULL::bigint, "rate_date" "date" DEFAULT CURRENT_DATE) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  currency_record RECORD;
  rate_value NUMERIC;
  updated_count INTEGER := 0;
  skipped_count INTEGER := 0;
  base_currency_code TEXT;
BEGIN
  -- Obtener el código de la moneda base
  SELECT code INTO base_currency_code 
  FROM currencies 
  WHERE id = base_currency_id
  LIMIT 1;

  -- Si no se encuentra la moneda base, retornar error
  IF base_currency_code IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'No se pudo encontrar el código de la moneda base',
      'updated_count', 0,
      'skipped_count', 0
    );
  END IF;

  -- Registrar la operación para depuración
  RAISE NOTICE 'Guardando tasas para organización % con base % para fecha %', 
               org_id, base_currency_code, rate_date;
  
  -- Iterar sobre todas las monedas de la organización
  FOR currency_record IN 
    SELECT c.id, c.code, c.template_code
    FROM currencies c
    WHERE c.organization_id = org_id
      AND c.id <> base_currency_id  -- Excluir la moneda base
  LOOP
    -- Verificar si tenemos una tasa para esta moneda
    IF rates ? currency_record.template_code THEN
      -- Extraer el valor de la tasa desde el JSON
      rate_value := (rates ->> currency_record.template_code)::NUMERIC;
      
      -- Verificar si ya existe una tasa para esta moneda y fecha
      BEGIN
        -- Eliminar primero cualquier tasa existente para evitar duplicados
        DELETE FROM currency_rates
        WHERE organization_id = org_id
          AND currency_id = currency_record.id
          AND rate_date = rate_date;
          
        -- Insertar la nueva tasa
        INSERT INTO currency_rates (
          organization_id,
          currency_id,
          code,
          rate_date,
          rate,
          source,
          base_currency_code,
          api_data,
          created_at,
          updated_at
        ) VALUES (
          org_id,
          currency_record.id,
          currency_record.code,
          rate_date,
          rate_value,
          source,
          base_currency_code,
          jsonb_build_object(
            'timestamp', api_timestamp,
            'base', base_currency_code
          ),
          CURRENT_TIMESTAMP,
          CURRENT_TIMESTAMP
        );
        
        updated_count := updated_count + 1;
      EXCEPTION WHEN OTHERS THEN
        skipped_count := skipped_count + 1;
        RAISE NOTICE 'Error al actualizar tasa para %: %', currency_record.code, SQLERRM;
      END;
    ELSE
      skipped_count := skipped_count + 1;
    END IF;
  END LOOP;
  
  RETURN jsonb_build_object(
    'success', true,
    'message', 'Tasas de cambio actualizadas exitosamente',
    'updated_count', updated_count,
    'skipped_count', skipped_count,
    'base_currency_code', base_currency_code
  );
END;
$$;


