CREATE OR REPLACE FUNCTION "public"."save_exchange_rates"("org_id" integer, "base_currency_id" "uuid", "rates" "jsonb", "source" "text" DEFAULT 'openexchangerates'::"text", "api_timestamp" bigint DEFAULT NULL::bigint, "rate_date" "date" DEFAULT CURRENT_DATE, "base_currency_code" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  currency_record RECORD;
  rate_value NUMERIC;
  updated_count INTEGER := 0;
  skipped_count INTEGER := 0;
  base_code TEXT;
BEGIN
  -- Obtener el código de moneda base si no se proporcionó
  IF base_currency_code IS NULL THEN
    SELECT code INTO base_code 
    FROM currencies 
    WHERE id = base_currency_id
    LIMIT 1;
  ELSE
    base_code := base_currency_code;
  END IF;

  IF base_code IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'No se pudo encontrar el código de la moneda base',
      'updated_count', 0,
      'skipped_count', 0
    );
  END IF;
  
  RAISE NOTICE 'Guardando tasas para organización % con base % para fecha %', 
               org_id, base_code, rate_date;
               
  -- Iterar sobre todas las monedas de la organización
  FOR currency_record IN 
    SELECT c.id, c.code, c.template_code
    FROM currencies c
    WHERE c.organization_id = org_id
      AND c.id <> base_currency_id  -- Excluir la moneda base
  LOOP
    -- Verificar si tenemos una tasa para esta moneda
    IF rates ? currency_record.template_code THEN
      -- Extraer el valor de la tasa desde el JSON
      rate_value := (rates ->> currency_record.template_code)::NUMERIC;
      
      -- Verificar si ya existe una tasa para esta moneda y fecha
      BEGIN
        -- Eliminar primero cualquier tasa existente para evitar duplicados
        DELETE FROM currency_rates
        WHERE organization_id = org_id
          AND currency_id = currency_record.id
          AND rate_date = rate_date;
          
        -- Insertar la nueva tasa
        INSERT INTO currency_rates (
          organization_id,
          currency_id,
          code,
          rate_date,
          rate,
          source,
          base_currency_code,
          api_data,
          created_at,
          updated_at
        ) VALUES (
          org_id,
          currency_record.id,
          currency_record.code,
          rate_date,
          rate_value,
          source,
          base_code,
          jsonb_build_object(
            'timestamp', api_timestamp,
            'base', base_code,
            'rates', rates
          ),
          CURRENT_TIMESTAMP,
          CURRENT_TIMESTAMP
        );
        
        updated_count := updated_count + 1;
      EXCEPTION WHEN OTHERS THEN
        skipped_count := skipped_count + 1;
        RAISE NOTICE 'Error al actualizar tasa para %: %', currency_record.code, SQLERRM;
      END;
    ELSE
      skipped_count := skipped_count + 1;
    END IF;
  END LOOP;
  
  RETURN jsonb_build_object(
    'success', true,
    'message', 'Tasas de cambio actualizadas exitosamente',
    'updated_count', updated_count,
    'skipped_count', skipped_count,
    'base_currency_code', base_code
  );
END;
$$;


ALTER FUNCTION "public"."save_exchange_rates"("org_id" integer, "base_currency_id" "uuid", "rates" "jsonb", "source" "text", "api_timestamp" bigint, "rate_date" "date", "base_currency_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_global_exchange_rates"("rates" "jsonb", "source" "text" DEFAULT 'openexchangerates'::"text", "api_timestamp" bigint DEFAULT NULL::bigint, "rate_date" "date" DEFAULT CURRENT_DATE, "base_currency_code" "text" DEFAULT 'USD'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  currency_code TEXT;
  rate_value NUMERIC;
  org_id INTEGER;
  updated_count INTEGER := 0;
  skipped_count INTEGER := 0;
BEGIN
  -- Validar que base_currency_code no sea nulo
  IF base_currency_code IS NULL THEN
    base_currency_code := 'USD';
  END IF;
  
  -- Si no se proporciona timestamp, usar el actual
  IF api_timestamp IS NULL THEN
    api_timestamp := EXTRACT(EPOCH FROM CURRENT_TIMESTAMP)::bigint;
  END IF;

  -- Obtener todas las organizaciones
  FOR org_id IN SELECT id FROM organizations
  LOOP
    -- Para cada moneda en rates
    FOR currency_code, rate_value IN 
      SELECT key, (value::text)::numeric FROM jsonb_each(rates)
    LOOP
      -- Verificar si existe la moneda en currencies (tabla normalizada)
      IF EXISTS (SELECT 1 FROM currencies WHERE code = currency_code AND is_active = true) THEN
        BEGIN
          -- Primero eliminar tasa anterior si existe (mismo código y fecha)
          DELETE FROM currency_rates 
          WHERE code = currency_code 
            AND rate_date = rate_date
            AND organization_id = org_id;
          
          -- Insertar la tasa para esta organización
          INSERT INTO currency_rates (
            organization_id,
            code,
            rate_date,
            rate,
            source,
            base_currency_code,
            api_data
          ) VALUES (
            org_id,
            currency_code,
            rate_date,
            rate_value,
            source,
            base_currency_code,
            jsonb_build_object(
              'timestamp', api_timestamp,
              'base', base_currency_code,
              'code', currency_code,
              'rate', rate_value
            )
          );
          
          updated_count := updated_count + 1;
        EXCEPTION WHEN OTHERS THEN
          skipped_count := skipped_count + 1;
        END;
      ELSE
        skipped_count := skipped_count + 1;
      END IF;
    END LOOP;
  END LOOP;
  
  RETURN jsonb_build_object(
    'success', true,
    'message', 'Tasas de cambio globales actualizadas exitosamente',
    'updated_count', updated_count,
    'skipped_count', skipped_count,
    'base_currency', base_currency_code
  );
END;
$$;


