CREATE OR REPLACE FUNCTION "public"."save_user_notification_preferences"("p_user_id" "uuid", "p_channel" "text", "p_mute" boolean, "p_allowed_types" "text"[], "p_dnd_start" time without time zone, "p_dnd_end" time without time zone) RETURNS "json"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  result json;
BEGIN
  -- Intentamos actualizar primero
  UPDATE public.user_notification_preferences
  SET 
    mute = p_mute,
    allowed_types = p_allowed_types,
    dnd_start = p_dnd_start,
    dnd_end = p_dnd_end,
    updated_at = now()
  WHERE user_id = p_user_id AND channel = p_channel
  RETURNING json_build_object(
    'user_id', user_id,
    'channel', channel,
    'mute', mute,
    'allowed_types', allowed_types,
    'dnd_start', dnd_start,
    'dnd_end', dnd_end,
    'created_at', created_at,
    'updated_at', updated_at
  ) INTO result;

  -- Si no actualizamos nada, insertamos un nuevo registro
  IF result IS NULL THEN
    INSERT INTO public.user_notification_preferences (
      user_id, 
      channel, 
      mute, 
      allowed_types, 
      dnd_start, 
      dnd_end, 
      created_at, 
      updated_at
    )
    VALUES (
      p_user_id, 
      p_channel, 
      p_mute, 
      p_allowed_types, 
      p_dnd_start, 
      p_dnd_end, 
      now(), 
      now()
    )
    RETURNING json_build_object(
      'user_id', user_id,
      'channel', channel,
      'mute', mute,
      'allowed_types', allowed_types,
      'dnd_start', dnd_start,
      'dnd_end', dnd_end,
      'created_at', created_at,
      'updated_at', updated_at
    ) INTO result;
  END IF;
  
  RETURN result;
END;
$$;


ALTER FUNCTION "public"."save_user_notification_preferences"("p_user_id" "uuid", "p_channel" "text", "p_mute" boolean, "p_allowed_types" "text"[], "p_dnd_start" time without time zone, "p_dnd_end" time without time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_knowledge_fragments"("p_organization_id" integer, "p_query_embedding" "public"."vector", "p_limit" integer DEFAULT 5, "p_similarity_threshold" numeric DEFAULT 0.7) RETURNS TABLE("fragment_id" "uuid", "title" "text", "content" "text", "similarity" numeric, "usage_count" integer, "priority" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    kf.id,
    kf.title,
    kf.content,
    ROUND((1 - (ke.embedding <=> p_query_embedding))::numeric, 4) as similarity,
    kf.usage_count,
    kf.priority
  FROM knowledge_embeddings ke
  INNER JOIN knowledge_fragments kf ON ke.fragment_id = kf.id
  WHERE kf.organization_id = p_organization_id
    AND kf.is_active = true
    AND (1 - (ke.embedding <=> p_query_embedding)) >= p_similarity_threshold
  ORDER BY 
    (1 - (ke.embedding <=> p_query_embedding)) DESC,
    kf.priority DESC,
    kf.usage_count DESC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION "public"."search_knowledge_fragments"("p_organization_id" integer, "p_query_embedding" "public"."vector", "p_limit" integer, "p_similarity_threshold" numeric) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."search_knowledge_fragments"("p_organization_id" integer, "p_query_embedding" "public"."vector", "p_limit" integer, "p_similarity_threshold" numeric) IS 'Búsqueda semántica de fragmentos de conocimiento usando embeddings (RAG)';



CREATE OR REPLACE FUNCTION "public"."send_invitation_email"("p_email" "text", "p_organization_id" integer, "p_role_id" integer, "p_invitation_code" "text") RETURNS "json"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  org_name text;
  role_name text;
  invite_url text;
  current_user_name text;
  temp_user_id uuid;
  result json;
BEGIN
  -- Verificar que el usuario actual tenga permisos
  IF NOT EXISTS (
    SELECT 1 FROM organization_members 
    WHERE user_id = auth.uid() 
    AND organization_id = p_organization_id 
    AND (is_super_admin = true OR role_id = 2)
    AND is_active = true
  ) THEN
    RETURN json_build_object('error', 'No tienes permisos para enviar invitaciones en esta organización');
  END IF;

  -- Obtener nombre de la organización
  SELECT name INTO org_name FROM organizations WHERE id = p_organization_id;

  -- Obtener nombre del rol
  SELECT name INTO role_name FROM roles WHERE id = p_role_id;

  -- Obtener nombre del usuario actual
  SELECT COALESCE(first_name || ' ' || last_name, email) INTO current_user_name
  FROM profiles WHERE id = auth.uid();

  -- Construir URL de invitación
  invite_url := 'https://go-admin-erp.vercel.app/auth/invite?code=' || p_invitation_code;

  BEGIN
    -- Intentar usar el servicio de invitación nativo de Supabase
    -- Crear un usuario temporal en auth.users que activará el envío de email
    temp_user_id := gen_random_uuid();
    
    -- Insertar en auth.users con invited_at para activar el email de invitación
    PERFORM auth.email_verification_request(p_email);
    
    result := json_build_object(
      'success', true,
      'message', 'Invitación enviada exitosamente',
      'email_data', json_build_object(
        'to_email', p_email,
        'organization_name', COALESCE(org_name, 'la organización'),
        'role_name', COALESCE(role_name, 'miembro'),
        'invite_url', invite_url,
        'invited_by', COALESCE(current_user_name, 'un administrador')
      )
    );

  EXCEPTION WHEN OTHERS THEN
    -- Si falla el envío automático, devolver datos para envío manual
    result := json_build_object(
      'success', false,
      'message', 'Email preparado para envío manual',
      'email_data', json_build_object(
        'to_email', p_email,
        'organization_name', COALESCE(org_name, 'la organización'),
        'role_name', COALESCE(role_name, 'miembro'),
        'invite_url', invite_url,
        'invited_by', COALESCE(current_user_name, 'un administrador'),
        'manual_send_required', true
      ),
      'error_detail', SQLERRM
    );
  END;

  RETURN result;
END;
$$;


