CREATE OR REPLACE FUNCTION "public"."set_currency_auto_update"("p_org_id" integer, "p_currency_code" character varying, "p_auto_update" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  affected_rows integer;
BEGIN
  UPDATE currencies
  SET 
    auto_update = p_auto_update,
    updated_at = now()
  WHERE 
    organization_id = p_org_id 
    AND code = p_currency_code;
    
  GET DIAGNOSTICS affected_rows = ROW_COUNT;
  
  IF affected_rows = 0 THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'No se encontró la moneda especificada'
    );
  END IF;
  
  RETURN jsonb_build_object(
    'success', true,
    'message', 'Configuración de actualización automática actualizada correctamente'
  );
END;
$$;


