CREATE OR REPLACE FUNCTION "public"."set_organization_base_currency"("p_organization_id" integer, "p_currency_code" character varying) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  -- Primero, quitar moneda base de todas las monedas de la organización
  UPDATE organization_currencies
  SET is_base = FALSE
  WHERE organization_id = p_organization_id;
  
  -- Luego, establecer la nueva moneda base
  UPDATE organization_currencies
  SET is_base = TRUE
  WHERE organization_id = p_organization_id AND currency_code = p_currency_code;
  
  RETURN TRUE;
END;
$$;


