CREATE OR REPLACE FUNCTION "public"."setup_organization_defaults"("org_id" integer, "country_code" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    country_record countries%ROWTYPE;
    tax_count INTEGER := 0;
    payment_count INTEGER := 0;
BEGIN
    -- 1. Verificar que el país existe
    SELECT * INTO country_record
    FROM countries 
    WHERE code = setup_organization_defaults.country_code;
    
    IF NOT FOUND THEN
        RETURN 'ERROR: País con código ' || country_code || ' no encontrado';
    END IF;
    
    -- 2. Actualizar país de la organización
    UPDATE organizations 
    SET country_code = setup_organization_defaults.country_code,
        updated_at = NOW()
    WHERE id = org_id;
    
    -- 3. Configurar moneda base
    DELETE FROM organization_currencies WHERE organization_id = org_id AND is_base = true;
    INSERT INTO organization_currencies (organization_id, currency_code, is_base, auto_update)
    VALUES (org_id, country_record.default_currency_code, true, true);
    
    -- 4. Configurar impuestos del país
    DELETE FROM organization_taxes WHERE organization_id = org_id;
    INSERT INTO organization_taxes (organization_id, template_id, name, rate, description, is_active, is_default)
    SELECT org_id, tt.id, tt.name, tt.rate, tt.description, true, false
    FROM tax_templates tt
    WHERE tt.country = setup_organization_defaults.country_code
    AND (tt.valid_to IS NULL OR tt.valid_to > NOW());
    GET DIAGNOSTICS tax_count = ROW_COUNT;
    
    -- 5. Configurar métodos de pago: solo manuales activos + wompi inactivo
    DELETE FROM organization_payment_methods WHERE organization_id = org_id;
    
    -- 5a. Métodos manuales activos (cash, transfer, card)
    INSERT INTO organization_payment_methods (
        organization_id, payment_method_code, is_active, settings,
        show_on_website, website_display_name, website_display_order
    )
    SELECT 
        org_id, 
        cpm.payment_method_code, 
        true, 
        cpm.default_settings,
        CASE 
            WHEN cpm.payment_method_code IN ('cash', 'transfer') THEN true
            ELSE false
        END,
        CASE 
            WHEN cpm.payment_method_code = 'cash' THEN 'Pago Contraentrega'
            ELSE NULL
        END,
        cpm.display_order
    FROM country_payment_methods cpm
    WHERE cpm.country_code = setup_organization_defaults.country_code
    AND cpm.is_active = true AND cpm.is_recommended = true
    ORDER BY cpm.display_order;
    GET DIAGNOSTICS payment_count = ROW_COUNT;
    
    -- 5b. Wompi como método de integración (inactivo hasta que se conecte)
    INSERT INTO organization_payment_methods (
        organization_id, payment_method_code, is_active, settings,
        show_on_website, website_display_order
    )
    VALUES (org_id, 'wompi', false, '{}'::jsonb, false, 4)
    ON CONFLICT DO NOTHING;
    
    payment_count := payment_count + 1;
    
    RETURN 'SUCCESS: ' || country_record.name || ' - Moneda: ' || country_record.default_currency_code || 
           ', Impuestos: ' || tax_count || ', Métodos: ' || payment_count;
    
EXCEPTION
    WHEN OTHERS THEN
        RETURN 'ERROR: ' || SQLERRM;
END;
$$;


ALTER FUNCTION "public"."setup_organization_defaults"("org_id" integer, "country_code" "text") OWNER TO "postgres";


