CREATE OR REPLACE FUNCTION "public"."soft_delete_product"("p_product_id" integer) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_org_id integer;
  v_user_id uuid := auth.uid();
BEGIN
  -- Obtener organization_id del producto
  SELECT organization_id INTO v_org_id
  FROM products WHERE id = p_product_id;

  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Producto no encontrado';
  END IF;

  -- Verificar que el usuario pertenezca a la organización
  IF NOT EXISTS (
    SELECT 1 FROM organization_members
    WHERE user_id = v_user_id AND organization_id = v_org_id
  ) THEN
    RAISE EXCEPTION 'No tiene permisos para eliminar este producto';
  END IF;

  -- Realizar soft-delete
  UPDATE products
  SET status = 'deleted', updated_at = NOW()
  WHERE id = p_product_id
    AND organization_id = v_org_id;

  RETURN true;
END;
$$;


ALTER FUNCTION "public"."soft_delete_product"("p_product_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_ai_credits_on_subscription"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  plan_credits INTEGER;
  plan_model TEXT;
  plan_max_tokens INTEGER;
BEGIN
  -- Solo ejecutar si la suscripción está activa o en trial
  IF NEW.status IN ('active', 'trialing') THEN
    -- Obtener los valores del plan
    SELECT 
      COALESCE(ai_credits_monthly, 0),
      COALESCE(ai_model, 'gpt-4o-mini'),
      COALESCE(ai_max_tokens, 1000)
    INTO plan_credits, plan_model, plan_max_tokens
    FROM plans 
    WHERE id = NEW.plan_id;

    -- Insertar o actualizar ai_settings
    INSERT INTO ai_settings (
      organization_id, 
      credits_remaining, 
      credits_reset_at,
      model,
      max_tokens,
      provider,
      is_active
    )
    VALUES (
      NEW.organization_id,
      plan_credits,
      NOW(),
      plan_model,
      plan_max_tokens,
      'openai',
      true
    )
    ON CONFLICT (organization_id) 
    DO UPDATE SET 
      credits_remaining = CASE 
        -- Si el plan cambió a uno con más créditos, actualizar al máximo
        WHEN plan_credits > ai_settings.credits_remaining THEN plan_credits
        -- Si el plan cambió a uno con menos créditos, mantener los actuales (hasta que se agoten)
        ELSE ai_settings.credits_remaining
      END,
      model = plan_model,
      max_tokens = plan_max_tokens,
      is_active = true;
  END IF;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_ai_credits_on_subscription"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sync_ai_credits_on_subscription"() IS 'Sincroniza automáticamente los créditos de IA en ai_settings cuando se crea o actualiza una suscripción';



CREATE OR REPLACE FUNCTION "public"."sync_ai_credits_to_settings"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  -- Solo procesar cuando el status es 'completed'
  IF NEW.status = 'completed' THEN
    -- Insertar o actualizar ai_settings
    INSERT INTO ai_settings (organization_id, credits_remaining, purchased_credits, updated_at)
    VALUES (NEW.organization_id, NEW.credits_amount, NEW.credits_amount, NOW())
    ON CONFLICT (organization_id)
    DO UPDATE SET
      credits_remaining = ai_settings.credits_remaining + NEW.credits_amount,
      purchased_credits = ai_settings.purchased_credits + NEW.credits_amount,
      updated_at = NOW();
  END IF;
  RETURN NEW;
END;
$$;


