CREATE OR REPLACE FUNCTION "public"."sync_space_status_with_reservations"() RETURNS TABLE("space_id" "uuid", "space_label" "text", "old_status" "public"."space_status", "new_status" "public"."space_status")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  -- Actualizar espacios que deberían estar ocupados (reservas con checked_in)
  RETURN QUERY
  UPDATE spaces s
  SET 
    status = 'occupied'::space_status,
    updated_at = now()
  FROM (
    SELECT DISTINCT rs.space_id
    FROM reservations r
    JOIN reservation_spaces rs ON r.id = rs.reservation_id
    WHERE r.status = 'checked_in'
  ) occupied_spaces
  WHERE s.id = occupied_spaces.space_id
    AND s.status != 'occupied'::space_status
    AND s.status != 'maintenance'::space_status
    AND s.status != 'out_of_order'::space_status
  RETURNING s.id, s.label, s.status, 'occupied'::space_status;
  
  -- Actualizar espacios que deberían estar disponibles (sin reservas activas)
  RETURN QUERY
  UPDATE spaces s
  SET 
    status = 'available'::space_status,
    updated_at = now()
  WHERE s.id NOT IN (
    SELECT DISTINCT rs.space_id
    FROM reservations r
    JOIN reservation_spaces rs ON r.id = rs.reservation_id
    WHERE r.status IN ('checked_in', 'confirmed')
  )
  AND s.status = 'occupied'::space_status
  RETURNING s.id, s.label, s.status, 'available'::space_status;
END;
$$;


ALTER FUNCTION "public"."sync_space_status_with_reservations"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sync_space_status_with_reservations"() IS 'Sincroniza el estado de los espacios basándose en el estado de las reservas activas';



CREATE OR REPLACE FUNCTION "public"."temp_audit_amount_validation"() RETURNS "text"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_func text;
    v_results text[] := ARRAY[]::text[];
    r RECORD;
BEGIN
    FOR r IN
        SELECT p.proname, p.prosrc
        FROM pg_proc p
        JOIN pg_namespace n ON n.oid = p.pronamespace
        WHERE n.nspname = 'public' AND p.proname LIKE 'fn_auto_journal%'
    LOOP
        -- Buscar llamadas a fn_create_journal_entry sin validación previa de amount
        IF r.prosrc LIKE '%fn_create_journal_entry%' 
           AND r.prosrc NOT LIKE '%IF v_amount%> 0%' 
           AND r.prosrc NOT LIKE '%COALESCE%amount%> 0%'
           AND r.prosrc NOT LIKE '%amount IS NULL%'
           AND r.prosrc NOT LIKE '%amount != 0%'
        THEN
            -- Verificar si pasa NEW.amount directamente sin COALESCE
            IF r.prosrc LIKE '%NEW.amount%' OR r.prosrc LIKE '%NEW.total%' OR r.prosrc LIKE '%NEW.net_pay%' OR r.prosrc LIKE '%NEW.principal%' OR r.prosrc LIKE '%NEW.price%' THEN
                v_results := array_append(v_results, r.proname);
            END IF;
        END IF;
    END LOOP;
    
    IF array_length(v_results, 1) > 0 THEN
        RETURN array_to_string(v_results, E'\n');
    ELSE
        RETURN 'OK - Todas validan';
    END IF;
END;
$$;


ALTER FUNCTION "public"."temp_audit_amount_validation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."test_alert_condition"("condition_sql" "text", "organization_id" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  result_count INTEGER := 0;
  execution_time INTERVAL;
  start_time TIMESTAMP;
  error_message TEXT := NULL;
BEGIN
  start_time := NOW();
  
  BEGIN
    -- Llamar a la función principal
    result_count := execute_alert_condition(condition_sql, organization_id);
    
    execution_time := NOW() - start_time;
    
    -- Retornar resultado exitoso
    RETURN jsonb_build_object(
      'success', true,
      'count', result_count,
      'execution_time_ms', EXTRACT(MILLISECONDS FROM execution_time),
      'condition_met', (result_count > 0),
      'tested_at', NOW()
    );
    
  EXCEPTION
    WHEN OTHERS THEN
      execution_time := NOW() - start_time;
      error_message := SQLERRM;
      
      -- Retornar resultado con error
      RETURN jsonb_build_object(
        'success', false,
        'error', error_message,
        'execution_time_ms', EXTRACT(MILLISECONDS FROM execution_time),
        'tested_at', NOW()
      );
  END;
END;
$$;


ALTER FUNCTION "public"."test_alert_condition"("condition_sql" "text", "organization_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."toggle_payment_method_status"("p_organization_id" integer, "p_payment_method_code" "text", "p_is_active" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_exists BOOLEAN;
BEGIN
  -- Verificar si ya existe una configuración para esta organización
  SELECT EXISTS(
    SELECT 1 FROM organization_payment_methods
    WHERE organization_id = p_organization_id 
    AND payment_method_code = p_payment_method_code
  ) INTO v_exists;
  
  IF v_exists THEN
    -- Actualizar registro existente
    UPDATE organization_payment_methods
    SET is_active = p_is_active, updated_at = now()
    WHERE organization_id = p_organization_id
    AND payment_method_code = p_payment_method_code;
  ELSE
    -- Crear nuevo registro
    INSERT INTO organization_payment_methods (
      organization_id, payment_method_code, is_active, settings
    ) VALUES (
      p_organization_id, p_payment_method_code, p_is_active, '{}'::jsonb
    );
  END IF;
END;
$$;


