CREATE OR REPLACE FUNCTION "public"."trg_only_one_base_currency"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    -- Si se está marcando esta moneda como base
    IF NEW.is_base = TRUE THEN
        -- Cambiar cualquier otra moneda base a false para la misma organización
        UPDATE public.currencies
        SET is_base = FALSE
        WHERE organization_id = NEW.organization_id
          AND code <> NEW.code
          AND is_base = TRUE;
    END IF;
    RETURN NEW;
END;
$$;


