CREATE OR REPLACE FUNCTION "public"."trigger_ai_auto_response"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'net', 'extensions', 'vault'
    AS $$
declare
  v_channel_ai_mode text;
  v_ai_active boolean;
  v_auto_enabled boolean;
  v_secret text;
begin
  if NEW.direction <> 'inbound' or NEW.role <> 'customer' then
    return NEW;
  end if;

  select c.ai_mode into v_channel_ai_mode
  from conversations conv
  join channels c on c.id = conv.channel_id
  where conv.id = NEW.conversation_id
    and conv.organization_id = NEW.organization_id;

  if v_channel_ai_mode is null or v_channel_ai_mode = 'manual' then
    return NEW;
  end if;

  select is_active, coalesce(auto_response_enabled, true)
    into v_ai_active, v_auto_enabled
  from ai_settings
  where organization_id = NEW.organization_id;

  if not coalesce(v_ai_active, false) or not coalesce(v_auto_enabled, false) then
    return NEW;
  end if;

  select decrypted_secret into v_secret
  from vault.decrypted_secrets
  where name = 'AI_INTERNAL_SECRET'
  limit 1;

  perform net.http_post(
    url := 'https://jgmgphmzusbluqhuqihj.supabase.co/functions/v1/ai-auto-response',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-internal-secret', coalesce(v_secret, '')
    ),
    body := jsonb_build_object(
      'conversationId', NEW.conversation_id,
      'messageId', NEW.id,
      'organizationId', NEW.organization_id
    )
  );

  return NEW;
end;
$$;


ALTER FUNCTION "public"."trigger_ai_auto_response"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trigger_auto_setup_organization_website"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  -- Si no hay subdominio, generarlo desde el nombre
  IF NEW.subdomain IS NULL OR NEW.subdomain = '' THEN
    NEW.subdomain := generate_subdomain_from_name(NEW.name);
  ELSE
    -- Si el subdominio fue proporcionado, verificar que sea único
    -- Si ya existe, appendar un contador hasta encontrar uno disponible
    IF EXISTS (SELECT 1 FROM organizations WHERE subdomain = NEW.subdomain) THEN
      NEW.subdomain := generate_subdomain_from_name(NEW.subdomain);
    END IF;
  END IF;
  
  RETURN NEW;
END;
$$;


