CREATE OR REPLACE FUNCTION "public"."trigger_sync_space_status"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  -- Si el status cambió a 'confirmed', marcar espacios como reserved
  IF NEW.status = 'confirmed' AND (OLD.status IS NULL OR OLD.status != 'confirmed') THEN
    UPDATE spaces
    SET 
      status = 'reserved',
      updated_at = now()
    WHERE id IN (
      SELECT space_id 
      FROM reservation_spaces 
      WHERE reservation_id = NEW.id
    )
    AND status NOT IN ('maintenance', 'out_of_order', 'occupied');
  END IF;
  
  -- Si el status cambió a 'checked_in', marcar espacios como occupied
  IF NEW.status = 'checked_in' AND (OLD.status IS NULL OR OLD.status != 'checked_in') THEN
    UPDATE spaces
    SET 
      status = 'occupied',
      updated_at = now()
    WHERE id IN (
      SELECT space_id 
      FROM reservation_spaces 
      WHERE reservation_id = NEW.id
    )
    AND status NOT IN ('maintenance', 'out_of_order');
  END IF;
  
  -- Si el status cambió a 'checked_out' (checkout), marcar espacios como cleaning
  IF NEW.status = 'checked_out' AND (OLD.status IS NULL OR OLD.status != 'checked_out') THEN
    UPDATE spaces
    SET 
      status = 'cleaning',
      updated_at = now()
    WHERE id IN (
      SELECT space_id 
      FROM reservation_spaces 
      WHERE reservation_id = NEW.id
    )
    AND status = 'occupied';
  END IF;
  
  -- Si el status cambió a 'cancelled' o 'no_show', liberar espacios si no hay otras reservas activas
  IF NEW.status IN ('cancelled', 'no_show') AND (OLD.status IS NULL OR OLD.status NOT IN ('cancelled', 'no_show')) THEN
    UPDATE spaces s
    SET 
      status = 'available',
      updated_at = now()
    WHERE s.id IN (
      SELECT space_id 
      FROM reservation_spaces 
      WHERE reservation_id = NEW.id
    )
    AND s.status IN ('occupied', 'reserved')
    AND NOT EXISTS (
      SELECT 1
      FROM reservation_spaces rs2
      JOIN reservations r2 ON rs2.reservation_id = r2.id
      WHERE rs2.space_id = s.id
        AND r2.id != NEW.id
        AND r2.status IN ('checked_in', 'confirmed')
    );
  END IF;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."trigger_sync_space_status"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."trigger_sync_space_status"() IS 'Trigger que sincroniza automáticamente el estado de los espacios cuando cambia el status de una reserva';



CREATE OR REPLACE FUNCTION "public"."update_accounts_receivable_on_payment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  invoice_record RECORD;
  account_record RECORD;
  source_id_uuid UUID;
BEGIN
  -- Manejar pagos de facturas (comportamiento original)
  IF NEW.source = 'invoice_sales' AND NEW.source_id IS NOT NULL THEN
    BEGIN
      source_id_uuid := NEW.source_id::UUID;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'Error al convertir source_id a UUID: %', SQLERRM;
      RETURN NEW;
    END;

    SELECT * INTO invoice_record FROM invoice_sales WHERE id = source_id_uuid;

    IF FOUND THEN
      IF NOT EXISTS (SELECT 1 FROM accounts_receivable WHERE invoice_id = invoice_record.id) THEN
        PERFORM create_account_receivable(invoice_record.id::TEXT);
      ELSE
        UPDATE accounts_receivable
        SET
          balance = invoice_record.balance,
          updated_at = NOW()
        WHERE invoice_id = invoice_record.id;
      END IF;
    END IF;

  -- Manejar pagos directos a cuentas por cobrar
  ELSIF NEW.source = 'account_receivable' AND NEW.source_id IS NOT NULL THEN
    BEGIN
      source_id_uuid := NEW.source_id::UUID;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'Error al convertir source_id a UUID para account_receivable: %', SQLERRM;
      RETURN NEW;
    END;

    SELECT * INTO account_record FROM accounts_receivable WHERE id = source_id_uuid;

    IF FOUND THEN
      DECLARE
        new_balance NUMERIC;
        new_status TEXT;
        settled NUMERIC;
      BEGIN
        settled := NEW.amount + COALESCE(NEW.discount_amount, 0);
        new_balance := account_record.balance - settled;
        new_balance := GREATEST(new_balance, 0);

        IF new_balance = 0 THEN
          new_status := 'paid';
        ELSIF new_balance < account_record.amount THEN
          new_status := 'partial';
        ELSE
          new_status := account_record.status;
        END IF;

        UPDATE accounts_receivable
        SET
          balance = new_balance,
          status = new_status,
          discount_amount = COALESCE(discount_amount, 0) + COALESCE(NEW.discount_amount, 0),
          updated_at = NOW()
        WHERE id = source_id_uuid;

        IF account_record.invoice_id IS NOT NULL THEN
          UPDATE invoice_sales
          SET
            balance = new_balance,
            status = CASE
              WHEN new_balance = 0 THEN 'paid'
              WHEN new_balance < total THEN 'partial'
              ELSE status
            END,
            updated_at = NOW()
          WHERE id = account_record.invoice_id;
        END IF;
      END;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


