CREATE OR REPLACE FUNCTION "public"."update_all_days_overdue"() RETURNS TABLE("updated_count" integer, "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  total_updated integer := 0;
BEGIN
  -- Actualizar todas las cuentas por cobrar
  UPDATE accounts_receivable 
  SET 
    days_overdue = CASE 
      WHEN due_date::date < CURRENT_DATE AND balance > 0 
      THEN (CURRENT_DATE - due_date::date)::integer
      ELSE 0 
    END,
    status = CASE 
      WHEN balance = 0 THEN 'paid'
      WHEN due_date::date < CURRENT_DATE AND balance > 0 AND balance < amount THEN 'partial'
      WHEN due_date::date < CURRENT_DATE AND balance > 0 AND balance = amount THEN 'overdue' 
      WHEN balance > 0 AND balance < amount THEN 'partial'
      ELSE 'current'
    END,
    updated_at = NOW()
  WHERE TRUE;
  
  GET DIAGNOSTICS total_updated = ROW_COUNT;
  
  RETURN QUERY SELECT total_updated, 'Días de atraso actualizados correctamente'::text;
END;
$$;


ALTER FUNCTION "public"."update_all_days_overdue"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_all_exchange_rates"() RETURNS TABLE("organization_id" integer, "updated_count" integer, "success" boolean, "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  org_record RECORD;
  result JSONB;
BEGIN
  -- Recorrer todas las organizaciones activas
  FOR org_record IN SELECT id FROM organizations WHERE is_active = true LOOP
    -- Intentar actualizar las tasas para esta organización
    BEGIN
      -- Obtener la configuración actual para la organización
      result := update_exchange_rates(org_record.id);
      
      -- Devolver los resultados
      organization_id := org_record.id;
      updated_count := (result->>'updated_count')::integer;
      success := (result->>'success')::boolean;
      message := result->>'message';
      RETURN NEXT;
    EXCEPTION WHEN OTHERS THEN
      -- Registrar error y continuar con la siguiente organización
      organization_id := org_record.id;
      updated_count := 0;
      success := false;
      message := 'Error: ' || SQLERRM;
      RETURN NEXT;
    END;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."update_all_exchange_rates"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_all_exchange_rates"("rates" "jsonb", "source" "text" DEFAULT 'openexchangerates'::"text", "api_timestamp" bigint DEFAULT NULL::bigint, "rate_date" "date" DEFAULT CURRENT_DATE) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  currency_code TEXT;
  rate_value NUMERIC;
  org_id INTEGER;
  base_currency_id UUID;
  updated_count INTEGER := 0;
  skipped_count INTEGER := 0;
  organizations_updated INTEGER := 0;
  result JSONB;
BEGIN
  -- Si no se proporciona timestamp, usar el actual
  IF api_timestamp IS NULL THEN
    api_timestamp := EXTRACT(EPOCH FROM CURRENT_TIMESTAMP)::bigint;
  END IF;

  -- Obtener todas las organizaciones
  FOR org_id IN SELECT id FROM organizations
  LOOP
    -- Intentar encontrar moneda base USD para la organización
    SELECT id INTO base_currency_id
    FROM currencies
    WHERE organization_id = org_id 
      AND (template_code = 'USD' OR code = 'USD')
    LIMIT 1;
    
    -- Si no se encuentra USD, usar la primera moneda disponible
    IF base_currency_id IS NULL THEN
      SELECT id INTO base_currency_id
      FROM currencies
      WHERE organization_id = org_id
      LIMIT 1;
      
      -- Si no hay monedas para esta organización, saltarla
      IF base_currency_id IS NULL THEN
        CONTINUE;
      END IF;
    END IF;
    
    -- Llamar a la función existente para guardar las tasas para esta organización
    SELECT save_exchange_rates(
      org_id, 
      base_currency_id, 
      rates, 
      source, 
      api_timestamp, 
      rate_date, 
      'USD'
    ) INTO result;
    
    -- Actualizar contadores
    updated_count := updated_count + (result->>'updated_count')::integer;
    skipped_count := skipped_count + (result->>'skipped_count')::integer;
    organizations_updated := organizations_updated + 1;
  END LOOP;
  
  RETURN jsonb_build_object(
    'success', true,
    'message', 'Tasas de cambio actualizadas para todas las organizaciones',
    'updated_count', updated_count,
    'skipped_count', skipped_count,
    'organizations_updated', organizations_updated,
    'base_currency', 'USD'
  );
END;
$$;


ALTER FUNCTION "public"."update_all_exchange_rates"("rates" "jsonb", "source" "text", "api_timestamp" bigint, "rate_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_all_exchange_rates_with_api"("rates" "jsonb", "source" "text" DEFAULT 'openexchangerates_api'::"text", "api_timestamp" bigint DEFAULT NULL::bigint, "rate_date" "date" DEFAULT CURRENT_DATE) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  updated_count INTEGER := 0;
  skipped_count INTEGER := 0;
  organizations_updated INTEGER := 0;
  base_currency_id UUID;
  org_id INTEGER;
  result JSONB;
BEGIN
  -- Si no se proporciona un timestamp, usar el actual
  IF api_timestamp IS NULL THEN
    api_timestamp := EXTRACT(EPOCH FROM CURRENT_TIMESTAMP)::bigint;
  END IF;

  -- Obtener todas las organizaciones
  FOR org_id IN SELECT id FROM organizations
  LOOP
    -- Intentar encontrar moneda base USD para la organización
    SELECT id INTO base_currency_id
    FROM currencies
    WHERE organization_id = org_id 
      AND (template_code = 'USD' OR code = 'USD')
      AND auto_update = true
    LIMIT 1;
    
    -- Si no se encuentra USD, usar la primera moneda disponible con auto_update
    IF base_currency_id IS NULL THEN
      SELECT id INTO base_currency_id
      FROM currencies
      WHERE organization_id = org_id
        AND auto_update = true
      LIMIT 1;
      
      -- Si no hay monedas para esta organización, saltarla
      IF base_currency_id IS NULL THEN
        CONTINUE;
      END IF;
    END IF;
    
    -- Llamar a la función existente para guardar las tasas para esta organización
    SELECT save_exchange_rates(
      org_id, 
      base_currency_id, 
      rates, 
      source, 
      api_timestamp, 
      rate_date, 
      'USD'
    ) INTO result;
    
    -- Actualizar contadores
    updated_count := updated_count + (result->>'updated_count')::integer;
    skipped_count := skipped_count + (result->>'skipped_count')::integer;
    organizations_updated := organizations_updated + 1;
  END LOOP;
  
  RETURN jsonb_build_object(
    'success', true,
    'message', 'Tasas de cambio actualizadas para todas las organizaciones',
    'updated_count', updated_count,
    'skipped_count', skipped_count,
    'organizations_updated', organizations_updated,
    'base_currency', 'USD'
  );
END;
$$;


