CREATE OR REPLACE FUNCTION "public"."update_exchange_rates"("org_id" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  config RECORD;
  base_currency TEXT;
  base_currency_id UUID;
  api_url TEXT;
  response JSONB;
  success_count INTEGER := 0;
  error_count INTEGER := 0;
  currency_count INTEGER := 0;
BEGIN
  -- Obtener configuración global
  SELECT * INTO config FROM openexchangerates_config LIMIT 1;
  
  -- Si no hay configuración o API key, salir
  IF NOT FOUND OR config.api_key IS NULL OR config.api_key = '' THEN
    RETURN jsonb_build_object(
      'success', false, 
      'message', 'No se encontró configuración de API o API key',
      'updated_count', 0
    );
  END IF;
  
  -- Obtener moneda base de la organización (la que tenga is_base=true)
  SELECT c.code, c.id INTO base_currency, base_currency_id
  FROM currencies c
  WHERE c.organization_id = org_id AND c.is_base = true
  LIMIT 1;
  
  -- Si no hay moneda base, usar la primera moneda disponible
  IF base_currency IS NULL THEN
    SELECT c.code, c.id INTO base_currency, base_currency_id
    FROM currencies c
    WHERE c.organization_id = org_id
    LIMIT 1;
    
    IF base_currency IS NULL THEN
      RETURN jsonb_build_object(
        'success', false, 
        'message', 'No se encontraron monedas para esta organización',
        'updated_count', 0
      );
    END IF;
  END IF;
  
  -- IMPORTANTE: Siempre construimos la URL para la API con USD como base
  -- porque el plan gratuito solo permite USD como base
  -- La conversión a la moneda base local se hará en el frontend/backend
  api_url := 'https://openexchangerates.org/api/latest.json?app_id=' || config.api_key;
  
  -- En este punto, el frontend hará la llamada a la API
  response := jsonb_build_object(
    'success', true,
    'api_url', api_url,
    'base_currency', base_currency,
    'base_currency_id', base_currency_id
  );
  
  -- Actualizar el timestamp de última actualización
  UPDATE openexchangerates_config
  SET last_update = CURRENT_TIMESTAMP,
      updated_at = CURRENT_TIMESTAMP
  WHERE id = config.id;
  
  RETURN response;
END;
$$;


