CREATE OR REPLACE FUNCTION "public"."update_expired_parking_passes"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    -- Si la fecha de fin es anterior a hoy, marcar como expirado
    IF NEW.end_date < CURRENT_DATE AND NEW.status != 'expired' THEN
        NEW.status := 'expired';
    -- Si la fecha de fin se actualiza a una fecha futura y estaba expirado, reactivar
    ELSIF NEW.end_date >= CURRENT_DATE AND OLD.end_date < CURRENT_DATE AND NEW.status = 'expired' THEN
        NEW.status := 'active';
    END IF;
    
    RETURN NEW;
END;
$$;


