CREATE OR REPLACE FUNCTION "public"."update_folio_balance"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        UPDATE folios
        SET balance = balance + NEW.amount
        WHERE id = NEW.folio_id;
    ELSIF TG_OP = 'UPDATE' THEN
        UPDATE folios
        SET balance = balance - OLD.amount + NEW.amount
        WHERE id = NEW.folio_id;
    ELSIF TG_OP = 'DELETE' THEN
        UPDATE folios
        SET balance = balance - OLD.amount
        WHERE id = OLD.folio_id;
    END IF;
    RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."update_folio_balance"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_global_exchange_rates"("rates" "jsonb", "source" "text" DEFAULT 'openexchangerates'::"text", "api_timestamp" bigint DEFAULT NULL::bigint, "rate_date" "text" DEFAULT NULL::"text", "base_currency_code" "text" DEFAULT 'USD'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $_$
DECLARE
  currency_code TEXT;
  rate_value NUMERIC;
  updated_count INTEGER := 0;
  inserted_count INTEGER := 0;
  skipped_count INTEGER := 0;
  current_rate_date DATE;
  start_time TIMESTAMP := clock_timestamp();
  currencies_count INTEGER;
  execution_ms NUMERIC;
  record_exists BOOLEAN;
BEGIN
  -- Validaciones iniciales
  IF rates IS NULL OR jsonb_typeof(rates) != 'object' THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'El parámetro rates debe ser un objeto JSON válido'
    );
  END IF;

  -- Configurar fecha
  current_rate_date := COALESCE(rate_date::DATE, CURRENT_DATE);
  
  -- Configurar timestamp
  IF api_timestamp IS NULL THEN
    api_timestamp := EXTRACT(EPOCH FROM CURRENT_TIMESTAMP)::bigint;
  END IF;

  -- Configurar base currency
  IF base_currency_code IS NULL THEN
    base_currency_code := 'USD';
  END IF;

  -- Contar monedas
  SELECT COUNT(*) INTO currencies_count FROM jsonb_object_keys(rates);

  -- Procesar cada moneda
  FOR currency_code, rate_value IN 
    SELECT key, (value::text)::numeric 
    FROM jsonb_each(rates)
    WHERE value::text ~ '^[0-9]+\.?[0-9]*$'
  LOOP
    -- Solo procesar monedas que existen en el catálogo
    IF EXISTS (SELECT 1 FROM currencies WHERE code = currency_code AND is_active = true) THEN
      
      -- Verificar si ya existe el registro (usando alias de tabla para evitar ambigüedad)
      SELECT EXISTS(
        SELECT 1 FROM currency_rates cr
        WHERE cr.code = currency_code AND cr.rate_date = current_rate_date
      ) INTO record_exists;

      IF record_exists THEN
        -- Actualizar (usando alias para evitar ambigüedad)
        UPDATE currency_rates cr SET 
          rate = rate_value,
          source = $2,
          base_currency_code = $5,
          api_data = jsonb_build_object(
            'timestamp', api_timestamp,
            'base', $5,
            'code', currency_code,
            'rate', rate_value,
            'source', $2
          ),
          updated_at = CURRENT_TIMESTAMP
        WHERE cr.code = currency_code AND cr.rate_date = current_rate_date;
        
        updated_count := updated_count + 1;
      ELSE
        -- Insertar nuevo registro
        INSERT INTO currency_rates (
          code, rate_date, rate, source, base_currency_code,
          api_data, created_at, updated_at
        ) VALUES (
          currency_code, current_rate_date, rate_value, $2, $5,
          jsonb_build_object(
            'timestamp', api_timestamp,
            'base', $5,
            'code', currency_code,
            'rate', rate_value,
            'source', $2
          ),
          CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
        );
        
        inserted_count := inserted_count + 1;
      END IF;
    ELSE
      skipped_count := skipped_count + 1;
    END IF;
  END LOOP;

  -- Calcular tiempo de ejecución
  execution_ms := EXTRACT(EPOCH FROM (clock_timestamp() - start_time)) * 1000;

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Tasas de cambio actualizadas exitosamente en ' || execution_ms || 'ms',
    'updated_count', updated_count,
    'inserted_count', inserted_count,
    'skipped_count', skipped_count,
    'base_currency', $5,
    'rate_date', current_rate_date,
    'source', $2,
    'currencies_count', currencies_count,
    'performance', jsonb_build_object('execution_time_ms', execution_ms)
  );
END;
$_$;


ALTER FUNCTION "public"."update_global_exchange_rates"("rates" "jsonb", "source" "text", "api_timestamp" bigint, "rate_date" "text", "base_currency_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_group_room_nights"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    nights INTEGER;
BEGIN
    IF TG_OP = 'INSERT' THEN
        -- Calcular noches para esta reserva
        SELECT 
            CASE 
                WHEN r.checkout IS NOT NULL AND r.checkin IS NOT NULL 
                THEN (r.checkout - r.checkin)
                ELSE 0
            END INTO nights
        FROM reservations r WHERE r.id = NEW.reservation_id;
        
        -- Actualizar el conteo en el grupo
        UPDATE groups 
        SET room_nights = room_nights + COALESCE(nights, 0)
        WHERE id = NEW.group_id;
    ELSIF TG_OP = 'DELETE' THEN
        -- Calcular noches para esta reserva
        SELECT 
            CASE 
                WHEN r.checkout IS NOT NULL AND r.checkin IS NOT NULL 
                THEN (r.checkout - r.checkin)
                ELSE 0
            END INTO nights
        FROM reservations r WHERE r.id = OLD.reservation_id;
        
        -- Actualizar el conteo en el grupo
        UPDATE groups 
        SET room_nights = room_nights - COALESCE(nights, 0)
        WHERE id = OLD.group_id;
    END IF;
    
    RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."update_group_room_nights"() OWNER TO "postgres";


