CREATE OR REPLACE FUNCTION "public"."update_knowledge_source_fragment_count"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF TG_OP = 'INSERT' AND NEW.is_active = true THEN
    UPDATE knowledge_sources 
    SET fragment_count = fragment_count + 1 
    WHERE id = NEW.source_id;
  ELSIF TG_OP = 'DELETE' AND OLD.is_active = true THEN
    UPDATE knowledge_sources 
    SET fragment_count = fragment_count - 1 
    WHERE id = OLD.source_id;
  ELSIF TG_OP = 'UPDATE' AND OLD.is_active != NEW.is_active THEN
    UPDATE knowledge_sources 
    SET fragment_count = fragment_count + (CASE WHEN NEW.is_active THEN 1 ELSE -1 END)
    WHERE id = NEW.source_id;
  END IF;
  RETURN NEW;
END;
$$;


