CREATE OR REPLACE FUNCTION "public"."update_manifest_counts"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  UPDATE dispatch_manifests
  SET 
    total_shipments = (SELECT COUNT(*) FROM manifest_shipments WHERE manifest_id = COALESCE(NEW.manifest_id, OLD.manifest_id)),
    delivered_count = (SELECT COUNT(*) FROM manifest_shipments WHERE manifest_id = COALESCE(NEW.manifest_id, OLD.manifest_id) AND status = 'delivered'),
    failed_count = (SELECT COUNT(*) FROM manifest_shipments WHERE manifest_id = COALESCE(NEW.manifest_id, OLD.manifest_id) AND status = 'failed'),
    pending_count = (SELECT COUNT(*) FROM manifest_shipments WHERE manifest_id = COALESCE(NEW.manifest_id, OLD.manifest_id) AND status = 'pending'),
    updated_at = now()
  WHERE id = COALESCE(NEW.manifest_id, OLD.manifest_id);
  
  RETURN COALESCE(NEW, OLD);
END;
$$;


