CREATE OR REPLACE FUNCTION "public"."update_opportunity_stage"("p_opportunity_id" "uuid", "p_stage_id" "uuid", "p_organization_id" integer) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_user_id UUID;
  v_belongs_to_org BOOLEAN;
  v_opportunity_exists BOOLEAN;
BEGIN
  -- Obtener el ID del usuario actual
  v_user_id := auth.uid();
  
  -- Verificar si el usuario pertenece a la organización
  SELECT EXISTS(
    SELECT 1 FROM organization_members
    WHERE user_id = v_user_id
    AND organization_id = p_organization_id
  ) INTO v_belongs_to_org;
  
  -- Si el usuario no pertenece a la organización, devolver falso
  IF NOT v_belongs_to_org THEN
    RETURN FALSE;
  END IF;
  
  -- Verificar si la oportunidad existe
  SELECT EXISTS(
    SELECT 1 FROM opportunities
    WHERE id = p_opportunity_id
    AND organization_id = p_organization_id
  ) INTO v_opportunity_exists;
  
  IF NOT v_opportunity_exists THEN
    RETURN FALSE;
  END IF;
  
  -- Actualizar la etapa de la oportunidad directamente con una consulta SQL
  -- en lugar de usar un UPDATE que podría activar triggers o actualizaciones de vistas
  EXECUTE 'UPDATE opportunities SET stage_id = $1, updated_at = NOW() WHERE id = $2 AND organization_id = $3'
  USING p_stage_id, p_opportunity_id, p_organization_id;
  
  RETURN TRUE;
END;
$_$;


ALTER FUNCTION "public"."update_opportunity_stage"("p_opportunity_id" "uuid", "p_stage_id" "uuid", "p_organization_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_opportunity_stage_safe"("p_opportunity_id" "uuid", "p_stage_id" "uuid", "p_organization_id" integer) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_user_id UUID;
  v_belongs_to_org BOOLEAN;
  v_stage_exists BOOLEAN;
  v_opportunity_exists BOOLEAN;
BEGIN
  -- Verificar que la etapa existe
  SELECT EXISTS(
    SELECT 1 FROM stages WHERE id = p_stage_id
  ) INTO v_stage_exists;
  
  IF NOT v_stage_exists THEN
    RETURN FALSE;
  END IF;

  -- Obtener el ID del usuario actual
  v_user_id := auth.uid();
  
  IF v_user_id IS NULL THEN
    RETURN FALSE;
  END IF;
  
  -- Verificar si el usuario pertenece a la organización
  SELECT EXISTS(
    SELECT 1 FROM organization_members
    WHERE user_id = v_user_id
    AND organization_id = p_organization_id
  ) INTO v_belongs_to_org;
  
  -- Si el usuario no pertenece a la organización, devolver falso
  IF NOT v_belongs_to_org THEN
    RETURN FALSE;
  END IF;
  
  -- Verificar si la oportunidad existe y pertenece a la organización
  SELECT EXISTS(
    SELECT 1 FROM opportunities
    WHERE id = p_opportunity_id
    AND organization_id = p_organization_id
  ) INTO v_opportunity_exists;
  
  IF NOT v_opportunity_exists THEN
    RETURN FALSE;
  END IF;
  
  -- Actualizar directamente en la tabla usando SQL sin activar triggers
  -- Este es un enfoque más directo que evita el RLS y cualquier actualización de vistas
  EXECUTE '
    UPDATE opportunities 
    SET 
      stage_id = $1, 
      updated_at = NOW()
    WHERE id = $2 
    AND organization_id = $3
  ' USING p_stage_id, p_opportunity_id, p_organization_id;
  
  RETURN TRUE;
END;
$_$;


ALTER FUNCTION "public"."update_opportunity_stage_safe"("p_opportunity_id" "uuid", "p_stage_id" "uuid", "p_organization_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_opportunity_stage_safe"("p_opportunity_id" "uuid", "p_stage_id" "uuid", "p_status" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$
DECLARE
    v_user_id UUID;
    v_organization_id INT;
    v_belongs_to_org BOOLEAN;
    v_current_status TEXT;
BEGIN
    -- Obtener el ID del usuario actual
    v_user_id := auth.uid();
    
    IF v_user_id IS NULL THEN
        RETURN FALSE;
    END IF;
    
    -- Obtener el organization_id y el status actual
    SELECT 
        organization_id, 
        status INTO v_organization_id, v_current_status
    FROM opportunities
    WHERE id = p_opportunity_id;
    
    IF v_organization_id IS NULL THEN
        RETURN FALSE;
    END IF;
    
    -- Verificar permisos
    SELECT EXISTS(
        SELECT 1 FROM organization_members
        WHERE user_id = v_user_id
        AND organization_id = v_organization_id
    ) INTO v_belongs_to_org;
    
    IF NOT v_belongs_to_org THEN
        RETURN FALSE;
    END IF;
    
    -- Realizar la actualización directamente sin activar triggers
    -- Usar SQL puro para evitar cualquier interacción con las vistas materializadas
    IF p_status IS NOT NULL THEN
        EXECUTE '
            UPDATE opportunities 
            SET 
                stage_id = $1,
                status = $2,
                updated_at = NOW()
            WHERE id = $3
        ' USING p_stage_id, p_status, p_opportunity_id;
    ELSE
        EXECUTE '
            UPDATE opportunities 
            SET 
                stage_id = $1,
                updated_at = NOW()
            WHERE id = $2
        ' USING p_stage_id, p_opportunity_id;
    END IF;
    
    -- Devolver éxito
    RETURN TRUE;
END;
$_$;


ALTER FUNCTION "public"."update_opportunity_stage_safe"("p_opportunity_id" "uuid", "p_stage_id" "uuid", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_opportunity_stage_without_refresh"("p_opportunity_id" "uuid", "p_stage_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$
DECLARE
    v_user_id UUID;
    v_organization_id INT;
    v_allowed BOOLEAN;
BEGIN
    -- Obtener el ID del usuario actual
    v_user_id := auth.uid();
    
    IF v_user_id IS NULL THEN
        RETURN FALSE;
    END IF;
    
    -- Obtener el ID de la organización y verificar permisos
    SELECT 
        o.organization_id, 
        EXISTS(
            SELECT 1 FROM organization_members om
            WHERE om.organization_id = o.organization_id
            AND om.user_id = v_user_id
        ) INTO v_organization_id, v_allowed
    FROM opportunities o
    WHERE o.id = p_opportunity_id;
    
    IF NOT v_allowed OR v_organization_id IS NULL THEN
        RETURN FALSE;
    END IF;
    
    -- Actualizar la oportunidad directamente usando SQL para evitar triggers
    EXECUTE 'UPDATE opportunities SET stage_id = $1, updated_at = NOW() WHERE id = $2'
    USING p_stage_id, p_opportunity_id;
    
    RETURN TRUE;
END;
$_$;


