CREATE OR REPLACE FUNCTION "public"."update_organization_payment_method"("p_organization_id" integer, "p_payment_method_code" "text", "p_is_active" boolean, "p_settings" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_exists BOOLEAN;
BEGIN
  -- Verificar si ya existe una configuración para esta organización
  SELECT EXISTS(
    SELECT 1 FROM organization_payment_methods
    WHERE organization_id = p_organization_id 
    AND payment_method_code = p_payment_method_code
  ) INTO v_exists;
  
  IF v_exists THEN
    -- Actualizar registro existente
    UPDATE organization_payment_methods
    SET is_active = p_is_active,
        settings = p_settings,
        updated_at = now()
    WHERE organization_id = p_organization_id
    AND payment_method_code = p_payment_method_code;
  ELSE
    -- Crear nuevo registro
    INSERT INTO organization_payment_methods (
      organization_id, payment_method_code, is_active, settings
    ) VALUES (
      p_organization_id, p_payment_method_code, p_is_active, p_settings
    );
  END IF;
END;
$$;


