CREATE OR REPLACE FUNCTION "public"."update_parking_session_after_payment"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    -- Si el pago está asociado a una sesión, marcarla como cerrada
    IF NEW.parking_session_id IS NOT NULL THEN
        UPDATE parking_sessions 
        SET status = 'closed', 
            exit_at = COALESCE(exit_at, now()) 
        WHERE id = NEW.parking_session_id AND status = 'open';
    END IF;
    
    RETURN NEW;
END;
$$;


