CREATE OR REPLACE FUNCTION "public"."update_parking_space_state"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        -- Al iniciar una sesión, marcar el espacio como ocupado
        IF NEW.parking_space_id IS NOT NULL THEN
            UPDATE parking_spaces 
            SET state = 'occupied' 
            WHERE id = NEW.parking_space_id;
        END IF;
    ELSIF TG_OP = 'UPDATE' THEN
        -- Al cerrar una sesión, liberar el espacio
        IF NEW.status = 'closed' AND OLD.status = 'open' AND NEW.parking_space_id IS NOT NULL THEN
            UPDATE parking_spaces 
            SET state = 'free' 
            WHERE id = NEW.parking_space_id;
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


