CREATE OR REPLACE FUNCTION "public"."update_payment_method"("p_organization_id" integer, "p_code" "text", "p_name" "text", "p_requires_reference" boolean, "p_is_active" boolean, "p_settings" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_is_system BOOLEAN;
BEGIN
  -- Verificar si es un método del sistema
  SELECT is_system INTO v_is_system
  FROM payment_methods
  WHERE code = p_code;
  
  -- Si no es un método del sistema, actualizamos el registro global
  IF NOT v_is_system THEN
    UPDATE payment_methods
    SET name = p_name,
        requires_reference = p_requires_reference,
        is_active = p_is_active,
        updated_at = now()
    WHERE code = p_code;
  END IF;
  
  -- Actualizar configuración específica de la organización
  PERFORM update_organization_payment_method(
    p_organization_id, p_code, p_is_active, p_settings
  );
END;
$$;


ALTER FUNCTION "public"."update_payment_method"("p_organization_id" integer, "p_code" "text", "p_name" "text", "p_requires_reference" boolean, "p_is_active" boolean, "p_settings" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_payment_method_gateway_config"("p_organization_id" integer, "p_payment_method_code" character varying, "p_gateway" character varying, "p_gateway_config" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_settings JSONB;
  v_method_exists BOOLEAN;
  v_org_method_exists BOOLEAN;
BEGIN
  -- Verificar si el método existe
  SELECT EXISTS(SELECT 1 FROM payment_methods WHERE code = p_payment_method_code) INTO v_method_exists;
  
  IF NOT v_method_exists THEN
    RETURN jsonb_build_object('success', false, 'message', 'El método de pago no existe');
  END IF;

  -- Verificar si existe configuración para esta organización
  SELECT EXISTS(
    SELECT 1 FROM organization_payment_methods 
    WHERE organization_id = p_organization_id AND payment_method_code = p_payment_method_code
  ) INTO v_org_method_exists;

  IF v_org_method_exists THEN
    -- Obtener la configuración actual
    SELECT settings FROM organization_payment_methods
    WHERE organization_id = p_organization_id AND payment_method_code = p_payment_method_code
    INTO v_settings;
    
    -- Si settings es NULL, inicializarlo como un objeto vacío
    IF v_settings IS NULL THEN
      v_settings := '{}'::JSONB;
    END IF;
    
    -- Actualizar la configuración con los nuevos valores
    v_settings := jsonb_set(
      v_settings, 
      '{gateway}', 
      to_jsonb(p_gateway)
    );
    
    v_settings := jsonb_set(
      v_settings, 
      '{gateway_config}', 
      p_gateway_config
    );
    
    -- Actualizar el registro
    UPDATE organization_payment_methods
    SET settings = v_settings,
        updated_at = NOW()
    WHERE organization_id = p_organization_id AND payment_method_code = p_payment_method_code;
    
  ELSE
    -- Crear un nuevo objeto settings
    v_settings := jsonb_build_object(
      'gateway', p_gateway,
      'gateway_config', p_gateway_config
    );
    
    -- Insertar un nuevo registro
    INSERT INTO organization_payment_methods (
      organization_id, 
      payment_method_code, 
      is_active, 
      settings,
      created_at,
      updated_at
    ) VALUES (
      p_organization_id,
      p_payment_method_code,
      true, -- Activar por defecto
      v_settings,
      NOW(),
      NOW()
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true, 
    'message', 'Configuración de gateway actualizada correctamente',
    'settings', v_settings
  );
END;
$$;


ALTER FUNCTION "public"."update_payment_method_gateway_config"("p_organization_id" integer, "p_payment_method_code" character varying, "p_gateway" character varying, "p_gateway_config" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_product_min_stock"("p_items" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    item jsonb;
    v_product_id INTEGER;
    v_branch_id INTEGER;
    v_min_level NUMERIC;
    v_user_id UUID;
    v_organization_id INTEGER;
BEGIN
    -- Obtener el user_id actual
    v_user_id := auth.uid();
    
    -- Verificar que el usuario esté autenticado
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Usuario no autenticado';
    END IF;
    
    -- Recorrer cada item en el array JSON
    FOR item IN SELECT * FROM jsonb_array_elements(p_items)
    LOOP
        -- Extraer valores del JSON
        v_product_id := (item->>'product_id')::INTEGER;
        v_branch_id := (item->>'branch_id')::INTEGER;
        v_min_level := (item->>'min_level')::NUMERIC;
        
        -- Obtener el organization_id del branch para validar permisos
        SELECT b.organization_id INTO v_organization_id
        FROM branches b 
        WHERE b.id = v_branch_id;
        
        -- Verificar que el usuario tenga acceso a esta organización
        IF NOT EXISTS (
            SELECT 1 FROM organization_members om 
            WHERE om.user_id = v_user_id 
            AND om.organization_id = v_organization_id
        ) THEN
            RAISE EXCEPTION 'Usuario no tiene permisos para esta organización';
        END IF;
        
        -- Verificar si ya existe el registro de stock_levels
        IF EXISTS (
            SELECT 1 FROM stock_levels 
            WHERE product_id = v_product_id AND branch_id = v_branch_id
        ) THEN
            -- Actualizar registro existente
            UPDATE stock_levels 
            SET min_level = v_min_level,
                updated_at = NOW()
            WHERE product_id = v_product_id AND branch_id = v_branch_id;
        ELSE
            -- Crear nuevo registro de stock_levels si no existe
            INSERT INTO stock_levels (
                product_id, 
                branch_id, 
                qty_on_hand, 
                qty_reserved, 
                avg_cost, 
                min_level,
                created_at,
                updated_at
            ) VALUES (
                v_product_id, 
                v_branch_id, 
                0, 
                0, 
                0, 
                v_min_level,
                NOW(),
                NOW()
            );
        END IF;
    END LOOP;
END;
$$;


ALTER FUNCTION "public"."update_product_min_stock"("p_items" "jsonb") OWNER TO "postgres";


