CREATE OR REPLACE FUNCTION "public"."update_room_status_after_housekeeping"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    -- Si la tarea cambia a 'done', actualizar el estado del espacio a 'available' y limpiar notas
    IF NEW.status = 'done' AND OLD.status != 'done' THEN
        UPDATE spaces 
        SET 
            status = 'available',
            maintenance_notes = NULL
        WHERE id = NEW.space_id;
    END IF;
    RETURN NEW;
END;
$$;


