CREATE OR REPLACE FUNCTION "public"."update_stage_bypass"("p_opportunity_id" "uuid", "p_stage_id" "uuid", "p_status" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_success BOOLEAN := FALSE;
BEGIN
    -- Intento simple y directo de actualizar sin verificaciones
    BEGIN
        IF p_status IS NULL THEN
            UPDATE opportunities 
            SET 
                stage_id = p_stage_id, 
                updated_at = NOW() 
            WHERE id = p_opportunity_id;
        ELSE
            UPDATE opportunities 
            SET 
                stage_id = p_stage_id, 
                status = p_status, 
                updated_at = NOW() 
            WHERE id = p_opportunity_id;
        END IF;
        
        -- Verificar si se actualizó alguna fila
        IF FOUND THEN
            RETURN TRUE;
        ELSE
            RETURN FALSE;
        END IF;
        
    EXCEPTION WHEN OTHERS THEN
        RAISE LOG 'Error en actualización: %', SQLERRM;
        RETURN FALSE;
    END;
END;
$$;


