CREATE OR REPLACE FUNCTION "public"."update_stage_bypass_triggers"("p_stage_id" "uuid", "p_name" "text", "p_color" "text", "p_description" "text", "p_probability" numeric) RETURNS SETOF "public"."stages"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  -- Actualizar la etapa directamente
  RETURN QUERY
  UPDATE stages
  SET 
    name = p_name,
    color = p_color,
    description = p_description,
    probability = p_probability,
    updated_at = NOW()
  WHERE id = p_stage_id
  RETURNING *;
END;
$$;


