COMMENT ON FUNCTION "public"."update_stage_bypass_triggers"("p_stage_id" "uuid", "p_name" "text", "p_color" "text", "p_description" "text", "p_probability" numeric) IS 'Actualiza una etapa del pipeline evitando problemas con triggers de vistas materializadas';



CREATE OR REPLACE FUNCTION "public"."update_stage_safe"("p_stage_id" "uuid", "p_name" "text", "p_probability" numeric, "p_color" "text", "p_description" "text") RETURNS SETOF "public"."stages"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_organization_id UUID;
  v_user_id UUID;
BEGIN
  -- Obtener el usuario actual
  v_user_id := auth.uid();
  
  -- Verificar que el stage existe y obtener el pipeline_id
  DECLARE
    v_pipeline_id UUID;
  BEGIN
    SELECT pipeline_id INTO v_pipeline_id
    FROM stages
    WHERE id = p_stage_id;
    
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Stage not found';
    END IF;
    
    -- Obtener organization_id del pipeline
    SELECT organization_id INTO v_organization_id
    FROM pipelines
    WHERE id = v_pipeline_id;
    
    -- Verificar que el usuario pertenece a la organización
    IF NOT EXISTS (
      SELECT 1 FROM organization_members
      WHERE user_id = v_user_id
      AND organization_id = v_organization_id
    ) THEN
      RAISE EXCEPTION 'User does not have permission to update this stage';
    END IF;
  END;
  
  -- Actualizar la etapa
  RETURN QUERY
  UPDATE stages
  SET 
    name = p_name,
    probability = p_probability,
    color = p_color,
    description = p_description,
    updated_at = NOW()
  WHERE id = p_stage_id
  RETURNING *;

  -- Refrescar la vista materializada explícitamente
  -- como parte de la misma transacción con permisos elevados
  REFRESH MATERIALIZED VIEW mv_crm_forecast;
END;
$$;


ALTER FUNCTION "public"."update_stage_safe"("p_stage_id" "uuid", "p_name" "text", "p_probability" numeric, "p_color" "text", "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_stage_without_triggers"("p_stage_id" "uuid", "p_name" "text", "p_color" "text", "p_description" "text", "p_probability" numeric) RETURNS SETOF "public"."stages"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  result public.stages%rowtype;
  v_uid  uuid := auth.uid();
  v_ok   boolean;
begin
  -- La funcion corre como su propietario y se salta RLS: la autorizacion tiene
  -- que ser explicita. `auth.uid()` nulo solo puede venir de service_role o de
  -- un trabajo interno, porque a `anon` se le revoca EXECUTE mas abajo.
  if v_uid is null then
    v_ok := true;
  else
    select exists (
      select 1
      from public.stages s
      join public.pipelines p on p.id = s.pipeline_id
      join public.organization_members m on m.organization_id = p.organization_id
      where s.id = p_stage_id
        and m.user_id = v_uid
        and coalesce(m.is_active, true)
        and (coalesce(m.is_super_admin, false) or m.role_id in (1, 2, 5))
    ) into v_ok;
  end if;

  if not coalesce(v_ok, false) then
    raise exception 'No autorizado para modificar esta etapa' using errcode = '42501';
  end if;

  -- Se conserva el comportamiento original: los triggers de forecast se
  -- desactivan durante la escritura y se vuelven a activar al terminar.
  alter table stages disable trigger refresh_forecast_on_stage_change;
  alter table stages disable trigger trg_refresh_forecast_on_stage;
  alter table stages disable trigger trg_refresh_forecast_stages;

  update stages
     set name = p_name,
         color = p_color,
         description = p_description,
         probability = p_probability,
         updated_at = now()
   where id = p_stage_id
  returning * into result;

  alter table stages enable trigger refresh_forecast_on_stage_change;
  alter table stages enable trigger trg_refresh_forecast_on_stage;
  alter table stages enable trigger trg_refresh_forecast_stages;

  if result.id is null then
    raise exception 'Etapa no encontrada' using errcode = 'P0002';
  end if;

  return next result;
  return;
end
$$;


ALTER FUNCTION "public"."update_stage_without_triggers"("p_stage_id" "uuid", "p_name" "text", "p_color" "text", "p_description" "text", "p_probability" numeric) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_stage_without_triggers"("p_stage_id" "uuid", "p_name" "text", "p_color" "text", "p_description" "text", "p_probability" numeric) IS 'Actualiza una etapa del pipeline desactivando temporalmente los triggers que refrescan vistas materializadas';



