CREATE OR REPLACE FUNCTION "public"."upload_temporary_image"("p_image_url" "text", "p_storage_path" "text", "p_file_name" "text", "p_file_size" integer, "p_mime_type" "text", "p_dimensions" "jsonb" DEFAULT NULL::"jsonb", "p_tags" "text"[] DEFAULT '{}'::"text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_image_id INTEGER;
    v_result JSONB;
BEGIN
    -- Registrar la imagen usando la función existente
    v_image_id := register_shared_image(
        p_image_url,
        p_storage_path,
        p_file_name,
        p_file_size,
        p_mime_type,
        p_dimensions,
        FALSE,  -- No es pública por defecto
        p_tags
    );
    
    -- Preparar resultado
    SELECT jsonb_build_object(
        'image_id', v_image_id,
        'image_url', p_image_url,
        'file_name', p_file_name,
        'tags', p_tags
    ) INTO v_result;
    
    RETURN v_result;
END;
$$;


