CREATE OR REPLACE FUNCTION "public"."user_register_image"("p_image_url" "text", "p_storage_path" "text", "p_file_name" "text", "p_file_size" integer, "p_mime_type" "text", "p_organization_id" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_image_id INTEGER;
    v_auth_user_id UUID;
    v_org_id INTEGER;
BEGIN
    -- Obtener el ID del usuario autenticado
    v_auth_user_id := auth.uid();
    
    IF v_auth_user_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Usuario no autenticado',
            'error_code', 'UNAUTHENTICATED'
        );
    END IF;
    
    -- Verificar que el usuario tenga acceso a la organización
    IF EXISTS (
        SELECT 1 FROM information_schema.tables 
        WHERE table_schema = 'public' AND table_name = 'organization_users'
    ) THEN
        SELECT organization_id INTO v_org_id 
        FROM public.organization_users 
        WHERE user_id = v_auth_user_id AND organization_id = p_organization_id;
    ELSE
        -- Si no existe la tabla, simplemente usamos el ID proporcionado
        v_org_id := p_organization_id;
    END IF;
    
    -- Insertar la imagen como el propietario de la función sin validación RLS
    INSERT INTO public.shared_images (
        image_url, 
        storage_path, 
        file_name, 
        file_size, 
        mime_type, 
        organization_id,
        is_public,
        created_at
    ) VALUES (
        p_image_url, 
        p_storage_path, 
        p_file_name, 
        p_file_size, 
        p_mime_type, 
        p_organization_id,
        false,
        now()
    )
    RETURNING id INTO v_image_id;
    
    RETURN jsonb_build_object(
        'success', true,
        'image_id', v_image_id,
        'message', 'Imagen registrada correctamente'
    );
EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', SQLERRM,
            'error_code', SQLSTATE,
            'organization_id', p_organization_id
        );
END;
$$;


ALTER FUNCTION "public"."user_register_image"("p_image_url" "text", "p_storage_path" "text", "p_file_name" "text", "p_file_size" integer, "p_mime_type" "text", "p_organization_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_accounts_receivable_relations"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  org_exists BOOLEAN;
  customer_exists BOOLEAN;
  invoice_exists BOOLEAN;
  sale_exists BOOLEAN;
BEGIN
  -- Validar organization_id si está presente
  IF NEW.organization_id IS NOT NULL THEN
    SELECT EXISTS(SELECT 1 FROM organizations WHERE id = NEW.organization_id::text::integer) INTO org_exists;
    IF NOT org_exists THEN
      RAISE EXCEPTION 'La organización con ID % no existe', NEW.organization_id;
    END IF;
  END IF;
  
  -- Validar customer_id si está presente
  IF NEW.customer_id IS NOT NULL THEN
    SELECT EXISTS(SELECT 1 FROM customers WHERE id = NEW.customer_id::text::uuid) INTO customer_exists;
    IF NOT customer_exists THEN
      RAISE EXCEPTION 'El cliente con ID % no existe', NEW.customer_id;
    END IF;
  END IF;
  
  -- Validar invoice_id si está presente
  IF NEW.invoice_id IS NOT NULL THEN
    SELECT EXISTS(SELECT 1 FROM invoice_sales WHERE id = NEW.invoice_id::text::uuid) INTO invoice_exists;
    IF NOT invoice_exists THEN
      RAISE EXCEPTION 'La factura con ID % no existe', NEW.invoice_id;
    END IF;
  END IF;
  
  -- Validar sale_id si está presente
  IF NEW.sale_id IS NOT NULL THEN
    SELECT EXISTS(SELECT 1 FROM sales WHERE id = NEW.sale_id::text::uuid) INTO sale_exists;
    IF NOT sale_exists THEN
      RAISE EXCEPTION 'La venta con ID % no existe', NEW.sale_id;
    END IF;
  END IF;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."validate_accounts_receivable_relations"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_branch_belongs_to_org"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  branch_org_id integer;
BEGIN
  -- Solo validar si branch_id no es NULL (NULL = global, válido)
  IF NEW.branch_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Obtener el organization_id del branch referenciado
  SELECT organization_id INTO branch_org_id FROM branches WHERE id = NEW.branch_id;

  -- Si el branch no existe, dejar que la FK maneje el error
  IF NOT FOUND THEN
    RETURN NEW;
  END IF;

  -- Validar que el branch pertenece a la misma organización
  IF branch_org_id <> NEW.organization_id THEN
    RAISE EXCEPTION 'branch_id % no pertenece a organization_id % (pertenece a org %)',
      NEW.branch_id, NEW.organization_id, branch_org_id;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."validate_branch_belongs_to_org"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_branch_limit"("org_id" integer) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  max_allowed INTEGER;
  current_count INTEGER;
BEGIN
  SELECT p.max_branches INTO max_allowed
  FROM subscriptions s
  JOIN plans p ON s.plan_id = p.id
  WHERE s.organization_id = org_id
    AND s.status IN ('active', 'trialing')
  ORDER BY s.created_at DESC
  LIMIT 1;
  
  IF max_allowed IS NULL THEN
    RETURN true;
  END IF;
  
  SELECT COUNT(*) INTO current_count
  FROM branches
  WHERE organization_id = org_id
    AND is_active = true;
  
  RETURN current_count < max_allowed;
END;
$$;


ALTER FUNCTION "public"."validate_branch_limit"("org_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_invitation_by_code"("invitation_code" "text") RETURNS TABLE("id" integer, "email" "text", "code" "text", "status" "text", "role_id" integer, "organization_id" integer, "expires_at" timestamp with time zone, "organization_name" "text", "role_name" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    i.id,
    i.email::TEXT,
    i.code::TEXT,
    i.status::TEXT,
    i.role_id,
    i.organization_id,
    i.expires_at,
    COALESCE(o.name, 'Organización')::TEXT as organization_name,
    COALESCE(r.name, 'Usuario')::TEXT as role_name
  FROM invitations i
  LEFT JOIN organizations o ON i.organization_id = o.id
  LEFT JOIN roles r ON i.role_id = r.id
  WHERE i.code = invitation_code
    AND i.status = 'pending'
    AND i.expires_at > NOW();
END;
$$;


ALTER FUNCTION "public"."validate_invitation_by_code"("invitation_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_module_activation"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  org_plan_limit INTEGER;
  current_paid_modules INTEGER;
  is_module_core BOOLEAN;
  core_modules_count INTEGER;
BEGIN
  -- Solo validar en INSERT o UPDATE que active un módulo
  IF TG_OP = 'INSERT' OR (TG_OP = 'UPDATE' AND NEW.is_active = true AND (OLD.is_active IS NULL OR OLD.is_active = false)) THEN
    
    -- Verificar si el módulo es core
    SELECT is_core INTO is_module_core 
    FROM modules 
    WHERE code = NEW.module_code;
    
    -- Si es core, permitir siempre
    IF is_module_core THEN
      -- Asegurar que enabled_at esté establecido
      IF NEW.enabled_at IS NULL THEN
        NEW.enabled_at := NOW();
      END IF;
      RETURN NEW;
    END IF;
    
    -- Obtener límite del plan (filtrar por suscripción activa o en trial)
    SELECT p.max_modules INTO org_plan_limit
    FROM subscriptions s
    JOIN plans p ON s.plan_id = p.id
    WHERE s.organization_id = NEW.organization_id
      AND s.status IN ('active', 'trialing')
    ORDER BY s.created_at DESC
    LIMIT 1;
    
    -- Si no hay límite definido (NULL = ilimitado), permitir
    IF org_plan_limit IS NULL THEN
      IF NEW.enabled_at IS NULL THEN
        NEW.enabled_at := NOW();
      END IF;
      RETURN NEW;
    END IF;
    
    -- Contar módulos core DINÁMICAMENTE en vez de hardcodear
    SELECT COUNT(*) INTO core_modules_count
    FROM modules
    WHERE is_core = true AND is_active = true;
    
    -- Calcular módulos pagados permitidos (total - core)
    org_plan_limit := org_plan_limit - core_modules_count;
    
    -- Asegurar que no sea negativo
    IF org_plan_limit < 0 THEN
      org_plan_limit := 0;
    END IF;
    
    -- Contar módulos pagados activos actuales
    SELECT COUNT(*) INTO current_paid_modules
    FROM organization_modules om
    JOIN modules m ON om.module_code = m.code
    WHERE om.organization_id = NEW.organization_id
    AND om.is_active = true
    AND m.is_core = false
    AND (TG_OP = 'INSERT' OR om.module_code != NEW.module_code); -- Excluir el módulo actual en UPDATE
    
    -- Validar límite
    IF current_paid_modules >= org_plan_limit THEN
      RAISE EXCEPTION 'Cannot activate module %. Organization has reached the limit of % paid modules allowed by their plan.', 
        NEW.module_code, org_plan_limit;
    END IF;
    
    -- Asegurar que enabled_at esté establecido
    IF NEW.enabled_at IS NULL THEN
      NEW.enabled_at := NOW();
    END IF;
  END IF;
  
  -- Si se está desactivando, establecer disabled_at
  IF TG_OP = 'UPDATE' AND NEW.is_active = false AND OLD.is_active = true THEN
    NEW.disabled_at := NOW();
  END IF;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."validate_module_activation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_module_limit"("org_id" integer) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  max_allowed INTEGER;
  current_count INTEGER;
BEGIN
  -- Obtener límite del plan actual
  SELECT p.max_modules INTO max_allowed
  FROM subscriptions s
  JOIN plans p ON s.plan_id = p.id
  WHERE s.organization_id = org_id
    AND s.status IN ('active', 'trialing')
  ORDER BY s.created_at DESC
  LIMIT 1;
  
  -- Si no se encontró plan o es NULL (ilimitado), permitir
  IF max_allowed IS NULL THEN
    RETURN true;
  END IF;
  
  -- Contar módulos activos actuales
  SELECT COUNT(*) INTO current_count
  FROM organization_modules
  WHERE organization_id = org_id
    AND is_active = true;
  
  -- Retornar si aún hay espacio
  RETURN current_count < max_allowed;
END;
$$;


ALTER FUNCTION "public"."validate_module_limit"("org_id" integer) OWNER TO "postgres";


