CREATE TABLE IF NOT EXISTS "public"."customers" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" integer,
    "branch_id" integer,
    "email" "text",
    "phone" "text",
    "first_name" "text",
    "last_name" "text",
    "identification_type" "text",
    "identification_number" "text",
    "address" "text",
    "city" "text",
    "notes" "text",
    "is_registered" boolean DEFAULT false,
    "user_id" "uuid",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "doc_type" "text" GENERATED ALWAYS AS ("identification_type") STORED,
    "doc_number" "text" GENERATED ALWAYS AS ("identification_number") STORED,
    "roles" "text"[] DEFAULT '{cliente,huesped}'::"text"[],
    "tags" "text"[] DEFAULT '{}'::"text"[],
    "preferences" "jsonb" DEFAULT '{}'::"jsonb",
    "avatar_url" "text",
    "is_online" boolean DEFAULT false,
    "last_seen_at" timestamp with time zone,
    "dv" integer,
    "company_name" "text",
    "trade_name" "text",
    "legal_organization_id" integer DEFAULT 2,
    "tribute_id" integer DEFAULT 21,
    "fiscal_municipality_id" "uuid",
    "fiscal_responsibilities" "text"[],
    "customer_type" "text" DEFAULT 'person'::"text" NOT NULL,
    "parent_customer_id" "uuid",
    "full_name" "text" GENERATED ALWAYS AS (
CASE
    WHEN ("customer_type" = 'company'::"text") THEN COALESCE(NULLIF(TRIM(BOTH FROM "company_name"), ''::"text"), NULLIF(TRIM(BOTH FROM "trade_name"), ''::"text"), NULLIF(TRIM(BOTH FROM ((COALESCE("first_name", ''::"text") || ' '::"text") || COALESCE("last_name", ''::"text"))), ''::"text"), 'Empresa sin nombre'::"text")
    ELSE NULLIF(TRIM(BOTH FROM ((COALESCE("first_name", ''::"text") || ' '::"text") || COALESCE("last_name", ''::"text"))), ''::"text")
END) STORED,
    "health_score" integer,
    "health_score_updated_at" timestamp with time zone,
    "company_size" "text",
    "branches_count" integer,
    "current_software" "text",
    "lifecycle_stage" "text" DEFAULT 'lead'::"text" NOT NULL,
    "vertical_id" "uuid",
    "timezone" "text" DEFAULT 'America/Bogota'::"text" NOT NULL,
    "do_not_call" boolean DEFAULT false NOT NULL,
    CONSTRAINT "customers_customer_type_check" CHECK (("customer_type" = ANY (ARRAY['person'::"text", 'company'::"text"]))),
    CONSTRAINT "customers_lifecycle_stage_check" CHECK (("lifecycle_stage" = ANY (ARRAY['lead'::"text", 'opportunity'::"text", 'customer'::"text", 'churned'::"text"])))
);


ALTER TABLE "public"."customers" OWNER TO "postgres";


COMMENT ON COLUMN "public"."customers"."doc_type" IS 'Tipo de documento de identidad (alias para identification_type)';



COMMENT ON COLUMN "public"."customers"."doc_number" IS 'Número de documento de identidad (alias para identification_number)';



