    "updated_at" timestamp with time zone DEFAULT "now"(),
    CONSTRAINT "check_trips_available_seats" CHECK ((("available_seats" >= 0) AND ("available_seats" <= "total_seats"))),
    CONSTRAINT "trips_status_check" CHECK (("status" = ANY (ARRAY['scheduled'::"text", 'boarding'::"text", 'in_transit'::"text", 'arrived'::"text", 'completed'::"text", 'cancelled'::"text", 'delayed'::"text"])))
);


ALTER TABLE "public"."trips" OWNER TO "postgres";


COMMENT ON TABLE "public"."trips" IS 'Viajes ejecutados o programados para transporte de pasajeros';



COMMENT ON CONSTRAINT "check_trips_available_seats" ON "public"."trips" IS 'Previene overbooking: available_seats debe estar entre 0 y total_seats';



CREATE OR REPLACE VIEW "public"."calendar_unified" WITH ("security_invoker"='true') AS
 SELECT 'calendar_event'::"text" AS "source_type",
    ("calendar_events"."id")::"text" AS "source_id",
    "calendar_events"."organization_id",
    "calendar_events"."branch_id",
    "calendar_events"."title",
    "calendar_events"."description",
    "calendar_events"."start_at",
    "calendar_events"."end_at",
    "calendar_events"."all_day",
    "calendar_events"."assigned_to",
    "calendar_events"."customer_id",
    "calendar_events"."event_type",
    "calendar_events"."color",
    "calendar_events"."status",
    "calendar_events"."recurrence_rule",
    "calendar_events"."metadata"
   FROM "public"."calendar_events"
  WHERE ("calendar_events"."status" <> 'cancelled'::"text")
UNION ALL
 SELECT 'task'::"text" AS "source_type",
    ("tasks"."id")::"text" AS "source_id",
    "tasks"."organization_id",
    NULL::integer AS "branch_id",
    "tasks"."title",
    "tasks"."description",
    COALESCE("tasks"."start_time", "tasks"."due_date") AS "start_at",
    COALESCE("tasks"."due_date", "tasks"."start_time") AS "end_at",
    false AS "all_day",
    "tasks"."assigned_to",
    "tasks"."customer_id",
    COALESCE("tasks"."type", 'task'::"text") AS "event_type",
        CASE "tasks"."priority"
            WHEN 'high'::"text" THEN '#EF4444'::"text"
            WHEN 'medium'::"text" THEN '#F59E0B'::"text"
            ELSE '#6B7280'::"text"
        END AS "color",
    "tasks"."status",
    NULL::"text" AS "recurrence_rule",
    '{}'::"jsonb" AS "metadata"
   FROM "public"."tasks"
  WHERE (("tasks"."status" <> ALL (ARRAY['done'::"text", 'canceled'::"text"])) AND (("tasks"."start_time" IS NOT NULL) OR ("tasks"."due_date" IS NOT NULL)))
UNION ALL
 SELECT 'shift'::"text" AS "source_type",
    ("sa"."id")::"text" AS "source_id",
    "sa"."organization_id",
    "sa"."branch_id",
    COALESCE("st"."name", 'Turno'::"text") AS "title",
    "sa"."notes" AS "description",
    (("sa"."work_date" + COALESCE("sa"."actual_start_time", "st"."start_time")))::timestamp with time zone AS "start_at",
    (("sa"."work_date" + COALESCE("sa"."actual_end_time", "st"."end_time")))::timestamp with time zone AS "end_at",
    false AS "all_day",
    "om"."user_id" AS "assigned_to",
    NULL::"uuid" AS "customer_id",
    'shift'::"text" AS "event_type",
    '#8B5CF6'::"text" AS "color",
    "sa"."status",
    NULL::"text" AS "recurrence_rule",
    '{}'::"jsonb" AS "metadata"
   FROM ((("public"."shift_assignments" "sa"
     LEFT JOIN "public"."shift_templates" "st" ON (("st"."id" = "sa"."shift_template_id")))
     LEFT JOIN "public"."employments" "emp" ON (("emp"."id" = "sa"."employment_id")))
     LEFT JOIN "public"."organization_members" "om" ON (("om"."id" = "emp"."organization_member_id")))
  WHERE ("sa"."status" <> 'cancelled'::"text")
UNION ALL
 SELECT 'leave'::"text" AS "source_type",
    ("lr"."id")::"text" AS "source_id",
    "lr"."organization_id",
    NULL::integer AS "branch_id",
    COALESCE("lt"."name", 'Ausencia'::"text") AS "title",
    "lr"."reason" AS "description",
    ("lr"."start_date")::timestamp with time zone AS "start_at",
    (("lr"."end_date" + '1 day'::interval))::timestamp with time zone AS "end_at",
    true AS "all_day",
    "om"."user_id" AS "assigned_to",
    NULL::"uuid" AS "customer_id",
    'leave'::"text" AS "event_type",
    '#F97316'::"text" AS "color",
    "lr"."status",
    NULL::"text" AS "recurrence_rule",
    '{}'::"jsonb" AS "metadata"
   FROM ((("public"."leave_requests" "lr"
     LEFT JOIN "public"."leave_types" "lt" ON (("lt"."id" = "lr"."leave_type_id")))
     LEFT JOIN "public"."employments" "emp" ON (("emp"."id" = "lr"."employment_id")))
     LEFT JOIN "public"."organization_members" "om" ON (("om"."id" = "emp"."organization_member_id")))
  WHERE ("lr"."status" = ANY (ARRAY['approved'::"text", 'pending'::"text"]))
UNION ALL
 SELECT 'reservation'::"text" AS "source_type",
    ("r"."id")::"text" AS "source_id",
    "r"."organization_id",
    "r"."branch_id",
    COALESCE("c"."full_name", 'Reserva'::"text") AS "title",
    "r"."notes" AS "description",
    COALESCE(("r"."checkin")::timestamp with time zone, "r"."start_date") AS "start_at",
    COALESCE(("r"."checkout")::timestamp with time zone, "r"."end_date") AS "end_at",
    true AS "all_day",
    NULL::"uuid" AS "assigned_to",
    "r"."customer_id",
    'reservation'::"text" AS "event_type",
    '#10B981'::"text" AS "color",
    ("r"."status")::"text" AS "status",
    NULL::"text" AS "recurrence_rule",
    COALESCE("r"."metadata", '{}'::"jsonb") AS "metadata"
   FROM ("public"."reservations" "r"
     LEFT JOIN "public"."customers" "c" ON (("c"."id" = "r"."customer_id")))
  WHERE (("r"."status")::"text" <> ALL (ARRAY['cancelled'::"text", 'no_show'::"text"]))
UNION ALL
 SELECT 'housekeeping'::"text" AS "source_type",
    ("ht"."id")::"text" AS "source_id",
    "b"."organization_id",
    "s"."branch_id",
    "concat"('Limpieza: ', "s"."label") AS "title",
    "ht"."notes" AS "description",
    ("ht"."task_date")::timestamp with time zone AS "start_at",
    (("ht"."task_date" + '02:00:00'::interval))::timestamp with time zone AS "end_at",
    false AS "all_day",
    "ht"."assigned_to",
    NULL::"uuid" AS "customer_id",
    'housekeeping'::"text" AS "event_type",
    '#06B6A4'::"text" AS "color",
    ("ht"."status")::"text" AS "status",
    NULL::"text" AS "recurrence_rule",
    '{}'::"jsonb" AS "metadata"
   FROM (("public"."housekeeping_tasks" "ht"
     LEFT JOIN "public"."spaces" "s" ON (("s"."id" = "ht"."space_id")))
     LEFT JOIN "public"."branches" "b" ON (("b"."id" = "s"."branch_id")))
  WHERE (("ht"."status")::"text" <> ALL (ARRAY['completed'::"text", 'cancelled'::"text"]))
UNION ALL
 SELECT 'maintenance'::"text" AS "source_type",
    ("mo"."id")::"text" AS "source_id",
    "b"."organization_id",
    "mo"."branch_id",
    "concat"('Mantenimiento: ', "left"("mo"."description", 50)) AS "title",
    "mo"."description",
    "mo"."created_at" AS "start_at",
    COALESCE("mo"."resolved_at", ("mo"."created_at" + '04:00:00'::interval)) AS "end_at",
    false AS "all_day",
    "mo"."assigned_to",
    NULL::"uuid" AS "customer_id",
    'maintenance'::"text" AS "event_type",
    '#EF4444'::"text" AS "color",
    ("mo"."status")::"text" AS "status",
    NULL::"text" AS "recurrence_rule",
    '{}'::"jsonb" AS "metadata"
   FROM ("public"."maintenance_orders" "mo"
     LEFT JOIN "public"."branches" "b" ON (("b"."id" = "mo"."branch_id")))
  WHERE (("mo"."status")::"text" <> ALL (ARRAY['resolved'::"text", 'cancelled'::"text"]))
UNION ALL
 SELECT 'gym_class'::"text" AS "source_type",
    ("gc"."id")::"text" AS "source_id",
    "gc"."organization_id",
    "gc"."branch_id",
    "gc"."title",
    "gc"."description",
    "gc"."start_at",
    COALESCE("gc"."end_at", ("gc"."start_at" + (("gc"."duration_minutes" || ' minutes'::"text"))::interval)) AS "end_at",
    false AS "all_day",
    "gc"."instructor_id" AS "assigned_to",
    NULL::"uuid" AS "customer_id",
    COALESCE("gc"."class_type", 'gym_class'::"text") AS "event_type",
    '#EC4899'::"text" AS "color",
    "gc"."status",
    ("gc"."recurrence")::"text" AS "recurrence_rule",
    '{}'::"jsonb" AS "metadata"
   FROM "public"."gym_classes" "gc"
  WHERE ("gc"."status" <> 'cancelled'::"text")
UNION ALL
 SELECT 'trip'::"text" AS "source_type",
    ("t"."id")::"text" AS "source_id",
    "t"."organization_id",
    "t"."branch_id",
    COALESCE("t"."trip_code", 'Viaje'::"text") AS "title",
    "t"."notes" AS "description",
    "t"."scheduled_departure" AS "start_at",
    "t"."scheduled_arrival" AS "end_at",
    false AS "all_day",
    "t"."driver_id" AS "assigned_to",
    NULL::"uuid" AS "customer_id",
    'trip'::"text" AS "event_type",
    '#0EA5E9'::"text" AS "color",
    "t"."status",
    NULL::"text" AS "recurrence_rule",
    COALESCE("t"."metadata", '{}'::"jsonb") AS "metadata"
   FROM "public"."trips" "t"
  WHERE ("t"."status" <> ALL (ARRAY['cancelled'::"text", 'completed'::"text"]));


