    "organization_id" integer NOT NULL,
    "code" "text" NOT NULL,
    "name" "text" NOT NULL,
    "description" "text",
    "module" "text" NOT NULL,
    "category" "text" DEFAULT 'custom'::"text",
    "sample_payload" "jsonb" DEFAULT '{}'::"jsonb",
    "is_active" boolean DEFAULT true,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"()
);


ALTER TABLE "public"."custom_events" OWNER TO "postgres";


COMMENT ON TABLE "public"."custom_events" IS 'Eventos personalizados definidos por cada organización';



COMMENT ON COLUMN "public"."custom_events"."code" IS 'Código único del evento (ej: cliente.vencimiento_contrato)';



COMMENT ON COLUMN "public"."custom_events"."category" IS 'Categoría: system, business, custom';



COMMENT ON COLUMN "public"."custom_events"."sample_payload" IS 'Ejemplo de payload para documentación';



CREATE TABLE IF NOT EXISTS "public"."customer_addresses" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" integer NOT NULL,
    "customer_id" "uuid" NOT NULL,
    "label" "text" DEFAULT 'Principal'::"text" NOT NULL,
    "recipient_name" "text",
    "recipient_phone" "text",
    "address_line1" "text" NOT NULL,
    "address_line2" "text",
    "city" "text" NOT NULL,
    "department" "text",
    "country_code" "text" DEFAULT 'CO'::"text",
    "postal_code" "text",
    "latitude" numeric(10,7),
    "longitude" numeric(10,7),
    "google_place_id" "text",
    "delivery_instructions" "text",
    "is_default" boolean DEFAULT false,
    "is_active" boolean DEFAULT true,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "municipality_id" "uuid",
    "branch_id" bigint
);


ALTER TABLE "public"."customer_addresses" OWNER TO "postgres";


COMMENT ON TABLE "public"."customer_addresses" IS 'Direcciones múltiples por cliente para envíos';



CREATE TABLE IF NOT EXISTS "public"."customer_biometrics" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "customer_id" "uuid" NOT NULL,
    "organization_id" integer NOT NULL,
    "biometric_type" "text" NOT NULL,
    "finger_index" integer,
    "template_data" "text" NOT NULL,
    "template_format" "text" DEFAULT 'base64'::"text",
    "enrolled_device_id" "uuid",
    "quality_score" integer,
    "is_active" boolean DEFAULT true,
    "enrolled_at" timestamp with time zone DEFAULT "now"(),
    "last_used_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    CONSTRAINT "customer_biometrics_biometric_type_check" CHECK (("biometric_type" = ANY (ARRAY['fingerprint'::"text", 'face'::"text"]))),
    CONSTRAINT "customer_biometrics_finger_index_check" CHECK ((("finger_index" IS NULL) OR (("finger_index" >= 1) AND ("finger_index" <= 10)))),
    CONSTRAINT "customer_biometrics_quality_score_check" CHECK ((("quality_score" IS NULL) OR (("quality_score" >= 0) AND ("quality_score" <= 100))))
);


ALTER TABLE "public"."customer_biometrics" OWNER TO "postgres";


COMMENT ON TABLE "public"."customer_biometrics" IS 'Almacena templates biométricos de clientes (huellas digitales, reconocimiento facial)';



COMMENT ON COLUMN "public"."customer_biometrics"."finger_index" IS 'Índice del dedo: 1=pulgar izq, 2=índice izq, ..., 6=pulgar der, ...';



COMMENT ON COLUMN "public"."customer_biometrics"."template_data" IS 'Template biométrico en formato base64 o propietario del SDK';



CREATE TABLE IF NOT EXISTS "public"."customer_channel_identities" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" integer NOT NULL,
    "customer_id" "uuid" NOT NULL,
    "channel_id" "uuid" NOT NULL,
    "identity_type" "text" NOT NULL,
    "identity_value" "text" NOT NULL,
    "verified" boolean DEFAULT false,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb",
    "first_seen_at" timestamp with time zone DEFAULT "now"(),
    "last_seen_at" timestamp with time zone DEFAULT "now"(),
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    CONSTRAINT "customer_channel_identities_identity_type_check" CHECK (("identity_type" = ANY (ARRAY['widget_anon'::"text", 'widget_identified'::"text", 'whatsapp_phone'::"text", 'instagram_user'::"text", 'facebook_psid'::"text"])))
);


ALTER TABLE "public"."customer_channel_identities" OWNER TO "postgres";


COMMENT ON TABLE "public"."customer_channel_identities" IS 'Identidades de clientes por canal - permite omnicanal unificado';



COMMENT ON COLUMN "public"."customer_channel_identities"."identity_type" IS 'Tipo de identidad según el canal';



COMMENT ON COLUMN "public"."customer_channel_identities"."identity_value" IS 'Valor único de la identidad (phone, username, session_id, etc)';



COMMENT ON COLUMN "public"."customer_channel_identities"."verified" IS 'Si la identidad ha sido verificada';



COMMENT ON COLUMN "public"."customer_channel_identities"."metadata" IS 'Datos adicionales específicos del canal';



