CREATE TABLE IF NOT EXISTS "public"."cycle_count_lines" (
    "id" integer NOT NULL,
    "cycle_count_id" integer NOT NULL,
    "product_id" integer NOT NULL,
    "expected_qty" numeric(12,3) DEFAULT 0,
    "counted_qty" numeric(12,3) DEFAULT 0,
    "lot_id" integer,
    "variance" numeric(12,3) GENERATED ALWAYS AS (("counted_qty" - "expected_qty")) STORED,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "status" "text" DEFAULT 'pending'::"text",
    CONSTRAINT "cycle_count_lines_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'counted'::"text", 'verified'::"text"])))
);


ALTER TABLE "public"."cycle_count_lines" OWNER TO "postgres";


CREATE SEQUENCE IF NOT EXISTS "public"."cycle_count_lines_id_seq"
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER TABLE "public"."cycle_count_lines_id_seq" OWNER TO "postgres";


ALTER SEQUENCE "public"."cycle_count_lines_id_seq" OWNED BY "public"."cycle_count_lines"."id";



