CREATE TABLE IF NOT EXISTS "public"."delivery_attempts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "shipment_id" "uuid" NOT NULL,
    "attempt_number" smallint NOT NULL,
    "attempted_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "status" "text" NOT NULL,
    "failure_reason_code" "text",
    "failure_reason_text" "text",
    "latitude" numeric(10,7),
    "longitude" numeric(10,7),
    "driver_id" "uuid",
    "driver_notes" "text",
    "reschedule_date" "date",
    "reschedule_notes" "text",
    "photo_urls" "text"[],
    "metadata" "jsonb" DEFAULT '{}'::"jsonb",
    "created_at" timestamp with time zone DEFAULT "now"(),
    CONSTRAINT "delivery_attempts_failure_reason_code_check" CHECK (("failure_reason_code" = ANY (ARRAY['not_home'::"text", 'wrong_address'::"text", 'incomplete_address'::"text", 'rejected'::"text", 'damaged'::"text", 'access_denied'::"text", 'business_closed'::"text", 'weather'::"text", 'vehicle_issue'::"text", 'customer_request'::"text", 'other'::"text"]))),
    CONSTRAINT "delivery_attempts_status_check" CHECK (("status" = ANY (ARRAY['success'::"text", 'failed'::"text", 'partial'::"text"])))
);


ALTER TABLE "public"."delivery_attempts" OWNER TO "postgres";


COMMENT ON TABLE "public"."delivery_attempts" IS 'Registro de intentos de entrega de envíos';



CREATE TABLE IF NOT EXISTS "public"."delivery_logs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "notification_id" "uuid" NOT NULL,
    "attempt_no" integer DEFAULT 1 NOT NULL,
    "provider_response" "jsonb" DEFAULT '{}'::"jsonb",
