    "status" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "delivery_logs_status_check" CHECK (("status" = ANY (ARRAY['success'::"text", 'fail'::"text"])))
);


ALTER TABLE "public"."delivery_logs" OWNER TO "postgres";


COMMENT ON TABLE "public"."delivery_logs" IS 'Traza de cada intento/envío externo de notificaciones';



COMMENT ON COLUMN "public"."delivery_logs"."notification_id" IS 'Referencia a la notificación relacionada';



COMMENT ON COLUMN "public"."delivery_logs"."attempt_no" IS 'Número de intento de envío (1-based)';



COMMENT ON COLUMN "public"."delivery_logs"."provider_response" IS 'Respuesta del proveedor en formato JSON';



COMMENT ON COLUMN "public"."delivery_logs"."delivered_at" IS 'Fecha y hora del intento de entrega';



COMMENT ON COLUMN "public"."delivery_logs"."status" IS 'Estado del intento: success, fail';



