CREATE TABLE IF NOT EXISTS "public"."electronic_invoicing_jobs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" integer NOT NULL,
    "invoice_id" "uuid",
    "document_type" "text" NOT NULL,
    "provider" "text" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "attempt_count" smallint DEFAULT 0 NOT NULL,
    "max_attempts" smallint DEFAULT 5 NOT NULL,
    "next_retry_at" timestamp with time zone,
    "request_payload" "jsonb",
    "response_payload" "jsonb",
    "cufe" character varying(100),
    "qr_code" "text",
    "error_code" "text",
    "error_message" "text",
    "processed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "support_document_id" "uuid",
    CONSTRAINT "electronic_invoicing_jobs_document_type_check" CHECK (("document_type" = ANY (ARRAY['invoice'::"text", 'credit_note'::"text", 'debit_note'::"text", 'support_document'::"text"]))),
    CONSTRAINT "electronic_invoicing_jobs_provider_check" CHECK (("provider" = ANY (ARRAY['carvajal'::"text", 'facturatech'::"text", 'siigo'::"text", 'alegra'::"text", 'world_office'::"text", 'factus'::"text", 'other'::"text"]))),
    CONSTRAINT "electronic_invoicing_jobs_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'processing'::"text", 'sent'::"text", 'accepted'::"text", 'rejected'::"text", 'failed'::"text", 'cancelled'::"text"])))
);


ALTER TABLE "public"."electronic_invoicing_jobs" OWNER TO "postgres";


COMMENT ON TABLE "public"."electronic_invoicing_jobs" IS 'Cola de trabajos para envío de facturas electrónicas a proveedores DIAN';



COMMENT ON COLUMN "public"."electronic_invoicing_jobs"."provider" IS 'Proveedor de facturación: carvajal, facturatech, siigo, alegra, world_office';



COMMENT ON COLUMN "public"."electronic_invoicing_jobs"."cufe" IS 'Código Único de Factura Electrónica asignado por DIAN';



COMMENT ON COLUMN "public"."electronic_invoicing_jobs"."qr_code" IS 'Código QR para validación DIAN';



