    CONSTRAINT "employee_loans_status_check" CHECK (("status" = ANY (ARRAY['requested'::"text", 'approved'::"text", 'active'::"text", 'paid'::"text", 'cancelled'::"text", 'defaulted'::"text", 'written_off'::"text"])))
);


