CREATE TABLE IF NOT EXISTS "public"."event_triggers" (
    "id" "uuid" DEFAULT "extensions"."uuid_generate_v4"() NOT NULL,
    "organization_id" integer NOT NULL,
    "name" "text" NOT NULL,
    "event_code" "text" NOT NULL,
    "template_id" "uuid",
    "channels" "text"[] NOT NULL,
    "priority" integer DEFAULT 1,
    "silent_window_minutes" integer DEFAULT 0,
    "active" boolean DEFAULT true,
    "conditions" "jsonb" DEFAULT '{}'::"jsonb",
    "webhook_url" "text",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "event_source" "text" DEFAULT 'system'::"text",
    "custom_event_id" "uuid",
    "last_executed_at" timestamp with time zone,
    CONSTRAINT "event_triggers_channels_check" CHECK (("channels" <@ ARRAY['email'::"text", 'whatsapp'::"text", 'webhook'::"text", 'push'::"text", 'sms'::"text"])),
    CONSTRAINT "event_triggers_event_source_check" CHECK (("event_source" = ANY (ARRAY['system'::"text", 'custom'::"text"]))),
    CONSTRAINT "event_triggers_priority_check" CHECK ((("priority" >= 1) AND ("priority" <= 10))),
    CONSTRAINT "event_triggers_silent_window_minutes_check" CHECK (("silent_window_minutes" >= 0)),
    CONSTRAINT "event_triggers_source_check" CHECK (((("event_source" = 'system'::"text") AND ("event_code" IS NOT NULL) AND ("custom_event_id" IS NULL)) OR (("event_source" = 'custom'::"text") AND ("custom_event_id" IS NOT NULL) AND ("event_code" IS NULL))))
);


ALTER TABLE "public"."event_triggers" OWNER TO "postgres";


COMMENT ON TABLE "public"."event_triggers" IS 'Configuración de triggers automáticos basados en eventos';



COMMENT ON COLUMN "public"."event_triggers"."silent_window_minutes" IS 'Tiempo mínimo entre ejecuciones del mismo trigger (en minutos)';



COMMENT ON COLUMN "public"."event_triggers"."event_source" IS 'Fuente del evento: system (predefinido) o custom (personalizado)';



COMMENT ON COLUMN "public"."event_triggers"."custom_event_id" IS 'ID del evento personalizado (si aplica)';



