    CONSTRAINT "integration_credentials_purpose_check" CHECK (("purpose" = ANY (ARRAY['primary'::"text", 'backup'::"text", 'legacy'::"text", 'rotation'::"text", 'public_key'::"text", 'private_key'::"text", 'events_secret'::"text", 'integrity_secret'::"text", 'access_token'::"text", 'refresh_token'::"text", 'webhook_secret'::"text"]))),
    CONSTRAINT "integration_credentials_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'expired'::"text", 'revoked'::"text", 'rotating'::"text"])))
);


ALTER TABLE "public"."integration_credentials" OWNER TO "postgres";


