COMMENT ON COLUMN "public"."integration_credentials"."metadata" IS 'Metadata adicional: scopes otorgados, account_id remoto, etc.';



CREATE TABLE IF NOT EXISTS "public"."integration_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "connection_id" "uuid" NOT NULL,
    "source" "text" NOT NULL,
    "direction" "text" NOT NULL,
    "event_type" "text" NOT NULL,
    "external_event_id" "text",
    "payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "status" "text" DEFAULT 'received'::"text" NOT NULL,
    "processed_at" timestamp with time zone,
    "error_message" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "correlation_id" "uuid",
    "event_time" timestamp with time zone GENERATED ALWAYS AS ("created_at") STORED,
    "organization_id" integer,
    CONSTRAINT "integration_events_direction_check" CHECK (("direction" = ANY (ARRAY['inbound'::"text", 'outbound'::"text"]))),
    CONSTRAINT "integration_events_source_check" CHECK (("source" = ANY (ARRAY['webhook'::"text", 'sync'::"text", 'manual'::"text", 'system'::"text"]))),
    CONSTRAINT "integration_events_status_check" CHECK (("status" = ANY (ARRAY['received'::"text", 'processed'::"text", 'error'::"text"])))
);


ALTER TABLE "public"."integration_events" OWNER TO "postgres";


COMMENT ON TABLE "public"."integration_events" IS 'Log inmutable de eventos de integración (auditoría y trazabilidad)';



COMMENT ON COLUMN "public"."integration_events"."source" IS 'Origen: webhook, sync, manual, system';



COMMENT ON COLUMN "public"."integration_events"."direction" IS 'Dirección: inbound (recibido), outbound (enviado)';



COMMENT ON COLUMN "public"."integration_events"."event_type" IS 'Tipo de evento: reservation.created, payment.succeeded, etc.';



COMMENT ON COLUMN "public"."integration_events"."external_event_id" IS 'ID del evento externo para deduplicación';



COMMENT ON COLUMN "public"."integration_events"."status" IS 'Estado: received, processed, error (sin retry, eso va en cola)';



COMMENT ON COLUMN "public"."integration_events"."correlation_id" IS 'UUID compartido entre eventos causados por la misma acción del usuario';



COMMENT ON COLUMN "public"."integration_events"."organization_id" IS 'ID de organización para filtrado directo. Derivado de integration_connections.';



CREATE TABLE IF NOT EXISTS "public"."integration_jobs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "connection_id" "uuid" NOT NULL,
    "job_type" "text" NOT NULL,
    "resource_type" "text" NOT NULL,
    "status" "text" DEFAULT 'queued'::"text" NOT NULL,
    "run_count" integer DEFAULT 0 NOT NULL,
    "last_run_at" timestamp with time zone,
    "last_status" "text",
    "last_error" "text",
    "cursor" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
