    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "integration_jobs_job_type_check" CHECK (("job_type" = ANY (ARRAY['pull'::"text", 'push'::"text", 'full_sync'::"text", 'incremental'::"text", 'reconcile'::"text", 'webhook_replay'::"text"]))),
    CONSTRAINT "integration_jobs_last_status_check" CHECK (("last_status" = ANY (ARRAY['success'::"text", 'failed'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "integration_jobs_status_check" CHECK (("status" = ANY (ARRAY['queued'::"text", 'running'::"text", 'success'::"text", 'failed'::"text", 'cancelled'::"text"])))
);


ALTER TABLE "public"."integration_jobs" OWNER TO "postgres";


COMMENT ON TABLE "public"."integration_jobs" IS 'Registro de jobs de sincronización para UI y soporte (sin scheduling)';



COMMENT ON COLUMN "public"."integration_jobs"."job_type" IS 'Tipo: pull, push, full_sync, incremental, reconcile, webhook_replay';



COMMENT ON COLUMN "public"."integration_jobs"."resource_type" IS 'Recurso: reservations, payments, products, messages, orders, payouts';



COMMENT ON COLUMN "public"."integration_jobs"."cursor" IS 'Cursor/checkpoint para sincronización incremental: {since, page_token, offset}';



COMMENT ON COLUMN "public"."integration_jobs"."stats" IS 'Estadísticas del último run: {created, updated, deleted, errors}';



CREATE TABLE IF NOT EXISTS "public"."integration_object_mappings" (
