CREATE MATERIALIZED VIEW "public"."mv_crm_forecast" AS
 SELECT "o"."id" AS "opportunity_id",
    "o"."organization_id",
    "o"."pipeline_id",
    "o"."stage_id",
    "o"."customer_id",
    "o"."name" AS "opportunity_name",
    "o"."amount",
    "o"."currency",
    "o"."expected_close_date",
    "o"."status",
    (EXTRACT(year FROM "o"."expected_close_date"))::integer AS "expected_year",
    (EXTRACT(month FROM "o"."expected_close_date"))::integer AS "expected_month",
    (EXTRACT(quarter FROM "o"."expected_close_date"))::integer AS "expected_quarter",
    "s"."name" AS "stage_name",
    "s"."probability",
    "s"."color",
    (("o"."amount" * ("s"."probability")::numeric) / 100.0) AS "forecast_amount",
    "c"."full_name" AS "customer_name",
    "p"."name" AS "pipeline_name"
   FROM ((("public"."opportunities" "o"
     JOIN "public"."stages" "s" ON (("o"."stage_id" = "s"."id")))
     LEFT JOIN "public"."customers" "c" ON (("o"."customer_id" = "c"."id")))
     JOIN "public"."pipelines" "p" ON (("o"."pipeline_id" = "p"."id")))
  WHERE ("o"."status" = ANY (ARRAY['open'::"text", 'won'::"text"]))
  WITH NO DATA;


ALTER TABLE "public"."mv_crm_forecast" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_folio_revenue" AS
 SELECT "date_trunc"('day'::"text", "f"."created_at") AS "date",
    "r"."branch_id",
    "r"."organization_id",
    "count"(DISTINCT "f"."id") AS "total_folios",
    "count"(DISTINCT
        CASE
            WHEN ("f"."status" = 'closed'::"public"."folio_status") THEN "f"."id"
            ELSE NULL::"uuid"
        END) AS "closed_folios",
    "sum"("f"."balance") AS "total_balance",
    "sum"(
        CASE
            WHEN ("f"."status" = 'closed'::"public"."folio_status") THEN (0)::numeric
            ELSE "f"."balance"
        END) AS "pending_balance",
    "sum"(
        CASE
            WHEN ("fi"."source" = 'pos'::"text") THEN "fi"."amount"
            ELSE (0)::numeric
        END) AS "pos_revenue",
    "sum"(
        CASE
            WHEN ("fi"."source" = 'manual'::"text") THEN "fi"."amount"
            ELSE (0)::numeric
        END) AS "manual_charges",
    "sum"(
        CASE
            WHEN ("fi"."source" = 'room_service'::"text") THEN "fi"."amount"
            ELSE (0)::numeric
        END) AS "room_service_revenue",
    "count"(DISTINCT "fi"."id") AS "total_items",
    "avg"("fi"."amount") AS "avg_item_amount"
   FROM (("public"."folios" "f"
     JOIN "public"."reservations" "r" ON (("f"."reservation_id" = "r"."id")))
     LEFT JOIN "public"."folio_items" "fi" ON (("f"."id" = "fi"."folio_id")))
  GROUP BY ("date_trunc"('day'::"text", "f"."created_at")), "r"."branch_id", "r"."organization_id"
  WITH NO DATA;


ALTER TABLE "public"."mv_folio_revenue" OWNER TO "postgres";


COMMENT ON MATERIALIZED VIEW "public"."mv_folio_revenue" IS 'Vista materializada con análisis de revenue por folios y fuentes.
Refrescar con: REFRESH MATERIALIZED VIEW mv_folio_revenue;';



