CREATE MATERIALIZED VIEW "public"."mv_pms_stats" AS
 SELECT "date_trunc"('day'::"text", ("r"."checkin")::timestamp with time zone) AS "date",
    "r"."branch_id",
    "st"."name" AS "space_type",
    "count"(DISTINCT "r"."id") AS "total_reservations",
    "count"(DISTINCT "rs"."space_id") AS "spaces_reserved",
    "sum"("r"."occupant_count") AS "total_occupants",
    "avg"("r"."total_estimated") AS "avg_reservation_value",
    "sum"("r"."total_estimated") AS "total_estimated_revenue",
    "count"(DISTINCT
        CASE
            WHEN ("r"."status" = 'checked_in'::"public"."reservation_status") THEN "r"."id"
            ELSE NULL::"uuid"
        END) AS "checked_in_count",
    "count"(DISTINCT
        CASE
            WHEN ("r"."status" = 'checked_out'::"public"."reservation_status") THEN "r"."id"
            ELSE NULL::"uuid"
        END) AS "checked_out_count",
    "count"(DISTINCT
        CASE
            WHEN ("r"."status" = 'cancelled'::"public"."reservation_status") THEN "r"."id"
            ELSE NULL::"uuid"
        END) AS "cancelled_count",
    "count"(DISTINCT
        CASE
            WHEN ("r"."status" = 'no_show'::"public"."reservation_status") THEN "r"."id"
            ELSE NULL::"uuid"
        END) AS "no_show_count"
   FROM ((("public"."reservations" "r"
     LEFT JOIN "public"."reservation_spaces" "rs" ON (("r"."id" = "rs"."reservation_id")))
     LEFT JOIN "public"."spaces" "s" ON (("rs"."space_id" = "s"."id")))
     LEFT JOIN "public"."space_types" "st" ON (("s"."space_type_id" = "st"."id")))
  WHERE ("r"."checkin" IS NOT NULL)
  GROUP BY ("date_trunc"('day'::"text", ("r"."checkin")::timestamp with time zone)), "r"."branch_id", "st"."name"
  WITH NO DATA;


