CREATE MATERIALIZED VIEW "public"."org_vocabulario" AS
 WITH "fuente" AS (
         SELECT "p"."organization_id",
            "public"."normalizar_busqueda"("concat_ws"(' '::"text", "p"."name", "p"."brand", "p"."reference")) AS "texto"
           FROM "public"."products" "p"
          WHERE ("p"."status" = 'active'::"text")
        UNION ALL
         SELECT "c"."organization_id",
            "public"."normalizar_busqueda"("c"."name") AS "normalizar_busqueda"
           FROM "public"."categories" "c"
          WHERE COALESCE("c"."is_active", true)
        )
 SELECT "f"."organization_id",
    "t"."palabra",
    ("count"(*))::integer AS "frecuencia"
   FROM ("fuente" "f"
     CROSS JOIN LATERAL "unnest"("string_to_array"("f"."texto", ' '::"text")) "t"("palabra"))
  WHERE ("length"("t"."palabra") >= 3)
  GROUP BY "f"."organization_id", "t"."palabra"
  WITH NO DATA;


ALTER TABLE "public"."org_vocabulario" OWNER TO "postgres";


COMMENT ON MATERIALIZED VIEW "public"."org_vocabulario" IS 'Palabras que aparecen en el catalogo de cada organizacion (nombre, marca, referencia y categorias). Sirve para decidir si el cliente esta hablando de productos y para corregir erratas sin listas cableadas.';



