CREATE OR REPLACE VIEW "public"."organization_module_status" WITH ("security_invoker"='true') AS
 SELECT "o"."id" AS "organization_id",
    "o"."name" AS "organization_name",
    "o"."subdomain",
    "p"."id" AS "plan_id",
    "p"."name" AS "plan_name",
    "p"."max_modules",
    "p"."max_branches",
    "count"(
        CASE
            WHEN ("om"."is_active" = true) THEN 1
            ELSE NULL::integer
        END) AS "total_active_modules",
    "count"(
        CASE
            WHEN (("om"."is_active" = true) AND ("m"."is_core" = true)) THEN 1
            ELSE NULL::integer
        END) AS "active_core_modules",
    "count"(
        CASE
            WHEN (("om"."is_active" = true) AND ("m"."is_core" = false)) THEN 1
            ELSE NULL::integer
        END) AS "active_paid_modules",
    GREATEST((0)::bigint, (COALESCE("p"."max_modules", 0) - "count"(
        CASE
            WHEN (("om"."is_active" = true) AND ("m"."is_core" = false)) THEN 1
            ELSE NULL::integer
        END))) AS "remaining_paid_modules",
        CASE
            WHEN ("count"(
            CASE
                WHEN (("om"."is_active" = true) AND ("m"."is_core" = false)) THEN 1
                ELSE NULL::integer
            END) >= COALESCE("p"."max_modules", 0)) THEN false
            ELSE true
        END AS "can_activate_more_modules",
    "array_agg"(
        CASE
            WHEN ("om"."is_active" = true) THEN "om"."module_code"
            ELSE NULL::"text"
        END ORDER BY "m"."rank") FILTER (WHERE ("om"."is_active" = true)) AS "active_module_codes"
   FROM (((("public"."organizations" "o"
     LEFT JOIN "public"."subscriptions" "s" ON (("o"."id" = "s"."organization_id")))
     LEFT JOIN "public"."plans" "p" ON (("s"."plan_id" = "p"."id")))
     LEFT JOIN "public"."organization_modules" "om" ON (("o"."id" = "om"."organization_id")))
     LEFT JOIN "public"."modules" "m" ON (("om"."module_code" = "m"."code")))
  GROUP BY "o"."id", "o"."name", "o"."subdomain", "p"."id", "p"."name", "p"."max_modules", "p"."max_branches";


