CREATE MATERIALIZED VIEW "public"."product_variations_summary" AS
 SELECT "p_parent"."id" AS "parent_id",
    "p_parent"."name" AS "parent_name",
    "p_parent"."sku" AS "parent_sku",
    "count"("p_child"."id") AS "total_variations",
    COALESCE("sum"("sl"."qty_on_hand"), (0)::numeric) AS "total_stock",
    COALESCE("avg"("pp"."price"), (0)::numeric) AS "avg_price",
    "array_agg"(DISTINCT "vt"."name") FILTER (WHERE ("vt"."name" IS NOT NULL)) AS "variation_types",
    "max"("p_child"."updated_at") AS "last_updated"
   FROM ((((("public"."products" "p_parent"
     LEFT JOIN "public"."products" "p_child" ON (("p_parent"."id" = "p_child"."parent_product_id")))
     LEFT JOIN "public"."stock_levels" "sl" ON (("p_child"."id" = "sl"."product_id")))
     LEFT JOIN "public"."product_prices" "pp" ON ((("p_child"."id" = "pp"."product_id") AND ("pp"."effective_to" IS NULL))))
     LEFT JOIN "public"."product_variant_relations" "pvr" ON (("p_child"."id" = "pvr"."product_id")))
     LEFT JOIN "public"."variant_types" "vt" ON (("pvr"."variant_type_id" = "vt"."id")))
  WHERE ("p_parent"."is_parent" = true)
  GROUP BY "p_parent"."id", "p_parent"."name", "p_parent"."sku"
  WITH NO DATA;


ALTER TABLE "public"."product_variations_summary" OWNER TO "postgres";


