CREATE TABLE IF NOT EXISTS "public"."sales" (
    "id" "uuid" DEFAULT "extensions"."uuid_generate_v4"() NOT NULL,
    "organization_id" integer NOT NULL,
    "branch_id" integer NOT NULL,
    "customer_id" "uuid",
    "user_id" "uuid" NOT NULL,
    "total" numeric(12,2) DEFAULT 0,
    "balance" numeric(12,2) DEFAULT 0,
    "status" "text" NOT NULL,
    "sale_date" timestamp with time zone DEFAULT "now"(),
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "payment_status" "text" DEFAULT 'pending'::"text",
    "tax_total" numeric(12,2) DEFAULT 0,
    "subtotal" numeric(12,2) DEFAULT 0,
    "discount_total" numeric(12,2) DEFAULT 0,
    "reservation_id" "uuid",
    "tax_included" boolean DEFAULT false NOT NULL,
    "tax_breakdown" "jsonb",
    "salesperson_id" "uuid",
    "commission_rate" numeric DEFAULT 0,
    "commission_type" "text" DEFAULT 'salesperson'::"text",
    "tip_amount" numeric DEFAULT 0,
    "tip_server_id" "uuid",
    "driver_id" "uuid",
    "table_session_id" "uuid",
    "delivery_fee" numeric DEFAULT 0,
    "opportunity_id" "uuid",
    "source" "text" DEFAULT 'pos'::"text" NOT NULL,
    "include_in_cash_register" boolean DEFAULT true NOT NULL,
    CONSTRAINT "sales_commission_type_check" CHECK (("commission_type" = ANY (ARRAY['salesperson'::"text", 'intermediation_sale'::"text", 'none'::"text"]))),
    CONSTRAINT "sales_payment_status_check" CHECK (("payment_status" = ANY (ARRAY['pending'::"text", 'paid'::"text", 'partial'::"text", 'refunded'::"text"]))),
    CONSTRAINT "sales_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'paid'::"text", 'partial'::"text", 'pending'::"text", 'void'::"text"])))
);


ALTER TABLE "public"."sales" OWNER TO "postgres";


COMMENT ON COLUMN "public"."sales"."reservation_id" IS 'Vincula la venta con una reserva PMS, permite agregar cargos al folio automáticamente';



COMMENT ON COLUMN "public"."sales"."tip_amount" IS 'Propina dejada por el cliente (mesas/restaurante)';



COMMENT ON COLUMN "public"."sales"."tip_server_id" IS 'UUID del mesero que recibió la propina';



COMMENT ON COLUMN "public"."sales"."driver_id" IS 'UUID del conductor asignado (delivery propio)';



COMMENT ON COLUMN "public"."sales"."table_session_id" IS 'UUID de la sesión de mesa asociada';



COMMENT ON COLUMN "public"."sales"."source" IS 'Origen de la venta: pos | web | invoice | crm | reservation';



COMMENT ON COLUMN "public"."sales"."include_in_cash_register" IS 'Si true, la venta aparece en el arqueo de caja POS';



