    CONSTRAINT "sequence_step_runs_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'running'::"text", 'completed'::"text", 'failed'::"text", 'skipped'::"text"])))
);


ALTER TABLE "public"."sequence_step_runs" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."sequence_steps" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" integer NOT NULL,
    "sequence_id" "uuid" NOT NULL,
    "step_number" integer NOT NULL,
    "delay_days" integer DEFAULT 0 NOT NULL,
    "channel" "text" NOT NULL,
    "template_id" "uuid",
    "action_config" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "name" "text",
    "delay_hours" integer DEFAULT 0 NOT NULL,
    "next_step_on_true" "uuid",
    "next_step_on_false" "uuid",
    "condition" "jsonb",
    "continue_on_error" boolean DEFAULT true NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "sequence_steps_channel_check" CHECK (("channel" = ANY (ARRAY['email'::"text", 'whatsapp'::"text", 'sms'::"text", 'call'::"text", 'task'::"text", 'wait'::"text", 'condition'::"text"]))),
    CONSTRAINT "sequence_steps_condition_no_continue_chk" CHECK ((("channel" <> 'condition'::"text") OR ("continue_on_error" = false))),
    CONSTRAINT "sequence_steps_condition_required_chk" CHECK ((("channel" <> 'condition'::"text") OR (("condition" IS NOT NULL) AND ((("jsonb_typeof"("condition") = 'object'::"text") AND ("condition" <> '{}'::"jsonb")) OR (("jsonb_typeof"("condition") = 'array'::"text") AND ("jsonb_array_length"("condition") > 0)))))),
    CONSTRAINT "sequence_steps_delay_days_check" CHECK ((("delay_days" >= 0) AND ("delay_days" <= 3650))),
    CONSTRAINT "sequence_steps_delay_hours_check" CHECK ((("delay_hours" >= 0) AND ("delay_hours" <= 23)))
);


ALTER TABLE "public"."sequence_steps" OWNER TO "postgres";


COMMENT ON CONSTRAINT "sequence_steps_condition_no_continue_chk" ON "public"."sequence_steps" IS 'FASE-08 N11: una condicion que falla al evaluarse corta la secuencia; continue_on_error no aplica a este canal.';



COMMENT ON CONSTRAINT "sequence_steps_condition_required_chk" ON "public"."sequence_steps" IS 'FASE-08 N10: un paso de condicion sin condicion evaluaba a verdadero y dejaba pasar la secuencia. Fail-closed.';



