CREATE OR REPLACE VIEW "public"."timeline_unified" WITH ("security_invoker"='true') AS
 SELECT ("ops_audit_log"."id")::"text" AS "event_id",
    "ops_audit_log"."organization_id",
    'audit'::"text" AS "source_category",
    'ops_audit_log'::"text" AS "source_table",
    "ops_audit_log"."entity_type" AS "event_type",
    "ops_audit_log"."action",
    "ops_audit_log"."user_id" AS "actor_id",
    "ops_audit_log"."entity_type",
    "ops_audit_log"."entity_id",
    "ops_audit_log"."branch_id",
    "jsonb_build_object"('previous_data', "ops_audit_log"."previous_data", 'new_data', "ops_audit_log"."new_data", 'changed_fields', "ops_audit_log"."changed_fields") AS "payload",
    "ops_audit_log"."metadata",
    "ops_audit_log"."ip_address",
    "ops_audit_log"."event_time",
    "ops_audit_log"."correlation_id",
    "ops_audit_log"."created_at"
   FROM "public"."ops_audit_log"
UNION ALL
 SELECT ("finance_audit_log"."id")::"text" AS "event_id",
    "finance_audit_log"."organization_id",
    'audit'::"text" AS "source_category",
    'finance_audit_log'::"text" AS "source_table",
    "finance_audit_log"."entity" AS "event_type",
    "finance_audit_log"."action",
    "finance_audit_log"."user_id" AS "actor_id",
    "finance_audit_log"."entity" AS "entity_type",
    "finance_audit_log"."entity_id",
    NULL::integer AS "branch_id",
    "jsonb_build_object"('diff', "finance_audit_log"."diff", 'reason', "finance_audit_log"."reason") AS "payload",
    NULL::"jsonb" AS "metadata",
    "finance_audit_log"."ip_address",
    "finance_audit_log"."event_time",
    "finance_audit_log"."correlation_id",
    "finance_audit_log"."timestamp" AS "created_at"
   FROM "public"."finance_audit_log"
UNION ALL
 SELECT ("products_audit_log"."id")::"text" AS "event_id",
    "products_audit_log"."organization_id",
    'audit'::"text" AS "source_category",
    'products_audit_log'::"text" AS "source_table",
    "products_audit_log"."entity_type" AS "event_type",
    "products_audit_log"."action_type" AS "action",
    "products_audit_log"."user_id" AS "actor_id",
    "products_audit_log"."entity_type",
    ("products_audit_log"."entity_id")::"text" AS "entity_id",
    NULL::integer AS "branch_id",
    "jsonb_build_object"('changes', "products_audit_log"."changes") AS "payload",
    NULL::"jsonb" AS "metadata",
    NULL::"text" AS "ip_address",
    "products_audit_log"."event_time",
    "products_audit_log"."correlation_id",
    "products_audit_log"."created_at"
   FROM "public"."products_audit_log"
UNION ALL
 SELECT ("roles_audit_log"."id")::"text" AS "event_id",
    "roles_audit_log"."organization_id",
    'audit'::"text" AS "source_category",
    'roles_audit_log'::"text" AS "source_table",
    "roles_audit_log"."entity" AS "event_type",
    "roles_audit_log"."action",
    "roles_audit_log"."user_id" AS "actor_id",
    "roles_audit_log"."entity" AS "entity_type",
    ("roles_audit_log"."entity_id")::"text" AS "entity_id",
    NULL::integer AS "branch_id",
    "jsonb_build_object"('diff', "roles_audit_log"."diff") AS "payload",
    NULL::"jsonb" AS "metadata",
    NULL::"text" AS "ip_address",
    "roles_audit_log"."event_time",
    "roles_audit_log"."correlation_id",
    "roles_audit_log"."logged_at" AS "created_at"
   FROM "public"."roles_audit_log"
UNION ALL
 SELECT ("chat_audit_logs"."id")::"text" AS "event_id",
    "chat_audit_logs"."organization_id",
    'audit'::"text" AS "source_category",
    'chat_audit_logs'::"text" AS "source_table",
    "chat_audit_logs"."entity_type" AS "event_type",
    "chat_audit_logs"."action",
    "chat_audit_logs"."actor_id",
    "chat_audit_logs"."entity_type",
    ("chat_audit_logs"."entity_id")::"text" AS "entity_id",
    NULL::integer AS "branch_id",
    "jsonb_build_object"('changes', "chat_audit_logs"."changes", 'actor_type', "chat_audit_logs"."actor_type") AS "payload",
    "chat_audit_logs"."metadata",
    ("chat_audit_logs"."ip_address")::"text" AS "ip_address",
    "chat_audit_logs"."event_time",
    "chat_audit_logs"."correlation_id",
    "chat_audit_logs"."created_at"
   FROM "public"."chat_audit_logs"
UNION ALL
 SELECT ("transport_events"."id")::"text" AS "event_id",
    "transport_events"."organization_id",
    'domain_event'::"text" AS "source_category",
    'transport_events'::"text" AS "source_table",
    "transport_events"."event_type",
    "transport_events"."event_type" AS "action",
    "transport_events"."actor_id",
    "transport_events"."reference_type" AS "entity_type",
