CREATE OR REPLACE VIEW "public"."vw_accounting_engine_health" WITH ("security_invoker"='true') AS
 SELECT "je"."organization_id",
    "o"."name" AS "organization_name",
    "count"(DISTINCT "je"."id") AS "total_asientos",
    "sum"("jl"."debit") AS "total_debitos",
    "sum"("jl"."credit") AS "total_creditos",
        CASE
            WHEN ("sum"("jl"."debit") = "sum"("jl"."credit")) THEN 'BALANCEADO'::"text"
            ELSE 'DESCUADRADO'::"text"
        END AS "estado_balance",
    "count"(DISTINCT
        CASE
            WHEN ("jl"."description" ~~ 'IVA - %'::"text") THEN "je"."id"
            ELSE NULL::integer
        END) AS "asientos_con_iva",
    "count"(DISTINCT "je"."source") AS "fuentes_cubiertas",
    ( SELECT "count"(*) AS "count"
           FROM "public"."accounting_rules" "ar"
          WHERE (("ar"."organization_id" = "je"."organization_id") AND ("ar"."is_active" = true))) AS "reglas_activas",
    ( SELECT "count"(*) AS "count"
           FROM "public"."branches" "b"
          WHERE ("b"."organization_id" = "je"."organization_id")) AS "total_branches",
    ( SELECT "count"(*) AS "count"
           FROM "public"."fiscal_periods" "fp"
          WHERE (("fp"."organization_id" = "je"."organization_id") AND ("fp"."status" = 'open'::"text"))) AS "periodos_abiertos"
   FROM (("public"."journal_entries" "je"
     JOIN "public"."journal_lines" "jl" ON (("jl"."journal_entry_id" = "je"."id")))
     JOIN "public"."organizations" "o" ON (("o"."id" = "je"."organization_id")))
  GROUP BY "je"."organization_id", "o"."name";


ALTER TABLE "public"."vw_accounting_engine_health" OWNER TO "postgres";


