CREATE TABLE IF NOT EXISTS "public"."website_visits" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" integer NOT NULL,
    "session_id" "text" NOT NULL,
    "page_path" "text" DEFAULT '/'::"text" NOT NULL,
    "referrer" "text",
    "user_agent" "text",
    "country" "text",
    "device_type" "text" DEFAULT 'desktop'::"text",
    "is_new_visitor" boolean DEFAULT true,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "ip_hash" "text"
);

ALTER TABLE ONLY "public"."website_visits" REPLICA IDENTITY FULL;


ALTER TABLE "public"."website_visits" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."whatsapp_qr_sessions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" integer NOT NULL,
    "channel_id" "uuid" NOT NULL,
    "session_ref" "text" NOT NULL,
    "phone_number" "text",
    "status" "text" DEFAULT 'disconnected'::"text" NOT NULL,
    "qr_code" "text",
    "qr_generated_at" timestamp with time zone,
    "connected_at" timestamp with time zone,
    "disconnected_at" timestamp with time zone,
    "last_error" "text",
    "last_warning" "text",
    "pairing_code" "text",
    "auth_state_path" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "whatsapp_qr_sessions_status_check" CHECK (("status" = ANY (ARRAY['disconnected'::"text", 'connecting'::"text", 'qr_ready'::"text", 'connected'::"text", 'reconnecting'::"text", 'banned'::"text", 'error'::"text"])))
);

ALTER TABLE ONLY "public"."whatsapp_qr_sessions" REPLICA IDENTITY FULL;


ALTER TABLE "public"."whatsapp_qr_sessions" OWNER TO "postgres";


COMMENT ON TABLE "public"."whatsapp_qr_sessions" IS 'Estado de sesiones WhatsApp vinculadas por QR (Baileys). Una fila por canal WhatsApp con connection_method=qr_scan.';



CREATE TABLE IF NOT EXISTS "public"."widget_sessions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" integer NOT NULL,
    "channel_id" "uuid" NOT NULL,
    "customer_id" "uuid",
    "anon_id" "text" NOT NULL,
    "session_token" "text" NOT NULL,
    "fingerprint_hash" "text",
    "ip_hash" "text",
    "user_agent" "text",
    "referrer" "text",
    "current_page" "text",
    "location_data" "jsonb",
    "device_type" "text",
    "is_active" boolean DEFAULT true,
    "last_seen_at" timestamp with time zone DEFAULT "now"(),
    "expires_at" timestamp with time zone NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"(),
    CONSTRAINT "widget_sessions_device_type_check" CHECK (("device_type" = ANY (ARRAY['desktop'::"text", 'mobile'::"text", 'tablet'::"text"])))
);


ALTER TABLE "public"."widget_sessions" OWNER TO "postgres";


