CREATE POLICY "Acceso a membership_payments por organización" ON "public"."membership_payments" USING ((EXISTS ( SELECT 1
   FROM ("public"."payments" "p"
     JOIN "public"."organization_members" "om" ON (("p"."organization_id" = "om"."organization_id")))
  WHERE (("p"."id" = "membership_payments"."payment_id") AND ("om"."user_id" = "auth"."uid"())))));



CREATE POLICY "Admin can manage commission rates" ON "public"."organization_commission_rates" USING (("auth"."role"() = 'authenticated'::"text"));



CREATE POLICY "Admin can manage payouts" ON "public"."organization_payouts" USING (("auth"."role"() = 'authenticated'::"text"));



CREATE POLICY "Administradores pueden gestionar alertas" ON "public"."system_alerts" USING ((EXISTS ( SELECT 1
   FROM "public"."organization_members"
  WHERE (("organization_members"."user_id" = "auth"."uid"()) AND ("organization_members"."organization_id" = "system_alerts"."organization_id") AND ("organization_members"."is_active" = true) AND (("organization_members"."role_id" = 2) OR ("organization_members"."is_super_admin" = true))))));



CREATE POLICY "Administradores pueden gestionar canales de su organización" ON "public"."notification_channels" USING ((EXISTS ( SELECT 1
   FROM "public"."organization_members"
  WHERE (("organization_members"."user_id" = "auth"."uid"()) AND ("organization_members"."organization_id" = "notification_channels"."organization_id") AND ("organization_members"."is_active" = true) AND (("organization_members"."role_id" = 2) OR ("organization_members"."is_super_admin" = true))))));



CREATE POLICY "Administradores pueden gestionar plantillas" ON "public"."notification_templates" USING ((EXISTS ( SELECT 1
   FROM "public"."organization_members"
  WHERE (("organization_members"."user_id" = "auth"."uid"()) AND ("organization_members"."organization_id" = "notification_templates"."organization_id") AND ("organization_members"."is_active" = true) AND (("organization_members"."role_id" = ANY (ARRAY[1, 2, 5])) OR ("organization_members"."is_super_admin" = true)))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM "public"."organization_members"
  WHERE (("organization_members"."user_id" = "auth"."uid"()) AND ("organization_members"."organization_id" = "notification_templates"."organization_id") AND ("organization_members"."is_active" = true) AND (("organization_members"."role_id" = ANY (ARRAY[1, 2, 5])) OR ("organization_members"."is_super_admin" = true))))));



CREATE POLICY "Administradores pueden gestionar reglas de alerta" ON "public"."alert_rules" USING ((EXISTS ( SELECT 1
   FROM "public"."organization_members"
  WHERE (("organization_members"."user_id" = "auth"."uid"()) AND ("organization_members"."organization_id" = "alert_rules"."organization_id") AND ("organization_members"."is_active" = true) AND (("organization_members"."role_id" = ANY (ARRAY[1, 2, 5])) OR ("organization_members"."is_super_admin" = true)))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM "public"."organization_members"
  WHERE (("organization_members"."user_id" = "auth"."uid"()) AND ("organization_members"."organization_id" = "alert_rules"."organization_id") AND ("organization_members"."is_active" = true) AND (("organization_members"."role_id" = ANY (ARRAY[1, 2, 5])) OR ("organization_members"."is_super_admin" = true))))));



CREATE POLICY "Administradores pueden gestionar webhooks" ON "public"."webhook_endpoints" USING ((EXISTS ( SELECT 1
   FROM "public"."organization_members"
  WHERE (("organization_members"."user_id" = "auth"."uid"()) AND ("organization_members"."organization_id" = "webhook_endpoints"."organization_id") AND ("organization_members"."is_active" = true) AND (("organization_members"."role_id" = 2) OR ("organization_members"."is_super_admin" = true))))));



CREATE POLICY "Administradores pueden ver logs de entrega de su organización" ON "public"."delivery_logs" FOR SELECT TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM ("public"."notifications" "n"
     JOIN "public"."organization_members" "om" ON (("n"."organization_id" = "om"."organization_id")))
  WHERE (("n"."id" = "delivery_logs"."notification_id") AND ("om"."user_id" = "auth"."uid"()) AND (("om"."role_id" = 2) OR ("om"."is_super_admin" = true)) AND ("om"."is_active" = true)))));



CREATE POLICY "Administradores pueden ver productos eliminados" ON "public"."products" FOR SELECT USING (("organization_id" = (("auth"."jwt"() ->> 'organization_id'::"text"))::integer));



CREATE POLICY "Admins can manage branches" ON "public"."branches" USING ((EXISTS ( SELECT 1
   FROM "public"."organization_members"
  WHERE (("organization_members"."user_id" = "auth"."uid"()) AND ("organization_members"."organization_id" = "branches"."organization_id") AND ("organization_members"."role_id" = 2) AND ("organization_members"."is_active" = true)))));



CREATE POLICY "Admins can manage organization modules" ON "public"."organization_modules" USING (("organization_id" IN ( SELECT "organization_members"."organization_id"
   FROM "public"."organization_members"
  WHERE (("organization_members"."user_id" = "auth"."uid"()) AND ("organization_members"."is_active" = true) AND (("organization_members"."role_id" = 2) OR ("organization_members"."is_super_admin" = true))))));



CREATE POLICY "Admins pueden gestionar páginas" ON "public"."website_pages" USING (("organization_id" IN ( SELECT "om"."organization_id"
   FROM ("public"."organization_members" "om"
     JOIN "public"."roles" "r" ON (("om"."role_id" = "r"."id")))
  WHERE (("om"."user_id" = "auth"."uid"()) AND (("r"."name")::"text" = ANY ((ARRAY['Super Admin'::character varying, 'Admin de organización'::character varying, 'owner'::character varying, 'admin'::character varying])::"text"[]))))));



CREATE POLICY "Admins pueden gestionar secciones" ON "public"."website_page_sections" USING (("organization_id" IN ( SELECT "om"."organization_id"
   FROM ("public"."organization_members" "om"
     JOIN "public"."roles" "r" ON (("om"."role_id" = "r"."id")))
  WHERE (("om"."user_id" = "auth"."uid"()) AND (("r"."name")::"text" = ANY ((ARRAY['Super Admin'::character varying, 'Admin de organización'::character varying, 'owner'::character varying, 'admin'::character varying])::"text"[]))))));



CREATE POLICY "Admins pueden gestionar testimonials" ON "public"."testimonials" TO "authenticated" USING (("organization_id" IN ( SELECT "om"."organization_id"
